L["Put this page's settings back to the active profile's own values (the defaults, or a built-in profile's)."] = "将本页设置恢复为当前配置文件自身的值（默认值，或内置配置文件的值）。"
L["Search Cinematic's settings"] = "搜索Cinematic的设置"
