L["|cff808080Nothing found|r"] = "|cff808080未找到任何结果|r"
L["Scroll for %d more"] = "滚动查看另外%d项"
L["Fades the UI and adds letterbox bars between fights. Combat, casting and opening windows like the spellbook bring it back. Typing just shows the chat. The pages under this one cover what shows when (CineMode, Game Frames, Addon Frames, Minimap, Quest tracker, Nameplates, Chat), visual effects and sound, the camera modes and triggers, and keybinds."] = "在战斗间隙淡出界面并加上宽银幕黑边。战斗、施法以及打开法术书等窗口会让界面重新出现。输入文字时只显示聊天框。本页下方的各页面分别设置何时显示什么（CineMode、游戏框体、插件框体、小地图、任务追踪、姓名板、聊天）、视觉效果和声音、镜头模式及其触发条件，以及按键绑定。"
L["Also toggled with /cine or the keybind under Key Bindings > AddOns."] = "也可以用 /cine 或“按键设置 > 插件”中的按键开关。"
L["Start in CineMode (fade UI, queue music, etc.)"] = "以CineMode启动（淡出界面、播放音乐等）"
L["Off: the UI stays as it is and the camera's left to you, with just the visual effects over it (as the Visual Effects page says), as in the Subtle profile. Events ticked in the Camera Triggers page's CineMode column still bring CineMode on while their camera runs: standing still or going AFK, say, for a screensaver."] = "关闭：界面保持原样，镜头由你控制，只在上面叠加视觉效果（按视觉效果页面的设置），与Subtle配置文件相同。在镜头触发页面的CineMode列中勾选的事件，在其镜头运行期间仍会开启CineMode：例如站着不动或暂离，可以当作屏幕保护。"
L["Left-click it for quick options (combat, music, tint), right-click for these settings, drag to move it."] = "左键点击打开快捷选项（战斗、音乐、色调），右键点击打开这些设置，拖动可移动。"
L["Language"] = "语言"
L["Game language"] = "游戏语言"
L["The language Cinematic's text is in, for all your characters. Game language follows the game's (English where Cinematic has no translation yet). A change needs a reload."] = "Cinematic文字所用的语言，对你的所有角色生效。“游戏语言”跟随游戏的语言（Cinematic尚无翻译的部分显示英文）。更改后需要重载界面。"
L["Turn off in"] = "在以下情况关闭"
L["Combat"] = "战斗"
L["Being in combat brings the UI back. Unticked, CineMode stays on in fights: only the frames ticked under In combat on the Game Frames page show. (Targeting an enemy only ever shows the frames chosen for it there.)"] = "进入战斗时界面重新出现。取消勾选时，CineMode在战斗中保持开启：只显示游戏框体页面中“战斗中”下勾选的框体。（选中敌人时只会显示在那里为此选择的框体。）"
L["Open world"] = "开放世界"
L["Anywhere outside cities, dungeons and raids (inns too), while you're not PvP flagged. Flights still go cinematic."] = "城市、地下城和团队副本以外的任何地方（也包括旅店），且你未处于PvP状态时。飞行时仍会使用电影效果。"
L["Cities"] = "城市"
L["Capital cities, including Dalaran. Flights leaving a city still go cinematic."] = "主城，包括达拉然。从城市出发的飞行仍会使用电影效果。"
L["Dungeons"] = "地下城"
L["Keep the normal UI in dungeons and scenarios."] = "在地下城和场景战役中保持正常界面。"
L["Raids"] = "团队副本"
L["PvP"] = "PvP"
L["Keep the normal UI while you're in a party (but not a raid group)."] = "当你在小队中（而非团队）时保持正常界面。"
L["Raid group"] = "团队"
L["Keep the normal UI while you're in a raid group, wherever you are."] = "当你在团队中时，无论身在何处都保持正常界面。"
L["Moving"] = "移动"
L["Walking or riding about yourself brings the UI back (names too), say to look for an NPC in a city. CineMode comes back once you've stood still, or kept moving, for the time below. Auto-run, RP walking and flights stay in CineMode."] = "你自己行走或骑乘移动时界面会重新出现（名字也是），例如在城市里寻找某个NPC时。当你站着不动或持续移动达到下方的时间后，CineMode会恢复。自动奔跑、RP漫步和飞行时保持CineMode。"
L["Keep VFX on"] = "保持视觉效果"
L["The visual effects (letterbox, tint and the rest on the Visual Effects page) stay on while moving brings the UI back."] = "移动使界面重新出现时，视觉效果（宽银幕黑边、色调以及视觉效果页面上的其他效果）保持开启。"
L["Back after"] = "恢复时间"
L["%d sec"] = "%d秒"
L["CineMode comes back once you've stood still this long, or kept moving this long without stopping (a long walk or ride)."] = "当你站着不动达到这段时间，或不停地持续移动这段时间（长距离步行或骑乘）后，CineMode会恢复。"
L["Reset profile"] = "重置配置文件"
L["Put the active profile's settings back to how it started (a built-in profile's own values, or the defaults). Frames you added or stopped fading are kept."] = "将当前配置文件的设置恢复为初始状态（内置配置文件自身的值，或默认值）。你添加的框体或已停止淡出的框体会保留。"
L["Profile: |cffff8000none yet|r (pick one on the Profiles page)"] = "配置文件：|cffff8000尚未选择|r（在配置文件页面中选择一个）"
L["Profile: %s"] = "配置文件：%s"
L[" (this character)"] = "（此角色）"
L["How fast the UI fades, what brings it (or parts of it) back while CineMode is on, and combat text. Fights and targeting are on the Game Frames page, names and nameplates on the Nameplates page, buffs on the Buffs/debuffs page, the minimap on the Minimap page, the quest tracker on the Quest tracker page, chat on the Chat page."] = "界面淡出的速度、CineMode开启时哪些情况会让界面（或其中一部分）重新出现，以及战斗文字。战斗和选择目标在游戏框体页面，名字和姓名板在姓名板页面，增益效果在增益/减益页面，小地图在小地图页面，任务追踪在任务追踪页面，聊天在聊天页面。"
L["Fading"] = "淡出"
L["Fade in time"] = "淡入时间"
L["How long things take to fade in out of combat: targeting something, a mouseover, a window opening. In fights the Combat fade in time is used."] = "非战斗时界面淡入所需的时间：选中目标、鼠标悬停、打开窗口。战斗中使用战斗淡入时间。"
L["%.1f sec"] = "%.1f秒"
L["Fade out time"] = "淡出时间"
L["How long things take to fade out, in and out of fights: letting go of a target, after a mouseover, and after a fight once the Calm Timer below is over. The mouseover time (Hover groups page) includes it: a time shorter than the fade just fades straight away."] = "界面淡出所需的时间，战斗中和战斗外都用：放开目标、鼠标悬停之后，以及战斗后下方的平静计时结束时。鼠标悬停时间（鼠标悬停分组页面）包含它：比淡出更短的时间会立即淡出。"
L["Combat fade in time"] = "战斗淡入时间"
L["How long things take to fade in during a fight: the UI coming back as one starts, and anything else that shows mid-fight. Other times use the Fade in time."] = "战斗中各元素淡入所需的时间：战斗开始时界面的重新出现，以及战斗中出现的其他任何元素。其他时候使用“淡入时间”。"
L["Calm Timer"] = "平静计时"
L["Exit Calm Timer when healthy"] = "生命值满时结束平静计时"
L["as soon as you're healthy"] = "一恢复健康就结束"
L["%d sec after you're healthy"] = "恢复健康后 %d 秒"
L["Include your pet"] = "包括宠物"
L["The Calm Timer runs out early once your health and power are back to full after a fight (mana, energy and focus refilled; rage, runic power, Insanity and the like drained). The seconds: how long things stay up once you're full, before they fade out at the Fade out time (a little wait keeps them up between pulls when you took no damage). Off: the Calm Timer always runs its full length."] = "战斗后生命值和能量恢复满时，平静计时提前结束（法力、能量和集中值回满；怒气、符文能量、狂乱值等清空）。秒数：恢复满后界面再保留多久，然后按淡出时间淡出（没有受到伤害时稍等一下，可让界面在两波怪之间保持显示）。关闭：平静计时总是走完全程。"
L["With a pet out, the Calm Timer only ends early once its health is back to full as well. No pet, or a dead one: just yours counts."] = "有宠物时，只有当宠物生命值也回满，平静计时才会提前结束。没有宠物或宠物已死亡：只看你自己的。"
L["%d sec after a fight"] = "战斗后%d秒"
L["How long things take to settle back into CineMode after a fight. Nameplates and names ticked In combat stay up this long (so they don't drop away between pulls), and visual effects that step aside for fights wait this long before fading back in. Your portrait and buffs, if they only show after combat, count a fight as recent for this long too, the RP walk, auto-run and cozy cameras wait this long before starting, and music muted for fights comes back after it. Then things fade out at the Fade out time. 0 settles at once. Exit Calm Timer when healthy, below, can end it early."] = "战斗结束后各元素回到CineMode所需的时间。勾选了“战斗中”的姓名板和名字会保持显示这段时间（这样它们不会在两次拉怪之间消失），为战斗让路的视觉效果也会等待这段时间后再淡入。如果你的头像和增益效果设为只在战斗后显示，在这段时间内也会把战斗视为刚刚发生；RP漫步、自动奔跑和温馨镜头会等待这段时间后再启动；因战斗而静音的音乐也会在之后恢复。之后界面按淡出时间淡出。0 表示立即平静。下方的“生命值满时结束平静计时”可以提前结束它。"
L["Combat text"] = "战斗文字"
L["Hide combat text out of combat"] = "脱离战斗时隐藏战斗文字"
L["No floating damage and healing numbers (like \"+10\" from a heal or regen) in cinematic mode while you're out of combat. They come back the moment a fight starts and stay for the Calm Timer after it, and your combat text settings are put back when the UI returns."] = "脱离战斗时，在电影模式下不显示浮动的伤害和治疗数字（例如治疗或回复带来的“+10”）。战斗一开始它们就会重新出现，并在战斗结束后的“平静计时”内保持显示；界面恢复时，你的战斗文字设置也会还原。"
L["Hide all floating text: XP, damage, healing (restart required)"] = "隐藏所有浮动文字：经验值、伤害、治疗（需要重启）"
L["The game has no way to hide just the XP you gain over your character: it draws that, the damage and healing numbers, misses and the like all in one font. This blanks that font, so they all go, always (not just in CineMode). Takes effect after you fully restart the game; /reload isn't enough."] = "游戏无法只隐藏角色头顶获得的经验值：它与伤害和治疗数字、未命中等都使用同一种字体绘制。此选项会清空该字体，因此它们会全部消失，并且是一直消失（不只是在CineMode中）。需要完全重启游戏后才生效；/reload 不够。"
L["Floating text changes after you fully restart the game (/reload isn't enough). Exit the game now?"] = "浮动文字需要完全重启游戏后才会改变（仅 /reload 不够）。现在退出游戏吗？"
L["Misc"] = "杂项"
L["Frames CineMode brings back while they have something to tell you. Always keeping a frame up, or in fights, is on the Game Frames page."] = "在有事要提醒你时，CineMode会让这些框体重新出现。要让框体一直显示或在战斗中显示，请到游戏框体页面设置。"
L["Show your portrait until health and power are full"] = "生命值和能量恢复满之前显示头像"
L["Keeps your player portrait up while you're recovering. Rage and runic power don't count, so a warrior's portrait hides once their health is full."] = "在你恢复期间保持显示玩家头像。怒气和符文能量不计算在内，因此战士的头像会在生命值满后隐藏。"
L["Only after combat"] = "仅限战斗后"
L["Only keep the portrait up if you've been in combat (or taken fall damage) within the Calm Timer (CineMode page), so things like casting a buff in town don't bring it up."] = "仅当你在“平静计时”（CineMode页面）内进入过战斗（或受到坠落伤害）时才保持显示头像，这样在城里施放增益效果之类的操作不会让它出现。"
L["Also after you resurrect"] = "复活后也显示"
L["After you come back to life, keep the portrait up until your health and power are full, however long that takes."] = "复活后，保持显示头像直到生命值和能量恢复满，无论需要多久。"
L["Show the durability figure when gear is damaged"] = "装备损坏时显示耐久度人形图"
L["Keeps the armor figure (by the minimap) up in CineMode, and in fights, while the game shows it: some of your gear is badly damaged (yellow) or broken (red). It goes again once you repair. Off, it fades with the rest of the UI."] = "在游戏显示护甲人形图（小地图旁）时，在CineMode和战斗中保持显示它：表示你的部分装备严重损坏（黄色）或已损坏（红色）。修理后它会再次消失。关闭时，它会随界面其他部分一起淡出。"
L["While a camera mode runs (AFK, auto-run, RP walk, flights and the rest), the figure fades with the rest of the UI. It comes back when the camera mode ends."] = "镜头模式运行时（暂离、自动奔跑、RP 步行、飞行等），人形图会随其余界面一起淡出。镜头模式结束后它会重新出现。"
L["Show the pet frame when your pet isn't happy"] = "宠物不快乐时显示宠物框体"
L["Keeps your pet's portrait up in CineMode, and in fights, while its happiness isn't green: content (yellow) or unhappy (red). It goes again once your pet is happy."] = "当宠物的快乐度不是绿色（满足：黄色，不快乐：红色）时，在 CineMode 和战斗中保持宠物头像显示。宠物快乐后再次隐藏。"
L["While a camera mode runs (AFK, auto-run, RP walk, flights and the rest), the pet frame fades with the rest of the UI. It comes back when the camera mode ends."] = "镜头模式运行时（暂离、自动奔跑、RP 漫步、飞行等），宠物框体随其余界面一起淡出。镜头模式结束后重新出现。"
L["Buffs/debuffs"] = "增益/减益"
L["Buffs/Debuffs"] = "增益/减益"
L["Your buff and debuff icons. They fade with the UI in CineMode; these bring them back."] = "你的增益和减益效果图标。它们在CineMode中随界面淡出；以下选项可以让它们重新出现。"
L["Show buffs when you gain or refresh one"] = "获得或刷新增益效果时显示"
L["Gaining or refreshing a buff briefly shows your buffs and debuffs. Not on flights."] = "获得或刷新增益效果时，短暂显示你的增益和减益效果。飞行时除外。"
L["On: CineMode fades your buffs and debuffs as this page and their Game Frames row say. Off: it leaves them alone, with no peeks."] = "开启：CineMode按照本页及游戏框体页面中对应行的设置淡出你的增益和减益效果。关闭：不做处理，也不会短暂显示。"
L["Only within the Calm Timer after a fight, so buffing up in town doesn't count."] = "仅限战斗后的“平静计时”内，这样在城里上增益效果不算在内。"
L["Not ones you cast on yourself"] = "不包括你对自己施放的"
L["Your own buffs on yourself (Power Word: Fortitude, Arcane Intellect, a self-cast shield...) and your pet's don't bring them up; ones from other players and the world still do."] = "你对自己施放的增益效果（真言术：韧、奥术智慧、自己施放的护盾……）以及你宠物的增益效果不会让它们出现；来自其他玩家和世界的增益效果仍然会。"
L["Show debuffs when you gain or refresh one"] = "获得或刷新减益效果时显示"
L["Gaining or refreshing a debuff briefly shows your buffs and debuffs. Not on flights."] = "获得或刷新减益效果时，短暂显示你的增益和减益效果。飞行时除外。"
L["Only within the Calm Timer after a fight. Off: debuffs like Hunter's Mark show any time."] = "仅限战斗后的“平静计时”内。关闭时：猎人印记之类的减益效果任何时候都会显示。"
L["Keep them up until the debuff is gone"] = "保持显示直到减益效果消失"
L["A debuff that brings them up keeps them up while you have any debuff (bar the ones listed below), however long that is. Combat still takes over."] = "让它们出现的减益效果会使它们在你身上有任何减益效果（下方列出的除外）期间一直保持显示，无论持续多久。战斗仍然优先。"
L["Show buffs for"] = "增益效果显示时长"
L["Show debuffs for"] = "减益效果显示时长"
L["Except for these buffs and debuffs:"] = "以下增益和减益效果除外："
L["Remove"] = "移除"
L["Add"] = "添加"
L["Gaining or stacking this doesn't bring your buffs up. Type a spell ID or a name. Names must match your game language; spell IDs work in any language (2479 is Honorless Target, 8326 and 20584 are Ghost)."] = "获得或叠加此效果不会让你的增益效果出现。输入法术ID或名称。名称必须与你的游戏语言一致；法术ID适用于任何语言（2479是无荣誉目标，8326和20584是灵魂）。"
L["Camera Modes"] = "镜头模式"
L["While CineMode is on, the camera comes alive in eight situations: Flight (on flight paths), AFK (once you've stood still a while, or go AFK), Cozy (campfires and emotes), Tele (casting your Hearthstone or a teleport), Vista (/stare), Fish (fishing), RP Walk (auto-walking) and Auto-run. Moving by hand cancels them all. Death Cam turns round your body when you die, and Quest Cam swings behind you at quest givers. The Camera Triggers page picks which camera each emote or event starts. Everything goes back to normal when the UI returns. The settings here apply to all of them."] = "CineMode开启时，镜头会在八种情况下动起来：飞行（在飞行路线上）、暂离（站着不动一段时间后，或暂离时）、温馨（篝火和表情）、传送（使用炉石或施放传送法术）、远景（/stare）、钓鱼（钓鱼时）、RP漫步（自动行走）以及自动奔跑。手动移动会取消所有这些镜头。死亡镜头会在你死亡时围绕你的尸体旋转，任务镜头会在与任务NPC对话时转到你身后。镜头触发页面用于选择每个表情或事件启动哪个镜头。界面恢复时一切都会回到正常。这里的设置对所有镜头生效。"
L["In the camera modes, the minimap and quest tracker hover holds and the buff and chat peeks use their short default times, so they clear the view quickly."] = "在镜头模式中，小地图和任务追踪的悬停保持时间，以及增益效果和聊天的短暂显示，都使用较短的默认时间，以便快速清空画面。"
L["Ticked, that camera doesn't start there (and stops if it's running): the UI stays faded, with the camera left to you. With the Death Cam off, dying brings the UI back as usual. To keep the normal UI somewhere instead, use Turn off in on the main page. For flights, Cities means taking off from one, and Open world taking off anywhere else. Calm Timer, on the right: ticked, that camera waits until the Calm Timer (CineMode page) has run out after a fight before it starts."] = "勾选后，该镜头不会在那里启动（正在运行的也会停止）：界面保持淡出，镜头由你控制。关闭死亡镜头时，死亡会像平常一样让界面重新出现。若想在某处保持正常界面，请使用主页面上的“在以下情况关闭”。对于飞行，“城市”指从城市起飞，“开放世界”指从其他任何地方起飞。右侧的“平静计时”：勾选后，该镜头会等到战斗后的“平静计时”（CineMode页面）结束才启动。"
L["in capital cities"] = "在主城中"
L["in dungeons, scenarios and raids"] = "在地下城、场景战役和团队副本中"
L["in battlegrounds and arenas"] = "在战场和竞技场中"
L["out in the world (not in a capital city or an instance), inns included"] = "在野外（不在主城或副本中），包括旅店"
L["Tick a camera here to turn it off %s."] = "在此勾选镜头，使其%s关闭。"
L["Tick a camera here to have it wait until the Calm Timer (CineMode page) has run out after a fight before it starts."] = "在此勾选镜头，使其等到战斗后的“平静计时”（CineMode页面）结束才启动。"
L["Flights don't start %s."] = "%s不启动飞行镜头。"
L["No Flight Cam on flights taking off from a capital city."] = "从主城起飞的飞行不使用飞行镜头。"
L["No Flight Cam on flights taking off anywhere but a capital city."] = "从主城以外任何地方起飞的飞行不使用飞行镜头。"
L["No %s Cam %s."] = "%s镜头%s关闭。"
L["You die in a fight: the Death Cam can't wait for one to be over."] = "你是在战斗中死亡的：死亡镜头无法等到战斗结束。"
L["The %s Cam waits until the Calm Timer has run out after a fight."] = "%s镜头会等到战斗后的“平静计时”结束才启动。"
L["Depth of field"] = "景深"
L["Cozy camera"] = "温馨镜头"
L["Vista camera"] = "远景镜头"
L["Fish camera"] = "钓鱼镜头"
L["AFK camera"] = "暂离镜头"
L["No camera"] = "无镜头"
L["Flight camera"] = "飞行镜头"
L["RP walk camera"] = "RP漫步镜头"
L["Auto-run camera"] = "自动奔跑镜头"
L["Death camera"] = "死亡镜头"
L["Quest camera"] = "任务镜头"
L["Tele camera"] = "传送镜头"
L["Standing or sitting still with any of the buffs listed below (like Welcoming Campfire)."] = "带着下方列出的任一增益效果（例如温馨篝火）站着或坐着不动。"
L["Doing the emote (or pressing the sit key). Moving, jumping or another emote ends it."] = "做出该表情（或按坐下键）。移动、跳跃或做其他表情会结束它。"
L["Doing the emote. Moving, jumping or another emote ends it."] = "做出该表情。移动、跳跃或做其他表情会结束它。"
L["Right-clicking a seat to sit on it; standing up ends it. Seats are recognized by name, using the words below."] = "右键点击座位坐下；站起来会结束它。座位按名称识别，使用下方的关键词。"
L["Unsheathing your weapon with your Sheathe/Unsheathe key out of combat, for a \"hero shot\" (not when it comes out from attacking or casting). Putting it away, running or combat ends it. With the cozy camera it carries on while you auto-walk (the camera swings round in front as you walk, even with Stop on move)."] = "在非战斗状态下用收起/拔出武器键拔出武器，来一个“英雄特写”（因攻击或施法而拔出武器时不算）。收起武器、奔跑或进入战斗会结束它。使用温馨镜头时，它会在你自动行走时继续（行走时镜头会转到你前方，即使开启了“移动时停止”）。"
L["Casting your Hearthstone (or Astral Recall, or any spell with \"Hearthstone\" in its name). The tele camera swings round in front of you and spins faster and faster as it zooms in, until you go. The cast doesn't bring the UI back or pause the camera."] = "使用炉石（或星界传送，或名称中带有“炉石”的任何法术）。传送镜头会转到你前方，一边拉近一边越转越快，直到你被传送走。施法不会让界面重新出现，也不会暂停镜头。"
L["Casting a teleport (a mage's \"Teleport: Stormwind\" and the like, or a druid's Teleport: Moonglade). The tele camera, as for the Hearthstone."] = "施放传送法术（法师的“传送：暴风城”之类，或德鲁伊的传送：月光林地）。使用传送镜头，与炉石相同。"
L["Logging out or quitting where the game counts down 20 seconds first (out in the world). In an inn or a city, logging out is instant, so there's nothing to see. Moving, jumping, casting or Cancel ends it. It comes before any other event (a Hearthstone or teleport cast calls it off)."] = "在游戏会先倒计时20秒的地方（野外）登出或退出游戏。在旅店或城市中登出是即时的，所以没有什么可看的。移动、跳跃、施法或点击取消会结束它。它优先于其他任何事件（使用炉石或施放传送法术会取消它）。"
L["Doing the emote while standing still. Moving, jumping or another emote ends it."] = "站着不动时做出该表情。移动、跳跃或做其他表情会结束它。"
L["Casting Fishing. It carries on after the cast ends (looting, casting again) until you move or jump. The cast doesn't bring the UI back or pause the camera."] = "施放钓鱼。施法结束后（拾取、再次抛竿）仍会继续，直到你移动或跳跃。施法不会让界面重新出现，也不会暂停镜头。"
L["Being flagged AFK (/afk, or away long enough). With \"No camera\", Stand still below still applies once you've stood still for its time."] = "处于暂离状态（/afk，或离开足够久）。选择“无镜头”时，当你站着不动达到其时间后，下方的“站着不动”仍然适用。"
L["Standing still for the time below with nothing else going on (no emote, no other event). \"No camera\": standing still starts nothing, though going AFK and the other events still do."] = "站着不动达到下方的时间，且没有其他情况发生（没有表情，也没有其他事件）。“无镜头”：站着不动不会启动任何东西，但暂离和其他事件仍然会。"
L["Taking off on a flight path. With \"No camera\", the camera is left to you for the whole flight."] = "沿飞行路线起飞。选择“无镜头”时，整个飞行过程中镜头由你控制。"
L["Talking to a quest giver (a quest to pick up or hand in). Works whether or not CineMode is on."] = "与任务NPC对话（有任务可接或可交）。无论CineMode是否开启都有效。"
L["Camera Triggers"] = "镜头触发"
L["What starts the AFK, cozy, vista and fish cameras. Pick a camera for each event; a Hearthstone or teleport cast comes first, then logging out, going AFK, the latest emote, a drawn weapon, a campfire, and standing still last. Taking a flight has the flight camera, talking to a quest giver the quest camera, and auto-walking, auto-running and dying their own."] = "什么会启动暂离、温馨、远景和钓鱼镜头。为每个事件选择一个镜头；使用炉石或施放传送法术最优先，然后是登出、暂离、最近的表情、拔出武器、篝火，站着不动排在最后。乘坐飞行使用飞行镜头，与任务NPC对话使用任务镜头，自动行走、自动奔跑和死亡各有自己的镜头。"
L["Event"] = "事件"
L["Camera"] = "镜头"
L["Music"] = "音乐"
L["Music starts as this event's camera starts, unless the addon started music within the fatigue time (Audio page). Music already playing just carries on. Off: this camera never starts music. Needs \"Allow CineMode to queue Music\" on the Audio page."] = "此事件的镜头启动时开始播放音乐，除非插件在疲劳时间（音频页面）内已经播放过音乐。正在播放的音乐会继续。关闭：此镜头从不播放音乐。需要在音频页面开启“允许CineMode播放音乐”。"
L["With \"Start in CineMode\" off (Cinematic's main page), this event's camera starting brings CineMode on (the UI fades, music, visual effects), and it ends with the camera. Tick Stand still and Go AFK for a screensaver: the normal UI while you play, CineMode once you've been idle a while."] = "在“以CineMode启动”关闭时（Cinematic主页面），此事件的镜头启动会开启CineMode（界面淡出、音乐、视觉效果），并随镜头一同结束。勾选“站着不动”和“暂离”可当作屏幕保护：游戏时是正常界面，闲置一段时间后进入CineMode。"
L[" While you're flagged AFK, whatever the camera. Off also keeps music from coming back after a pause while you're away."] = "在你处于暂离状态期间，无论使用哪个镜头。关闭时，你离开期间音乐暂停后也不会再恢复。"
L[" Off also keeps music from coming back after a pause while you stand still."] = "关闭时，你站着不动期间音乐暂停后也不会再恢复。"
L["Buff names or spell IDs, separated by commas. Names must match your game language; spell IDs work in any language."] = "增益效果名称或法术ID，用逗号分隔。名称必须与你的游戏语言一致；法术ID适用于任何语言。"
L["Buffs, separated by commas."] = "增益效果，用逗号分隔。"
L["Words that mark a seat when they're in an object's name (\"Wooden Chair\"), separated by commas. Use words in your game language."] = "物体名称中出现时即表示座位的词语（如“木椅”），用逗号分隔。请使用你游戏语言中的词语。"
L["Seat words, separated by commas."] = "座位关键词，用逗号分隔。"
L["After standing still for"] = "站着不动多久后"
L["How long you stand still before this row's camera starts (an event set to the AFK camera, like going AFK, skips the wait). Also used by the other options that mention standing still (tint, tracking, music, tooltips)."] = "站着不动多久后启动此行的镜头（设为暂离镜头的事件，例如暂离，会跳过等待）。其他提到站着不动的选项（色调、追踪、音乐、鼠标提示）也使用此时间。"
L["Auto-walk (RP walk)"] = "自动行走（RP漫步）"
L["After auto-walking for"] = "自动行走多久后"
L["Auto-walking (auto-run in walk mode). The camera's settings are under RP Walk Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "自动行走（行走模式下的自动奔跑）。镜头设置在镜头设置页面的RP漫步镜头中；镜头模式页面可在某些地方关闭它。"
L["After auto-running for"] = "自动奔跑多久后"
L["Auto-running. The camera's settings are under Auto-run Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "自动奔跑。镜头设置在镜头设置页面的自动奔跑镜头中；镜头模式页面可在某些地方关闭它。"
L["Die"] = "死亡"
L["Dying, until you release or are resurrected. The camera's settings are under Death Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "死亡，直到你释放灵魂或被复活。镜头设置在镜头设置页面的死亡镜头中；镜头模式页面可在某些地方关闭它。"
L["A song of its own plays while the death camera runs, in place of the zone music (pick the songs under Death Cam on the Camera Settings page). With CineMode music off, only if your game music is on."] = "死亡镜头运行时，会播放专属歌曲来代替区域音乐（在镜头设置页面的死亡镜头中选择歌曲）。关闭CineMode音乐时，仅在游戏音乐开启时播放。"
L["How long you keep going before this row's camera starts (and CineMode, if its CineMode box is ticked). 0: straight away. Stopping or moving by hand first starts the count over."] = "持续多久后启动此行的镜头（如果勾选了其CineMode复选框，也会启动CineMode）。0：立即启动。在此之前停下或手动移动会重新计时。"
L["An event set to the AFK camera starts it without waiting out Stand still's time."] = "设为暂离镜头的事件会直接启动它，无需等待“站着不动”的时间。"
L["Strength"] = "强度"
L["%.2f sec"] = "%.2f秒"
L["Visual Effects"] = "视觉效果"
L["How the game world looks in CineMode (or over the normal UI, with Start in CineMode off on the main page): letterbox bars, color grading, vignette, inn glow and weather. The UI isn't tinted. Names and nameplates are on the Nameplates page."] = "游戏世界在CineMode中的外观（或在主页面关闭“以CineMode启动”时叠加在正常界面上）：宽银幕黑边、调色、暗角、旅店光晕和天气。界面本身不会被染色。名字和姓名板在姓名板页面。"
L["Turns everything on this page on or off at once: the letterbox, tint, time of day, zone tints, vignette, inn glow, weather and depth of field. Each keeps its own settings for when you turn this back on."] = "一次性开启或关闭本页的所有效果：宽银幕黑边、色调、时段、区域色调、暗角、旅店光晕、天气和景深。重新开启时，各项会保留自己的设置。"
L["Ticked, that effect doesn't show there. Always: not at all. Combat: it goes for fights, and comes back once the Calm Timer (CineMode page) has run out after. Outside camera modes: it only shows while a camera mode runs (flights, AFK, cozy and the rest)."] = "勾选后，该效果不在那里显示。始终：完全不显示。战斗：战斗时消失，战斗后“平静计时”（CineMode页面）结束后恢复。镜头模式之外：只在镜头模式运行时显示（飞行、暂离、温馨等）。"
L["Letterbox"] = "宽银幕黑边"
L["Vignette"] = "暗角"
L["Weather"] = "天气"
L["letterbox"] = "宽银幕黑边"
L["tint"] = "色调"
L["vignette"] = "暗角"
L["weather tint"] = "天气色调"
L["Always"] = "始终"
L["No %s at all."] = "完全不显示%s。"
L["No %s %s."] = "无%s：%s。"
L["The %s goes for fights, and comes back once the Calm Timer (CineMode page) has run out after one."] = "%s在战斗时消失，战斗后“平静计时”（CineMode页面）结束后恢复。"
L["Outside camera modes"] = "镜头模式之外"
L["The %s only shows while a camera mode runs: flights, AFK, cozy and the rest."] = "%s只在镜头模式运行时显示：飞行、暂离、温馨等。"
L["Bar height"] = "黑边高度"
L["Black bars slide in at the top and bottom of the screen."] = "黑边从屏幕顶部和底部滑入。"
L["Bar opacity"] = "黑边不透明度"
L["Current time"] = "当前时间"
L["Preview time"] = "预览时间"
L["See how the tint looks at another time of day. Only a preview: it goes back to the real clock when you leave this page."] = "查看色调在一天中其他时段的效果。仅为预览：离开本页面后会回到实际时间。"
L["Here: %s (%s's own preset)"] = "此处：%s（%s自身的预设）"
L["Here: %s (%s%s)"] = "此处：%s（%s%s）"
L[", your choice"] = "，你的选择"
L["Previewing: %s (%02d:00)"] = "预览中：%s（%02d:00）"
L["Now: %s (%02d:%02d your time)"] = "现在：%s（本地时间%02d:%02d）"
L["Now: %s (%02d:%02d game time)"] = "现在：%s（游戏时间%02d:%02d）"
L["Custom color"] = "自定义颜色"
L["Click to choose the color used by the Custom preset."] = "点击选择“自定义”预设使用的颜色。"
L["Subtle drift"] = "细微浮动"
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive. Paused while this page is open."] = "色调强度会在几分钟内缓慢地上下浮动，让静止的画面显得更生动一些。打开本页面时暂停。"
L["Drift amount"] = "浮动幅度"
L["How far the strength wanders either way, as a share of the strength."] = "强度向上或向下浮动的幅度，以强度的比例表示。"
L["Time of day"] = "时段"
L["For the Time of day and Zone + time of day presets, and the time of day message."] = "用于“时段”和“区域 + 时段”预设，以及时段提示信息。"
L["Follows"] = "按照"
L["Game time (matches the game's day and night)"] = "游戏时间（与游戏中的昼夜一致）"
L["Your computer's clock"] = "你电脑的时钟"
L["Time of day strength"] = "时段强度"
L["How strongly the time-of-day color applies, in Time of day and Zone + time of day. Lower it for softer nights; 0 leaves just the zone mood."] = "在“时段”和“区域 + 时段”中，时段颜色的应用强度。调低可让夜晚更柔和；设为0则只保留区域氛围。"
L["Phases (click a color to change it)"] = "阶段（点击颜色进行更改）"
L["Reset"] = "重置"
L["Back to the built-in color and strength."] = "恢复为内置的颜色和强度。"
L["Choose your own color for %s."] = "为%s选择你自己的颜色。"
L["Zone tints"] = "区域色调"
L["Give the zone you're standing in, or just the area within it (a town, a port), a preset of its own: it replaces your main preset there. With a Zone preset you can also choose its color, which replaces the built-in mood. An area's choices win over its zone's."] = "为你所在的区域，或只为其中的某个地点（城镇、港口），设置专属预设：它会在那里代替你的主预设。使用“区域”预设时，你还可以选择其颜色，代替内置的氛围。地点的设置优先于所在区域的设置。"
L[", |cffffd100%s|r preset"] = "，|cffffd100%s|r预设"
L["This zone: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "此区域：|cffffd100%s|r - %s%s，强度%d%%%s%s"
L[" (your choice)"] = "（你的选择）"
L[" (built in)"] = "（内置）"
L[" (its own)"] = "（自身的）"
L["This area: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "此地点：|cffffd100%s|r - %s%s，强度%d%%%s%s"
L["Change:"] = "更改："
L["the zone"] = "区域"
L["this area (%s)"] = "此地点（%s）"
L["this area (none here)"] = "此地点（此处没有）"
L["Same as the zone"] = "与区域相同"
L["Main preset"] = "主预设"
L["Preset here"] = "此处预设"
L["A preset for the zone or area chosen above, used there instead of your main preset."] = "为上方所选区域或地点设置的预设，在那里代替你的主预设。"
L["Built-in mood"] = "内置氛围"
L["No tint"] = "无色调"
L["Pick a color..."] = "选择颜色……"
L["Choose your own color for the zone or area chosen above (for the Zone presets)."] = "为上方所选区域或地点选择你自己的颜色（用于“区域”预设）。"
L["Your zone tints"] = "你的区域色调"
L["%s preset, "] = "%s预设，"
L[", %d%% strength"] = "，强度%d%%"
L["None yet."] = "暂无。"
L["...and %d more."] = "……还有%d个。"
L["At zone borders"] = "在区域边界"
L["Fade time"] = "过渡时间"
L["With a Zone tint preset, crossing into a zone with a different mood fades the old mood out over this long, pauses, then fades the new one in over this long."] = "使用“区域”色调预设时，进入氛围不同的区域，旧氛围会在这段时间内淡出，停顿一下，然后新氛围在这段时间内淡入。"
L["Pause between tints when flying"] = "飞行时色调之间的停顿"
L["Untinted time between the two zones' moods while you're in the air, where you see the old zone's ground for longer (snow under an ember tint looks red)."] = "在空中时，两个区域氛围之间无色调的时间，因为在空中你会更久地看到旧区域的地面（余烬色调下的雪看起来是红色的）。"
L["Pause between tints on the ground"] = "地面上色调之间的停顿"
L["The same pause when you cross a border on foot or riding."] = "步行或骑乘越过边界时的相同停顿。"
L["Vignette strength"] = "暗角强度"
L["Soft dark edges that draw the eye to the middle. Works with any tint."] = "柔和的暗色边缘，把视线引向画面中央。适用于任何色调。"
L["Inns"] = "旅店"
L["Light up inns"] = "照亮旅店"
L["Indoors in an inn, the outdoor tint (a gloomy marsh, a moonlit night) partly lifts and a soft firelit glow fades in, colored by the zone: cooler in the snow, greener in a swamp. Blends over a few seconds as you go through the door."] = "在旅店室内时，室外色调（阴沉的沼泽、月夜）会部分消退，并淡入柔和的炉火光晕，颜色随区域而定：雪地中偏冷，沼泽中偏绿。穿过门时会在几秒内逐渐过渡。"
L["Inn glow amount"] = "旅店光晕强度"
L["How much light the glow adds at its brightest, low on the screen."] = "光晕在最亮处（屏幕下方）增加多少亮度。"
L["Weather strength"] = "天气强度"
L["Rain grays and cools the scene, snow turns it pale blue and a sandstorm gives it a dusty orange haze, more strongly the heavier the weather. Works with any tint (None included), lifts under a roof and blends in as a storm builds. Needs a game version that reports the weather."] = "雨天让画面变灰变冷，雪天让它变成淡蓝色，沙尘暴则带来一层尘土般的橙色薄雾，天气越恶劣效果越强。适用于任何色调（包括“无”），在屋顶下会消退，并随风暴增强而逐渐融入。需要能报告天气的游戏版本。"
L["Haze the screen edges in the camera modes"] = "在镜头模式中模糊屏幕边缘"
L["A soft haze around the edges of the screen, as if the camera had focused on you. Each camera mode's page sets its own strength. /cine doftest shows it on demand."] = "屏幕边缘的柔和模糊，就像镜头聚焦在你身上。每个镜头模式的页面各自设置其强度。/cine doftest 可随时显示它。"
L["Sound during CineMode. Your own sound settings are saved first and put back afterwards, even after a crash. Pick which cameras play music as they start."] = "CineMode期间的声音。你自己的声音设置会先保存，之后再还原，即使游戏崩溃也一样。选择哪些镜头在启动时播放音乐。"
L["With your game music off, a camera starting (the ones ticked under Music on the Camera Triggers page) switches it on and fades it in, at your music volume; it fades out when the UI returns and your music is switched off again (logging out too). With your game music on, it's left alone. Unticked, music is never switched on."] = "当你的游戏音乐关闭时，镜头启动（在镜头触发页面的“音乐”下勾选的镜头）会以你的音乐音量开启音乐并淡入；界面恢复时音乐淡出，你的音乐再次关闭（登出时也是）。当你的游戏音乐开启时，不做处理。取消勾选时，从不开启音乐。"
L["Music fade time"] = "音乐过渡时间"
L["How long music takes to fade in or out with CineMode."] = "音乐随CineMode淡入或淡出所需的时间。"
L["Fatigue"] = "疲劳"
L["Music fatigue"] = "音乐疲劳"
L["Once a camera has started music, no camera starts it again for this long, counted from when it started. The first camera after a login or /reload always can. Music coming back after a mute doesn't count. 0 turns this off."] = "某个镜头播放音乐后，在这段时间内（从开始播放时算起）没有镜头会再次播放音乐。登录或 /reload 后的第一个镜头总是可以播放。静音后恢复的音乐不计算在内。设为0则关闭此功能。"
L["Stop music"] = "停止音乐"
L["In combat"] = "战斗中"
L["Music fades out over about a second when a fight starts, and a fresh track fades back in once the Calm Timer (on the CineMode page) has passed with no new fight. Works on your own game music too; your volume is put back afterwards."] = "战斗开始时，音乐会在大约一秒内淡出；在“平静计时”（CineMode页面）结束且没有新的战斗后，会淡入一首新的曲目。对你自己的游戏音乐也有效；之后会还原你的音量。"
L["Leaving a camera mode"] = "离开镜头模式时"
L["Music fades out once you leave the camera modes and move on: walking off from the cozy camera, say. Going from one camera straight to another (vista to cozy) keeps it playing, as does standing still. A fresh track fades in when the next camera starts (standing still counts once the AFK camera starts, with Go AFK's music on, Camera Triggers page). Fades at the music fade time."] = "当你离开镜头模式并继续前进时，音乐会淡出：例如从温馨镜头中走开。从一个镜头直接切换到另一个（从远景到温馨）会继续播放，站着不动也是如此。下一个镜头启动时会淡入一首新的曲目（站着不动在暂离镜头启动后才算，需在镜头触发页面开启“暂离”的音乐）。按音乐过渡时间淡入淡出。"
L["In cities"] = "在城市中"
L["In dungeons"] = "在地下城中"
L["In raids"] = "在团队副本中"
L["In PvP"] = "PvP中"
L["Music fades out here (your own game music too) and back in when you leave."] = "音乐在这里淡出（你自己的游戏音乐也是），离开时再淡入。"
L["Tar enemy"] = "敌方目标"
L["Tar friendly"] = "友方目标"
L["More settings on the %s page. They can keep it up beyond what's ticked here (hovering, tracking, new auras, cooldowns recharging and the like)."] = "更多设置在%s页面。它们可以在此处勾选的情况之外保持显示（鼠标悬停、追踪、新的光环、冷却恢复中等）。"
L["Show it whenever its frame shows. This overrides its Hover groups: untick it to hide it in CineMode except when hovered or brought up by the other columns."] = "只要其框体显示就显示它。此项优先于其鼠标悬停分组：取消勾选可在CineMode中隐藏它，除非鼠标悬停或其他列让它出现。"
L["Show it all through CineMode, instead of hiding it. (The other columns then have nothing to add.)"] = "在整个CineMode期间显示，而不是隐藏。（这样其他列就没有作用了。）"
L["Standard Frames"] = "标准框体"
L["Everything here is hidden in CineMode unless ticked. Tick a column to show that frame: Always shows it the whole time, the next three only while you fight or have something targeted, and the places the whole time while you're there (Grouped: in a party or raid). Frames fade in and out at the fade times on the CineMode page. Other addons' frames are on the Addon Frames page."] = "除非勾选，这里的所有内容在CineMode中都会隐藏。勾选某一列即可显示该框体：“始终”一直显示，接下来三列仅在你战斗或选中目标时显示，各地点列则在你身处那里时一直显示（组队时：在小队或团队中）。框体按CineMode页面上的过渡时间淡入淡出。其他插件的框体在插件框体页面。"
L["Enable Page"] = "启用页面"
L["On: CineMode fades the frames on this page as their rows say. Off: it leaves them all alone, the minimap, quest tracker, buffs and Cooldown Manager included (their pages' switches only count while this is on)."] = "开启：CineMode按照各行的设置淡出本页上的框体。关闭：全部不做处理，包括小地图、任务追踪、增益效果和冷却管理器（它们页面上的开关只在此项开启时有效）。"
L["In combat rows stay for the Calm Timer"] = "“战斗中”的行在平静计时内保持显示"
L["Frames ticked In combat (here and on the Addon Frames page) stay up after a fight until the Calm Timer (CineMode page) has run out, then fade. Off: they fade as soon as the fight ends."] = "勾选了“战斗中”的框体（此处和插件框体页面）在战斗结束后会保持显示，直到“平静计时”（CineMode页面）结束，然后淡出。关闭：战斗一结束就淡出。"
L["Cast fade into combat"] = "施法渐入战斗"
L["Out of combat, casting a spell at an enemy brings up the frames ticked In combat, as if the fight had started: they fade in over the cast and are fully up as it lands. Instant spells bring them up at the Combat fade in time."] = "在战斗外对敌人施法时，勾选“战斗中”的框体会像战斗已经开始一样出现：它们在施法过程中渐显，法术命中时完全显示。瞬发法术按战斗渐显时间显示它们。"
L["Unit frames"] = "单位框体"
L["Unit Frames"] = "单位框体"
L["Interface"] = "界面"
L["Party frames (not raid-style)"] = "小队框架（非团队样式）"
L["Battlegrounds"] = "战场"
L["Other"] = "其他"
L["Fishing"] = "钓鱼"
L["Casting and catching, with the mouse or a gamepad, CineMode or not."] = "使用鼠标或手柄抛竿和收竿，无论是否处于CineMode。"
L["On: right-click (or a gamepad button) casts again, and the Fishing cast bar hides, as this page says. Off: fishing is left to the game. (The fish camera is on the Camera Modes and Camera Triggers pages.)"] = "开启：按照本页设置，右键点击（或手柄按键）再次抛竿，并隐藏钓鱼施法条。关闭：钓鱼交由游戏处理。（钓鱼镜头在镜头模式和镜头触发页面。）"
L["Casting"] = "抛竿"
L["Hide the Fishing cast bar"] = "隐藏钓鱼施法条"
L["Your cast bar stays hidden while it shows Fishing. Every other spell shows it as usual."] = "施法条显示钓鱼时保持隐藏。其他所有法术照常显示。"
L["Right-click to cast again"] = "右键点击再次抛竿"
L["While the fish camera is on and no bobber is out, right-clicking in the world casts Fishing again. Each cast still comes from your own click. While the bobber is out, right-click clicks it as usual; in combat, with the loot window open or with your mouse on a player or NPC, right-click is left alone. (Meanwhile right-drag doesn't turn the camera: left-drag still does.)"] = "钓鱼镜头开启且没有鱼漂时，在世界中右键点击会再次施放钓鱼。每次抛竿仍然来自你自己的点击。有鱼漂时，右键点击照常点击鱼漂；在战斗中、拾取窗口打开时或鼠标指向玩家或NPC时，右键点击不做处理。（在此期间，按住右键拖动不会转动镜头：按住左键拖动仍然可以。）"
L["Also the first cast, with a pole equipped"] = "装备鱼竿时也包括第一次抛竿"
L["With a fishing pole in your main hand, standing still, right-clicking in the world casts Fishing, so you don't have to start the first cast yourself. Not while your mouse is on a player, NPC or object (mailbox, corpse...): right-click works on them as usual. Swap the pole out to have right-click back everywhere."] = "主手装备鱼竿并站着不动时，在世界中右键点击会施放钓鱼，这样你就不必自己开始第一次抛竿。鼠标指向玩家、NPC或物体（邮箱、尸体……）时除外：右键点击对它们照常有效。换下鱼竿即可让右键点击在所有地方恢复正常。"
L["Wait after a cast ends"] = "抛竿结束后的等待"
L["How long after a cast ends (a catch looted, or the bobber gone) before right-click casts again, so the click that loots the fish doesn't cast straight away."] = "抛竿结束（拾取了渔获，或鱼漂消失）后多久右键点击才会再次抛竿，这样拾取鱼的那次点击不会立刻抛竿。"
L["Pause after a missed cast"] = "抛竿失败后的暂停"
L["When a cast doesn't land in fishable water (say, a pole left equipped away from water), right-click goes back to normal for this long before it casts again. Moving and then standing still for 1 sec ends it early: you're likely at a new spot to fish from. Off doesn't pause. (\"Skill not high enough\" always pauses it for 30 sec, moving or not.)"] = "当抛竿没有落入可钓鱼的水域时（例如远离水边时仍装备着鱼竿），右键点击会在这段时间内恢复正常，之后才会再次抛竿。移动后再站着不动1秒会提前结束暂停：你很可能到了新的钓鱼地点。关闭则不暂停。（“技能不够高”总是暂停30秒，无论是否移动。）"
L["Gamepad: a button casts too"] = "手柄：按键也可抛竿"
L["In gamepad mode, the button below casts Fishing whenever right-click would: in the fish camera with no bobber out, and (if ticked above) with a pole equipped, standing still. The rest of the time it does what it usually does. Each cast still comes from your own press."] = "在手柄模式中，只要右键点击会抛竿，下方的按键就会施放钓鱼：在钓鱼镜头中且没有鱼漂时，以及（如果上方已勾选）装备鱼竿并站着不动时。其他时候它照常工作。每次抛竿仍然来自你自己的按键。"
L["Left face button (Xbox X)"] = "左侧功能键（Xbox X）"
L["Top face button (Xbox Y)"] = "上方功能键（Xbox Y）"
L["Bottom face button (Xbox A)"] = "下方功能键（Xbox A）"
L["Right face button (Xbox B)"] = "右侧功能键（Xbox B）"
L["The gamepad button that casts Fishing."] = "施放钓鱼的手柄按键。"
L["Gamepad"] = "手柄"
L["The frames gamepad mode adds (Options, Controls, Gamepad): its action bars, the button hints and the reticle (the dot you aim with). As on the Game Frames page, each is hidden in CineMode unless ticked: Always shows it the whole time, the next three only while you fight or have something targeted, and the places while you're there. Rows also on the Game Frames page (the experience bars) follow this page in gamepad mode, and that one otherwise."] = "手柄模式（选项、控制、手柄）添加的框体：其动作条、按键提示和准星（用于瞄准的点）。与游戏框体页面一样，除非勾选，它们在CineMode中都会隐藏：“始终”一直显示，接下来三列仅在你战斗或选中目标时显示，各地点列则在你身处那里时显示。同样出现在游戏框体页面上的行（经验条）在手柄模式下按本页设置，其他情况按那个页面设置。"
L["On: CineMode fades the gamepad's bars, button hints and reticle as this page says. Off: it leaves them alone."] = "开启：CineMode按照本页设置淡出手柄的动作条、按键提示和准星。关闭：不做处理。"
L["Show the interact prompt (X)"] = "显示互动提示（X）"
L["The button prompt over things you can use or talk to (your bobber, an NPC) stays up in CineMode while the nameplates fade, so you can see what the gamepad can reach: a bobber showing it can be caught. Unticked, it fades with them."] = "在你可以使用或对话的对象（你的鱼漂、NPC）上方的按键提示，在CineMode中姓名板淡出时仍保持显示，让你看到手柄能互动的对象：显示提示的鱼漂表示可以收竿。取消勾选时，它会随姓名板一起淡出。"
L["Show the action bars when you press a button"] = "按下按键时显示动作条"
L["Gamepad mode's mouseover: pressing any gamepad button brings the action bars up, and they fade out again your \"stays after mouseover\" time later (Hover groups page). Each press starts that time again. Choose the buttons in the list below. Presses that make you jump don't count (whichever button jumps), nor presses while you fish (the fish camera on, a cast going, or looting)."] = "手柄模式的“鼠标悬停”：按下任意手柄按键会显示动作条，并在你的“悬停后保持”时间（鼠标悬停分组页面）后再次淡出。每次按键都会重新计时。在下方列表中选择按键。让你跳跃的按键不计算在内（无论哪个按键是跳跃），钓鱼时的按键也不算（钓鱼镜头开启、正在抛竿或正在拾取）。"
L["Buttons that show them"] = "显示动作条的按键"
L["Click to show or hide the list of buttons: untick one and pressing it doesn't bring the action bars up."] = "点击显示或隐藏按键列表：取消勾选某个按键后，按下它不会显示动作条。"
L["Action bar fading"] = "动作条淡出"
L["Stay after a press"] = "按键后保持"
L["How long the action bars stay after your last button press, counting their fade out."] = "最后一次按键后动作条保持显示的时间，包括淡出时间。"
L["How long the gamepad action bars take to fade in: for button presses, fights and targets alike. The rest of the UI uses the fade times on the CineMode page."] = "手柄动作条淡入所需的时间：按键、战斗和选中目标时都一样。界面的其他部分使用CineMode页面上的过渡时间。"
L["How long the gamepad action bars take to fade out."] = "手柄动作条淡出所需的时间。"
L["Nameplates"] = "姓名板"
L["Friendly nameplates"] = "友方姓名板"
L["Enemy nameplates"] = "敌方姓名板"
L["Which nameplates and names stay up in CineMode: in groups, in fights and in each kind of place."] = "哪些姓名板和名字在CineMode中保持显示：组队时、战斗中以及各类地点。"
L["On: CineMode fades nameplates and names as this page says. Off: it leaves them alone, and the game's own options decide, in CineMode and out."] = "开启：CineMode按照本页设置淡出姓名板和名字。关闭：不做处理，无论是否处于CineMode都由游戏自身的选项决定。"
L["Show in fights, and for the Calm Timer after."] = "战斗中显示，并在战斗后的“平静计时”内保持显示。"
L["Show in fights while you're PvP flagged, and for the Calm Timer after."] = "处于PvP状态时在战斗中显示，并在战斗后的“平静计时”内保持显示。"
L["Always show while you're in a party or raid."] = "在小队或团队中时始终显示。"
L["Blizzard's Always Show Nameplates is off, so nameplates only show in combat."] = "暴雪的“总是显示姓名板”已关闭，因此姓名板只在战斗中显示。"
L["Target Nameplate"] = "目标姓名板"
L["Enemy Player"] = "敌对玩家"
L["Enemy NPC"] = "敌对NPC"
L["Neutral Player"] = "中立玩家"
L["Neutral NPC"] = "中立NPC"
L["Friendly Player"] = "友方玩家"
L["Friendly NPC"] = "友方NPC"
L["Your pet"] = "你的宠物"
L["Group members"] = "队伍成员"
L[" Your target's nameplate while it's a player you can attack, whatever the Nameplates grid says."] = " 目标为你可攻击的玩家时显示目标的姓名板，无论姓名板表格如何设置。"
L[" Your target's nameplate while it's a hostile NPC, whatever the Nameplates grid says."] = " 目标为敌对NPC时显示目标的姓名板，无论姓名板表格如何设置。"
L[" Your target's nameplate while it's the other faction's player but you can't attack them, whatever the Nameplates grid says."] = " 目标为你无法攻击的另一阵营玩家时显示目标的姓名板，无论姓名板表格如何设置。"
L[" Your target's nameplate while it's a neutral NPC, whatever the Nameplates grid says."] = " 目标为中立NPC时显示目标的姓名板，无论姓名板表格如何设置。"
L[" Your target's nameplate while it's a friendly or dead player, whatever the Nameplates grid says."] = " 目标为友方或已死亡的玩家时显示目标的姓名板，无论姓名板表格如何设置。"
L[" Your target's nameplate while it's a friendly or dead NPC, whatever the Nameplates grid says."] = " 目标为友方或已死亡的NPC时显示目标的姓名板，无论姓名板表格如何设置。"
L[" Your pet's nameplate, whatever the Minions rows say, grouped or not."] = " 你宠物的姓名板，无论仆从行如何设置，是否在队伍中都一样。"
L[" Your party or raid members' nameplates, whatever Friendly players says. Not in dungeons and raids: there, Friendly plates in dungeons and raids decides."] = " 你的小队或团队成员的姓名板，不受“友方玩家”影响。地下城和团队副本中除外：那里由“地下城和团队副本中的友方姓名板”决定。"
L["Friendly plates in dungeons and raids"] = "地下城和团队副本中的友方姓名板"
L["In dungeons and raids the game won't let addons fade friendly nameplates, so each kind below is either all on or all off there, in CineMode. The grids' friendly rows (your target's included) have no Instances box: these take its place.\n\nWith a friendly target: on while you have one of that kind targeted, out of fights. Every plate of that kind shows then, not just your target's.\n\nThe game won't switch nameplates on or off during a fight: they stay as the fight found them.\n\nFriendly players' setting covers their pets too, so with pets shown, friendly players' plates show as well."] = "在地下城和团队副本中，游戏不允许插件淡化友方姓名板，因此在 CineMode 中，下面每一类在那里只能全部显示或全部隐藏。表格中的友方行（包括你目标的行）没有“副本”勾选框：由这里代替。\n\n有友方目标时：在战斗外，当你选中该类目标时显示。此时该类的所有姓名板都会显示，而不仅是你目标的。\n\n战斗中游戏不会开关姓名板：它们保持战斗开始时的状态。\n\n友方玩家的设置也涵盖他们的宠物，因此显示宠物时，友方玩家的姓名板也会显示。"
L["Pets and minions"] = "宠物和仆从"
L["Hidden"] = "隐藏"
L["Shown"] = "显示"
L["With a friendly target"] = "有友方目标时"
L[" Your party or raid members' pets, whatever the Minions rows say."] = " 你的小队或团队成员的宠物，无论仆从行如何设置。"
L["Show while PvP flagged, outside battlegrounds and arenas."] = "在战场和竞技场之外处于PvP状态时显示。"
L["Show in battlegrounds and arenas."] = "在战场和竞技场中显示。"
L["Show everywhere else, cities and inns included."] = "在其他所有地方显示，包括城市和旅店。"
L["Show everywhere, in fights and out. The rest of the row keeps its ticks for when you untick this."] = "在任何地方显示，战斗中和战斗外都是。取消勾选此项时，该行其余的勾选仍会保留。"
L["Show in dungeons, scenarios and raids."] = "在地下城、场景战役和团队副本中显示。"
L["In PvP combat"] = "PvP战斗中"
L["Hostile NPCs"] = "敌对NPC"
L["Neutral NPCs"] = "中立NPC"
L["Minor"] = "次要单位"
L["Friendly NPCs"] = "友方NPC"
L[" Also turns these nameplates on in the game's options."] = "同时会在游戏选项中开启这些姓名板。"
L[" Ticking any box turns these names on in the game's options. Ticking none turns them off."] = "勾选任意复选框会在游戏选项中开启这些名字。一个都不勾选则关闭它们。"
L[" Beyond nameplate range (the game's nameplateMaxDistance setting: 60 yards on retail) the game draws raid markers over units itself, as it does over your own head, and addons can't hide them."] = "超出姓名板距离（游戏的 nameplateMaxDistance 设置：正式服为60码）时，游戏会自己在单位头顶绘制团队标记，就像在你自己头顶一样，插件无法隐藏。"
L[" Ticked, raid markers (skull, moon...) stay over their units in CineMode as the rest of their nameplates fades, or shows just their names, so your group can still see what's marked. Unticked, they fade with the plates (the Plate parts row decides them on the plates that are up)."] = "勾选后，在CineMode中，当姓名板的其余部分淡出或只显示名字时，团队标记（骷髅、月亮……）仍留在单位头顶，让你的队伍仍能看到标记了什么。不勾选则随姓名板一起淡出（在显示的姓名板上由姓名板部件中的那一行决定）。"
L[" In CineMode, away from dungeons and raids, the name shows on the unit's nameplate instead, with the rest of the plate hidden."] = "在CineMode中，地下城和团队副本之外，名字改为显示在单位的姓名板上，姓名板的其余部分隐藏。"
L[" The game only allows this to be set as the fight starts."] = "游戏只允许在战斗开始时设置此项。"
L["The chat window fades with the rest of the UI in CineMode. Mousing over it or typing always shows it."] = "在CineMode中，聊天窗口会随界面其他部分一起淡出。鼠标悬停或输入文字时总会显示它。"
L["On: CineMode fades the chat windows and tabs as this page says. Off: it leaves them alone."] = "开启：CineMode按照本页设置淡出聊天窗口和标签。关闭：不做处理。"
L["Chat window"] = "聊天窗口"
L["Show chat when a message arrives"] = "收到消息时显示聊天"
L["While the UI is faded, a new message briefly shows just the chat window it arrived in, with its tabs. Choose which messages below."] = "界面淡出时，新消息会短暂显示它所在的聊天窗口及其标签。在下方选择哪些消息。"
L["Show chat for"] = "聊天显示时长"
L["How long chat stays up after a message arrives or after you finish typing."] = "收到消息或你输入完文字后，聊天保持显示的时间。"
L["Keep chat up until whispers are read"] = "保持显示聊天直到密语已读"
L["When a whisper arrives in its own tab, the whole chat window stays up in CineMode while that tab flashes, until you click it. Whispers that land in the tab you're looking at don't flash, so they just show as above."] = "当密语出现在它自己的标签中时，在该标签闪烁期间，整个聊天窗口在CineMode中保持显示，直到你点击它。出现在你正在查看的标签中的密语不会闪烁，因此只按上述方式显示。"
L["Hide your messages"] = "隐藏你的消息"
L["Your own messages don't show chat: your emotes (a /bow, or sitting or kneeling at the campfire), and what you say in /say, party, guild and so on. Other people's still do."] = "你自己的消息不会显示聊天：你的表情（/bow，或在营火旁坐下或跪下），以及你在 /say、小队、公会等频道说的话。其他人的消息仍会显示。"
L["Hide speech you can see as a bubble"] = "隐藏能在气泡中看到的话"
L["Says and yells (people's and NPCs') don't show chat when their chat bubble shows on your screen: you can read it there. Ones from out of view, or where bubbles are off, still do."] = "说话和大喊（玩家和NPC）的气泡出现在你的屏幕上时不会显示聊天：你可以在那里看到。视野外的，或气泡已关闭时，仍会显示。"
L["%s is under attack!"] = "%s正遭到攻击！"
L["Show chat for these messages"] = "以下消息显示聊天"
L["Game messages"] = "游戏消息"
L["Capital cities. "] = "主城。"
L["Show chat for these channels"] = "以下频道显示聊天"
L["Channels you've joined, like General or Trade. The list updates each time you open this page."] = "你已加入的频道，例如综合或交易。每次打开本页面时列表都会更新。"
L["No channels joined."] = "未加入任何频道。"
L["Takes this frame off the list. A frame you added stops fading; one you kept up fades again if it's one the addon fades by itself."] = "将此框体从列表中移除。你添加的框体会停止淡出；你设为保持显示的框体，如果插件本身就会淡出它，则会再次淡出。"
L["Show this frame the whole time in CineMode (Cinematic leaves it alone). Unticked, it's hidden, except as the other columns say."] = "在CineMode中一直显示此框体（Cinematic不做处理）。取消勾选时将其隐藏，其他列另有设置的除外。"
L["picked"] = "已选"
L["When the minimap (and on retail the quest waypoint) stays up in CineMode. Hovering the minimap always shows it. To keep it up all the time, or in fights, see the Game Frames page."] = "小地图（在正式服中还有任务路径点）何时在CineMode中保持显示。鼠标悬停在小地图上时总会显示它。若要一直显示或在战斗中显示，请查看游戏框体页面。"
L["On: CineMode fades and shrinks the minimap as this page and its Game Frames row say. Off: it leaves it alone."] = "开启：CineMode按照本页及游戏框体页面中对应行的设置淡出并缩小小地图。关闭：不做处理。"
L["Always show the quest waypoint"] = "始终显示任务路径点"
L["Keeps the marker showing where your tracked quest or map pin is, with its distance, visible in CineMode. Off, it fades with the rest of the UI."] = "在CineMode中保持显示指示你追踪的任务或地图标记位置及距离的标记。关闭时，它会随界面其他部分一起淡出。"
L["Keep minimap open while tracking"] = "追踪时保持小地图显示"
L["While you're tracking one of the kinds ticked below, the minimap stays up during CineMode. Also on the minimap button's menu."] = "当你追踪下方勾选的某一类目标时，小地图在CineMode期间保持显示。小地图按钮的菜单中也有此选项。"
L["Reveal when a group member pings it"] = "队伍成员标记时显示"
L["You or someone in your party or raid pinging the minimap shows it as if you'd hovered it, so you can see where, with the rest of the Hover groups that have Minimap ping ticked, for as long as the slider under it says. Ore, herbs and treasure pinged by Ping where it is don't count."] = "你或你的小队或团队中有人在小地图上标记时，小地图会像被鼠标悬停一样显示，让你看到标记的位置，同时显示勾选了“小地图标记”的其他鼠标悬停分组，持续时间由下方的滑块决定。“在位置发信号”标记的矿石、草药和宝藏不计算在内。"
L["Show for"] = "显示时长"
L["How long the minimap stays up after someone pings it, before it fades."] = "有人在小地图上标记后，小地图在淡出前保持显示的时间。"
L["Keep minimap open indoors"] = "在室内保持小地图显示"
L["Inside buildings, caves and cities like Ironforge, the minimap stays up during CineMode. The game stops updating the indoor map while the minimap is hidden, so after walking around it can come back blank or out of date for a moment. Off, it's redrawn as it comes back."] = "在建筑物、洞穴以及铁炉堡这样的城市中，小地图在CineMode期间保持显示。小地图隐藏时游戏会停止更新室内地图，因此走动后它重新出现时可能会短暂地显示空白或过时的内容。关闭时，它会在重新出现时重绘。"
L["While this tracking is active, the minimap stays up during cinematic mode so you can spot nodes or creatures."] = "此追踪启用时，小地图在电影模式期间保持显示，以便你发现资源点或生物。"
L["Herbs (Find Herbs)"] = "草药（寻找草药）"
L["Minerals (Find Minerals)"] = "矿物（寻找矿物）"
L["Reveal"] = "显示"
L["Pings"] = "信号"
L["Keep open"] = "保持打开"
L["Nearby ore, herbs and treasure"] = "附近的矿石、草药和宝藏"
L["Ping where it is"] = "在位置发信号"
L["When a vein, herb or chest shows up on the minimap, it's pinged there, the same ping as clicking the minimap: in a group, everyone sees it."] = "矿脉、草药或箱子出现在小地图上时，会在那里发出信号，和点击小地图一样：在队伍中所有人都能看到。"
L["Quest turn-ins"] = "交任务"
L["Other icons"] = "其他图标"
L["Tracking creatures or fish"] = "追踪生物或鱼"
L["Tracking herbs, minerals or treasure"] = "追踪草药、矿物或宝藏"
L["Cinematic looks every second or two by pointing at the minimap the way your mouse would (not in combat), and the minimap fades again a few seconds after it's gone. While any of these is ticked, the faded minimap stays in its place, invisible, instead of being shrunk away."] = "Cinematic 每一两秒像鼠标一样指向小地图查看（战斗中不会），消失几秒后小地图会再次淡出。只要勾选了其中任意一项，淡出的小地图会留在原位隐形，而不是被缩小。"
L["With Find Minerals, Find Herbs or Find Treasure on, the minimap comes up while a vein, herb or chest shows on it."] = "开启寻找矿物、寻找草药或寻找财宝时，小地图上出现矿脉、草药或箱子时会显示小地图。"
L["The minimap comes up while a quest of yours that's done shows on it, where you hand it in."] = "小地图上出现你已完成任务的交付地点时会显示小地图。"
L["Quest areas"] = "任务区域"
L["The minimap comes up while the area of a quest of yours that isn't done shows on it, the shaded part where its objectives are."] = "小地图上出现你未完成任务的区域（任务目标所在的阴影部分）时会显示小地图。"
L["The minimap comes up while anything else with a name shows on it: quest givers with a quest for you, flight masters and innkeepers you track and the like. Your group and pets don't count."] = "小地图上出现其他有名字的东西时会显示小地图：有任务给你的NPC、你追踪的飞行管理员和旅店老板等。队伍和宠物不算。"
L["While hunter, druid or warlock creature tracking, or Find Fish, is on, the minimap stays up during CineMode."] = "开启猎人、德鲁伊或术士的生物追踪或寻找鱼类时，小地图在 CineMode 中保持显示。"
L["While Find Herbs, Find Minerals or Find Treasure is on, the minimap stays up during CineMode, except in the places below."] = "开启寻找草药、寻找矿物或寻找财宝时，小地图在 CineMode 中保持显示，下面的地点除外。"
L["Treasure (Find Treasure)"] = "宝藏（寻找财宝）"
L["Fish (Find Fish)"] = "鱼类（寻找鱼群）"
L["Creatures (hunter, druid, warlock)"] = "生物（猎人、德鲁伊、术士）"
L["Except in"] = "以下地点除外"
L["Battlegrounds and arenas (being flagged for PvP out in the world doesn't count). Alterac Valley's mines do have ore, so untick this if you mine there. "] = "战场和竞技场（在野外处于PvP状态不算）。奥特兰克山谷的矿洞里确实有矿石，如果你在那里采矿，请取消勾选此项。"
L["BGs"] = "战场"
L["Tracking doesn't keep the minimap up here. Hovering it still shows it."] = "在这里追踪不会让小地图保持显示。鼠标悬停仍会显示它。"
L["Hide in camera modes"] = "在镜头模式中隐藏"
L["When the quest tracker comes up in CineMode. Hovering it always shows it. To keep it up all the time, or in fights, see the Game Frames page."] = "任务追踪何时在CineMode中出现。鼠标悬停时总会显示它。若要一直显示或在战斗中显示，请查看游戏框体页面。"
L["Reveal on new quest"] = "接受新任务时显示"
L["Accepting a quest shows the quest tracker as if you'd hovered it (with the rest of the Hover groups that have Quest progress ticked): it goes after \"Stays after mouseover\" (Hover groups page)."] = "接受任务时，任务追踪会像被鼠标悬停一样显示（同时显示勾选了“任务进度”的其他鼠标悬停分组）：在“悬停后保持”（鼠标悬停分组页面）时间后消失。"
L["On: CineMode fades the quest tracker (and the quest timer and waypoint) as this page and its Game Frames row say. Off: it leaves them alone."] = "开启：CineMode按照本页及游戏框体页面中对应行的设置淡出任务追踪（以及任务计时器和路径点）。关闭：不做处理。"
L["Reveal on receiving quest objective"] = "完成任务目标时显示"
L["Keep up for the Calm Timer"] = "在平静计时内保持显示"
L["The quest tracker stays up for the Calm Timer (CineMode page) instead of the mouseover time, if that's longer."] = "任务追踪会在“平静计时”（CineMode页面）内保持显示，而不是鼠标悬停时间（取较长者）。"
L["Progress on a quest's objectives (a kill or item counted towards it) shows the quest tracker the same way."] = "任务目标有进展时（击杀或获得计入任务的物品），以同样的方式显示任务追踪。"
L["Show just that quest"] = "只显示该任务"
L["When accepting a quest or progress on one brings the quest tracker up, just that quest shows (and any others accepted or moved on while it's up); the rest of the tracker, headers and all, stays faded. Scenario progress shows just the scenario. Hovering it shows it all."] = "接受任务或任务有进展而显示任务追踪器时，只显示该任务（以及显示期间接受或有进展的其他任务）；追踪器的其余部分（包括标题）保持隐藏。场景有进展时只显示该场景。鼠标悬停时显示全部。"
L["Stay up for the Calm Timer after a fight"] = "战斗后在平静计时内保持显示"
L["With the quest tracker ticked In combat (Game Frames page), it stays up after a fight until the Calm Timer (CineMode page) has run out, then fades. Off: it fades as soon as the fight ends."] = "当任务追踪勾选了“战斗中”（游戏框体页面）时，它会在战斗结束后保持显示，直到“平静计时”（CineMode页面）结束，然后淡出。关闭：战斗一结束就淡出。"
L["Show the quest timer while one is running"] = "任务计时进行中时显示任务计时器"
L["Keeps the quest timer box up in CineMode, and in fights, while a timed quest counts down. Just the timer: the quest tracker stays faded."] = "限时任务倒计时期间，在CineMode和战斗中保持显示任务计时器框。只显示计时器：任务追踪仍保持淡出。"
L["Which of the game's swing timer bars show, in CineMode and out. When they come up in CineMode is the Swing timer row on the Game Frames page."] = "游戏的哪些攻击计时条会显示，无论是否处于CineMode。它们在CineMode中何时出现由游戏框体页面上的“攻击计时条”行决定。"
L["On: CineMode fades the swing timer as this page and its Game Frames row say. Off: it leaves it alone, and the game shows every bar as usual, in CineMode and out."] = "开启：CineMode按照本页及游戏框体页面中对应行的设置淡出攻击计时条。关闭：不做处理，无论是否处于CineMode，游戏都照常显示所有计时条。"
L["Only show the weapons you're using"] = "只显示你正在使用的武器"
L["The main hand (and off-hand) bars show while you auto-attack, the ranged bar while you shoot. A hunter's main hand bar comes up when they melee, a warrior's ranged bar when they shoot, and each fades out a while after (the slider below)."] = "自动攻击时显示主手（和副手）计时条，射击时显示远程计时条。猎人进行近战时会出现主手计时条，战士射击时会出现远程计时条，各自在一段时间后淡出（见下方滑块）。"
L["Fade out after the bar is done for"] = "计时条结束多久后淡出"
L["Once you stop swinging or shooting and the bar has run down to 0, it stays this long before fading out."] = "你停止攻击或射击且计时条归零后，它会保持这段时间再淡出。"
L["Hide the off-hand bar"] = "隐藏副手计时条"
L["Never show the off-hand swing timer, dual wielding or not."] = "从不显示副手攻击计时条，无论是否双持武器。"
L["Ranged bar on top for %s"] = "%s的远程计时条置顶"
L["The main hand and ranged bars trade places, so the ranged bar is where the main hand's was. Set for each class on its own (ticked for hunters, mages, priests and warlocks to start with), so one profile suits all your characters."] = "主手和远程计时条互换位置，让远程计时条位于原来主手计时条的位置。每个职业单独设置（猎人、法师、牧师和术士默认勾选），这样一个配置文件就能适用于你的所有角色。"
L["When the Cooldown Manager comes up in CineMode (Enhanced Cooldown Manager's bars too). Hovering it always shows it. To keep it up all the time, or in fights, see the Game Frames page; what comes up with it is on the Hover groups page."] = "冷却管理器（以及Enhanced Cooldown Manager的计时条）何时在CineMode中出现。鼠标悬停时总会显示它。若要一直显示或在战斗中显示，请查看游戏框体页面；随它一起出现的内容在鼠标悬停分组页面。"
L["On: CineMode fades the Cooldown Manager as this page and its Game Frames row say. Off: it leaves it alone, and the game's own options decide, in CineMode and out."] = "开启：CineMode按照本页及游戏框体页面中对应行的设置淡出冷却管理器。关闭：不做处理，无论是否处于CineMode都由游戏自身的选项决定。"
L["Stay up while a cooldown is recharging"] = "冷却恢复中时保持显示"
L["Keeps the Cooldown Manager up until every cooldown in it is ready again, then it fades. Not the global cooldown, nor its buff bars. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "保持显示冷却管理器，直到其中所有冷却都再次就绪，然后淡出。不包括公共冷却及其增益效果条。（它会让勾选了“冷却恢复中”的鼠标悬停分组出现：默认是“冷却”分组。）"
L["Only within the Calm Timer after a fight (CineMode page): after that it fades even with a long cooldown still going, and cooldowns used out of fights don't bring it up."] = "仅限战斗后的“平静计时”（CineMode页面）内：之后即使仍有较长的冷却在进行，它也会淡出，并且在战斗之外使用的冷却不会让它出现。"
L["Only when ready in combat"] = "仅在战斗中就绪时"
L["Tick a spell to show its icon only in fights, and only once it's nearly ready: out of fights, and while it recharges, it fades out, in CineMode or not. It comes back once it's ready, or with Show early ticked the seconds set beside it before (left empty: %d%% of its cooldown). Its place in the bar stays, so it sits best at the end of one. In fights the game may not say how long is left, so then it goes by when you last cast it."] = "勾选一个法术，使其图标只在战斗中且即将就绪时显示：在战斗之外以及冷却期间，无论是否处于CineMode，它都会淡出。它会在就绪时重新出现，或者勾选“提前显示”后，在就绪前按旁边设置的秒数提前出现（留空：其冷却时间的%d%%）。它在条中的位置保持不变，所以最好放在一条的末尾。战斗中游戏可能不会告知剩余时间，此时会按你上次施放它的时间来计算。"
L["Spell"] = "法术"
L["Show early"] = "提前显示"
L["No spells in the Cooldown Manager's spell bars right now."] = "冷却管理器的法术条中目前没有法术。"
L["Out of fights, and while it recharges, this spell's icon fades out of the Cooldown Manager."] = "在战斗之外以及冷却期间，此法术的图标会从冷却管理器中淡出。"
L["Bring the icon back a little before it's ready, by the seconds beside it. Unticked, it comes back once it's ready."] = "按旁边的秒数在就绪前稍早让图标重新出现。取消勾选时，就绪后才会重新出现。"
L["How many seconds before it's ready the icon comes back. Leave it empty for %d%% of its cooldown."] = "图标在就绪前多少秒重新出现。留空则为其冷却时间的%d%%。"
L["sec (empty: %d)"] = "秒（留空：%d）"
L["sec (empty: %d%%)"] = "秒（留空：%d%%）"
L["Spell %d"] = "法术%d"
L[" |cff808080(not in it now)|r"] = " |cff808080（目前不在其中）|r"
L["On: CineMode hides tooltips as this page says. Off: every tooltip shows as normal."] = "开启：CineMode按照本页设置隐藏鼠标提示。关闭：所有鼠标提示照常显示。"
L["Only in CineMode. Hold your Show hidden tooltips key (set it on the Keybinds page) to see a hidden one anyway."] = "仅在CineMode中。按住你的“显示隐藏的鼠标提示”键（在按键绑定页面设置）可以照样查看隐藏的提示。"
L["Players and NPCs you can attack (neutral mobs too), and their pets, minions and totems."] = "你可以攻击的玩家和NPC（包括中立怪物），以及他们的宠物、仆从和图腾。"
L["Herbs, ore and creatures you can skin."] = "草药、矿石和可剥皮的生物。"
L["Tooltips listing one of your quest objectives (like \"5/7 Thistle Boar slain\")."] = "列出你某个任务目标的鼠标提示（如\"已杀死蓟皮野猪 5/7\"）。"
L["Mouse still"] = "鼠标静止"
L["Hide tooltips"] = "隐藏鼠标提示"
L["In CineMode. Ticked, those tooltips hide. Always: in and out of fights. In combat: just in fights. Something that's more than one kind (a quest mob is an enemy too) hides only with each of its kinds ticked."] = "在CineMode中。勾选后，这些鼠标提示会隐藏。总是：战斗内外都隐藏。战斗中：仅在战斗时。同时属于多种类型的（任务怪也是敌人），只有其所有类型都勾选时才隐藏。"
L["Hidden all the time."] = "一直隐藏。"
L["Hidden in fights only."] = "仅在战斗时隐藏。"
L["Objects in the world, and the UI's tooltips: action bars, buffs and debuffs, bags, menus and the rest."] = "世界中的物体，以及界面的鼠标提示：动作条、增益和减益效果、背包、菜单等。"
L["Every tooltip in the world and on unit frames is hidden while this camera mode is running."] = "此镜头模式运行期间，隐藏世界中和单位框体上的所有鼠标提示。"
L["Tooltip look"] = "鼠标提示外观"
L["Ticked, that part of the tooltip shows: On first hover, as soon as it appears; After, once you've hovered as long as set above, until you mouse over something else. In and out of CineMode."] = "勾选后，鼠标提示的该部分会显示：首次悬停——一出现就显示；之后——悬停达到上面设定的时间后显示，直到你把鼠标移到别的东西上。CineMode内外均如此。"
L["Where the game's tooltips (things in the world, unit frames, action bars, bags) show: in their default position (the bottom-right corner, or wherever you've moved it), or by the mouse cursor, following it (or just in fights)."] = "游戏的鼠标提示（世界中的事物、单位框体、动作条、背包）显示在哪里：默认位置（右下角，或你移动到的地方），或鼠标指针旁并跟随它（或仅在战斗时）。"
L["Default position"] = "默认位置"
L["At the mouse cursor in combat"] = "战斗中在鼠标指针旁"
L["Fade in/out"] = "淡入/淡出"
L["How long tooltips take to fade in as they show, and to fade out when the mouse has been still too long (Mouse still, below). Off: no fading."] = "鼠标提示显示时淡入的用时，以及鼠标静止太久时淡出的用时（下面的鼠标静止）。关闭：不淡入淡出。"
L["After hovering for"] = "悬停时间"
L["How long you hover over something before the After column's parts take over, until you mouse over something else. Off: tooltips show as normal, every part of them."] = "悬停多久后改用\"之后\"列的部分，直到你把鼠标移到别的东西上。关闭：鼠标提示照常完整显示。"
L["On first hover"] = "首次悬停"
L["After %d sec"] = "%d秒后"
L["After (off)"] = "之后（关闭）"
L["Shown as soon as the tooltip appears."] = "鼠标提示一出现就显示。"
L["Shown once you've hovered as long as set above."] = "悬停达到上面设定的时间后显示。"
L["At the mouse cursor"] = "在鼠标指针旁"
L["Health bar"] = "生命条"
L["The health bar under the tooltips of players, NPCs and mobs."] = "玩家、NPC和怪物鼠标提示下方的生命条。"
L["Works with this page switched off too."] = "即使此页面关闭也有效。"
L["Background and border"] = "背景和边框"
L["The box around the tooltip. Unticked, just the text shows."] = "鼠标提示周围的边框。不勾选时只显示文字。"
L["Guild and title (<...>)"] = "公会和头衔 (<...>)"
L["A player's <Guild> line, or an NPC's <Innkeeper>-style title."] = "玩家的<公会>行，或NPC的<旅店老板>之类的头衔。"
L["The level line (for players, with their race and class)."] = "等级行（玩家的还包括种族和职业）。"
L["Level"] = "等级"
L["Spec and class"] = "专精和职业"
L["A player's spec and class line (\"Fury Warrior\")."] = "玩家的专精和职业行（\"狂怒战士\"）。"
L["Creature type"] = "生物类型"
L["The kind of creature: Elemental, Beast, Humanoid and so on."] = "生物的种类：元素生物、野兽、人型生物等。"
L["Faction and PvP"] = "阵营和PvP"
L["The Horde or Alliance line and the PvP line."] = "部落或联盟行，以及PvP行。"
L["Reputation faction"] = "声望阵营"
L["The faction an NPC belongs to, whose reputation you earn (\"Hara'ti\")."] = "NPC所属的声望阵营，你可以获得其声望（\"Hara'ti\"）。"
L["Threat"] = "仇恨"
L["How much of the mob's threat you have (\"100% Threat\")."] = "你占该怪物仇恨的多少（\"100%仇恨\"）。"
L["Quest lines"] = "任务行"
L["The names of your quests the unit is for, and their objectives (\"5/7 Thistle Boar slain\")."] = "该单位相关的你的任务名称及其目标（\"5/7 蓟皮野猪已杀死\"）。"
L["Quest lines on objects"] = "物体上的任务行"
L["The same on things in the world you use or pick up for a quest (\"0/1 Palehill Runestone\")."] = "对你为任务使用或拾取的世界中的物体同样适用（\"0/1 Palehill符文石\"）。"
L["On flights"] = "飞行中"
L["AFK camera (standing still or AFK)"] = "暂离镜头（站着不动或暂离）"
L["Cozy (campfire, sitting, emotes)"] = "温馨（篝火、坐下、表情）"
L["Tele (Hearthstone, teleports)"] = "传送（炉石、传送法术）"
L["Vista (/stare)"] = "远景（/stare）"
L["Fish (fishing)"] = "钓鱼（钓鱼时）"
L["RP walking"] = "RP漫步"
L["Auto-running"] = "自动奔跑"
L["Quest camera (talking to quest givers)"] = "任务镜头（与任务NPC对话）"
L["Enemies"] = "敌人"
L["Friendlies"] = "友方"
L["Gatherables (herbs, ore, skinnable)"] = "可采集物（草药、矿石、可剥皮）"
L["Quest objectives"] = "任务目标"
L["Players and NPCs you can't attack, and their pets, minions and totems."] = "你不能攻击的玩家和NPC，以及他们的宠物、仆从和图腾。"
L["Everything else"] = "其他所有"
L["Advanced Frames"] = "高级框体"
L["On: CineMode fades the supported addons' frames, and frames you added, as this page says. Off: it leaves them all alone."] = "开启：CineMode按照本页设置淡出受支持插件的框体以及你添加的框体。关闭：全部不做处理。"
L["Supported addons"] = "受支持的插件"
L["These addons' frames are hidden in CineMode unless ticked, like the game's frames on the Game Frames page. Tick Always to leave an addon's frames alone (shown the whole time); the next three show them only while you fight or have something targeted, and the places while you're there."] = "除非勾选，这些插件的框体在CineMode中都会隐藏，与游戏框体页面上的游戏框体一样。勾选“始终”可让某个插件的框体不受影响（一直显示）；接下来三列仅在你战斗或选中目标时显示它们，各地点列则在你身处那里时显示。"
L["Show %s the whole time in CineMode (Cinematic leaves them alone). Unticked, they're hidden, except as the other columns say.%s"] = "在CineMode中一直显示%s（Cinematic不做处理）。取消勾选时将其隐藏，其他列另有设置的除外。%s"
L["Click to show or hide its parts."] = "点击显示或隐藏其组成部分。"
L["Loaded"] = "已加载"
L["Installed, not loaded"] = "已安装，未加载"
L["Not installed"] = "未安装"
L["Also supported, when installed: %s"] = "安装后同样支持：%s"
L["Custom frames"] = "自定义框体"
L["To fade something else, hover over it and type |cffffd100/cine add|r, or type |cffffd100/cine add|r and its frame name. To pick up several, use the button below (or |cffffd100/cine add mode|r) and hover over each one. The columns work as for the supported addons above; the X takes a frame off the list."] = "要淡出其他东西，将鼠标悬停在它上面并输入 |cffffd100/cine add|r，或输入 |cffffd100/cine add|r 加上其框体名称。要一次选取多个，请使用下方的按钮（或 |cffffd100/cine add mode|r）并依次悬停在每一个上面。各列的作用与上方受支持的插件相同；点击X可将框体从列表中移除。"
L["Hover over the frames you want to fade (move this window out of the way, or close it), then click Stop or type /cine add mode again to fade them all. The game's own frames and ones already faded are left out. /cine add cancel drops them."] = "将鼠标悬停在你想要淡出的框体上（把这个窗口移开或关闭），然后点击“停止”或再次输入 /cine add mode 将它们全部淡出。游戏自带的框体和已淡出的框体不包括在内。/cine add cancel 可放弃。"
L["Stop"] = "停止"
L["Pick frames by hovering"] = "悬停选取框体"
L["Hide the UI"] = "隐藏界面"
L["Like Blizzard's Alt+Z: hides the whole UI, but keeps the tint, letterbox and time-of-day title. Press again (or Blizzard's key) to bring it back."] = "类似暴雪的Alt+Z：隐藏整个界面，但保留色调、宽银幕黑边和时段标题。再按一次（或按暴雪的按键）即可恢复。"
L["Take a CineShot"] = "拍摄 CineShot"
L["Hides the UI but keeps the tint and letterbox, takes a screenshot, then brings the UI straight back. Not in a fight."] = "隐藏界面但保留色调和宽银幕黑边，截一张图，然后立刻恢复界面。战斗中不可用。"
L["Turns CineMode on or off, like /cine."] = "开启或关闭CineMode，与 /cine 相同。"
L["Starts the AFK camera now, without waiting out its delay. Press again, move or jump to stop it."] = "立即启动暂离镜头，无需等待其延迟。再按一次、移动或跳跃可停止。"
L["Starts the cozy camera now, as if you'd sat down. Press again, move or jump to stop it."] = "立即启动温馨镜头，就像你坐下了一样。再按一次、移动或跳跃可停止。"
L["Starts the vista camera now, as if you'd done a /stare. Press again, move or jump to stop it."] = "立即启动远景镜头，就像你做了 /stare 一样。再按一次、移动或跳跃可停止。"
L["Starts the fish camera now, without casting. Press again, move or jump to stop it."] = "立即启动钓鱼镜头，无需抛竿。再按一次、移动或跳跃可停止。"
L["Starts the tele camera now, as if you were casting your Hearthstone. Press again, move or jump to stop it."] = "立即启动传送镜头，就像你正在使用炉石一样。再按一次、移动或跳跃可停止。"
L["Death camera test"] = "死亡镜头测试"
L["Camera wheel"] = "镜头轮盘"
L["Hold to bring up a wheel of the cameras below, an icon for each: point at one and let go to start it. Tap it instead and the wheel stays up for you to click one. Picking the camera that's running stops it."] = "按住以打开下列镜头的轮盘，每个镜头一个图标：指向其中一个并松开即可启动。只轻按一下，轮盘会保持打开，供你点击选择。选择正在运行的镜头会将其停止。"
L["Menu wheel"] = "菜单轮盘"
L["Hold to bring up a wheel of the game's menu buttons (character, spellbook, quest log...), the ones on your menu bar: point at one and let go to open its window, even with the UI hidden. Tap it instead and the wheel stays up for you to click one."] = "按住以呼出由游戏菜单按钮（角色、法术书、任务日志……）组成的轮盘，即你菜单栏上的那些按钮：指向一个并松开即可打开它的窗口，即使界面已隐藏。如果只是轻按，轮盘会保持打开，供你点击选择。"
-- CameraWheel.lua
L["running: pick it to stop it"] = "运行中：再次选择以停止"
L["can't start now"] = "现在无法启动"
-- MenuWheel.lua
L["open: pick it to close it"] = "已打开：再次选择以关闭"
L["can't open now"] = "现在无法打开"
L["Pretends you're dead for 30 seconds so the death camera runs. Press again to stop. Like /cine deathtest."] = "假装你已死亡30秒，让死亡镜头运行。再按一次可停止。与 /cine deathtest 相同。"
L["Show hidden tooltips"] = "显示隐藏的鼠标提示"
L["Hold to see the tooltips the Tooltips page hides, in combat and in CineMode. Pressing it while you're on a unit or something in the world brings its tooltip up; anything else, hover it again with the key held."] = "按住可查看鼠标提示页面所隐藏的鼠标提示，在战斗中和CineMode中均有效。鼠标指向某个单位或世界中的物体时按下，会显示其鼠标提示；其他东西则需按住该键再次悬停。"
L["Turns the Tooltips page's \"CineMode Tooltips\" switch on or off."] = "开启或关闭鼠标提示页面上的“CineMode 鼠标提示”开关。"
L["Press a key"] = "请按下一个键"
L["|cff808080Not bound|r"] = "|cff808080未绑定|r"
L["keybinds can't be changed in combat"] = "战斗中无法更改按键绑定"
L["%s was bound to %s and now isn't"] = "%s原本绑定到%s，现已解除"
L["Click, then press a key (with Shift, Ctrl or Alt if you like). Right-click to clear. Escape cancels."] = "点击后按下一个键（可搭配Shift、Ctrl或Alt）。右键点击可清除。按Esc取消。"
L["Keybinds"] = "按键绑定"
L["Keys for Cinematic. These are the same bindings as under Key Bindings > AddOns, so setting them in either place works."] = "Cinematic的按键。它们与“按键设置 > 插件”中的绑定相同，因此在任一处设置都可以。"
L["Keys"] = "按键"
L["settings can't be opened in combat"] = "战斗中无法打开设置"
L["A profile needs a name."] = "配置文件需要一个名称。"
L["There's already a profile called %s."] = "已经有一个名为%s的配置文件。"
L["Name the new profile (it starts from your current settings):"] = "为新配置文件命名（它将以你当前的设置为基础）："
L["Rename the profile:"] = "重命名配置文件："
L["Describe the profile:"] = "描述配置文件："
L["Delete the profile %s?"] = "删除配置文件%s？"
L["Put the profile %s back to how it started? Every change you've made to it goes."] = "将配置文件%s恢复为初始状态？你对它做的所有更改都将丢失。"
L["Profiles"] = "配置文件"
L["A profile is a whole set of settings. Pick one to switch to it; changes you make go into the active profile and stay with it. The built-in ones keep your changes too, until you reset them. New profile starts one of your own from the settings you have now. Every character uses the same profile unless you tick the box below for one. Not part of a profile: the minimap button, frames you added or stopped fading, and the zone and time tint colors you picked."] = "配置文件是一整套设置。选择一个即可切换到它；你所做的更改会保存到当前配置文件中。内置配置文件也会保留你的更改，直到你重置它们。“新建配置文件”会以你现在的设置为基础创建一个你自己的配置文件。除非你为某个角色勾选下方的复选框，否则所有角色都使用同一个配置文件。不属于配置文件的内容：小地图按钮、你添加或停止淡出的框体，以及你选择的区域和时段色调颜色。"
L["Use a profile just for this character"] = "为此角色使用单独的配置文件"
L["Ticked: switching profiles changes only this character's, and it stays on it whatever your other characters use. Unticked: this character uses the same profile as the rest (switching back to it now if this one's differs)."] = "勾选：切换配置文件只会更改此角色的配置文件，无论你的其他角色使用什么，它都保持不变。取消勾选：此角色与其他角色使用同一个配置文件（如果当前不同，会立即切换回去）。"
L["Use a profile just for this character |cff808080(other characters use %s)|r"] = "为此角色使用单独的配置文件 |cff808080（其他角色使用%s）|r"
L["New profile"] = "新建配置文件"
L["A profile of your own, starting from your current settings. To copy another profile, switch to it first."] = "以你当前的设置为基础创建你自己的配置文件。若要复制其他配置文件，请先切换到它。"
L["Rename"] = "重命名"
L["Rename the active profile (your own ones only)."] = "重命名当前配置文件（仅限你自己的）。"
L["Description"] = "描述"
L["Write what the active profile is for, shown when you point at its icon (your own ones only)."] = "写下当前配置文件的用途，鼠标指向它的图标时显示（仅限你自己的）。"
L["Delete"] = "删除"
L["Delete the active profile (your own ones only), switching to %s."] = "删除当前配置文件（仅限你自己的），并切换到%s。"
L["Put the active built-in profile back to its own values (your own profiles keep your changes as you go)."] = "将当前内置配置文件恢复为其自身的值（你自己的配置文件会随时保存你的更改）。"
L["Your own profile. Pick it, then Description to say what it's for."] = "你自己的配置文件。选中它，然后点击“描述”说明它的用途。"
L["Mouseover groups"] = "鼠标悬停分组"
L["Mouseover Groups"] = "鼠标悬停分组"
L["UI Manager"] = "界面管理器"
L["Frames in the same group come up together when you mouse over any of them. A frame can be in more than one group; one in no group comes up on its own."] = "鼠标悬停在同一分组中的任一框体上时，该组框体会一起出现。一个框体可以属于多个分组；不属于任何分组的框体会单独出现。"
L["Pointing at a faded frame shows it, with the rest of its groups."] = "指向已淡出的框体时会显示它，以及其所在分组的其他框体。"
L["Stays after mouseover"] = "悬停后保持"
L["How long until a frame is gone after your mouse leaves it (and its groups), fade included. Events that bring a group up hold it this long too. In the camera modes the shorter default is used."] = "鼠标离开框体（及其分组）后，框体消失所需的时间，包括淡出时间。让分组出现的事件也会使其保持这么久。在镜头模式中使用较短的默认值。"
L["addon"] = "插件"
L["custom"] = "自定义"
L["not faded yet"] = "尚未淡出"
L["No frames match"] = "没有匹配的框体"
L["No events match"] = "没有匹配的事件"
L["in %s"] = "在%s中"
L["already here"] = "已在此处"
L["New group"] = "新建分组"
L["Group %d"] = "分组%d"
L["Take it out of this group."] = "将其移出此分组。"
L["The group's name: click to change it."] = "分组名称：点击进行更改。"
L["Delete group"] = "删除分组"
L["Its frames come up on their own again (or with their other groups)."] = "其中的框体会重新单独出现（或随它们的其他分组出现）。"
L["also in %s"] = "也在%s中"
L["No frames yet."] = "暂无框体。"
L["Add a frame: type to search..."] = "添加框体：输入以搜索……"
L["Also bring this group up for:"] = "以下情况也让此分组出现："
L["Add an event: type to search..."] = "添加事件：输入以搜索……"
L["Cinematic's language changes after a reload. Reload now?"] = "Cinematic的语言在重载界面后更改。现在重载吗？"
L["Settings window"] = "设置窗口"
L["Force reload on Settings exit"] = "退出设置时强制重载"
L["A workaround for a game bug: in gamepad mode, closing the Settings window after using an addon's settings (any addon's, not just Cinematic's) can freeze the game. With this on, once you've opened a Cinematic page, closing Settings (X, Close, Escape or the gamepad) reloads the UI instead, which closes it without the freeze. Your settings are saved first, as they are on every reload. Turning it off takes effect after a reload."] = "针对游戏错误的变通办法：在手柄模式下，使用过插件的设置（任何插件，不只是Cinematic）后关闭设置窗口可能会让游戏卡死。开启后，在打开过Cinematic页面后关闭设置（X、关闭、Esc或手柄）会改为重载界面，从而关闭窗口而不卡死。和每次重载一样，你的设置会先保存。关闭此项需重载后生效。"
L["closing Settings now reloads the UI (Force reload on Settings exit, Gamepad Frames page)."] = "现在关闭设置会重载界面（退出设置时强制重载，手柄页面）。"
L["Hide the minimap button in gamepad mode"] = "手柄模式下隐藏小地图按钮"
L["Using Cinematic's minimap button in gamepad mode tends to freeze the game, like closing Settings does. With this on, the button is hidden while gamepad mode is on and comes back when it's off. Cinematic's settings are still in the game's Settings (AddOns tab), or type /cine."] = "在手柄模式下使用Cinematic的小地图按钮常会让游戏卡死，就像关闭设置时一样。开启后，手柄模式开启期间按钮会隐藏，关闭手柄模式后再出现。Cinematic的设置仍在游戏设置（插件标签）中，或输入/cine。"
L["Reload"] = "重载"
L["Later"] = "稍后"
L["General"] = "常规"
L["Exit CineMode"] = "退出CineMode"
L["While casting"] = "施法时"
L["Includes mounting and hearthstone casts."] = "包括召唤坐骑和使用炉石。"
L["At vendors, banks, mail and trainers"] = "在商人、银行、邮箱和训练师处"
L["Opening windows"] = "打开窗口时"
L["While dragging something"] = "拖动物品时"
L["Back into CineMode after"] = "多久后回到CineMode"
L["Random zoom in and out"] = "随机拉近拉远"
L["Zoom out up to"] = "最远拉远至"
L["%d yards"] = "%d码"
L["Zoom in up to"] = "最近拉近至"
L["Random zoom only. How much closer than your own zoom it may come."] = "仅限随机缩放。最多可以比你自己的缩放距离近多少。"
L["Each zoom takes"] = "每次缩放用时"
L["Zoom ease in/out"] = "缩放缓入缓出"
L["Pause between zooms"] = "缩放间隔"
L["Random zoom only."] = "仅限随机缩放。"
L["Pause varies by up to"] = "间隔最多浮动"
L["Allow zooming past your maximum"] = "允许超过你的最大缩放距离"
L["Indoors"] = "室内"
L["Limit the camera indoors"] = "在室内限制镜头"
L["Zoom out indoors up to"] = "室内最远拉远至"
L["%.1f yards"] = "%.1f码"
L["Swing indoors up to"] = "室内最大摆动角度"
L["No AFK camera sweep indoors"] = "室内不进行暂离镜头环绕"
L["Turn clockwise"] = "顺时针旋转"
L["Sweeps turn the other way round."] = "环绕时朝另一个方向旋转。"
L["Random direction"] = "随机方向"
L["Turn per sweep"] = "每次环绕的转角"
L["How far each sweep turns, always the same way, staying level."] = "每次环绕转动的角度，始终朝同一方向，并保持水平。"
L["Turn speed"] = "旋转速度"
L["Minimum change"] = "最小变化"
L["Swing either side of the front"] = "在正面两侧摆动"
L["Swing either side of behind"] = "在背后两侧摆动"
L["Tilt up as far as"] = "最大上仰角度"
L["Tilt down as far as"] = "最大俯视角度"
L["How far below level a move may tilt."] = "一次移动最多可以低于水平线多少度。"
L["Lowest tilt"] = "最低倾角"
L["Each move takes"] = "每次移动用时"
L["How long each move takes, however far it goes."] = "每次移动所需的时间，无论移动多远。"
