-- Profiles.lua
L["Everything on: the UI fades, the letterbox and tint, and every camera mode. The defaults, and how the developer plays every day."] = "全部开启：界面淡出、宽银幕黑边和色调，以及所有镜头模式。这是默认设置，也是开发者每天的游戏方式。"
L["Immersive, with the Cooldown Manager in place of action bars 1 to 3, the micro menu and the XP bar in fights and with an enemy targeted. After a fight it stays up until its cooldowns are ready."] = "沉浸式，在战斗中和以敌人为目标时，用冷却管理器代替动作条1到3、微型菜单和经验条。战斗结束后，冷却管理器会保持显示直到其冷却就绪。"
L["The UI fades and the look stays, with just a few cameras: flights (and fly-bys), AFK, and your Hearthstone and teleports. No cozy, vista, fish, RP walk, auto-run, death or quest cameras."] = "界面淡出并保留画面效果，只有少数几个镜头：飞行（及掠过）、暂离，以及炉石和传送法术。没有温馨、远景、钓鱼、RP漫步、自动奔跑、死亡或任务镜头。"
L["Just the visual effects (tint, vignette, weather) over your normal UI: nothing fades, no letterbox, and the camera's left to you."] = "只在正常界面上叠加视觉效果（色调、暗角、天气）：不淡出任何东西，没有宽银幕黑边，镜头由你控制。"
L["The normal UI until a camera starts (standing still, going AFK, a flight, an emote...), then CineMode until it ends. The letterbox, tint, vignette and weather show only while a camera mode runs; no soft edges. Standing still starts the AFK camera, and every camera can start music."] = "在镜头启动之前（站着不动、暂离、飞行、表情……）保持正常界面，之后进入CineMode直到镜头结束。宽银幕黑边、色调、暗角和天气只在镜头模式运行时显示；没有边缘模糊。站着不动会启动暂离镜头，所有镜头都可以播放音乐。"
L["Everything on while you're out in the world on your own; the normal UI in a group, in dungeons, raids and PvP."] = "独自在野外时全部开启；在队伍中、地下城、团队副本和PvP中使用正常界面。"
L["As little UI as possible: chat, buffs, the quest tracker and your portrait don't pop up on their own (hovering still shows them), group members' nameplates aren't kept up, and fights don't bring the letterbox down. Fights bring up only your target and your cast bar (hidden otherwise), and every camera can start music."] = "尽可能少的界面：聊天、增益效果、任务追踪和你的头像不会自动弹出（鼠标悬停仍会显示），不会保持显示队伍成员的姓名板，战斗时也不会撤下宽银幕黑边。战斗中只会出现你的目标和施法条（其他时候隐藏），所有镜头都可以播放音乐。"
L["Started from %s."] = "基于%s创建。"

-- Share.lua
L["Export"] = "导出"
L["Import"] = "导入"
L["The active profile as a line of text to copy and paste wherever your friends will see it, so they can import it (your own ones only: everyone has the built-in ones)."] = "将当前配置文件转为一行文本，复制并粘贴到朋友能看到的地方，他们就能导入（仅限你自己的：内置配置文件人人都有）。"
L["Add a profile someone shared with you, from the text they gave you. Your own profiles stay as they are."] = "用别人分享给你的文本添加一个配置文件。你自己的配置文件保持不变。"
L["Share a profile with friends."] = "与朋友分享配置文件。"
L["share the active profile as text to copy"] = "将当前配置文件分享为可复制的文本"
L["add a profile someone shared with you"] = "添加别人分享给你的配置文件"
L["%s is a built-in profile, which everyone has already. To share your changes to it, make a New profile from it on the Profiles page and export that."] = "%s 是内置配置文件，人人都已经有了。要分享你对它的改动，请在配置文件页面用它新建一个配置文件，再导出那个。"
L["Shared profile"] = "分享的配置文件"
L["This profile needs a newer version of Cinematic. Update it, then try again."] = "此配置文件需要更新版本的 Cinematic。请更新后再试。"
L["That isn't a whole Cinematic profile. Copy all of it and paste it again."] = "这不是完整的 Cinematic 配置文件。请全部复制后重新粘贴。"
L["Paste a profile someone shared with you (Ctrl+V)."] = "粘贴别人分享给你的配置文件（Ctrl+V）。"
L["%s, shared by %s: %d settings changed from the defaults."] = "%s，由 %s 分享：%d 项设置与默认值不同。"
L["%s: %d settings changed from the defaults."] = "%s：%d 项设置与默认值不同。"
L["%d settings from a newer Cinematic (%s) will be skipped. Update Cinematic to get them all."] = "将跳过 %d 项来自更新版 Cinematic（%s）的设置。更新 Cinematic 即可全部获得。"
L["Shared by %s."] = "由 %s 分享。"
L["profile imported: %s"] = "已导入配置文件：%s"
L["Select all"] = "全选"
L["Save as:"] = "保存为："
L["Export profile: %s"] = "导出配置文件：%s"
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import on their Cinematic Profiles page (or /cine import)."] = "按 Ctrl+C 复制，然后粘贴到朋友能看到的地方。他们可在 Cinematic 配置文件页面点击导入（或 /cine import）来添加。"
L["Only Cinematic settings are in it: nothing about you or your character but its name. Not in it, as with any profile: frames you added and your zone and time tint colors."] = "其中只有 Cinematic 设置：除角色名外不含任何关于你或你角色的信息。与所有配置文件一样，不包含你添加的框体以及区域和时段的色调颜色。"
L["Import a profile"] = "导入配置文件"
L["Paste in a profile someone shared, give it a name, and Import. It's added as a new profile and switched to; your own profiles stay as they are."] = "粘贴分享的配置文件，起个名字，然后点击导入。它会作为新配置文件添加并启用；你自己的配置文件保持不变。"

