-- Tint.lua
L["None"] = "无"
L["No color tint."] = "没有颜色色调。"
L["Warm / golden hour"] = "暖色 / 黄金时刻"
L["Soft orange, like late-afternoon light."] = "柔和的橙色，就像傍晚前的阳光。"
L["Cool"] = "冷色"
L["Pale blue, crisp and wintry."] = "淡蓝色，清冷而有冬日感。"
L["Night"] = "夜晚"
L["Deep blue and darker, like moonlight."] = "深蓝且更暗，就像月光。"
L["Dusk gradient"] = "黄昏渐变"
L["Orange at the top fading to purple at the bottom, like a sunset."] = "顶部橙色渐变到底部紫色，就像日落。"
L["Sepia-ish"] = "近似棕褐色"
L["Warm brownish yellow, old-photo warmth. (The world can't be truly desaturated.)"] = "温暖的棕黄色，带有老照片的暖意。（游戏世界无法真正去饱和。）"
L["Dreamy"] = "梦幻"
L["A faint warm glow added over the scene. Soft and hazy."] = "在画面上叠加一层淡淡的暖光。柔和而朦胧。"
L["Custom"] = "自定义"
L["Your own color, chosen with the color picker below."] = "你自己的颜色，用下方的取色器选择。"
L["Changes through the day: blue at night, pink at dawn, clear in the day, golden in the evening and purple at dusk."] = "随一天中的时间变化：夜晚蓝色，黎明粉色，白天无色，傍晚金色，黄昏紫色。"
L["Zone"] = "区域"
L["A mood for the zone you're in: pale blue in the snow, sandy in deserts, green in swamps and jungles, sickly in blighted lands, ember red near volcanoes. Other zones are left untinted."] = "为你所在区域设置的氛围：雪地淡蓝，沙漠沙黄，沼泽和丛林偏绿，被污染的土地病态，火山附近余烬红。其他区域不加色调。"
L["Zone + time of day"] = "区域 + 时段"
L["The zone's mood and the time-of-day color together: a desert at night is warm sand darkened by moonlight."] = "区域氛围与时段颜色叠加：夜晚的沙漠是被月光压暗的暖色沙地。"
L["Snow"] = "雪地"
L["Desert"] = "沙漠"
L["Savanna"] = "草原"
L["Swamp and jungle"] = "沼泽和丛林"
L["Blighted"] = "污染之地"
L["Volcanic"] = "火山"
L["Forest"] = "森林"
L["Dusky"] = "昏暗"
L["Forge"] = "熔炉"
L["Warm"] = "温暖"
L["Dusty red"] = "尘红"
L["Sickly"] = "病态"
L["Airy"] = "空灵"
L["Moonlit"] = "月光"
L["Gloomy"] = "阴郁"
L["Twilight"] = "暮光"
L["Deep twilight"] = "深邃暮光"
L["Golden"] = "金色"
L["Autumn"] = "秋季"
L["Summer"] = "夏季"
L["Fel"] = "邪能"
L["Void"] = "虚空"
L["same as the zone"] = "与区域相同"

-- Welcome.lua
L["Trying %s. Pick another to compare."] = "正在试用%s。选择另一个进行比较。"
L["Done"] = "完成"
L["Nothing runs until you pick one."] = "在你选择之前不会运行任何功能。"
L["Decide later"] = "稍后决定"
L["Welcome to Cinematic"] = "欢迎使用Cinematic"
L["Between fights, Cinematic fades your UI away, adds letterbox bars and a color tint, and brings the camera to life: on flights, standing still, sitting by a campfire. Fights, casting and opening windows bring the UI back. Hovering a faded frame shows it.\n\nHow much of that do you want? Pick a profile to start from:"] = "在战斗间隙，Cinematic会淡出你的界面，加上宽银幕黑边和颜色色调，并让镜头动起来：飞行时、站着不动时、坐在篝火旁时。战斗、施法和打开窗口会让界面重新出现。鼠标悬停在已淡出的框体上会显示它。\n\n你想要多少这样的效果？选择一个配置文件作为起点："
L["Try as many as you like: each one starts straight away behind this window. Afterwards you can switch any time, tweak a profile or make your own on the Profiles page (Options > AddOns > Cinematic, or right-click the minimap button), or with /cine profile. /cine toggles Cinematic on and off."] = "想试多少个都可以：每一个都会在此窗口后方立即生效。之后你可以随时切换，在配置文件页面（选项 > 插件 > Cinematic，或右键点击小地图按钮）调整配置文件或创建你自己的配置文件，也可以使用 /cine profile。/cine 可开关Cinematic。"
L["off until you pick a profile. This window comes back next login, or now with /cine welcome."] = "在你选择配置文件之前处于关闭状态。此窗口会在下次登录时再次出现，也可以现在输入 /cine welcome 打开。"
L["profile: %s. Change it any time on the Profiles settings page, or with /cine profile."] = "配置文件：%s。可随时在配置文件设置页面或使用 /cine profile 更改。"
L["Turn Cinematic off"] = "关闭Cinematic"
L["turned off. /cine brings this window back to pick a profile."] = "已关闭。/cine 可重新打开此窗口以选择配置文件。"
L["Settings"] = "设置"

-- Looked up by name (page names, times of day...)
L["Dawn"] = "黎明"
L["Day"] = "白天"
L["Golden hour"] = "黄金时刻"
L["Dusk"] = "黄昏"
L["Morning"] = "上午"
L["Midday"] = "正午"
L["Afternoon"] = "下午"
L["Evening"] = "傍晚"
L["turned off"] = "已关闭"
L["you moved the camera"] = "你移动了镜头"
L["combat"] = "战斗"
L["landed"] = "已降落"
L["cozy camera"] = "温馨镜头"
L["vista camera"] = "远景镜头"
L["fish camera"] = "钓鱼镜头"
L["tele camera"] = "传送镜头"
L["death camera"] = "死亡镜头"

-- Campfire.lua
L["Quality of life"] = "便利功能"
L["Small helpers for getting about the world. Ideas for more in the spirit of this page are welcome: please send them to the developer."] = "在世界中游历时的小帮手。如果你有更多与本页类似的点子，欢迎发给开发者。"
L["Campfire button"] = "篝火按钮"
L["Hovering a campfire with the cursor near the middle of the screen shows a campfire icon where the cursor is: click it to settle down by the fire (sit, kneel or lie down, as ticked below), without typing the emote. Moving the cursor off it puts it away. Not in a fight or while mounted."] = "光标在屏幕中央附近悬停于篝火上时，光标处会出现篝火图标：点击即可在火边歇息（坐下、跪下或躺下，按下方勾选），无需输入表情命令。光标移开后图标消失。战斗中或骑乘时不会出现。"
L["Sit"] = "坐下"
L["Kneel"] = "跪下"
L["Lie down"] = "躺下"
L["What clicking the Campfire button does. With more than one ticked, it's one of them at random each time."] = "点击篝火按钮时做的动作。勾选多个时，每次随机选其中一个。"
L["Clicking the Campfire button (Quality of life page). Once the campfire's buff comes, the first row's camera takes over. Moving, jumping or another emote ends it."] = "点击篝火按钮（便利功能页面）。篝火增益出现后，由第一行的镜头接管。移动、跳跃或其他表情会结束它。"
L["Stand up once you get Camp Benefits"] = "获得营地增益后站起"
L["Open the character window when dragging gear out of your bags"] = "把装备拖出背包时打开角色窗口"
L["Dragging something you can wear out of your bags, over the game world, opens the character window, so its slots are there to drop it on. Moving it between bags doesn't. Put it back without wearing it and the window closes again. Not in a fight."] = "把可穿戴的物品拖出背包、移到游戏世界上方时会打开角色窗口，方便把它放到栏位上。在背包之间移动不会打开。没穿上就放回去，窗口会再次关闭。战斗中不生效。"
L["Off by default on this client: opened by an addon, the window makes your player frame's health and power numbers show errors in BugSack and other error catchers. They're harmless."] = "此客户端默认关闭：由插件打开时，该窗口会让你的玩家框体的生命值和能量数字在 BugSack 等错误收集插件中报错。这些错误无害。"
L["Open windows in the middle of the screen"] = "在屏幕中间打开窗口"
L["Windows the game opens on the left (quest log, group finder, character, spellbook and the like) open in the middle of the screen instead. Two open at once still sit side by side, together in the middle. Quest givers' windows open a little in from the left edge instead, out of the way of the quest giver. A window another addon has moved stays where that addon put it."] = "游戏在左侧打开的窗口（任务日志、队伍查找器、角色、法术书等）改为在屏幕中间打开。同时打开两个时仍并排显示，一起居中。任务给予者的窗口则在离左边缘稍远处打开，以免挡住任务给予者。被其他插件移动过的窗口留在该插件放置的位置。"
L["Drag windows to move them"] = "拖动窗口来移动它们"
L["Drag the game's windows (quest log, group finder, character, spellbook and the like) to move them. A window opens where you last dropped it from then on, in this profile. Some windows can't be moved in a fight."] = "拖动游戏的窗口（任务日志、队伍查找器、角色、法术书等）来移动它们。此后窗口会在你上次放下的位置打开（本配置）。部分窗口在战斗中无法移动。"
L["Put windows back"] = "窗口复位"
L["Forget where you've dragged the windows to: each opens in its usual place again."] = "忘记你把窗口拖到了哪里：每个窗口重新在原来的位置打开。"
L["Sitting by a Welcoming Campfire for its minute gives you Camp Benefits: as it arrives, you stand up again, ready to go."] = "在迎客篝火旁坐满一分钟会获得营地增益：获得时你会站起来，随时出发。"

-- Options.lua: the Camera Settings page
L["Camera Settings"] = "镜头设置"
L["Each camera's own settings. Click a camera's name to open its settings, and again to close them. The Camera Modes page has the settings they share, and Camera Triggers what starts each one."] = "每个镜头各自的设置。点击镜头名称展开其设置，再次点击收起。共用设置在镜头模式页面，启动各镜头的条件在镜头触发页面。"
L["Put this camera's settings back to the profile's own?"] = "将此镜头的设置恢复为配置文件自身的设置？"
L["Put this camera's settings back to the active profile's own values (the defaults, or a built-in profile's)."] = "将此镜头的设置恢复为当前配置文件的值（默认值或内置配置文件的值）。"
L["While the death camera runs, a song picked at random from the list below plays in place of the zone music. With CineMode music off, only if your game music is on. It stops when you release or come back."] = "死亡镜头运行时，会从下方列表中随机选一首歌代替区域音乐播放。关闭CineMode音乐时，仅在游戏音乐开启时播放。释放灵魂或复活时停止。"
L["Hunter"] = "猎人"

-- QuestTalk.lua (and its options on the Quest Vision page)
L["%s artifact power"] = "%s 神器能量"
L["%s honor"] = "%s 荣誉"
L["Quests"] = "任务"
L["Show the game's window"] = "显示游戏窗口"
L["Talk"] = "对话"
L["Title: %s"] = "头衔：%s"
L["campaign"] = "战役"
L["daily"] = "日常"
L["done"] = "已完成"
L["important"] = "重要"
L["in progress"] = "进行中"
L["legendary"] = "传说"
L["locked"] = "已锁定"
L["low level"] = "低等级"
L["meta"] = "元任务"
L["ready to turn in"] = "可交付"
L["repeatable"] = "可重复"
L["weekly"] = "每周"
L["Talking to NPCs"] = "与NPC对话"
L["Custom dialogue frames"] = "自定义对话框"
L["Talking to an NPC, what they say shows in a speech bubble over their head, and what you can say back in a list near the bottom of the screen, instead of the game's gossip and quest windows. The list has everything the window would: quests to turn in, pick up or still in progress, and every other option (vendor, trainer, inn, flight master...). A quest offered or turned in shows its objective and rewards on a card, with its buttons; click a reward to choose it. \"Show the game's window\" on the card brings the game's window back for that conversation. The game's popups (a cost to confirm, a party member's escort quest) come up as usual."] = "与NPC对话时，NPC说的话会显示在其头顶的对话气泡中，你可以回答的内容则显示在屏幕下方的列表中，取代游戏的对话和任务窗口。列表包含窗口中的所有内容：可交付、可接取或仍在进行的任务，以及所有其他选项（商人、训练师、旅店、飞行管理员……）。提供或交付的任务会在卡片上显示目标和奖励以及按钮；点击奖励即可选择。卡片上的“显示游戏窗口”会在本次对话中恢复游戏窗口。游戏的弹出窗口（确认费用、队友的护送任务）照常出现。"
L["Parchment"] = "羊皮纸"
L["Chat bubble"] = "聊天气泡"
L["How the bubble looks: parchment like the quest window's, or the game's own chat bubble."] = "气泡的外观：像任务窗口那样的羊皮纸，或游戏自己的聊天气泡。"
L["Bubble look"] = "气泡外观"
L["Number keys and Space"] = "数字键和空格"
L["1 to 9 and 0 pick from the list, as numbered. Space shows the next paragraph, and on the last one does the card's first button (Accept, Continue, Complete Quest). Only keys that do something there are held back from your action bars, and none in a fight."] = "1到9和0按编号从列表中选择。空格显示下一段，在最后一段时按下卡片的第一个按钮（接受、继续、完成任务）。只有在这里有作用的按键才会从动作条截留，战斗中一个也不会。"
L["Size"] = "大小"
L["The size of the bubble and the list."] = "气泡和列表的大小。"
L["List height on the screen"] = "列表在屏幕上的高度"
L["How far up the screen the list of replies starts: its top edge, from the bottom of the screen. Moving this also forgets where you dragged the list to."] = "回答列表在屏幕上从多高开始：从屏幕底部算起到它的上边缘。调整它也会忘记你拖动列表到的位置。"
L["The NPC's portrait"] = "NPC头像"
L["Their portrait, round, on the bubble's top left corner, as on the game's quest window. Not for a quest from an item, with nobody to show."] = "在气泡左上角显示其圆形头像，就像游戏的任务窗口。来自物品的任务没有人可显示，因此不显示。"
L["Put them back"] = "全部复位"
L["Drag the list of replies to move it, and the bubble while it isn't over an NPC. This forgets where you dropped them: each opens in its usual place again."] = "拖动回答列表可以移动它，气泡不在NPC上方时也可以拖动。此按钮会忘记你放置的位置：它们会重新在原来的位置打开。"
L["Bubble height"] = "气泡高度"
L["%d lines"] = "%d 行"
L["How many lines of their words the bubble holds. It's always this tall, however little is on the page; more words go on the next page."] = "气泡能容纳几行话。无论页面上内容多少，它总是这个高度；更多的话放到下一页。"
L["Below"] = "下方"
L["Quest card beside the bubble"] = "气泡旁的任务卡片"
L["Quest card on the bubble's background"] = "任务卡片使用气泡背景"
L["The quest card has the bubble's look (parchment, or the chat bubble) instead of its own dark one, its words in colors that suit it."] = "任务卡片使用气泡的外观（羊皮纸或聊天气泡）而不是自己的深色背景，文字颜色随之调整。"
L["Space above the bubble"] = "气泡上方留白"
L["Over the NPC's head, the bubble always stays at least this far down from the top of the screen (and below the letterbox), so it never sits right against the edge."] = "在NPC头顶时，气泡总是离屏幕顶部（以及宽银幕黑边下方）至少这么远，不会贴着边缘。"
L["Over the head"] = "头顶"
L["Fixed"] = "固定"
L["Opposite clicked"] = "点击的对侧"
L["Where the bubble goes. Over the head: over the NPC's nameplate, following them on the screen. Fixed: above the middle of the screen, or wherever you drag it. Opposite clicked: wherever you drag it, but when you clicked the NPC on that half of the screen, at the same spot on the other half (they stand where you clicked, so that half is clearer), the quest card beside it. With nobody to stand over or no click (a quest from an item, or the interact key), it goes where Fixed would."] = "气泡的位置。头顶：在NPC姓名板上方，在屏幕上跟随它。固定：屏幕中央上方，或你拖动到的位置。点击的对侧：在你拖动到的位置，但如果你在屏幕那一半点击了NPC，就放在另一半的相同位置（NPC站在你点击的地方，所以那一半更空），任务卡片在旁边。没有可跟随的人或没有点击时（来自物品的任务，或互动键），放在固定的位置。"
L["Bubble position"] = "气泡位置"
L["Hold the camera still"] = "保持镜头静止"
L["With the bubble over the head, the quest camera turns in as usual but doesn't drift to and fro while you talk: following the NPC on the screen, the bubble and card would jiggle as it moved."] = "气泡在头顶时，任务镜头照常转入，但在对话时不会来回漂移：气泡和卡片在屏幕上跟随NPC，镜头移动会让它们抖动。"
L["+%d reputation"] = "+%d 声望"
L["More rewards"] = "更多奖励"
L["Back"] = "返回"
L["Right"] = "右侧"
L["Left"] = "左侧"
L["Where the quest card (the objective, rewards and buttons, or the list of replies) goes beside the bubble. Below: as wide as the bubble, which moves up to make room for it. Side: with Opposite clicked, on the bubble's outer side (away from the middle of the screen), else on the right. Right or Left: always that side. Beside it, it's as tall as the bubble."] = "任务卡片（目标、奖励和按钮，或回答列表）放在气泡旁的哪里。下方：与气泡等宽，气泡上移腾出空间。侧边：使用点击的对侧时放在气泡外侧（远离屏幕中央），否则放在右侧。右侧或左侧：总是那一侧。在旁边时与气泡等高。"
L["\"Show the game's window\" link"] = "“显示游戏窗口”链接"
L["A small link at the bottom of the quest card that brings back the game's own quest window for the rest of that conversation (for a long quest text, or to read it the usual way)."] = "任务卡片底部的小链接，在本次对话剩余时间里恢复游戏自己的任务窗口（用于很长的任务文本，或按平常方式阅读）。"
L["Look"] = "外观"
L["Where they go"] = "位置"

-- StoryVision.lua
L["Opens the Story Vision page."] = "打开 Story Vision 页面。"
L["Shows it now, to see how it looks."] = "立即显示，看看效果。"
L["Words that fade in on the screen at moments in your session that aren't your own fights: what you did last time, the time of day, a place under attack, your death. (Fights and bosses: Battle Vision.)"] = "在并非你自己战斗的时刻，于屏幕上淡入的文字：你上次做了什么、时段、遭到攻击的地点、你的死亡。（战斗和首领：Battle Vision。）"
L["Last time"] = "上次"
L["On a real login (not a reload), a line under the zone name saying what you did last time you played: where you spent the most time, quests done, a level reached and bosses killed, such as \"Last time: Darkshore · 3 quests done · reached level 24\". Only what happened, and nothing if nothing did; never in a fight, nor after more than two weeks away."] = "真正登录时（不是重载界面），在区域名称下方用一行文字说明你上次游戏时做了什么：待得最久的地方、完成的任务、达到的等级和击败的首领，例如\"上次：黑海岸 · 完成3个任务 · 达到24级\"。只显示发生过的事，什么都没发生就不显示；战斗中不显示，离开超过两周也不显示。"
L["Last time: nothing to say yet this session (no quests, level or bosses), so this is a sample."] = "上次：本次会话暂时没有可说的（没有任务、等级或首领），所以这是示例。"
L["Plays your login now: the zone name fades in with the Last time line under it, from this session so far (a sample if nothing counted yet). Close the settings to see it."] = "立即重现登录画面：区域名称淡入，下方显示根据本次会话到目前为止的\"上次\"一行（尚未记录任何内容时显示示例）。关闭设置即可看到。"
L["The font of every line on this page. General: the one picked on the Style hub's General page, so changing it there changes it here. Russian, Korean or Chinese text keeps the game's, so its letters show. Only with Enable Style on (Style hub, General page)."] = "此页面上每一行文字的字体。General：Style 中心 General 页面所选的字体，在那里更改，这里也随之更改。俄文、韩文或中文文字保留游戏字体，以便正常显示。仅在开启 Enable Style 时生效（Style 中心，General 页面）。"
L["Last time: %s"] = "上次：%s"
L["%d quest done"] = "完成%d个任务"
L["%d quests done"] = "完成%d个任务"
L["reached level %d"] = "达到%d级"
L["%d boss down"] = "击败%d个首领"
L["%d bosses down"] = "击败%d个首领"
L["On: each moment below shows as ticked. Off: none of them do, and each keeps its tick for when you turn this back on."] = "开启：下方每个时刻按勾选显示。关闭：都不显示，各自保留勾选，以便你重新开启。"
L["Time of day at login"] = "登录时的时段"
L["Dawn, Morning, Midday, Afternoon, Evening, Dusk or Night, under the zone name when you log in or reload. Follows the clock picked on the Tint page."] = "登录或重载界面时，在区域名称下方显示黎明、上午、正午、下午、傍晚、黄昏或夜晚。按照色调页面所选的时钟。"
L["Time of day changes"] = "时段变化"
L["When the time of day changes during play (not in combat), its name fades in where the zone name shows, with a fitting sound: a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "游戏中时段变化时（战斗中除外），其名称会在区域名称出现的位置淡入，并配有相应的音效：黎明是公鸡、上午是马、正午是你阵营的钟声、傍晚是青蛙、黄昏是猫头鹰、夜晚是狼。"
L["Under attack"] = "遭到攻击"
L["When the LocalDefense channel says a place is under attack (\"Dun Algaz is under attack!\"), it shows in red where the zone name appears, with your faction's city bell. The same place shows at most once every 90 seconds."] = "当本地防务频道通报某地正遭到攻击时（\"丹奥加兹正遭到攻击！\"），会在区域名称出现的位置以红色显示，并敲响你所在阵营的城市钟声。同一地点每90秒最多显示一次。"
L["Only with the death camera on (the Die row on the Scenes page)."] = "仅在死亡镜头开启时（场景页面的死亡一行）。"
L["The time of day's title and sound:"] = "时段的标题和音效："
L["Attacks shown on the screen:"] = "屏幕上显示的攻击："
L["The death banner:"] = "死亡横幅："

