L["Hover Groups"] = "鼠标悬停分组"
L["Gamepad Frames"] = "手柄框体"
L["Resource Display"] = "资源显示"
L["Visibility"] = "显示"
L["Trackers"] = "追踪"
L["Info and menus"] = "信息与菜单"
