L["Parts"] = "部件"
L["When it shows in CineMode (always, in fights, in places): its rows on the Game Frames page."] = "在 CineMode 中何时显示（始终、战斗中、特定地点）：游戏框体页面上的对应行。"
L["Opens the Unit Frames page: which parts of your own, your target's and the other unit frames show, and when."] = "打开单位框体页面：你自己的、目标的及其他单位框体显示哪些部分，以及何时显示。"

-- More pages and settings (AI translation)
L[" A class icon beside enemy players' health bars."] = " 敌方玩家生命条旁的职业图标。"
L[" A class icon beside friendly players' health bars."] = " 友方玩家生命条旁的职业图标。"
L[" A mark on your target's nameplate (and its name, health bar or border in its color), shown even while the rest of the plate is faded or shows just its name. Its look: the Style hub's Nameplates page."] = " 你目标姓名板上的标记（其名字、生命条或边框也会显示成该颜色），即使姓名板其余部分已淡出或只显示名字也会显示。外观：风格中心的姓名板页面。"
L[" A role icon beside your group's damage dealers' health bars."] = " 你队伍中伤害输出者生命条旁的职责图标。"
L[" A role icon beside your group's healers' health bars."] = " 你队伍中治疗者生命条旁的职责图标。"
L[" A role icon beside your group's tanks' health bars."] = " 你队伍中坦克生命条旁的职责图标。"
L[" Beyond nameplate range, and in dungeons and raids, the game has no setting for neutral NPCs' names alone: they show there while all three NPC rows do."] = " 在姓名板范围之外，以及在地下城和团队副本中，游戏没有单独控制中立NPC名字的设置：只有三个NPC行都显示时，它们才会在那里显示。"
L[" Beyond nameplate range, and in dungeons and raids, the game only shows friendly NPCs with something for you (quest givers, vendors, flight masters...) unless all three NPC rows show: then all of them, guards too."] = " 在姓名板范围之外，以及在地下城和团队副本中，游戏只显示与你有关的友方NPC（任务NPC、商人、飞行管理员……），除非三个NPC行都显示：那时会显示所有NPC，包括卫兵。"
L[" In CineMode, on the nameplates that are up."] = " 在CineMode中，显示在已出现的姓名板上。"
L[" Its look: the Dialogue tab."] = " 外观：对话标签页。"
L[" Its look: the Quest Item Button tab."] = " 外观：任务物品按钮标签页。"
L[" Off unless ticked. In CineMode, on the nameplates that are up; outside it, only with Always ticked."] = " 未勾选时关闭。在CineMode中，显示在已出现的姓名板上；在CineMode之外，只有勾选“始终”时才显示。"
L[" Players' guilds, under their names wherever their names show: over their heads, and in CineMode on nameplates showing just the name."] = " 玩家的公会，显示在其名字下方，凡是显示名字的地方都会显示：头顶上，以及CineMode中只显示名字的姓名板上。"
L[" Quest objective icons and other widgets over the plate."] = " 姓名板上方的任务目标图标和其他小部件。"
L[" The border round your target's or mouseover's plate."] = " 你的目标或鼠标悬停单位姓名板周围的边框。"
L[" The buffs shown on the plate."] = " 姓名板上显示的增益效果。"
L[" The cast bar."] = " 施法条。"
L[" The debuffs (and crowd control) shown on the plate."] = " 姓名板上显示的减益效果（以及控制效果）。"
L[" The elite, rare or boss icon."] = " 精英、稀有或首领图标。"
L[" The glow while a mob has you (or is about to) as its target."] = " 怪物把你选为目标（或即将选你）时的光晕。"
L[" The health bar."] = " 生命条。"
L[" The level."] = " 等级。"
L[" The name on the plate (the Names grid below is for names without a plate)."] = " 姓名板上的名字（下方的名字表格用于没有姓名板的名字）。"
L[" The raid target marker (skull, star...)."] = " 团队目标标记（骷髅、星形……）。"
L[" Their look: the Style hub's Names page."] = " 外观：风格中心的名字页面。"
L[" Your target's name, even with its kind's names off in the Names grid. For some kinds only, name them in its rule (Edit): Enemy players, Hostile NPCs, Neutral players... Beyond nameplate range, and in dungeons and raids, the game has one setting for your target's name, which can't change in fights: it stays as the fight found it."] = " 你目标的名字，即使名字表格中该类别的名字已关闭。若只对某些类别生效，请在其规则（编辑）中写明：敌方玩家、敌对NPC、中立玩家……在姓名板范围之外，以及在地下城和团队副本中，游戏只有一个控制目标名字的设置，且战斗中无法更改：它会保持战斗开始时的状态。"
L[" Your target's nameplate, whatever the Nameplates grid says. For some kinds only, name them in its rule (Edit): Enemy players, Hostile NPCs, Neutral players... In dungeons and raids, friendly targets go by Friendly plates in dungeons and raids."] = " 你目标的姓名板，无论姓名板表格如何设置。若只对某些类别生效，请在其规则（编辑）中写明：敌方玩家、敌对NPC、中立玩家……在地下城和团队副本中，友方目标按照“地下城和团队副本中的友方姓名板”设置。"
