L["1. Type |cffffd100/cine log|r in chat, or click Open the log below.\n2. The log opens already selected: press Ctrl+C to copy it.\n3. Paste it into your bug report. On Discord it's too long for a message: paste it into a .txt file and attach that.\nIt holds the addon's recent history, any Lua errors and a summary of your setup (game version, changed settings, other addons). It doesn't include your character's name or realm."] = "1. 在聊天中输入 |cffffd100/cine log|r，或点击下方的“打开日志”。\n2. 日志打开时已全部选中：按 Ctrl+C 复制。\n3. 将其粘贴到你的错误报告中。在 Discord 上它太长，无法作为一条消息发送：请粘贴到一个 .txt 文件中并附上该文件。\n它包含插件最近的记录、所有Lua错误以及你的设置概要（游戏版本、更改过的设置、其他插件）。它不包含你角色的名字或服务器。"
L["1.85:1"] = "1.85:1"
L["2 minutes"] = "2分钟"
L["2.39:1 (cinema)"] = "2.39:1（电影院）"
L["2:1"] = "2:1"
L["30 seconds"] = "30秒"
L["5 minutes"] = "5分钟"
L["< Back"] = "< 返回"
L["<NAME>"] = "<NAME>"
L["A 2.39:1 frame, as at the cinema."] = "2.39:1 的画幅，和电影院一样。"
L["A Stop camera button on screen while its steps run (under the release popup when you're dead): click it for your own view back, until what started it is over."] = "其步骤运行时屏幕上会出现“停止镜头”按钮（死亡时在释放灵魂弹窗下方）：点击它可恢复你自己的视角，直到启动它的事件结束。"
L["A big bar in a gold frame, red when you're behind, gold when you lead, loud words."] = "金色框中的大条，落后时为红色，领先时为金色，配上醒目的文字。"
L["A big hit takes"] = "一次重击用时"
L["A big hit's flash, and the color the world drains toward."] = "重击的闪光，以及世界褪色时趋向的颜色。"
L["A black border round its numbers."] = "数字周围的黑色描边。"
L["A black border around the letters, for see-through backgrounds."] = "文字周围的黑色描边，适用于透明背景。"
L["A black border around the letters, on every Vision that follows this page."] = "文字周围的黑色描边，应用于所有跟随本页面的 Vision。"
L["A black border around the letters, on every page that follows General. The game's: as each page's default has it."] = "文字周围的黑色描边，应用于所有跟随“常规”的页面。游戏自带：按各页面的默认设置。"
L["A black border around the letters, so they stand out against the world. Thick + shadow also drops a shadow below and to the right of them."] = "文字周围的黑色描边，让文字在世界背景中更醒目。“粗 + 阴影”还会在文字右下方加上阴影。"
L["A black border around the letters: easier to read with no panel behind them."] = "文字周围的黑色描边：在没有背景面板时更易阅读。"
L["A black border around the letters: for light words with no panel behind them."] = "文字周围的黑色描边：适用于没有背景面板的浅色文字。"
L["A border in the color beside it around the icon while it flashes."] = "图标闪烁时，在其周围显示旁边所选颜色的边框。"
L["A border around the letters."] = "文字周围的描边。"
L["A boss"] = "首领"
L["A box where it and its recap show: drag it where you want it, left-click to set, right-click to put it back. Close the settings to see it."] = "它和它的回顾显示的方框：拖到你想要的位置，左键点击确定，右键点击复位。关闭设置后即可看到。"
L["A breeze that shows you the way: wind blows across the screen toward your waypoint (your map pin, or the quest you're tracking), in gusts. When it's off the screen, the wind sweeps off the side to turn to. It goes by the way you face, so it's off while you swing the camera round on its own (on retail it follows the game's waypoint marker exactly). A demo for now."] = "为你指路的微风：风会一阵阵地吹过屏幕，指向你的路径点（你的地图标记，或你正在追踪的任务）。路径点不在屏幕上时，风会吹向你应转向的一侧。它以你面朝的方向为准，所以当你单独转动镜头时它会关闭（在正式服上，它会精确跟随游戏的路径点标记）。目前为演示功能。"
L["A bubble the game would put at the very top of the screen (someone above you, up some stairs say) shows a little lower instead, below the letterbox bar (or a bit down from the top with the bars off), where you can read it."] = "游戏原本会放在屏幕最顶端的气泡（例如在你上方的人，比如在楼梯上面）会显示得低一点，位于宽银幕黑边下方（关闭黑边时则从顶部往下一点），让你能看清。"
L["A built-in camera: Copy it to change it."] = "内置镜头：复制后才能更改。"
L["A button on your talents window opens a talent calculator: your class's three trees side by side, to plan a build without learning anything. Left-click adds a point, right-click takes one back; above the trees, the level the build needs and the points left. It opens in the talents window's place, and a button on it takes you back. It starts from the talents you have; Copy over changes puts what the plan adds in your talents window, to apply there. Also /cine talents."] = "天赋窗口上的一个按钮可以打开天赋模拟器：你职业的三个天赋树并排显示，无需学习任何东西就能规划天赋。左键点击加一点，右键点击退回一点；天赋树上方显示该方案所需的等级和剩余点数。它在天赋窗口的位置打开，上面有按钮可以返回。它从你现有的天赋开始；“复制更改”会把方案新增的天赋放入你的天赋窗口，以便在那里应用。也可用 /cine talents。"
L["A button under the release popup while the death camera's on: click it for your own view back until you release or come back. The Stop the camera key binding does the same."] = "死亡镜头开启时，释放灵魂弹窗下方的按钮：点击它可恢复你自己的视角，直到你释放灵魂或复活。“停止镜头”按键绑定的效果相同。"
L["A change here starts a profile of your own, %s."] = "在这里做出更改会创建一个你自己的配置文件：%s。"
L["A chat message is peeking"] = "有聊天消息正在短暂显示"
L["A close, gentle zoom: it starts by easing in to the close-up distance below, then drifts a little in and out around it."] = "近距离的柔和缩放：先缓慢拉近到下方的特写距离，然后在其附近轻微地前后漂移。"
L["A color of your own (the swatch), for both lines."] = "你自己的颜色（色块），用于两行。"
L["A color of your own (the swatch)."] = "你自己的颜色（色块）。"
L["A copy of this camera's script, yours to change, and its tab opened."] = "此镜头脚本的副本，可由你更改，并打开其标签页。"
L["A copy of this script, yours to change."] = "此脚本的副本，可由你更改。"
L["A crown"] = "王冠"
L["A crown and the number in its color."] = "王冠和该颜色的数字。"
L["A damage dealer (or anyone without a role) shows once their health drops below this. 100% shows them at any damage; lower keeps them hidden through small hits."] = "伤害输出者（或没有职责的任何人）的生命值低于此值时显示。100%表示受到任何伤害都会显示；更低的值可在受到小伤害时保持隐藏。"
L["A dark copy of the letters just behind them, down and to the right."] = "文字正后方偏右下的一层深色副本。"
L["A dark copy of the letters just behind them, to lift them off the world."] = "文字正后方的一层深色副本，让文字从世界背景中凸显出来。"
L["A dark fill over the icon, going down as the cooldown runs out."] = "覆盖在图标上的深色填充，随冷却结束逐渐下降。"
L["A dark panel behind it all, this dark. 0: none."] = "所有内容后面的深色面板，深度为此值。0：无。"
L["A dark panel in the rounded edge of the game's roll frames, in the item's quality color."] = "游戏掷骰框圆角边缘内的深色面板，使用物品品质的颜色。"
L["A dark panel with a thin line round it, in the item's quality color."] = "带细边线的深色面板，使用物品品质的颜色。"
L["A debuff that brings them up keeps them up while you have any debuff (bar the ones listed below), however long that is, fights included."] = "让它们出现的减益效果会使它们在你身上有任何减益效果（下方列出的除外）期间一直保持显示，无论持续多久，包括战斗中。"
L["A dungeon"] = "地下城"
L["A feared, stunned, polymorphed, rooted or silenced duelist gets an icon of the spell beside their nameplate, with the time left."] = "被恐惧、昏迷、变形、定身或沉默的决斗者，其姓名板旁会显示该法术的图标和剩余时间。"
L["A fight you go into with your mana, rage, energy or the like at rest (rage at 0, mana full...) brings up your resource bar only once it changes: your first cast, your first hit. Going in with it still filling or draining, it comes up straight away. It stays up for the rest of the fight."] = "如果你进入战斗时法力、怒气、能量等处于静止状态（怒气为0、法力已满……），资源条只会在其发生变化时出现：你的第一次施法、第一次攻击。如果进入战斗时它仍在恢复或消耗，就会立即出现。之后在整场战斗中保持显示。"
L["A film's frame"] = "电影画幅"
L["A flat bubble in a color of your own (the swatch)."] = "你自选颜色（色块）的扁平气泡。"
L["A flat dark bubble."] = "扁平的深色气泡。"
L["A flat fill in your colors on a dark ground, a thin black edge, Arial Narrow, the seconds left."] = "深色底上的你的颜色平涂填充，细黑边，Arial Narrow 字体，显示剩余秒数。"
L["A glow along the row, a crown and the number in its color."] = "沿该行的光晕、王冠和该颜色的数字。"
L["A golden exclamation mark beside their nameplates' health bars, wherever their plates show (beside their names when just their names show). Always on with Quest mark above. Needs the Nameplates page enabled."] = "在他们姓名板生命条旁显示金色感叹号，只要其姓名板显示就会显示（只显示名字时则在名字旁）。开启上方的“任务标记”时始终开启。需要启用姓名板页面。"
L["A group of your own, to pick its frames and icon."] = "你自己的分组，可选择其框体和图标。"
L["A healer shows once their health drops below this. 100% shows them at any damage; lower keeps them hidden through small hits."] = "治疗者的生命值低于此值时显示。100%表示受到任何伤害都会显示；更低的值可在受到小伤害时保持隐藏。"
L["A line of text to copy and paste to friends, who add it with Import a wheel."] = "一行可复制并粘贴给朋友的文本，他们可以用“导入轮盘”添加。"
L["A little icon before each detail: a map, a watch, a quest mark, a skull, coins..."] = "每条信息前的小图标：地图、手表、任务标记、骷髅、钱币……"
L["A made-up fight for 25 seconds, to see how it looks (Stop ends it). It works with the page off too. Close the settings to see it."] = "一场持续25秒的模拟战斗，用来查看效果（“停止”可结束）。即使页面关闭也有效。关闭设置后即可看到。"
L["A member with a debuff you can dispel shows, at full health too."] = "身上有你能驱散的减益效果的成员会显示，满血时也会。"
L["A member with any debuff at all shows, at full health too."] = "身上有任何减益效果的成员都会显示，满血时也会。"
L["A message shows"] = "显示消息"
L["A minimap blip's tooltip, which always shows"] = "小地图光点的鼠标提示，总是会显示"
L["A name of your own for it, shown on the rows. Empty: what starts it."] = "你给它起的名字，显示在各行上。留空：显示启动它的事件。"
L["A name of your own for this row, shown on the grid and the preview, say Far trash. Empty: its kind's name."] = "你给这一行起的名字，显示在表格和预览中，例如“远处小怪”。留空：显示其类别的名称。"
L["A name of your own for this row, shown on the grid, say AFK in dungeons. Empty: its trigger's."] = "你给这一行起的名字，显示在表格中，例如“地下城中暂离”。留空：显示其触发条件的名称。"
L["A new camera of yours, with a few steps to start from."] = "你自己的新镜头，带几个步骤作为起点。"
L["A new name for this theme of yours."] = "你这个主题的新名字。"
L["A new rule above the last one, for the fights you pick."] = "在最后一条规则上方新增一条规则，用于你选择的战斗。"
L["A new rule at the end, for the places you pick (move it up to read it first)."] = "在末尾新增一条规则，用于你选择的地点（把它上移可让它优先生效）。"
L["A new rule at the end, for the time of day and places you pick."] = "在末尾新增一条规则，用于你选择的时段和地点。"
L["A new rule for boss fights, first on this tab."] = "新增一条用于首领战的规则，放在此标签页的最前面。"
L["A new script of yours, with a few steps to start from."] = "你自己的新脚本，带几个步骤作为起点。"
L["A pet shows once its health drops below this. 100% shows it at any damage."] = "宠物的生命值低于此值时显示。100%表示受到任何伤害都会显示。"
L["A picture: red with a dark outline, on a flat black band, its own colors."] = "一张图片：红色带深色轮廓，位于扁平的黑色条带上，使用其自身的颜色。"
L["A plate takes its whole look (mark, colors, opacity) from the first row that fits it, top to bottom; the rows below aren't looked at. Click a row to open its settings: its mark, the plate's colors and opacity, and When it fits. The chips beside its name show what's set apart from the usual. Move a row with its arrows, copy it with its two squares, take it off with its x. Add row puts a new one at the end; its Row line says what it's for: a Kind, for Aggro and Units which of them, Who for just its enemies, neutral units or friends, and Distance for just those within or past 11, 28 or 40 yards (Any unit past 40 yards fades far plates). The same kind again is another row of it (Target (2)), say with a different When for raids. Put a row for just some units above its kind's own row, so it comes first for them. Default, always last, is for plates no row fits: the game's look unless you change it."] = "姓名板的整体外观（标记、颜色、不透明度）取自从上到下第一个符合它的行；下面的行不再查看。点击一行可打开其设置：标记、姓名板的颜色和不透明度，以及“符合条件”。名字旁的小标签显示与常规不同的设置。用箭头移动行，用两个方块复制，用 x 删除。“添加行”会在末尾新增一行；其“行”一栏说明它的用途：类别；对于仇恨和单位，指定其中哪些；“对象”只针对敌人、中立单位或友方；“距离”只针对11、28或40码以内或以外的单位（“40码外的任何单位”会淡出远处的姓名板）。同一类别再加一行就是它的另一行（目标 (2)），例如为团队副本设置不同的“符合条件”。把只针对部分单位的行放在其类别自身的行上方，这样对这些单位会优先生效。“默认”总在最后，用于没有任何行符合的姓名板：除非你更改，否则使用游戏的外观。"
L["A player's class icon in place of their face (NPCs keep theirs)."] = "用玩家的职业图标代替其头像（NPC保持原样）。"
L["A pretend 8-second cast, on the screen (close the settings to see it)."] = "屏幕上的一次8秒模拟施法（关闭设置后即可看到）。"
L["A profile of your own, a copy of the active one as you have it now, named after it. To copy another profile, right-click it, then Copy profile."] = "你自己的配置文件，复制当前配置文件的现状，并以其命名。若要复制其他配置文件，请右键点击它，然后选择“复制配置文件”。"
L["A profile of your own, a copy of the active one as you have it now, named after it. To copy another profile, switch to it first."] = "你自己的配置文件，复制当前配置文件的现状，并以其命名。若要复制其他配置文件，请先切换到它。"
L["A profile preview shows just its own frames"] = "配置文件预览只显示它自己的框体"
L["A quest timer is running"] = "任务计时器正在运行"
L["A quiet flat bar: no icon, spark or border, a soft ground, small outlined text."] = "安静的扁平条：没有图标、火花或边框，柔和的底色，小号描边文字。"
L["A ring of color round it."] = "围绕它的一圈颜色。"
L["A round button with a soft glow when ready."] = "圆形按钮，就绪时有柔和光晕。"
L["A scene of your own. Open it to set its triggers, when it ends, and where it comes among the others."] = "你自己的场景。打开它可设置触发条件、何时结束，以及在其他场景中的顺序。"
L["A script holds 80 steps at most."] = "一个脚本最多包含80个步骤。"
L["A set time"] = "固定时间"
L["A shot is one of the cameras that run while you stand still (cozy, vista, fish or AFK) with numbers of your own for how it sways and zooms. Make one here, then pick it as a scene's camera on the Scenes page. A number you haven't changed follows the camera's own settings."] = "机位是你站着不动时运行的镜头之一（温馨、远景、钓鱼或暂离），用你自己的数值决定它如何摇摆和缩放。在这里制作一个，然后在场景页面中把它选为某个场景的镜头。你没有更改的数值会跟随该镜头自身的设置。"
L["A slider changes nothing until you move it. Higher (in gold) costs frame rate, lower (in blue) saves it. Tick and untick a setting to compare it with the game's own; Reset page leaves them all alone again."] = "滑块在你移动之前不会改变任何东西。更高（金色）会降低帧率，更低（蓝色）会提高帧率。勾选和取消勾选一项设置，可与游戏自身的设置比较；“重置本页”会让它们全部恢复不受影响。"
L["A small Reload button at the top of the screen reloads the UI in one click. It stays up with the UI hidden. Drag it to move it. There's a key for it too (Keybinds page)."] = "屏幕顶部的一个小“重载”按钮，一键重载界面。界面隐藏时它仍保持显示。拖动可移动它。它也有对应的按键（按键绑定页面）。"
L["A small icon in the bottom right of a chat window, while your mouse is over it, opens that window's lines as text you can select and copy with Ctrl+C."] = "鼠标悬停在聊天窗口上时，其右下角会出现一个小图标，点击可将该窗口的内容打开为文本，你可以选中并用 Ctrl+C 复制。"
L["A small line low on the screen, where a film's subtitles go."] = "屏幕下方的一小行文字，位于电影字幕的位置。"
L["A soft halo round it."] = "围绕它的柔和光环。"
L["A soft haze around the edges of the screen in the camera modes, as if the camera had focused on you. Each camera mode's page sets its own strength: this turns them all up or down. /cine doftest shows it on demand."] = "在镜头模式中，屏幕边缘的柔和模糊，就像镜头对焦在你身上。每个镜头模式的页面设置各自的强度：此项整体调高或调低。/cine doftest 可随时显示它。"
L["A soft haze around the edges of the screen in this camera mode, as if the camera had focused on you. 0% leaves it off. Moving the slider shows it for a moment. Needs \"Camera haze\" on the Visual Effects page, which also turns it up or down."] = "在此镜头模式中，屏幕边缘的柔和模糊，就像镜头对焦在你身上。0%表示关闭。移动滑块会短暂显示效果。需要开启视觉效果页面的“镜头模糊”，那里也可以整体调高或调低。"
L["A soft haze around the edges of the screen while this camera runs, as if it had focused on you. 0 leaves it off. Needs Camera haze on the Visual Effects page, which also turns it up or down."] = "此镜头运行时屏幕边缘的柔和模糊，就像镜头对焦在你身上。0表示关闭。需要开启视觉效果页面的“镜头模糊”，那里也可以整体调高或调低。"
L["A string of this script to give to friends."] = "可以发给朋友的此脚本字符串。"
L["A style with +2 has two settings of its own over the one it starts from (the Style tab lists them)."] = "带 +2 的风格在其起始风格之上有两项自己的设置（风格标签页会列出）。"
L["A tank (by role, or main tank in a raid) shows once their health drops below this. 100% shows tanks always, at full health too."] = "坦克（按职责，或团队中的主坦克）的生命值低于此值时显示。100%表示坦克始终显示，满血时也会。"
L["A theme of your own, made from the one shown."] = "你自己的主题，基于当前显示的主题制作。"
L["A thick black border around the letters."] = "文字周围的粗黑描边。"
L["A thin black border around the letters."] = "文字周围的细黑描边。"
L["A thin black edge, the icon zoomed in to cut its border, an edge glow when ready, Arial Narrow."] = "细黑边，图标放大以裁掉其边框，就绪时边缘发光，Arial Narrow 字体。"
L["A thin line, no border or spark."] = "细线，没有边框或火花。"
L["A wave of the game's art creeping in from past the edges on each heartbeat (each second without one). With Blizzard art, or a Game art theme."] = "每次心跳（每一秒没有心跳时）游戏美术图案从边缘外缓缓涌入的波浪。需要暴雪美术或游戏美术主题。"
L["A whole look in one pick. Changing a setting after it shows Custom; picking Custom puts back your own settings from before the preset."] = "一次选择整套外观。之后更改任何设置会显示为“自定义”；选择“自定义”会恢复你在使用预设之前的设置。"
L["ANY OF THESE WOULD SHOW IT"] = "以下任一项都会让它显示"
L["Achievement"] = "成就"
L["Across the middle of the screen on a dark band with soft edges, coming in and going slowly, as YOU DIED does."] = "在屏幕中间带柔和边缘的深色条带上，缓慢出现和消失，就像“你死了”一样。"
L["Action bars 1-3"] = "动作条1-3"
L["Add %s"] = "添加%s"
L["Add a rule"] = "添加规则"
L["Add a scene or shot a friend shared (the text from their Share button)."] = "添加朋友分享的场景或机位（他们“分享”按钮中的文本）。"
L["Add a script someone shared with you."] = "添加别人分享给你的脚本。"
L["Add a sound"] = "添加音效"
L["Add a wheel someone shared with you: paste in its text, and read what's on it before you add it."] = "添加别人分享给你的轮盘：粘贴其文本，并在添加前阅读上面的内容。"
L["Add an emote"] = "添加表情"
L["Add an emote: %s"] = "添加表情：%s"
L["Add an icon"] = "添加图标"
L["Add back"] = "加回"
L["Add back all"] = "全部加回"
L["Add it"] = "添加"
L["Add it to the rows below, with its When set to anywhere but battlegrounds and arenas, out of fights (open its row to change that)."] = "将它添加到下方的行中，其“符合条件”设为战场和竞技场以外的任何地方、非战斗中（打开其行可更改）。"
L["Add row"] = "添加行"
L["Add script"] = "添加脚本"
L["Add this zone"] = "添加此区域"
L["Add wheel"] = "添加轮盘"
L["Added"] = "已添加"
L["Addon"] = "插件"
L["Addons installed but not loaded, and the ones supported but not installed."] = "已安装但未加载的插件，以及受支持但未安装的插件。"
L["Adds \"%s\". A green dot: true where you are now."] = "添加“%s”。绿点：在你当前所在的地方为真。"
L["Adds \"%s\": true for a tooltip of this kind (one can be more than one: a quest mob is an enemy too). Anything else: none of the others, and every tooltip of the UI."] = "添加“%s”：对这一类鼠标提示为真（一个提示可以属于多类：任务怪也是敌人）。其他所有：不属于其他任何一类，以及界面的所有鼠标提示。"
L["Adds a row at the end of the grid, for any unit to start with, its settings open: pick what it's for on its Row line, and its look."] = "在表格末尾添加一行，起初适用于任何单位，并打开其设置：在其“行”一栏选择它的用途，以及它的外观。"
L["Adds a theme a friend shared with Share theme."] = "添加朋友用“分享主题”分享的主题。"
L["Adds an icon to the wheel, for a command of its own."] = "向轮盘添加一个图标，对应一个它自己的命令。"
L["After"] = "之后"
L["After a Zone or Subzone card, no other comes for this long, so passing through places quickly doesn't bring one after another. 0: every time."] = "出现区域或子区域卡片后，在这段时间内不会再出现其他卡片，这样快速经过多个地方时不会接连弹出。0：每次都出现。"
L["After a fight"] = "战斗后"
L["After a reload (/reload, the Reload button or its key), what you had open opens again: these settings at the page you were on, your bags, the character window, map, spellbook and the game's other windows, and Cinematic's own."] = "重载后（/reload、“重载”按钮或其按键），你之前打开的东西会重新打开：这些设置及你所在的页面、背包、角色窗口、地图、法术书以及游戏的其他窗口，还有Cinematic自己的窗口。"
L["After swinging behind you, the camera comes round this far to one side, so you see the quest giver past you at an angle rather than straight over your head. 0 stays straight behind you. It turns back behind you as the window closes."] = "转到你身后之后，镜头会向一侧转过这么多角度，这样你会从斜角越过自己看到任务NPC，而不是从头顶正上方看。0 表示保持在你正后方。窗口关闭时它会转回你身后。"
L["After the first pull-back, keep drifting to new random distances (within the limits below), pausing between each. Off: a single pull-back that then holds."] = "第一次拉远后，继续漂移到新的随机距离（在下方的限制内），每次之间暂停。关闭：只拉远一次，然后保持。"
L["After you drag the camera, use camera keys or zoom, this camera waits this long, then carries on from your new view."] = "你拖动镜头、使用镜头按键或缩放后，此镜头会等待这段时间，然后从你的新视角继续。"
L["After you log in or /reload, the camera zooms to the distance below, rather than staying wherever you left it."] = "登录或 /reload 后，镜头会缩放到下方的距离，而不是停留在你离开时的位置。"
L["After you stop turning, the view holds this long before gliding around to your new facing, in case you turn again. Turning again starts the wait over."] = "你停止转向后，视角会保持这段时间，再平滑转到你的新朝向，以防你再次转向。再次转向会重新开始等待。"
L["Aggro"] = "仇恨"
L["Aggro on a healer"] = "治疗者获得仇恨"
L["Aggro on non-tank"] = "非坦克获得仇恨"
L["Aggro on not you"] = "不是你获得仇恨"
L["Aggro on you"] = "你获得仇恨"
L["Align:"] = "对齐："
L["All"] = "全部"
L["All addons"] = "所有插件"
L["All addons %.1f%% (%.3f ms)"] = "所有插件 %.1f%%（%.3f 毫秒）"
L["All addons (the game's figures, ms a frame)"] = "所有插件（游戏的数据，每帧毫秒）"
L["All bosses"] = "所有首领"
L["All changes"] = "所有更改"
L["All marks"] = "所有标记"
L["All of them"] = "全部"
L["All rows"] = "所有行"
L["Along the top"] = "沿顶部"
L["Already on this card (or the card is full). Right-click: play it."] = "已在此卡片上（或卡片已满）。右键点击：播放。"
L["Also for NPCs with nothing to say about quests (innkeepers, guards...), as the \"Talk to a quest giver\" event. Off: only when they have a quest to offer or take in, or a \"(Quest)\" line (the \"Talk about a quest\" event)."] = "也适用于没有任务相关对话的NPC（旅店老板、卫兵……），作为“与任务NPC对话”事件。关闭：只有当他们有任务可接或可交，或有“（任务）”对话选项时（“谈论任务”事件）。"
L["Always backed up just before Delete and Reset, and the saved version on Save."] = "在“删除”和“重置”之前总会备份，“保存”时备份已保存的版本。"
L["Always is ticked"] = "已勾选“始终”"
L["Always is ticked on the Tooltips row"] = "鼠标提示行已勾选“始终”"
L["Always list your own roll"] = "始终列出你自己的掷骰"
L["Always show the waypoint is on"] = "始终显示路径点已开启"
L["Always show their"] = "始终显示他们的"
L["Amber while you're behind, teal once you lead (or your own two)."] = "落后时为琥珀色，领先后为青色（或你自己的两种颜色）。"
L["Amount"] = "数量"
L["An NPC you're talking to (its window open, or closed in the last 30 seconds), your target, or a party NPC talking (their chat bubbles). The camera zooms in and swings toward whoever's talking, drifting while they go on, and turns back once no one's talked for a while. Moving hands the camera straight back to you. Its settings are under Chat Cam on the Camera Settings page."] = "与你对话的NPC（其窗口已打开，或在最近30秒内关闭）、你的目标，或正在说话的小队NPC（其聊天气泡）。镜头会拉近并转向正在说话的人，在对方持续说话时漂移，有一段时间没人说话后转回。移动会立即把镜头交还给你。其设置在镜头设置页面的聊天镜头中。"
L["An addon"] = "插件"
L["An edge"] = "边缘"
L["An icon before the words: each event's own (a map for a zone, a skull for a boss...), unless it's given another with the button beside this."] = "文字前的图标：每个事件自己的图标（区域是地图，首领是骷髅……），除非用旁边的按钮给它换一个。"
L["Animation:"] = "动画："
L["Another of the game's effects over the first, added on as light and cut by the same edge (not over an edge like the red one). Theme's pick: the one picked to go with your theme, if any."] = "在第一个效果之上再叠加游戏的另一个效果，以光的形式叠加，并被同一边缘裁切（不像红色那样叠在边缘上）。主题的选择：为配合你的主题而选的效果（如果有）。"
L["Another thing that starts this scene: any one of its triggers starts it."] = "启动此场景的另一个条件：任一触发条件都能启动它。"
L["Any"] = "任何"
L["Any distance"] = "任何距离"
L["Any distance: all of them, near or far. Within or past 11, 28 or 40 yards: just those that far from you, say Any unit past 40 yards to fade the plates far off. 40 yards asks a 40-yard spell on your action bars; with none there, the row fits no unit past 28 yards."] = "任何距离：所有单位，无论远近。11、28或40码以内或以外：只针对离你那么远的单位，例如“40码外的任何单位”可淡出远处的姓名板。40码需要你的动作条上有一个40码的法术；如果没有，该行不适用于28码外的任何单位。"
L["Any edge"] = "任何边缘"
L["Any enemy attacking a healer (you too, if you're one): for a healer, who's after you or the other healers; for a tank, the ones to pull off them."] = "攻击治疗者（如果你是治疗者，也包括你）的任何敌人：对治疗者来说，是追着你或其他治疗者的敌人；对坦克来说，是要从他们身上拉走的敌人。"
L["Any enemy attacking a player who isn't a tank (you too, unless you're one): for a healer, who's in trouble; for a tank, the ones to taunt. A pet tanking doesn't count."] = "攻击非坦克玩家（除非你是坦克，否则也包括你）的任何敌人：对治疗者来说，是陷入危险的人；对坦克来说，是要嘲讽的敌人。宠物坦怪不算。"
L["Any enemy attacking you (you have its aggro). Above the Target row, or that one wins on your target. A cell set to Your target's takes the Target row's; change it to set this one apart."] = "攻击你的任何敌人（你拥有它的仇恨）。放在目标行上方，否则在你的目标上以目标行为准。设为“你目标的”的单元格会采用目标行的设置；更改它可让此行与之不同。"
L["Any enemy in a fight attacking someone friendly other than you: a group member, a pet or another player. For a tank, the ones to pick up."] = "战斗中攻击你以外的友方单位的任何敌人：队伍成员、宠物或其他玩家。对坦克来说，是要接过来的敌人。"
L["Any enemy in a fight attacking whoever its ticks say: you or someone friendly other than you, and their role (no role set counts as DPS; a pet only with all three roles ticked)."] = "战斗中攻击其勾选项所指对象的任何敌人：你或你以外的友方单位，以及他们的职责（未设职责算作输出；宠物只在三种职责都勾选时才算）。"
L["Any fight"] = "任何战斗"
L["Any living NPC, normal or elite."] = "任何活着的NPC，普通或精英。"
L["Any time"] = "任何时候"
L["Any unit"] = "任何单位"
L["Anyone"] = "任何人"
L["Anything a player controls: pets, totems and guardians."] = "任何由玩家控制的单位：宠物、图腾和守护者。"
L["Anything else"] = "其他任何"
L["Anything targeted"] = "任何被选中的目标"
L["Arcade"] = "街机"
L["Arenas"] = "竞技场"
L["Arrived"] = "已抵达"
L["Arrow"] = "箭头"
L["Arrows and bullets at a vendor get a Fill button: it buys enough to fill your quiver or ammo pouch, topping up its part stacks and filling its empty slots, as far as your money goes. Point at it to see how many and the cost first."] = "商人处的箭和子弹会多出一个“装满”按钮：它会购买足够的数量来装满你的箭袋或弹药袋，补满未满的堆叠并填满空格，以你的金钱为限。先把鼠标指向它，可以看到数量和花费。"
L["Art"] = "美术"
L["As NPCs talk near you, the camera zooms in and swings toward whoever's talking (by their chat bubble), drifting slowly while they go on. It swings again only when someone else speaks, and turns back and zooms out once no one's talked for a while. Moving, or moving the camera yourself, hands it straight back to you."] = "当NPC在你附近说话时，镜头会拉近并转向正在说话的人（根据其聊天气泡），在对方持续说话时缓慢漂移。只有当另一个人说话时才会再次转向，有一段时间没人说话后会转回并拉远。移动或自己移动镜头会立即把镜头交还给你。"
L["As Roll Vision has always looked (the defaults)."] = "与 Roll Vision 一直以来的外观相同（默认值）。"
L["As a fight starts or as it ends. Click to switch."] = "战斗开始时或结束时。点击切换。"
L["As it always has, in its own look (the Style tab)."] = "与一直以来相同，使用它自己的外观（风格标签页）。"
L["As it comes: amber when you're behind, teal when you lead, a thin border."] = "原样：落后时为琥珀色，领先时为青色，细边框。"
L["As it comes: nothing changed."] = "原样：不做任何更改。"
L["As it shows"] = "按显示的"
L["As it starts, the camera rises this much to look down on your body; it comes back down afterwards. The game stops it just short of straight down, so a big number means \"as high as it goes\". 0 keeps your angle."] = "开始时镜头会升高这么多来俯视你的尸体；之后再降回来。游戏会让它停在接近垂直向下之前，所以很大的数值意味着“升到最高”。0 表示保持你的角度。"
L["As it swings round, the camera also comes down this much toward the ground, so it feels low and close rather than looking down from above. It stops at the ground, so a big number just means \"as low as it goes\". 0 keeps your angle."] = "转动时镜头也会向地面降低这么多，让画面显得低而贴近，而不是从上方俯视。它会停在地面，所以很大的数值只意味着“降到最低”。0 表示保持你的角度。"
L["As little UI as possible: nameplates show only for enemies in fights, and fights don't bring the letterbox down. Fights bring up only your resource bar and the Cooldown Manager, the cast bar shows all through CineMode, your health shows at the screen's edges and your personal resource display fades in as it drops (Vitals Vision), and every camera can start music."] = "尽可能少的界面：姓名板只在战斗中为敌人显示，战斗也不会收起宽银幕黑边。战斗只会调出你的资源条和冷却管理器，施法条在整个CineMode期间显示，你的生命值显示在屏幕边缘，个人资源显示会随生命值下降而淡入（Vitals Vision），每个镜头都可以播放音乐。"
L["As the Style hub's General page says."] = "按照风格中心的常规页面。"
L["As the Visions hub's Style page says."] = "按照 Visions 中心的风格页面。"
L["As the boss is pulled, as it dies or as your group wipes. Click to switch."] = "首领被拉住时、死亡时或你的队伍团灭时。点击切换。"
L["As the card shows."] = "按卡片显示的。"
L["As the game's options say (class colors, or green)."] = "按照游戏选项（职业颜色或绿色）。"
L["As you cast your Hearthstone, Astral Recall or a teleport, a portal's glowing rim closes in around you, brighter and turning quicker as the cast fills, and flashes as you're whisked away. It shows whenever the tele camera would play for that cast (Cameras), with or alongside it."] = "当你使用炉石、星界传送或传送法术时，传送门发光的边缘会向你收拢，随着施法进度越来越亮、转得越来越快，并在你被传送走时闪光。只要传送镜头会为这次施法播放（镜头页面），它就会显示，可与镜头一起或单独出现。"
L["As you land, the camera glides back to the zoom distance you had when you took off. If you zoomed yourself on the way, it stays where you put it."] = "降落时，镜头会平滑恢复到你起飞时的缩放距离。如果你在途中自己缩放过，它会保持在你调整的位置。"
L["At full"] = "满值时"
L["At most this many rows: #1 on down, and you in the last row if you're further down than that."] = "最多显示这么多行：从第1名往下，如果你的排名更靠后，则在最后一行显示你。"
L["At the start of a fight"] = "战斗开始时"
L["Auras"] = "光环"
L["Auras anchored to another frame fade with that frame."] = "锚定在其他框体上的光环会随该框体一起淡出。"
L["Auto"] = "自动"
L["Auto (%s)"] = "自动（%s）"
L["Auto-running. The camera's settings are under Auto-run Cam on the Camera Settings page."] = "自动奔跑。镜头设置在镜头设置页面的自动奔跑镜头中。"
L["Auto-walking (auto-run in walk mode). The camera's settings are under RP Walk Cam on the Camera Settings page."] = "自动行走（行走模式下的自动奔跑）。镜头设置在镜头设置页面的RP漫步镜头中。"
L["Automatic"] = "自动"
L["Average"] = "平均"
L["Away"] = "离开"
L["BG objectives"] = "战场目标"
L["Back as it comes:"] = "恢复原样："
L["Back to every card's row."] = "恢复为每张卡片的行。"
L["Back to its own settings"] = "恢复为它自己的设置"
L["Back to its style:"] = "恢复为它的风格："
