L["Battleground"] = "战场"
L["Battleground assaults, captures and flags."] = "战场中的突袭、占领和旗帜。"
L["Beats a minute as they start"] = "开始时每分钟心跳数"
L["Beats a minute at full"] = "满值时每分钟心跳数"
L["Before delete"] = "删除前"
