L["Behind and ahead"] = "落后和领先"
L["Behind the bar"] = "条后方"
L["Behind the bar:"] = "条后方："
L["Behind the words:"] = "文字后方："
L["Beside the game's roll frames"] = "在游戏掷骰框旁"
L["Big words"] = "大字"
L["Big words across the middle of the screen on a dark band, as YOU DIED shows: a win in gold, a loss in red (the Victory and Death styles' looks)."] = "屏幕中间深色条带上的大字，与“你死了”的显示方式相同：胜利为金色，失败为红色（胜利和死亡风格的外观）。"
L["Big words in the middle of the screen, the rest under them."] = "屏幕中间的大字，其余内容在下方。"
L["Black"] = "黑色"
L["Black edges"] = "黑色边缘"
L["Black edges closing in from the screen's sides as the cast fills, then over the whole screen at the last moment."] = "随着施法进度，黑色边缘从屏幕两侧向内收拢，在最后一刻覆盖整个屏幕。"
L["Blackout"] = "黑屏"
L["Blank: never shown."] = "留空：从不显示。"
L["Blizzard art assets"] = "暴雪美术资源"
L["Bloodsail Buccaneers"] = "血帆海盗"
L["Blows toward your waypoint for 30 seconds (or, with none, a pretend one off to your right: turn toward it and the wind follows). It works with the page off too. Close the settings to see it."] = "朝你的路径点吹30秒（如果没有路径点，则朝你右侧一个假想的点吹：转向它，风也会跟着转）。即使页面关闭也有效。关闭设置后即可看到。"
L["Blue"] = "蓝色"
L["Blue, as the game's names over their heads (green while they're PvP flagged, as there too)."] = "蓝色，与游戏中他们头顶的名字相同（处于PvP状态时为绿色，也与那里相同）。"
L["Bold"] = "粗体"
L["Border"] = "边框"
L["Border:"] = "边框："
L["Borderless flat bars in class colors, small white names."] = "职业颜色的无边框扁平条，白色小号名字。"
L["Borderless flat bars on a faint ground, small names."] = "淡色底上的无边框扁平条，小号名字。"
L["Boss"] = "首领"
L["Boss %d"] = "首领%d"
L["Boss %d of %d"] = "首领 %d/%d"
L["Boss fight"] = "首领战"
