L["Boss targeted"] = "已选中首领"
L["Bosses"] = "首领"
L["Bosses %d%%   Not bosses %d%%"] = "首领 %d%%   非首领 %d%%"
L["Bosses down"] = "已击败首领"
L["Both"] = "两者"
L["Both names as the duel is accepted and its countdown starts."] = "决斗被接受、开始倒计时时显示双方名字。"
L["Bottom"] = "底部"
L["Bottom letterbox bar"] = "底部宽银幕黑边"
L["Brackets"] = "括号"
L["Brightness"] = "亮度"
L["Bring back a built-in scene you deleted, with its settings as they were."] = "恢复你删除的内置场景，设置保持原样。"
L["Brings up the window with three made-up drops, your group picking and rolling on them over a few seconds. Change things here while it's up to see them."] = "打开窗口并显示三件模拟掉落，你的队伍在几秒钟内对它们进行选择和掷骰。在它显示时更改这里的设置即可看到效果。"
L["Bubble"] = "气泡"
L["Bubble:"] = "气泡："
L["Buff on you"] = "你身上的增益效果"
L["Buff: %s"] = "增益效果：%s"
L["Buffs not in the Cooldown Manager now"] = "当前不在冷却管理器中的增益效果"
L["Building detail distance"] = "建筑细节距离"
L["Built in"] = "内置"
L["Built in, changed by you: change anything. Reset puts ours back. The camera itself still runs on its own code: set a row to this script to use it instead."] = "内置，已被你更改：可更改任何内容。“重置”会恢复我们的版本。镜头本身仍运行它自己的代码：把某行设为此脚本即可改用它。"
L["Built in, from your settings: change anything, and it's kept as yours of it (Reset puts ours back). The camera itself still runs on its own code: set a row to this script to use it instead."] = "内置，来自你的设置：可更改任何内容，更改后会作为你的版本保存（“重置”会恢复我们的版本）。镜头本身仍运行它自己的代码：把某行设为此脚本即可改用它。"
L["Built in:"] = "内置："
L["Built-in camera"] = "内置镜头"
L["Button"] = "按钮"
L["Buttons"] = "按钮"
L["Buys %d for %s."] = "购买%d个，花费%s。"
L["By %s"] = "按%s"
L["By reaction"] = "按关系"
L["By role (healing for healers)"] = "按职责（治疗者为治疗量）"
L["By where it's moved to"] = "按移动到的位置"
L["CPU recording done"] = "CPU记录完成"
L["CPU recording done (%.3f ms a frame measured): see the %s page."] = "CPU记录完成（测得每帧%.3f毫秒）：请查看%s页面。"
L["CPU recording for %d seconds: play as usual."] = "CPU记录%d秒：照常游戏即可。"
L["Calendar"] = "日历"
L["Calls a frame"] = "每帧调用"
L["Calm Timer is ticked, and a fight just ended"] = "已勾选“平静计时”，且战斗刚刚结束"
L["Calm Timer is ticked: it stays a while after a fight"] = "已勾选“平静计时”：战斗后会保持一段时间"
L["Camera and nameplates"] = "镜头和姓名板"
L["Camera haze"] = "镜头模糊"
L["Camera settings that aren't on the Scripts page yet, a tab for each camera that has some. The rest of each camera's settings are on the Scripts page, under the steps they make; the Scenes page has what starts each one."] = "尚未移到脚本页面的镜头设置，每个有此类设置的镜头一个标签页。每个镜头的其余设置在脚本页面上，位于它们生成的步骤下方；场景页面中设置启动每个镜头的条件。"
L["Camera: %s"] = "镜头：%s"
L["Cameras"] = "镜头"
