L["Campfire names:"] = "篝火名称："
L["Can now reach %d"] = "现在可达%d"
L["Can't be interrupted"] = "无法打断"
L["Can't find them now: target them, or get them on screen, to see their talents."] = "现在找不到他们：选中他们，或让他们出现在屏幕上，才能查看他们的天赋。"
L["Can't inspect them from here: too far away, or gone."] = "无法从这里观察他们：距离太远，或已离开。"
L["Can't: %s. Open the rule to change it, or Reset to grid there."] = "无法：%s。打开规则进行更改，或在那里“重置为表格”。"
L["Cancel"] = "取消"
L["Card Types"] = "卡片类型"
L["Card Vision"] = "Card Vision"
L["Card size"] = "卡片大小"
L["Cards"] = "卡片"
L["Cards on:"] = "卡片位置："
L["Carets"] = "尖角"
L["Cast %s"] = "施放%s"
L["Cast Bars"] = "施法条"
L["Cast Fishing (or any event set to it on the Scenes page): the vista camera, made for fishing. The camera glides around behind you and sways only a little either side, so your bobber stays in view. It carries on after the cast until you move or jump."] = "施放钓鱼（或在场景页面中设为它的任何事件）：远景镜头，专为钓鱼设计。镜头会平滑转到你身后，只向两侧轻微摇摆，让你的鱼漂保持在视野中。施法结束后会继续，直到你移动或跳跃。"
L["Cast bar is the bar under the target and focus frames as they cast."] = "施法条是目标和焦点框体施法时其下方的条。"
L["Cast bar style"] = "施法条风格"
L["Casting your Hearthstone or a teleport, the camera swings round in front of you, quickly enough to be there before you go, then spins around you faster and faster as it zooms in. Cancel the cast and it goes back to where it was; once you're there, it swings around behind you. Its music, haze and tooltips follow the Cozy Cam's settings. The events on the Scenes page can also make it wait a moment."] = "使用炉石或施放传送法术时，镜头会转到你前方，速度足够快，赶在你被传送走之前到位，然后一边拉近一边围着你越转越快。取消施法，它会回到原来的位置；抵达后，它会转到你身后。它的音乐、模糊和鼠标提示按照温馨镜头的设置。场景页面中的事件也可以让它稍等片刻。"
L["Center"] = "居中"
L["Challenges you to a duel"] = "向你发起决斗"
L["Change icon"] = "更改图标"
