L["Change time"] = "更改时间"
L["Changed: %s."] = "已更改：%s。"
L["Changes go in your profile %s."] = "更改会保存在你的配置文件%s中。"
L["Changes go in your profile %s. This part is a mix of its own."] = "更改会保存在你的配置文件%s中。此部分是它自己的混合设置。"
