L["Clean Up Bags leaves the part stack of arrows or bullets last, but you shoot from the first stack, so a full one would run down and leave you with two part stacks. Once the bags are cleaned up, the smallest stack is moved first, to be shot first."] = "“整理背包”会把未满的箭或子弹堆叠放在最后，但你射击时从第一个堆叠开始用，所以满的那组会先用掉，最后留下两个未满的堆叠。整理完背包后，最小的堆叠会被移到最前面，以便先用掉。"
L["Clear"] = "清除"
