L["Clear the Profiler's graph and its last recording, here and in what's saved? (The game's own figures for each addon start again only when the game does.)"] = "清除性能分析器的图表和上次记录，包括此处和已保存的数据？（游戏自身对每个插件的统计只有在游戏重新启动时才会重新开始。）"
L["Cleared"] = "已清除"
L["Clears the graph's samples and the last recording, here and in what's saved."] = "清除图表的采样和上次记录，包括此处和已保存的数据。"
L["Clears this shot's numbers, so each follows its camera's own setting again."] = "清除此机位的数值，让每一项重新跟随其镜头自身的设置。"
L["Click a group's icon below to go to it, or the + to make one of your own."] = "点击下方分组的图标前往该分组，或点击 + 创建你自己的分组。"
L["Click a line to open its setting. Click another frame to look at it."] = "点击一行打开其设置。点击另一个框体查看它。"
