L["Dawn, Morning, Midday, Afternoon, Evening, Dusk or Night as you log in or reload: over the name on this card, or under the game's zone name with Zone unticked. Follows the clock picked on the Tint page."] = "登录或重载时显示黎明、上午、正午、下午、傍晚、黄昏或夜晚：在此卡片的名字上方，或者在未勾选“区域”时位于游戏区域名称下方。按照色调页面所选的时钟。"
L["Day/night dial"] = "昼夜表盘"
L["Dead"] = "死亡"
L["Dead members are hidden whatever their health, debuffs or role (unless one is your target). How much of them still shows. 0% hides them completely."] = "死亡的成员无论生命值、减益效果或职责如何都会隐藏（除非是你的目标）。此值决定他们仍显示多少。0%表示完全隐藏。"
L["Dead opacity"] = "死亡时不透明度"
L["Death banner:"] = "死亡横幅："
L["Deaths"] = "死亡次数"
L["Debuffs that last longer than this (their full time, not what's left: Deserter, Resurrection Sickness...) don't bring them up, nor keep them up until gone. Not in fights, when what they are can't be seen. Buffs always do."] = "持续时间超过此值的减益效果（按其总时长，而非剩余时间：逃亡者、复活虚弱……）不会让它们出现，也不会让它们保持显示直到消失。战斗中不适用，因为那时无法得知它们是什么。增益效果总是会。"
L["Default"] = "默认"
L["Defeat"] = "失败"
L["Delete the camera %s? Scenes set to it go back to no camera."] = "删除镜头%s？设为它的场景会改为无镜头。"
L["Delete the scene %s and its settings?"] = "删除场景%s及其设置？"
L["Delete the scene %s? It starts no camera until you bring it back with Add back, above the rows (its settings are kept)."] = "删除场景%s？在你用行上方的“加回”恢复之前，它不会启动任何镜头（其设置会保留）。"
L["Delete the shot %s? Scenes that played it go back to its camera."] = "删除机位%s？播放它的场景会改回其镜头。"
L["Delete the theme %s?"] = "删除主题%s？"
L["Delete the wheel %s?"] = "删除轮盘%s？"
L["Delete this scene of your own, with its copies."] = "删除你自己的这个场景及其副本。"
L["Delete this scene: its rows go and it starts no camera. Add back, above the rows, brings it back with its settings."] = "删除此场景：其行会移除，且不再启动任何镜头。行上方的“加回”可连同其设置一起恢复。"
L["Delete this shot. Scenes that played it go back to its camera."] = "删除此机位。播放它的场景会改回其镜头。"
L["Delete wheel"] = "删除轮盘"
L["Deleted"] = "已删除"
L["Deleted %s, kept until %s"] = "已删除%s，保留至%s"
L["Deletes this script (click twice). Rows set to it go back to no camera."] = "删除此脚本（点击两次）。设为它的行会改为无镜头。"
L["Deletes this theme of yours."] = "删除你的这个主题。"
L["Deletes this wheel, and takes its keys off."] = "删除此轮盘，并解除其按键绑定。"
L["Departing"] = "出发"
L["Describe the camera:"] = "描述镜头："
L["Detailed"] = "详细"
L["Detailed CPU recording  %d:%02d"] = "详细CPU记录  %d:%02d"
L["Detailed CPU recording for %d seconds: play as usual."] = "详细CPU记录%d秒：照常游戏即可。"
L["Details"] = "详情"
L["Dialogue"] = "对话"
L["Diamond"] = "菱形"
L["Dim"] = "暗淡"
L["Discovered"] = "已发现"
L["Do /%s"] = "执行 /%s"
L["Dock"] = "停靠"
L["Dots:"] = "圆点："
L["Drag over the lines you want (or Select all), then press Ctrl+C to copy them."] = "拖动选中你想要的行（或点击“全选”），然后按 Ctrl+C 复制。"
L["Drag to move it."] = "拖动可移动它。"
L["Dragging the window moves only it, not the game's roll frames, and dragging those moves only them, so the two can sit anywhere on the screen. The window comes up where you last dropped it. Until you've dragged it, it comes up by the game's roll frames as usual. Its dragging works even with \"Drag windows to move them\" off."] = "拖动此窗口只会移动它，不会移动游戏的掷骰框；拖动掷骰框也只会移动它们，所以两者可以放在屏幕上的任何位置。窗口会出现在你上次放下它的位置。在你拖动它之前，它会照常出现在游戏的掷骰框旁。即使“拖动窗口来移动它们”已关闭，它也可以拖动。"
L["Drifting gas"] = "飘散的气体"
L["Drops the rule: its ticks, as they were, decide again."] = "放弃规则：由其勾选项（保持原样）重新决定。"
L["Drops the rule: the row's dropdowns decide again, ticked as they were before."] = "放弃规则：由该行的下拉菜单重新决定，勾选状态与之前相同。"
L["Duel"] = "决斗"
L["Duel Vision"] = "Duel Vision"
L["Duel Vision test: not shown now (%s)."] = "Duel Vision 测试：现在不显示（%s）。"
L["Duel starts"] = "决斗开始"
L["Dungeon"] = "地下城"
L["Dungeon done"] = "地下城完成"
L["Dungeon line"] = "地下城行"
L["Dungeons & raids"] = "地下城和团队副本"
L["Dying while a boss fight is on, you keep your own view to watch the rest of it. The death camera starts once the encounter ends (a kill or a wipe), if you're still dead."] = "首领战进行中死亡时，你会保持自己的视角来观看剩下的战斗。如果你在战斗结束（击杀或团灭）时仍处于死亡状态，死亡镜头才会启动。"
L["Dying, until you release or are resurrected. The camera's settings are under Death Cam on the Camera Settings page."] = "死亡，直到你释放灵魂或被复活。镜头设置在镜头设置页面的死亡镜头中。"
L["Each Vision's own"] = "每个 Vision 自己的"
L["Each bar a share of the screen's height."] = "每个条占屏幕高度的一部分。"
L["Each dot its player's class icon."] = "每个圆点为对应玩家的职业图标。"
L["Each event's card on or off, and where it shows."] = "每个事件的卡片开关及其显示位置。"
L["Each fight"] = "每场战斗"
L["Each line slides up from below the bottom of the screen, as if from behind the camera, instead of just fading in."] = "每一行从屏幕底部下方向上滑入，就像从镜头后方出现一样，而不只是淡入。"
L["Each moment's card has a button for each emote under it, in that order. Untick a moment for no card at all. + opens a moment."] = "每个时刻的卡片下方都有对应每个表情的按钮，按此顺序排列。取消勾选一个时刻则完全不显示卡片。+ 可打开一个时刻。"
L["Each move also tilts the camera to a random angle between the down and up limits. 0 on both keeps it level."] = "每次移动还会把镜头倾斜到上下限之间的一个随机角度。两者都为0时保持水平。"
L["Each page as its own defaults have it (the game's look)."] = "每个页面按其自身的默认设置（游戏的外观）。"
L["Each player's number at the end of their row once the game reveals the rolls. Unticked: just who won."] = "游戏公布掷骰结果后，在每个玩家所在行的末尾显示其点数。未勾选：只显示谁赢了。"
L["Each row is a scene: when one of its triggers happens, it plays its camera. When two scenes are on at once, a Hearthstone or teleport cast comes first, then logging out, going AFK, the latest emote, a drawn weapon, a campfire, and standing still last. Click a row to open its settings: its camera, Music and CineMode, When it may start, its triggers, and anything it needs. The chips beside its name show what's set apart from the usual. Where its When doesn't fit, a row starts no camera. Untick the box at the start of a row to turn it off for now."] = "每一行是一个场景：当其触发条件之一发生时，就播放它的镜头。当两个场景同时生效时，使用炉石或施放传送法术最优先，然后是登出、暂离、最近的表情、拔出武器、篝火，站着不动排在最后。点击一行可打开其设置：其镜头、音乐和CineMode、何时可以启动、其触发条件以及它需要的任何东西。名字旁的小标签显示与常规不同的设置。在其“符合条件”不满足的地方，该行不会启动任何镜头。取消勾选行首的复选框可暂时关闭它。"
L["Each time the camera starts, it picks clockwise or anticlockwise at random (and keeps to it until it stops)."] = "每次镜头启动时，随机选择顺时针或逆时针（并保持到停止为止）。"
L["Earlier around the wheel (the first is at the top)."] = "在轮盘上更靠前（第一个在顶部）。"
L["Edge darkness"] = "边缘暗度"
L["Edge pulse"] = "边缘脉动"
L["Edge reach"] = "边缘范围"
L["Edge:"] = "边缘："
L["Edges creep in over"] = "边缘涌入用时"
L["Edges lift as you near your body"] = "接近尸体时边缘褪去"
L["Edges reach in"] = "边缘涌入范围"
L["Edit"] = "编辑"
L["Edit Mode keeps its old list of layouts until you reload, and saving there before then would undo this. Reload now?"] = "编辑模式在你重载之前会保留旧的布局列表，在此之前在那里保存会撤销这一更改。现在重载吗？"
L["Edit as a rule"] = "作为规则编辑"
L["Edit style"] = "编辑风格"
L["Editing"] = "编辑中"
L["Edwin VanCleef"] = "艾德温·范克里夫"
L["Elite NPC"] = "精英NPC"
L["Elite near (11 yards)"] = "附近有精英（11码）"
L["Elite near (28 yards)"] = "附近有精英（28码）"
L["Elite near (40 yards)"] = "附近有精英（40码）"
L["Elite/rare icon"] = "精英/稀有图标"
L["Emote"] = "表情"
L["Emote Vision"] = "Emote Vision"
L["Emote Vision test: you'd %s %s."] = "Emote Vision 测试：你会%s%s。"
L["Emote Vision:"] = "Emote Vision："
L["Emotes (someone's /point, an NPC that laughs or looks around) never have a bubble: they show with the off-screen bubbles too, in a bubble with no tail so they don't read as speech, instead of bringing up chat."] = "表情（某人的 /point、发笑或四处张望的NPC）从来没有气泡：它们也会和屏幕外的气泡一起显示，使用没有尾巴的气泡，以免被当成说话，而不会调出聊天框。"
L["Emotes: the command, with or without its slash. Spells and buffs: the name in your game language, or a spell ID (works in any language). Places: the zone or subzone name as the game shows it."] = "表情：命令，带或不带斜杠均可。法术和增益效果：游戏语言中的名称，或法术ID（适用于任何语言）。地点：游戏中显示的区域或子区域名称。"
L["Empties the rule."] = "清空规则。"
L["Empty: its ticks decide."] = "留空：由其勾选项决定。"
L["Enable Cameras"] = "启用镜头"
L["Enable Style"] = "启用风格"
L["Enable Visual Effects"] = "启用视觉效果"
L["Encounter"] = "首领战"
L["Encounter bar"] = "首领战条"
L["Ending"] = "结束"
L["Ends"] = "结束"
L["Enemy"] = "敌人"
L["Enemy targeted"] = "已选中敌人"
L["Entering combat"] = "进入战斗"
L["Epic and up"] = "史诗及以上"
L["Essential"] = "核心"
L["Essential Cooldowns"] = "核心冷却"
L["Essential: stay up while a cooldown is recharging"] = "核心：冷却恢复中时保持显示"
L["Event boxes (top of the screen)"] = "事件框（屏幕顶部）"
L["Events"] = "事件"
L["Every Style page at once: a switch for them all, and the settings they share. Each page's shared settings start on General and follow it; change one on its page and it's that page's own."] = "一次设置所有风格页面：一个总开关，以及它们共享的设置。每个页面的共享设置以“常规”为起点并跟随它；在某页面更改一项后，它就成为该页面自己的设置。"
L["Every Vision's words bigger or smaller, times each one's own size on its page (cards too)."] = "所有跟随此设置的 Vision 文字放大或缩小，再乘以每个 Vision 在其页面上的大小（卡片也是）。"
L["Every Vision's words that follow this page. Each Vision's own: the game's font, or the one its page starts with."] = "所有跟随本页面的 Vision 文字。每个 Vision 自己的：游戏字体，或其页面初始使用的字体。"
L["Every camera's settings are on the Scripts page now."] = "现在每个镜头的设置都在脚本页面上。"
L["Every camera, built in and yours: click to pick another."] = "所有镜头，内置的和你的：点击选择其他镜头。"
L["Every camera, made of small steps: rotate, tilt, zoom, sway, wait, and Together and Repeat for steps at once or again. Stop rules say what happens when you move the camera, walk, zoom, a fight starts or its trigger ends. The built-in ones are our own cameras' steps, with your settings: set a row on the Scenes page to one to run it instead of the camera, or Copy it to make it yours. A hollow dot: that camera isn't a script yet."] = "每个镜头都由小步骤组成：旋转、倾斜、缩放、摇摆、等待，以及用于同时执行或重复执行步骤的“同时”和“重复”。停止规则决定你移动镜头、行走、缩放、战斗开始或其触发条件结束时会发生什么。内置的脚本是我们自己镜头的步骤，带有你的设置：在场景页面中把某行设为其中一个，即可用它代替原镜头运行，或复制它使其成为你的。空心圆点：该镜头还不是脚本。"
L["Every card's words bigger or smaller, for a big or wide screen (a card in a letterbox bar goes by the bar's height instead)."] = "所有卡片的文字放大或缩小，适用于大屏或宽屏（位于宽银幕黑边中的卡片则按黑边的高度）。"
L["Every change made to Cinematic, newest first, as written when it was made (in English)."] = "Cinematic的每一次更改，最新的在前，保持当时的原文（英文）。"
L["Every fight"] = "每场战斗"
L["Every kind of cast bar looks as this tab says until its own tab has Use default settings unticked."] = "每种施法条的外观都按此标签页设置，除非其自己的标签页取消勾选了“使用默认设置”。"
L["Every moment that puts words on your screen, as a card: going into a fight and coming out of it, a boss, a new zone, what you did last time, the time of day, a place under attack, a duel, your death. A row for each: its tick, the style it uses and where it shows; click it for its settings. How they look: the Style tab. One card at a time: a more important one cuts in, a less important one waits for it."] = "每个在你屏幕上显示文字的时刻，都以卡片形式出现：进入战斗和脱离战斗、首领、新区域、你上次做了什么、时段、某地遭到攻击、决斗、你的死亡。每个时刻一行：其勾选框、使用的风格和显示位置；点击可打开其设置。外观：风格标签页。一次只显示一张卡片：更重要的会插队，次要的会等待。"
L["Every moment's emotes as they come."] = "每个时刻的表情按原样。"
L["Every other plate, when no row above fits it: the game's own look to start with (no mark, its own colors). Give it a mark or an Also color to change them all."] = "上方没有任何行符合的其他所有姓名板：起初为游戏自身的外观（没有标记，使用其自身的颜色）。给它一个标记或“附加”颜色即可全部更改。"
L["Every page's bars that follow General. The game's: each page's own. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "所有跟随“常规”的页面的条。游戏自带：每个页面自己的。在游戏自带的几种之下：其他插件共享的任何材质（通过 LibSharedMedia）。"
L["Every page's words that follow General. The game's: each page's own. Russian, Korean or Chinese text keeps the game's, so its letters show."] = "所有跟随“常规”的页面的文字。游戏自带：每个页面自己的。俄文、韩文或中文文本保持使用游戏字体，以便正确显示字符。"
L["Every part below is Cinematic's own code: an addon can only time its own. For other addons, see All addons above."] = "下方的每个部分都是Cinematic自己的代码：插件只能为自己计时。其他插件请查看上方的“所有插件”。"
L["Every plate's, those no row fits too, times its row's own. When they show is the Target Indicator row's, as the rows'."] = "每个姓名板的（包括没有任何行符合的），再乘以其所在行自己的值。显示时机与各行一样，取决于目标指示器行。"
L["Every plate: NPCs, players and minions."] = "每个姓名板：NPC、玩家和仆从。"
L["Every tooltip: units, things in the world and the UI's (action bars, bags, menus and the rest)."] = "每个鼠标提示：单位、世界中的物体以及界面的提示（动作条、背包、菜单等）。"
L["Every way to style this part, in a panel beside the settings. Pop out to drag it anywhere; Escape or its X closes it."] = "设置此部件风格的所有方式，在设置旁的面板中。弹出后可拖到任何位置；按 Esc 或点击其 X 关闭。"
L["Every wheel back on the master wheel, in their usual order (your own wheels off it)."] = "所有轮盘回到主轮盘上，按通常的顺序（你自己的轮盘不在其中）。"
L["Everyone passed"] = "所有人都放弃了"
L["Everything at once, bars and words."] = "一次设置所有内容，包括条和文字。"
L["Everything here as text, to copy and send us (on Discord, or in a bug report): your game version, the graph's figures, every addon's and the last recording. It's in English, for us to read."] = "此处所有内容以文本形式呈现，可复制后发给我们（在 Discord 上，或在错误报告中）：你的游戏版本、图表数据、每个插件的数据以及上次记录。内容为英文，便于我们阅读。"
L["Everything here is hidden in CineMode unless ticked. Always shows a frame the whole time; its Fights dropdown, only while you fight or have something targeted; its Places dropdown, the whole time while you're there (Grouped: in a party or raid). Edit turns a row into a rule, for AND, NOT and more places. Frames fade in and out at the fade times on the CineMode page. Other addons' frames are on the Addon Frames page."] = "除非勾选，否则此处所有内容在CineMode中都会隐藏。“始终”让框体一直显示；其“战斗”下拉菜单：只在你战斗或选中目标时显示；其“地点”下拉菜单：只要你在那里就一直显示（组队时：在小队或团队中）。“编辑”会把一行变成规则，可使用 AND、NOT 和更多地点。框体按CineMode页面上的淡入淡出时间淡入和淡出。其他插件的框体在插件框体页面。"
L["Exalted"] = "崇拜"
L["Exit CineMode while a vendor, bank, mailbox, class trainer, trade or auction house window is open. When off, the window still shows but the rest stays hidden."] = "打开商人、银行、邮箱、职业训练师、交易或拍卖行窗口时退出CineMode。关闭时，窗口仍会显示，但其余部分保持隐藏。"
L["Exit CineMode while the spellbook, character sheet, talents, macros, key bindings or these options are open. When off, the window still shows but the rest stays hidden."] = "打开法术书、角色面板、天赋、宏、按键设置或这些选项时退出CineMode。关闭时，窗口仍会显示，但其余部分保持隐藏。"
