L["Flash: the icon flashes for a few seconds as its cooldown ends, shown then even if its setting has it faded."] = "闪光：冷却结束时图标闪烁几秒，即使其设置让它淡出，此时也会显示。"
L["Flashes every icon in the Essential and Utility bars once, in this style."] = "以此风格让核心和辅助技能条中的每个图标闪烁一次。"
