L["Frame:"] = "框架："
L["Framed like the game's extra ability button (the defaults)."] = "像游戏的额外技能按钮一样带框（默认值）。"
L["Frames where the addon took over 5 ms, and their share of all frames."] = "插件耗时超过5毫秒的帧，以及它们在所有帧中的占比。"
