L["Friendly player"] = "友方玩家"
L["Friendly players around you duel for 30 seconds, in pretend: their nameplates, made-up crowd control, and winners and losers, to see how it looks. Needs CineMode and other players nearby. Clicking Stop ends it."] = "你周围的友方玩家进行30秒的模拟决斗：显示他们的姓名板、模拟的控制效果以及胜负双方，用来查看效果。需要CineMode以及附近有其他玩家。点击“停止”结束。"
L["Friendly players:"] = "友方玩家："
L["From far out, the zoom in or back out speeds up so it's done in this long. A short zoom still goes at the speeds above."] = "从远处开始时，拉近或拉远会加速，以便在这段时间内完成。短距离缩放仍按上方的速度进行。"
L["From your settings now"] = "来自你当前的设置"
L["Frost"] = "冰霜"
L["Full"] = "完整"
L["Full report"] = "完整报告"
L["Gaining or refreshing a debuff briefly shows your debuffs (not your buffs), in fights too. Not on flights."] = "获得或刷新减益效果时，短暂显示你的减益效果（不包括增益效果），战斗中也会。飞行时除外。"
