L["Heal Vision after a fight, until the Calm Timer (CineMode page) has run out."] = "战斗后显示 Heal Vision，直到平静计时（CineMode页面）结束。"
L["Heal Vision everywhere. The rest of the row keeps its ticks for when you untick this."] = "在所有地方显示 Heal Vision。取消勾选此项时，该行的其余部分会保留其勾选项。"
L["Heal Vision in fights."] = "战斗中显示 Heal Vision。"
L["Heal Vision out of fights while you have a living enemy targeted."] = "非战斗中选中活着的敌人时显示 Heal Vision。"
