L["Held till you've been out of the fight 5 seconds (back in it, longer: a feign death or vanish doesn't let it through), then shown. Dropped after 5 minutes."] = "暂缓到你脱离战斗5秒后（重新进入战斗则更久：假死或消失不会让它显示），然后显示。5分钟后丢弃。"
