L["Hide when the mouse is still: a tooltip in the world or on a unit frame hides once it's been up this long with the mouse still. Move the mouse and it comes back. Hide until the mouse is still: it shows only once the mouse has rested on it this long. Off leaves tooltips be."] = "鼠标静止时隐藏：世界中或单位框体上的鼠标提示在鼠标静止状态下显示这么久后隐藏。移动鼠标它就会回来。鼠标静止前隐藏：只有鼠标在其上停留这么久后才显示。关闭则不处理鼠标提示。"
L["Hit text"] = "命中文字"
L["Hold to bring up a wheel of the ground markers (the colored lights you drop on the floor): point at one and let go, and it drops under the cursor. Picking one that's down moves it; Clear all takes them all up. Tap it instead and the wheel stays up for you to click one. Only in a group."] = "按住可调出地面标记轮盘（你放在地上的彩色光圈）：指向其中一个并松开，它就会放在光标下方。选择一个已放下的标记会移动它；“全部清除”会把它们全部收起。改为轻按的话，轮盘会保持显示，供你点击选择。仅限组队时。"
L["Hold to bring up a wheel of the raid target markers (skull, cross, square...) for your target, or with none, whatever the cursor is on: point at one and let go to put it on them, or at None to take theirs off. Tap it instead and the wheel stays up for you to click one."] = "按住可调出团队目标标记轮盘（骷髅、十字、方块……），用于你的目标；没有目标时，用于光标所指的单位：指向其中一个并松开即可标记，指向“无”则移除其标记。改为轻按的话，轮盘会保持显示，供你点击选择。"
L["Hold to bring up a wheel of the visions (Heal, Quest, Duel...), ringed while they're on: point at one and let go to turn it on or off, in a fight too. Tap it instead and the wheel stays up for you to click one."] = "按住可调出各个 Vision 的轮盘（Heal、Quest、Duel……），已开启的会带圆环：指向其中一个并松开即可开关，战斗中也可以。改为轻按的话，轮盘会保持显示，供你点击选择。"
L["Hold to bring up a wheel of the wheels below (camera, menu, marker...): point at one and let go to open it, then click what you want on it. Tap it instead and the wheel stays up for you to click one. The camera wheel can't open in a fight."] = "按住可调出下方各轮盘的轮盘（镜头、菜单、标记……）：指向其中一个并松开即可打开它，然后点击你想要的选项。改为轻按的话，轮盘会保持显示，供你点击选择。镜头轮盘在战斗中无法打开。"
L["Holds the card up so you can drag it where you want it; Done lets it go. Close the settings to see it."] = "保持卡片显示，以便你把它拖到想要的位置；“完成”会放开它。关闭设置后即可看到。"
L["Honored"] = "尊敬"
L["Horizon Suite's quest tracker (Focus), its dungeon banner and its floating quest item button fade with the Quest tracker row on the Game Frames page."] = "Horizon Suite 的任务追踪（Focus）、其地下城横幅和浮动任务物品按钮会随游戏框体页面上的任务追踪行一起淡出。"
L["Hostile"] = "敌对"
L["Hover Find"] = "悬停查找"
L["Hover Find: %d frame put on the Find frames list."] = "悬停查找：已将%d个框体放入查找框体列表。"
L["Hover Find: %d frames put on the Find frames list."] = "悬停查找：已将%d个框体放入查找框体列表。"
L["Hover Find: hover over the frames you want, then click Stop: they go on the Find frames list, to add. The game's own frames and ones already faded are left out."] = "悬停查找：将鼠标悬停在你想要的框体上，然后点击“停止”：它们会进入查找框体列表，供你添加。游戏自带的框体和已淡出的框体不包括在内。"
L["Hover group \"%s\": %s"] = "鼠标悬停分组“%s”：%s"
L["Hover over the frames you want (move this window out of the way, or close it), then click Stop: they go on the list below, to add. The game's own frames and ones already faded are left out. /cine add cancel drops them."] = "将鼠标悬停在你想要的框体上（把这个窗口移开或关闭），然后点击“停止”：它们会进入下方列表，供你添加。游戏自带的框体和已淡出的框体不包括在内。/cine add cancel 可放弃它们。"
L["Hovering the chat, typing or a whisper to read still brings it all up."] = "鼠标悬停在聊天上、输入文字或有待读密语时，仍会让聊天全部显示。"
L["How Damage Vision looks and where it sits. Press Test on the Settings tab and close the settings to see it."] = "Damage Vision 的外观和位置。在设置标签页按“测试”，然后关闭设置即可看到。"
L["How big a name is with its unit about 10 yards from the camera, next to the plates' own. Nearer, bigger still; further, smaller, as the game's names over heads."] = "单位离镜头约10码时名字的大小，相对于姓名板自身的大小。更近时更大，更远时更小，就像游戏头顶上的名字一样。"
L["How big a name is with its unit about 50 yards from the camera: about the size of the game's names where those take over, at the edge of nameplate range."] = "单位离镜头约50码时名字的大小：大约与姓名板范围边缘处由游戏接管显示的名字一样大。"
L["How big speech from behind you is, next to a bubble overhead: smaller sounds further away."] = "来自你身后的话语的大小，相对于头顶上的气泡：越小听起来越远。"
L["How big the names are, next to the plates' own."] = "名字的大小，相对于姓名板自身的大小。"
L["How big the text is, next to its usual size."] = "文字的大小，相对于其通常大小。"
L["How big the words are, next to their usual size."] = "文字的大小，相对于其通常大小。"
L["How big they are, next to the usual."] = "它们的大小，相对于通常大小。"
L["How big your class resource is (combo points, holy power, runes and the like), next to the game's."] = "你的职业资源（连击点数、圣能、符文等）的大小，相对于游戏的大小。"
L["How bright both arts' colors are: at 50% as the theme has them; less, darker, down to black at 0%; more, lighter, toward white."] = "两种美术颜色的亮度：50%为主题的原样；更低则更暗，0%时为全黑；更高则更亮，趋向白色。"
L["How chat bubbles look, and speech from behind you with them. Where bubbles show: the UI Manager's Chat bubbles page. Bubbles already showing change with the next thing said."] = "聊天气泡以及与之一起显示的来自你身后的话语的外观。气泡在哪里显示：界面管理器的聊天气泡页面。已显示的气泡会在下一句话时改变。"
L["How close to the waypoint the wind stops (you're there)."] = "风在离路径点多近时停止（你已到达）。"
L["How dark it is behind the bar."] = "条后方的暗度。"
L["How dark it is behind the bars, with a border of ours."] = "条后方的暗度，带我们的边框。"
L["How dark it is behind the fill (with a fill of your own; the game's keeps its own)."] = "填充后方的暗度（使用你自己的填充时；游戏的填充保持原样）。"
L["How dark it is behind the health bar, with a border of ours."] = "生命条后方的暗度，带我们的边框。"
L["How dark the black edges get."] = "黑色边缘的最大暗度。"
L["How dark the edges are at full."] = "满值时边缘的暗度。"
L["How dark the empty part of the bar is."] = "条的空白部分的暗度。"
L["How dark the shadow is."] = "阴影的暗度。"
L["How dark the world gets outside the portal's rim, in a deep shade of its color."] = "传送门边缘外世界变暗的程度，使用其颜色的深色调。"
L["How faded the page count (2 / 3) and the numbers by the replies and buttons are."] = "页数（2 / 3）以及回复和按钮旁数字的淡化程度。"
L["How far above the letters it falls (below, below 0)."] = "它落在文字上方多远（低于0则在下方）。"
L["How far away buildings keep their full detail."] = "建筑物在多远距离内保持完整细节。"
L["How far away creatures and characters keep their full detail before they're swapped for simpler models."] = "生物和角色在多远距离内保持完整细节，超过后会换成更简单的模型。"
L["How far away grass and flowers grow full before they start thinning out towards the clutter distance. Above the clutter distance it makes no more difference."] = "草和花在多远距离内完全生长，超过后开始向地面杂物距离逐渐稀疏。超过地面杂物距离后不再有影响。"
L["How far away grass and flowers still show."] = "草和花在多远距离内仍会显示。"
L["How far away nameplates show, in yards. The game won't go past its own limit. Reset page puts the game's default back."] = "姓名板显示的最远距离，单位为码。游戏不会超过它自己的上限。“重置本页”会恢复游戏的默认值。"
L["How far away small objects stay before they fade out. Much higher costs a lot of frame rate for little to see."] = "小物体在多远距离内保持显示，超过后淡出。设得很高会消耗大量帧率，却看不到多少东西。"
L["How far away the land is drawn in full before it turns into the flat, faded horizon, and how far anything is drawn at all. Very demanding: with terrain and building detail turned up too, most of all."] = "地形在多远距离内完整绘制，超过后变成扁平、褪色的地平线，以及任何东西最远绘制到多远。非常消耗性能：尤其是同时调高了地形和建筑细节时。"
L["How far away the land keeps its full shape before it turns low detail."] = "地形在多远距离内保持完整形状，超过后变成低细节。"
L["How far away trees, rocks and other objects keep their full detail before they're swapped for simpler ones or fade out."] = "树木、岩石和其他物体在多远距离内保持完整细节，超过后会换成更简单的模型或淡出。"
L["How far either side of behind the flight, RP walk and auto-run cameras may swing indoors."] = "飞行、RP漫步和自动奔跑镜头在室内可在你身后两侧摆动多远。"
L["How far in it all comes: at 50% as the settings below say (and the theme's own); less, nearer the edges, down to none at 0% (the shadow only to half); more, further in, up to double. It scales the shadow's reach and both arts' reach."] = "整体向内延伸多远：50%为下方设置所定（以及主题自身）；更低则更靠近边缘，0%时为无（阴影只减到一半）；更高则更向内，最多两倍。它会缩放阴影和两种美术的延伸范围。"
L["How far in it comes from the left and right of the screen at full (screens are wide: the same share comes further in there)."] = "满值时从屏幕左右两侧向内延伸多远（屏幕较宽：同样的比例在那里会延伸得更远）。"
L["How far in it comes from the top and bottom of the screen at full."] = "满值时从屏幕顶部和底部向内延伸多远。"
L["How far in its clear middle closes at full."] = "满值时其清晰的中间区域收拢到多小。"
L["How far in the black edges come as the cast fills (a share of the screen from each side)."] = "随着施法进度，黑色边缘向内延伸多远（从每一侧算起占屏幕的比例）。"
L["How far out you can zoom the camera, as times the game's base distance. The game won't go past its own limit. Idle zoom's \"past your max\" still raises it to 2.6 while it zooms, if it's lower."] = "镜头最远可拉远到多远，以游戏基础距离的倍数表示。游戏不会超过它自己的上限。如果此值较低，闲置缩放的“超过你的最大缩放距离”在缩放时仍会将其提高到2.6。"
L["How far past the bars' edge they fade into the scene."] = "它们越过黑边边缘多远后融入画面。"
L["How far past your own distance the slow zoom may pull back indoors. It also never raises the max zoom distance indoors. Walking in pulled back, the camera glides in to this."] = "在室内，缓慢缩放最多可比你自己的距离拉远多少。它在室内也不会提高最大缩放距离。拉远状态下走进室内时，镜头会平滑拉近到此距离。"
L["How far past your own zoom the camera pulls back (the first move always goes this far)."] = "镜头比你自己的缩放距离再拉远多少（第一次移动总会拉到这么远）。"
L["How far right (X) and up (Y) from the middle of the screen it sits; below 0, left or down. Dragging it with Move fills these in."] = "它距屏幕中央向右（X）和向上（Y）多远；低于0则向左或向下。用“移动”拖动它会自动填入这些值。"
L["How far right (X) of the middle of the screen, and up (Y) from its bottom, the card sits. Typing here or dragging it with Move puts it there; Reset puts it back above speech from behind you."] = "卡片距屏幕中央向右（X）多远，以及距屏幕底部向上（Y）多远。在这里输入或用“移动”拖动它即可放到那里；“重置”会把它放回来自你身后的话语上方。"
L["How far right of the letters it falls (left, below 0)."] = "它落在文字右侧多远（低于0则在左侧）。"
L["How far around you the camera turns with each move."] = "每次移动镜头绕你转多远。"
L["How far the camera comes down toward eye level, from wherever you had it. Much more and, close up, it can meet the ground or scenery behind you (a small jump). It goes back up as the window closes (unless you moved the camera yourself meanwhile). 0 keeps your angle."] = "镜头从你原来的位置向视线高度降低多少。降得太多的话，近距离时可能会碰到你身后的地面或景物（会小跳一下）。窗口关闭时它会升回去（除非你在此期间自己移动过镜头）。0 表示保持你的角度。"
L["How far the camera may come in from its distance."] = "镜头最多可从其距离拉近多少。"
L["How far the camera may pull back from its distance."] = "镜头最多可从其距离拉远多少。"
L["How far the camera may sway either side of where it settles."] = "镜头最多可在其停留位置两侧摇摆多远。"
L["How far the camera may swing to either side of directly behind your character. 90° reaches side-on; smaller keeps it closer behind."] = "镜头最多可在你角色正后方两侧摆动多远。90°可达到正侧面；更小则保持更靠近身后。"
L["How far the camera may tilt down as it moves."] = "镜头移动时最多可向下倾斜多少。"
L["How far the camera may tilt up as it moves."] = "镜头移动时最多可向上倾斜多少。"
L["How far the dark edges reach in once they've closed in, as a share of the screen from each side."] = "暗色边缘收拢后向内延伸多远，以从每一侧算起占屏幕的比例表示。"
L["How far up the screen the list of replies starts: its top edge, from the bottom of the screen. Changing this also forgets where you dragged the list to."] = "回复列表从屏幕上多高处开始：其顶部边缘距屏幕底部的距离。更改此值也会忘记你把列表拖到的位置。"
L["How fast"] = "速度"
L["How fast they travel to the waypoint, next to the style's own speed."] = "它们飞向路径点的速度，相对于该风格自身的速度。"
L["How it looks: the theme, our art and Blizzard's, the shadow and the heartbeat."] = "外观：主题、我们的美术和暴雪的美术、阴影和心跳。"
L["How long"] = "时长"
L["How long a card stays before it fades. The mouse over it holds it."] = "卡片淡出前停留多久。鼠标悬停在其上会让它保持。"
L["How long a plate takes to change its opacity or size a whole 100% when the row it goes by changes: from 100% to 15% takes a bit less. If it changes back before it's there, it turns back from where it is, so a quick look away from an elite and back barely shows. A plate just come into view starts at its row's. 0: at once."] = "当姓名板所依据的行发生变化时，其不透明度或大小完整变化100%所需的时间：从100%到15%用时稍短。如果在变化完成前又变回去，它会从当前状态折返，所以从精英身上快速移开视线再移回来几乎看不出变化。刚进入视野的姓名板直接从其所在行的值开始。0：立即。"
L["How long a recording runs."] = "一次记录持续多久。"
L["How long a repeat is ignored for."] = "重复出现时忽略多久。"
L["How long before the cast ends the black takes over the whole screen. 0: it doesn't."] = "施法结束前多久黑色覆盖整个屏幕。0：不覆盖。"
L["How long each move takes, start to stop. Longer is slower and smoother."] = "每次移动从开始到停止所需的时间。越长越慢越平滑。"
L["How long each zoom in or out takes."] = "每次拉近或拉远所需的时间。"
L["How long it stays up once a fight is over."] = "战斗结束后它保持显示多久。"
L["How long its camera runs."] = "其镜头运行多久。"
L["How long the bars take to come in or go. 0: as long as the UI's own fades (the main page's Fade in and Fade out times)."] = "黑边出现或消失所需的时间。0：与界面自身的淡入淡出相同（主页面的淡入和淡出时间）。"
L["How long the camera holds still between moves."] = "两次移动之间镜头保持静止的时间。"
L["How long the camera rests between sweeps. 0 keeps it turning continuously at the turn speed, without slowing between sweeps."] = "两次环绕之间镜头停留的时间。0 表示按旋转速度持续转动，环绕之间不减速。"
L["How long the card stays between fading in and out (Typewriter: once typed)."] = "卡片在淡入和淡出之间停留多久（打字机：打完字后算起）。"
L["How long the dark edges take to close in after you die, starting gently and settling at the end."] = "你死亡后暗色边缘收拢所需的时间，开始时柔和，结束时平稳停下。"
L["How long the icon flashes once its cooldown ends."] = "冷却结束后图标闪烁多久。"
L["How long the session was."] = "这次游戏时长。"
L["How long things must stay calm (no cast, window, dragging and the like) before CineMode comes back. After a fight it comes back at once instead. 0 returns at once."] = "需要保持平静（没有施法、窗口、拖动等）多久，CineMode才会回来。战斗后则立即回来。0 表示立即返回。"
L["How long things take to fade out, in and out of fights: letting go of a target, after a mouseover, and after a fight once the Calm Timer below is over. The mouseover time (Mouseover groups page) includes it: a time shorter than the fade just fades straight away."] = "界面淡出所需的时间，战斗中和战斗外都用：放开目标、鼠标悬停之后，以及战斗后下方的平静计时结束时。鼠标悬停时间（鼠标悬停分组页面）包含它：比淡出更短的时间会立即淡出。"
L["How long you stand still before NPCs chatting nearby start this row's camera. 0: straight away. Moving starts the count over."] = "附近有NPC交谈时，你站着不动多久后启动此行的镜头。0：立即。移动会重新计时。"
L["How loud the sounds are, next to your sound effects' volume."] = "音效的音量，相对于你的音效音量。"
L["How many come a minute at full (a big hit brings a few more)."] = "满值时每分钟出现多少次（重击会多带来几次）。"
L["How many dungeon or raid bosses you killed."] = "你击杀了多少个地下城或团队副本首领。"
L["How many quests you turned in."] = "你交了多少个任务。"
L["How many seconds before it's ready the icon comes back: 0 for once it's ready. Leave it empty for %d%% of its cooldown."] = "冷却就绪前多少秒图标重新出现：0 表示就绪时才出现。留空则为其冷却时间的%d%%。"
L["How many streaks (or leaves, or motes) start each second."] = "每秒开始出现多少条光痕（或叶子、光点）。"
L["How many times you died."] = "你死亡了多少次。"
L["How much further in each beat pushes the edges (some themes throb more or less)."] = "每次跳动让边缘再向内推进多少（有些主题跳动得更强或更弱）。"
L["How much of a hidden damage dealer still shows, and of the group titles. 0% hides them completely."] = "隐藏的伤害输出者以及小队标题仍显示多少。0%表示完全隐藏。"
L["How much of a hidden healer still shows. 0% hides them completely."] = "隐藏的治疗者仍显示多少。0%表示完全隐藏。"
L["How much of a hidden pet still shows. 0% hides them completely."] = "隐藏的宠物仍显示多少。0%表示完全隐藏。"
L["How much of a hidden tank still shows. 0% hides them completely."] = "隐藏的坦克仍显示多少。0%表示完全隐藏。"
L["How much of each move is spent speeding up, and again slowing down. 50% is one smooth swell, gentlest at the ends. Lower values get up to speed quicker and cruise in the middle."] = "每次移动中用于加速和减速的比例。50%是一次平滑的起伏，两端最柔和。更低的值会更快达到速度，并在中间匀速移动。"
L["How much of each zoom is spent speeding up, and again slowing down. 50% is one smooth swell; lower gets moving sooner and glides in the middle."] = "每次缩放中用于加速和减速的比例。50%是一次平滑的起伏；更低则更快动起来，并在中间匀速滑行。"
L["How much of the screen's height the dark top and bottom edges cover at full."] = "满值时上下暗色边缘覆盖屏幕高度的比例。"
L["How much of the screen's width the dark left and right edges cover at full."] = "满值时左右暗色边缘覆盖屏幕宽度的比例。"
L["How much of your computer's time Cinematic takes. The graph is the game's own figure for this addon: its share of each frame's time, sampled every second (the last five minutes, kept over a reload), each bar colored by what was going on. A recording times the addon's busy parts: it starts when you close the settings, and its results show here. If Cinematic seems slow for you, record a while of your usual play (a fight too), then Copy report and send it to us: it helps us find what to speed up."] = "Cinematic占用你电脑多少时间。图表是游戏自身对此插件的统计：它占每帧时间的比例，每秒采样一次（最近五分钟，重载后保留），每个柱按当时发生的事情着色。记录会为插件的繁忙部分计时：它在你关闭设置时开始，结果显示在这里。如果你觉得Cinematic很慢，请记录一段你平常的游戏过程（包括一场战斗），然后点击“复制报告”发送给我们：这能帮助我们找到需要提速的地方。"
L["How much richer you came out, if you did."] = "如果有的话，你变得富有了多少。"
L["How much this theme throbs, next to Throb above."] = "此主题的跳动强度，相对于上方的“跳动”。"
L["How names look on nameplates showing just the name: in CineMode, away from dungeons and raids, a name kept up over a faded plate is drawn by the plate. Changes show at once, here and on the plates around you."] = "只显示名字的姓名板上名字的外观：在CineMode中，地下城和团队副本以外，淡出的姓名板上保持显示的名字由姓名板绘制。更改会立即显示，包括此处和你周围的姓名板上。"
L["How see-through the background is."] = "背景的透明度。"
L["How see-through the bars are."] = "条的透明度。"
L["How see-through the bubble is."] = "气泡的透明度。"
L["How see-through the cards are."] = "卡片的透明度。"
L["How see-through the names are, on top of their fades."] = "名字的透明度，在其淡出效果之上叠加。"
L["How see-through the panels are."] = "面板的透明度。"
L["How see-through the whole of it is."] = "整体的透明度。"
L["How solid speech from behind you is: fainter sounds muffled, out of view."] = "来自你身后的话语的不透明程度：越淡的声音越模糊，在视野之外。"
L["How solid the game's dark background behind each frame is."] = "每个框体后方游戏深色背景的不透明程度。"
L["How strong"] = "强度"
L["How strong it all is: at 50% as the settings below say (and the theme's own); less, lighter, down to nothing at 0%; more, up to double. It scales the darkness, the shadow's reach, the throb and both arts' opacity. The color grade (the world draining toward grey, tinged with the theme's color) is as strong as this says."] = "整体强度：50%为下方设置所定（以及主题自身）；更低则更淡，0%时为无；更高则最多两倍。它会缩放暗度、阴影范围、跳动以及两种美术的不透明度。色彩分级（世界褪向灰色，带有主题颜色的色调）的强度也按此值。"
L["How strong it is as the cast ends (it starts faint)."] = "施法结束时的强度（开始时很淡）。"
L["How strong it is at full."] = "满值时的强度。"
L["How strong the edges are out of a fight (eating and drinking back up, say), next to in one. Some clients keep your health secret in fights; there the edges only fade in and out with it."] = "非战斗中（例如吃喝恢复时）边缘的强度，相对于战斗中。有些客户端在战斗中会把你的生命值设为保密；在那里，边缘只会随之淡入和淡出。"
L["How strong the glow is, next to the art."] = "光晕的强度，相对于美术。"
L["How strongly the tint colors the world, for every preset."] = "色调为世界着色的强度，适用于所有预设。"
L["How tall each bar is, as a share of the screen's height."] = "每个条的高度，以占屏幕高度的比例表示。"
L["How tall the bar for the time left is."] = "剩余时间条的高度。"
L["How tall the bar is (the race track's line is half that, the ladder's rows a little more)."] = "条的高度（赛道的线为其一半，阶梯的行稍高一些）。"
L["How tall the words are on the screen; the other lines go by them. (In a letterbox bar: Letterbox scale.)"] = "文字在屏幕上的高度；其他行以它为准。（在宽银幕黑边中：黑边缩放。）"
L["How the bars at the top and bottom of the screen look and come in. When they show: the Letterbox tab. Changes show at once, here and on the bars."] = "屏幕顶部和底部黑边的外观和出现方式。何时显示：宽银幕黑边标签页。更改会立即显示，包括此处和黑边上。"
L["How the big button for the nearest quest's item looks. Turning it on: the Vision tab. Where it sits: the extra ability button's place in Edit Mode. Changes show at once (its size after a fight, if you're in one)."] = "最近任务物品的大按钮的外观。开启它：Vision 标签页。位置：编辑模式中额外技能按钮的位置。更改会立即显示（如果你在战斗中，其大小在战斗后改变）。"
L["How the card comes in."] = "卡片如何出现。"
L["How the card is set: a title card, a subtitle, a chapter line or a banner."] = "卡片的排版：标题卡、字幕、章节行或横幅。"
L["How the cast bars look: on nameplates, yours, your target's and focus's, and the bosses' and arena enemies'. The Default tab's settings are every bar's until its own tab has Use default settings unticked. All but the nameplates' keep the game's look until their tab's Restyle these bars is ticked. Whether the nameplates' show in CineMode: the Nameplates page's Plate parts grid. Changes show at once, here and on bars casting now."] = "施法条的外观：姓名板上的、你的、你目标和焦点的，以及首领和竞技场敌人的。默认标签页的设置适用于每种施法条，除非其自己的标签页取消勾选了“使用默认设置”。除姓名板外，其他施法条保持游戏外观，直到其标签页勾选了“重新设置这些条的风格”。姓名板施法条是否在CineMode中显示：姓名板页面的姓名板部件表格。更改会立即显示，包括此处和正在施法的条上。"
L["How the dialogue looks, the \"Show the game's window\" link and the number keys."] = "对话的外观、“显示游戏窗口”链接和数字键。"
L["How the game world looks in CineMode (or over the normal UI, with Start in CineMode off on the main page): vignette, inn glow, weather and depth of field. The letterbox bars and the color grading have pages of their own (Letterbox, Tint). The UI isn't tinted. Names and nameplates are on the Nameplates page."] = "CineMode中游戏世界的外观（或在主页面关闭“以CineMode启动”时，叠加在正常界面上）：暗角、旅店光晕、天气和景深。宽银幕黑边和色彩分级有各自的页面（宽银幕黑边、色调）。界面不会被着色。名字和姓名板在姓名板页面。"
L["How the game's tooltips look: their background, edge and words, names in their colors and the health bar. Which lines show and when: the Interface hub's Tooltips page."] = "游戏鼠标提示的外观：背景、边缘和文字、带颜色的名字以及生命条。显示哪些行以及何时显示：界面中心的鼠标提示页面。"
L["How the low-health edges look: the theme, our art and Blizzard's, the shadow and the effects. When they show: the Vision tab. Changes show at once in the preview."] = "低生命值边缘的外观：主题、我们的美术和暴雪的美术、阴影和效果。何时显示：Vision 标签页。更改会立即在预览中显示。"
L["How the personal resource display under your character looks: its health and power bars, and your class resource. When the bars come up: the Interface hub's Resource Display page."] = "角色下方个人资源显示的外观：生命条和能量条，以及你的职业资源。资源条何时出现：界面中心的资源显示页面。"
L["How the quest item button looks."] = "任务物品按钮的外观。"
L["How the raid frames look, the party's when the game draws them raid-style, and the arena's. The Default tab's settings are each group's until its own tab has Use default settings unticked. Which parts show: the Game Frames page's party and raid rows."] = "团队框架的外观，以及游戏以团队样式绘制时的小队框架和竞技场框架。默认标签页的设置适用于每个分组，除非其自己的标签页取消勾选了“使用默认设置”。显示哪些部分：游戏框体页面的小队和团队行。"
L["How the result shows: its card (with the words above), or a souls banner: VICTORY ACHIEVED or DEFEATED across the middle of the screen, who it was against under it."] = "结果的显示方式：其卡片（带上方的文字），或魂系横幅：屏幕中间显示“胜利达成”或“战败”，下方显示对手是谁。"
L["How the roll window looks."] = "掷骰窗口的外观。"
L["How the rows are listed: Camera groups them by camera name, Scene by scene name. Either way a scene's rows stay together, in the order they're tried."] = "行的排列方式：“镜头”按镜头名称分组，“场景”按场景名称分组。无论哪种，一个场景的行都会排在一起，按尝试顺序排列。"
L["How the window of the group's loot rolls looks: its cards, the bar for the time left, and each player's pick and number. Turning it on: the Vision tab. Changes show at once, here and on the window."] = "队伍拾取掷骰窗口的外观：其卡片、剩余时间条，以及每个玩家的选择和点数。开启它：Vision 标签页。更改会立即显示，包括此处和窗口上。"
L["How thick the border is, in pixels."] = "边框的粗细，单位为像素。"
L["How thickly grass, flowers and stones grow on the ground."] = "地面上草、花和石头的密度。"
L["How this card looks. It starts from a style (a subzone's, the zone's), each setting following it until you change it here, then the card's own until you put it back. Change the style itself on the Card Types tab, for every card using it. Changes play at once in the preview."] = "此卡片的外观。它以一种风格（子区域的、区域的）为起点，每项设置都跟随该风格，直到你在这里更改，此后就是卡片自己的设置，直到你恢复。要更改风格本身（对使用它的每张卡片生效），请到卡片类型标签页。更改会立即在预览中播放。"
L["How wide a line of speech from behind you can get before it wraps onto the next row, as a bubble overhead does."] = "来自你身后的一行话语在换行前最多可以有多宽，就像头顶上的气泡一样。"
L["How wide it is."] = "它的宽度。"
L["How your player, target, focus, pet, target of target and party frames look. The Default tab's settings are every frame's until its own tab has Use default settings unticked. Which parts show: the Interface hub's Unit Frames page."] = "你的玩家、目标、焦点、宠物、目标的目标以及小队框体的外观。默认标签页的设置适用于每个框体，除非其自己的标签页取消勾选了“使用默认设置”。显示哪些部分：界面中心的单位框体页面。"
L["How your target, focus and the unit under the mouse stand out on the nameplates, for when no target frame shows them: a mark on each one's plate, a row for each in the grid, and its name, health bar or border in its mark's color (the row's Also color). When they show is the Target Indicator row's, on the Nameplates page's Cinematic plate parts grid. Changes show at once, here and on the plates."] = "当没有目标框体显示时，你的目标、焦点和鼠标下的单位如何在姓名板上突出显示：在各自的姓名板上显示一个标记，表格中各占一行，其名字、生命条或边框使用其标记的颜色（该行的“附加”颜色）。显示时机取决于姓名板页面Cinematic姓名板部件表格中的目标指示器行。更改会立即显示，包括此处和姓名板上。"
L["How:"] = "方式："
L["Icon"] = "图标"
L["Icon shows"] = "显示图标"
L["Icons"] = "图标"
L["Icons have a dark border of their own: zoomed in a little, it's cut off."] = "图标自带深色边框：稍微放大一点就会被裁掉。"
L["Icons of your own, after the wheel's own: each runs a command, as on your own wheels. Room for %d. The same for all your characters."] = "你自己的图标，排在轮盘自带图标之后：每个运行一条命令，与你自己的轮盘相同。可放%d个。对你的所有角色相同。"
L["Icons on it"] = "上面的图标"
L["Ignore repeats from the same person"] = "忽略同一个人的重复"
L["Ignored for:"] = "忽略时长："
L["Immerse yourself in the world. How much do you want?"] = "沉浸在这个世界中。你想要多少？"
L["Import a Vitals theme"] = "导入 Vitals 主题"
L["Import a camera script"] = "导入镜头脚本"
L["Import a scene or shot"] = "导入场景或机位"
L["Import a wheel"] = "导入轮盘"
L["Import theme"] = "导入主题"
L["In %s"] = "在%s"
L["In CineMode"] = "CineMode中"
L["In CineMode the death camera hides all the frames it fades (bars, chat, unit frames...). The Mouseover page's groups ticked here stay up throughout, party or raid frames say, to watch your group. The release and resurrect popups always show."] = "在CineMode中，死亡镜头会隐藏它淡出的所有框体（动作条、聊天、单位框体……）。在此勾选的鼠标悬停页面分组会全程保持显示，例如小队或团队框体，以便观察你的队伍。释放灵魂和复活弹窗始终显示。"
L["In CineMode, a health bar faded out comes back as your health drops: hidden above its Starts, fading in to fully up at its Full."] = "在CineMode中，淡出的生命条会随你的生命值下降而重新出现：高于其“开始”值时隐藏，逐渐淡入，到其“完整”值时完全显示。"
L["In CineMode, as it rains, the view distance comes in from yours: the harder the rain, the closer. At 100% a downpour brings it all the way in, as far as the Graphics menu's lowest View distance; it never goes further out than yours. Yours is put back once the rain stops or you go indoors."] = "在CineMode中，下雨时视野距离会从你的设定值开始缩短：雨越大，越近。100%时，倾盆大雨会让它一直缩短到图形菜单中最低的视野距离；它永远不会比你的设定值更远。雨停或你进入室内后，会恢复你的设定值。"
L["In CineMode, away from dungeons and raids, nameplates stay on (just faded), and the game takes its own names away from over the heads of units with a plate. So where a name is kept up over a faded plate, Cinematic draws it on the plate itself, made to look like the game's names: colored, and smaller further off. Beyond nameplate range the game's own names show, so a name can change a little in size or place as its unit crosses that range."] = "在CineMode中，地下城和团队副本以外，姓名板保持开启（只是淡出），游戏会移除有姓名板的单位头顶上自带的名字。因此，在淡出的姓名板上保持显示名字时，Cinematic会把名字绘制在姓名板本身上，看起来像游戏的名字：带颜色，越远越小。超出姓名板范围后显示游戏自带的名字，所以当单位跨越该范围时，名字的大小或位置可能会略有变化。"
L["In CineMode, the nameplates of two players dueling near you show, so you can watch their health. Only in the open world, out of fights. Turns on friendly player nameplates while it watches, kept invisible and click-through bar the duelists'. Each duel has its own color, and the winner and loser show when it ends. Needs the Nameplates page enabled."] = "在CineMode中，你附近两名正在决斗的玩家的姓名板会显示，以便你观察他们的生命值。仅在开放世界、非战斗中。观战期间会开启友方玩家姓名板，除决斗者外都保持不可见且可点击穿透。每场决斗有自己的颜色，结束时会显示胜负双方。需要启用姓名板页面。"
L["In CineMode, where and when tooltips show; the rest of the time they're hidden. For some kinds only (enemies, friendlies, gatherables, quest objectives, anything else), Edit its rule: the Tooltip line has a word for each."] = "在CineMode中，鼠标提示在何处、何时显示；其余时间隐藏。若只对某些类别生效（敌人、友方、可采集物、任务目标、其他所有），请编辑其规则：鼠标提示一栏中每个类别都有对应的词。"
L["In CineMode, your player frame shows whenever your mana is under this share, in a fight or not: drinking, or saving mana for the pull. Off: 0."] = "在CineMode中，只要你的法力低于此比例，无论是否在战斗中，你的玩家框体都会显示：喝水时，或为开怪保留法力时。关闭：0。"
L["In CineMode, your resource bar shows whenever your mana is under this share, in a fight or not: drinking, or saving mana for the pull. Off: 0."] = "在CineMode中，只要你的法力低于此比例，无论是否在战斗中，你的资源条都会显示：喝水时，或为开怪保留法力时。关闭：0。"
L["In a camera mode"] = "镜头模式中"
L["In a fight"] = "战斗中"
L["In a fight:"] = "战斗中："
L["In a group, items rolled on show in a window instead of only as lines in chat: each item, a bar for the time left, and everyone's pick (need, greed, transmog) and number, the winner lit at the top. It opens as an item drops, just under the game's roll frame, so you can see who's picked what before you choose, and takes its place once you have. Each item fades a few seconds after it's won (point at them to keep them). It stays with the game's roll frames: with \"Drag windows to move them\" on, dragging either moves both. /cine rolls shows the latest rolls."] = "在队伍中，被掷骰的物品会显示在一个窗口中，而不只是聊天中的几行：每件物品、剩余时间条，以及每个人的选择（需求、贪婪、幻化）和点数，获胜者在顶部高亮。物品掉落时它会在游戏掷骰框正下方打开，让你在选择前看到谁选了什么，你选择后它会占据那个位置。每件物品在被获得几秒后淡出（指向它们可保持显示）。它与游戏的掷骰框保持在一起：开启“拖动窗口来移动它们”时，拖动任一个会同时移动两者。/cine rolls 显示最近的掷骰。"
L["In a raid, each item lists only this many players' rolls: the winner, then need before greed, the highest numbers first. The rest are counted on an \"and N more\" line. In a party, everyone is listed. Click an item's panel to list everyone on it."] = "在团队中，每件物品只列出这么多玩家的掷骰：获胜者，然后需求在贪婪之前，点数高的在前。其余的计入“还有N人”一行。在小队中会列出所有人。点击物品的面板可列出所有人。"
L["In class color"] = "职业颜色"
L["In combat is ticked, and you're fighting"] = "已勾选“战斗中”，且你正在战斗"
L["In combat is ticked, but CineMode doesn't stay on in fights"] = "已勾选“战斗中”，但CineMode在战斗中不会保持开启"
L["In combat is ticked: it shows when a fight starts"] = "已勾选“战斗中”：战斗开始时显示"
L["In gusts"] = "阵风"
L["In no scene"] = "不在任何场景中"
L["In the bar:"] = "条内："
L["In the middle of the screen (a subtitle: low on it)."] = "在屏幕中间（字幕：在屏幕下方）。"
L["In the zones listed here, the minimap stays up during CineMode: say, one where you do a lot of dailies. Caves and towns inside a zone count as the zone."] = "在此列出的区域中，CineMode期间小地图会保持显示：例如你经常做日常任务的区域。区域内的洞穴和城镇也算作该区域。"
L["In these zones:"] = "在这些区域："
L["Inner edge:"] = "内边缘："
L["Inside buildings and caves, the camera modes zoom out less and swing less, so the camera doesn't keep pushing into walls and ceilings. Uses the game's own indoor check."] = "在建筑物和洞穴内，镜头模式会减少拉远和摆动，这样镜头就不会一直撞进墙壁和天花板。使用游戏自身的室内判断。"
L["Inside it: %s"] = "其中：%s"
L["Inspect: click any frame to see why it's showing or hidden. Right-click or Escape to stop."] = "检查：点击任何框体，查看它为什么显示或隐藏。右键点击或按 Esc 停止。"
L["Inspecting someone, a button just right of their level and class opens their talents, and one with their portrait on the talents window takes you back to the inspect window. Not in a fight."] = "观察某人时，其等级和职业右侧的按钮可打开他们的天赋，天赋窗口上带其头像的按钮可返回观察窗口。战斗中不可用。"
L["Instead of a rule, this row shows whenever another row of its table does, however that one is set now or later. All or nothing: none of this row's own settings count while it follows, and they're kept for when it stops (Grid on the row)."] = "此行不使用规则，而是在其表格中另一行显示时显示，无论那一行现在或以后如何设置。全有或全无：跟随期间，此行自己的设置都不起作用，它们会保留，以便停止跟随时使用（该行上的“表格”）。"
L["Instead of stopping between moves, the camera keeps creeping slowly back toward the middle."] = "镜头在两次移动之间不会停下，而是继续缓慢地向中间回移。"
L["Interface Style"] = "界面风格"
L["Interrupted"] = "被打断"
L["Is Cinematic slowing your game?"] = "Cinematic是否拖慢了你的游戏？"
L["It ends"] = "它结束时"
L["It goes with the %s row, which is hidden"] = "它与%s行一起，而该行已隐藏"
L["It shows only if something happened that's ticked here: quests, a level, bosses, deaths or gold. The zone and time played come with it."] = "只有当发生了此处勾选的事情时才会显示：任务、升级、首领、死亡或金币。区域和游戏时长会随之显示。"
L["It sits where the game's %s was, or is named like it: it takes that row's ticks on the Game Frames page until you give it its own."] = "它位于游戏的%s原来的位置，或名称与之相似：在你给它单独设置之前，它采用游戏框体页面上该行的勾选项。"
L["It starts once the swing behind you is done, while the zoom carries on. The tilt down follows."] = "它在转到你身后完成后开始，同时缩放继续进行。之后是向下倾斜。"
L["It stops"] = "它停止时"
L["It's full (or you can't afford any)."] = "已满（或你买不起）。"
L["Items shown at once"] = "同时显示的物品数"
L["Items you can't use (armor or weapons you can't wear, another class's, or a level you're not yet: anything in red on its tooltip) don't get a panel. Their rolls are only in chat."] = "你无法使用的物品（你无法穿戴的护甲或武器、其他职业的、或你尚未达到等级的：鼠标提示中任何红色的内容）不会有面板。它们的掷骰只在聊天中显示。"
L["Its card"] = "其卡片"
L["Its cast bar isn't faded, like the game's."] = "其施法条不会淡出，与游戏的一样。"
L["Its choices come next."] = "接下来是它的选项。"
L["Its color."] = "其颜色。"
L["Its color. Auto: your class and spec's (the glow of the Vitals Vision theme Auto picks for you), changing with your spec. Or pick any class and spec's, or your own color beside this."] = "其颜色。自动：你的职业和专精的颜色（自动为你选择的 Vitals Vision 主题的光晕），随专精变化。也可以选择任何职业和专精的颜色，或旁边你自己的颜色。"
L["Its colors, bars and words, and where it sits."] = "其颜色、条和文字，以及其位置。"
L["Its group is kept up through the death camera"] = "其分组在死亡镜头期间保持显示"
L["Its height, next to the game's (nameplates only). The health bar and name ride up on it."] = "其高度，相对于游戏的高度（仅限姓名板）。生命条和名字会随之上移。"
L["Its icon is on the master wheel, which opens it. Untick to leave it off: its own key still brings it up. The master wheel is the same for all your characters."] = "其图标在主轮盘上，可从主轮盘打开它。取消勾选可不放在上面：它自己的按键仍能调出它。主轮盘对你的所有角色相同。"
L["Its info panel (XP bar and minimap) follows the Minimap row on the Game Frames page; its unit frames, bars, buffs, chat and quest tracker follow the rows of the frames they replace."] = "其信息面板（经验条和小地图）跟随游戏框体页面上的小地图行；其单位框体、动作条、增益效果、聊天和任务追踪跟随它们所替代框体的行。"
L["Its key binding in the corner"] = "角落显示其按键绑定"
L["Its look is on the Style tab, a sound for each time of day on the Sounds tab."] = "其外观在风格标签页，每个时段的音效在音效标签页。"
L["Its look is on the Style tab, its sound on the Sounds tab."] = "其外观在风格标签页，其音效在音效标签页。"
L["Its look is the Victory style's (the Style tab), its sound on the Sounds tab."] = "其外观使用胜利风格（风格标签页），其音效在音效标签页。"
L["Its messages show chat any time the UI is faded. (The other columns then have nothing to add.)"] = "界面淡出时，其消息随时显示聊天。（其他列就没有什么可补充的了。）"
L["Its messages show chat in battlegrounds and arenas."] = "其消息在战场和竞技场中显示聊天。"
L["Its messages show chat in capital cities."] = "其消息在主城中显示聊天。"
L["Its messages show chat in dungeons, scenarios and raids."] = "其消息在地下城、场景战役和团队副本中显示聊天。"
L["Its messages show chat in fights (while you stay cinematic in them)."] = "其消息在战斗中显示聊天（当你在战斗中保持电影模式时）。"
L["Its messages show chat out in the world, inns included (capital cities are Cities)."] = "其消息在野外显示聊天，包括旅店（主城属于“城市”）。"
L["Its messages show chat out of combat with a living enemy targeted."] = "其消息在非战斗中选中活着的敌人时显示聊天。"
L["Its messages show chat out of combat with anything else targeted (friends, NPCs, dead enemies)."] = "其消息在非战斗中选中其他任何目标时显示聊天（友方、NPC、死亡的敌人）。"
L["Its messages show chat while you're in a party or raid, wherever you are."] = "当你在小队或团队中时，无论身在何处，其消息都显示聊天。"
L["Its name in the wheel's middle as you point at it. Empty: its command's first line."] = "你指向它时在轮盘中间显示的名称。留空：其命令的第一行。"
L["Its name, mark and the rest of the plate move with the bar's edges. Not on WoW Forever: its plates don't change size."] = "其名字、标记和姓名板的其余部分会随条的边缘移动。在 WoW Forever 上不适用：其姓名板不会改变大小。"
L["Its numbers in a color of your own."] = "其数字使用你自己的颜色。"
L["Its other bars, pet, stance, bag, micro menu, status and art bars are rows on the Standard Frames page."] = "其他动作条、宠物条、姿态条、背包条、微型菜单、状态条和装饰条是标准框体页面上的行。"
L["Its other bars, pet, stance, totem, micro, bag and data bars are rows on the Standard Frames page, with its unit frames, buffs and chat panels."] = "其他动作条、宠物条、姿态条、图腾条、微型菜单、背包条和数据条是标准框体页面上的行，还有其单位框体、增益效果和聊天面板。"
L["Its own colors"] = "其自身的颜色"
L["Its own:"] = "其自身的："
L["Its own: %s. The rest: %s."] = "其自身的：%s。其余：%s。"
L["Its rule, as things are now: %s"] = "其规则，按当前状态：%s"
L["Its size, next to the game's."] = "其大小，相对于游戏的大小。"
L["Its style, words, frame and face, and where it sits."] = "其风格、文字、框架和头像，以及其位置。"
L["Its type, and that type's settings."] = "其类型，以及该类型的设置。"
L["Its unit frames, cast bar, resource bars, buffs, quest tracker, party and raid frames, XP bar and totems are rows on the Game Frames page."] = "其单位框体、施法条、资源条、增益效果、任务追踪、小队和团队框体、经验条和图腾是游戏框体页面上的行。"
L["Its unnamed frames"] = "其未命名的框体"
L["Its warnings aren't faded, like the game's raid warnings."] = "其警告不会淡出，与游戏的团队警告一样。"
L["Its width, next to the game's, about its middle (nameplates only)."] = "其宽度，相对于游戏的宽度，以中心为基准（仅限姓名板）。"
L["Just at the top"] = "仅在顶部"
L["Just the new one"] = "仅新的"
L["Just the text, over the world."] = "仅文字，叠加在世界上。"
L["Just the words, over the world: an outline helps them read."] = "仅文字，叠加在世界上：描边有助于阅读。"
L["KEEPING IT HIDDEN"] = "保持隐藏的原因"
L["Keep bubbles on screen"] = "让气泡保持在屏幕内"
L["Keep open: a tracked quest"] = "保持打开：已追踪的任务"
L["Keep open: always"] = "保持打开：始终"
L["Keep open: in this zone"] = "保持打开：在此区域"
L["Keep open: indoors, and you're inside"] = "保持打开：在室内，且你在里面"
L["Keep the active profile as it is now: Reset and each page's Reset put it back to this instead of Cinematic's own settings."] = "将当前配置文件保持为现在的状态：“重置”和每个页面的“重置”都会恢复到此状态，而不是Cinematic自己的设置。"
L["Keep windows open across a reload"] = "重载后保持窗口打开"
L["Keeping a frame up, always or in fights, is on the Game Frames page; your own while you recover, on the Resource Display page."] = "要让框体一直显示或在战斗中显示，请到游戏框体页面设置；你自己的框体在恢复期间的显示，在资源显示页面设置。"
L["Keeps the Cooldown Manager up until every cooldown in its Essential bar (and Enhanced Cooldown Manager's cooldown bars) is ready again, then it fades. Not the global cooldown, nor its buff bars. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "保持冷却管理器显示，直到其核心技能条（以及Enhanced Cooldown Manager的冷却条）中的每个冷却都再次就绪，然后淡出。不包括公共冷却及其增益效果条。（它会调出勾选了“冷却恢复中”的鼠标悬停分组：默认是冷却分组。）"
L["Keeps the Cooldown Manager up until every cooldown in its Utility bar is ready again, then it fades. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "保持冷却管理器显示，直到其辅助技能条中的每个冷却都再次就绪，然后淡出。（它会调出勾选了“冷却恢复中”的鼠标悬停分组：默认是冷却分组。）"
L["Keeps the quest tracker's timers up in CineMode, and in fights, while one counts down: a scenario's or assault's timer, a dungeon's clock, a timed quest's bar. Just the timer's quest or scenario: the rest of the tracker stays faded. Hovering it shows it all."] = "当任务追踪中有计时器在倒计时时，在CineMode和战斗中保持其显示：场景战役或突袭的计时器、地下城的时钟、限时任务的计时条。只显示该计时器所属的任务或场景战役：追踪的其余部分保持淡出。鼠标悬停可显示全部。"
L["Keeps your pet frame up after a fight or a fall, within the Calm Timer, until your pet's health is full."] = "战斗或坠落后，在平静计时内保持显示你的宠物框体，直到宠物生命值回满。"
L["Keeps your pet frame up in CineMode, and in fights, while its happiness isn't green: content (yellow) or unhappy (red). It goes again once your pet is happy."] = "当宠物的快乐度不是绿色（满足：黄色，不快乐：红色）时，在CineMode和战斗中保持宠物框体显示。宠物快乐后再次隐藏。"
L["Keeps your player frame up after a fight, a fall or resurrecting, until your health and power are full. Rage and runic power don't count."] = "战斗、坠落或复活后保持显示你的玩家框体，直到生命值和能量恢复满。怒气和符文能量不计算在内。"
L["Kept from the %s profile, which Cinematic no longer has."] = "保留自%s配置文件，Cinematic已不再有该配置文件。"
L["Key"] = "按键"
L["Key binding"] = "按键绑定"
L["Kill streak"] = "连杀"
L["Land and buildings"] = "地形和建筑"
L["Last recording: %s, %s"] = "上次记录：%s，%s"
