L["Last tooltip"] = "上一个鼠标提示"
L["Later around the wheel."] = "在轮盘上更靠后。"
L["Layout"] = "布局"
L["Learned"] = "已学会"
L["Leave the speaker off center"] = "让说话者偏离中心"
L["Leaving combat"] = "脱离战斗"
L["Leaving the quest giver, the camera stays close until you walk more than 10 yards from where you started talking (talk to another quest giver and it counts from there), then zooms back out to your own distance at this speed, in a few seconds at most. At 0 it stays in."] = "离开任务NPC时，镜头会保持拉近，直到你走离开始对话的位置超过10码（与另一个任务NPC对话则从那里重新计算），然后以此速度拉远回你自己的距离，最多几秒钟。为0时保持拉近。"
L["Left-click: add a point. Right-click: take one back."] = "左键点击：加一点。右键点击：退回一点。"
L["Letterbox scale"] = "黑边缩放"
L["Level %d"] = "%d级"
L["Level reached"] = "达到的等级"
L["Level required: %s"] = "需要等级：%s"
L["Level up"] = "升级"
L["Lift speed"] = "抬升速度"
L["Light words on a dark, see-through bubble with a thin edge, in Arial Narrow."] = "带细边的半透明深色气泡上的浅色文字，Arial Narrow 字体。"
L["Light words on dark, see-through panels, in Arial Narrow."] = "半透明深色面板上的浅色文字，Arial Narrow 字体。"
L["Lightning"] = "闪电"
L["Like the game's"] = "与游戏相同"
L["Like the game's names"] = "与游戏的名字相同"
L["Like the quest window's page."] = "与任务窗口的页面相同。"
L["Line along the edge:"] = "沿边缘的线："
L["Line up behind you over %s s"] = "在%s秒内排到你身后"
L["Lines"] = "行"
L["Lit"] = "点亮"
L["Living NPCs that aren't elite, rare elite or a boss (minor critters too). Normal NPC - Enemy starts faded to 40% while an elite enemy is within about 28 yards (its When rule: elite28), so in a pull the elites stand out."] = "非精英、稀有精英或首领的活着的NPC（也包括次要的小动物）。“普通NPC - 敌人”在约28码内有精英敌人时起始淡出到40%（其“符合条件”规则：elite28），这样拉怪时精英会更醒目。"
L["Living elite, rare elite and boss NPCs."] = "活着的精英、稀有精英和首领NPC。"
L["Location"] = "地点"
L["Logic"] = "逻辑"
L["Look around for speakers off screen"] = "寻找屏幕外的说话者"
L["Look in the background"] = "在背景中观看"
L["Look:"] = "外观："
L["Looking out"] = "向外看"
L["Looking... %ds"] = "寻找中……%d秒"
L["Looks once a second for a while, so a frame that only shows now and then is caught: bring it up while it runs. Click again to stop."] = "每秒查看一次，持续一段时间，这样只偶尔出现的框体也能被捕捉到：在它运行时让该框体出现。再次点击可停止。"
L["Looks over what's on screen for other addons' frames that nothing fades, and guesses which Game Frames row each stands in for. Add one to fade it: it goes on the Loaded tab, under its addon."] = "查看屏幕上没有被任何东西淡出的其他插件框体，并猜测每个框体对应游戏框体页面的哪一行。添加一个即可将其淡出：它会出现在“已加载”标签页中其插件下方。"
L["Loot rolls"] = "拾取掷骰"
L["Lost"] = "失败"
L["Lost:"] = "失去："
L["Low mana"] = "法力不足"
L["Low mana brings up your player frame as well as your resource bar."] = "法力不足时会调出你的玩家框体以及资源条。"
L["Low on the left of the screen, as a film names someone, its line fading out to the right."] = "在屏幕左下方，像电影介绍人物那样，其文字行向右淡出。"
L["Lower picks: %d"] = "较低的选择：%d"
L["Lower third"] = "下三分之一"
L["Lower third with no letterbox"] = "无宽银幕黑边的下三分之一"
L["Made by %s"] = "由%s制作"
L["Made from these settings. Copy the camera to change the step itself."] = "根据这些设置生成。复制此镜头才能更改步骤本身。"
L["Made up"] = "模拟"
L["Make a scene of your own: its triggers (an emote, a spell, a buff, a place, a moment, something you are, or a key), the camera it plays and when it ends."] = "制作你自己的场景：其触发条件（表情、法术、增益效果、地点、时刻、你的某种状态或按键）、它播放的镜头以及何时结束。"
L["Make a shot, starting from the cozy camera's own numbers. Pick another camera for it below."] = "制作一个机位，以温馨镜头自己的数值为起点。在下方为它选择另一个镜头。"
L["Make this layout again as Cinematic has it, undoing any changes you made to it in Edit Mode."] = "按照Cinematic的设定重新生成此布局，撤销你在编辑模式中对它做的所有更改。"
L["Makes the tint stronger on this client, whose brighter, more colorful world shows the same tint less than retail does. Off: the tint as the Strength slider sets it."] = "在此客户端上让色调更强，因为它的世界更明亮、色彩更丰富，同样的色调效果比正式服弱。关闭：按强度滑块设置的色调。"
L["Mana"] = "法力值"
L["Mana bar"] = "法力条"
L["Mana bar:"] = "法力条："
L["Manage and share"] = "管理和分享"
L["Mark"] = "标记"
L["Mark %d%%"] = "标记 %d%%"
L["Mark's"] = "标记的"
L["Marker wheel"] = "标记轮盘"
L["Marks"] = "标记"
L["Master wheel"] = "主轮盘"
L["Max level"] = "满级"
L["Max width"] = "最大宽度"
L["Max zoom distance"] = "最大缩放距离"
L["Meanwhile the camera pulls back this far, and returns to your own distance afterwards. Zooming yourself leaves it where you put it."] = "同时镜头会拉远这么多，之后回到你自己的距离。你自己缩放的话，会保持在你调整的位置。"
L["Mechanical Squirrel"] = "机械松鼠"
L["Members more than 100 yards away show this much, out of reach of your heals, whatever their health, debuffs or role (unless one is your target). In a dungeon or raid, so does anyone not in it with you. In battlegrounds, where WoW Forever won't say how far anyone is, members out of range of your heals (about 40 yards) fade to this instead of the game's own dimming, on top of the rest of the page. 100% leaves them be; 0% hides them completely."] = "距离超过100码、超出你治疗范围的成员，无论生命值、减益效果或职责如何，都显示这么多（除非是你的目标）。在地下城或团队副本中，不在其中与你一起的任何人也是如此。在战场中，由于 WoW Forever 不会告知任何人的距离，超出你治疗范围（约40码）的成员会淡出到此值，而不是使用游戏自身的变暗，并叠加在本页面其余设置之上。100%表示不做处理；0%表示完全隐藏。"
L["Memory made and thrown away, a second: the game spends time clearing it up."] = "每秒产生和丢弃的内存：游戏需要花时间清理它。"
L["Menu look"] = "菜单外观"
L["Mine"] = "我的"
L["Minimal"] = "极简"
L["Minimap Glow Helper"] = "小地图光晕助手"
L["Minimap header"] = "小地图标题"
L["Minion"] = "仆从"
L["Mobs and NPCs you still need for a quest objective keep their nameplates up, with a quest mark on them and on your target frame, and the quest object in front of you glows."] = "你仍需要用于任务目标的怪物和NPC会保持显示姓名板，其上和你的目标框体上带有任务标记，你面前的任务物体也会发光。"
L["Moment"] = "时刻"
L["Moments"] = "时刻"
L["Mor'Ladim"] = "莫拉迪姆"
L["More themes"] = "更多主题"
L["Motes of its color winding in from the rim."] = "其颜色的光点从边缘蜿蜒而入。"
L["Motes spiraling in"] = "螺旋涌入的光点"
L["Mounted"] = "骑乘中"
L["Mouseover"] = "鼠标悬停"
L["Mouseover min opacity"] = "鼠标悬停最低不透明度"
L["Mouseover, at least"] = "鼠标悬停时至少"
L["Move"] = "移动"
L["Move across"] = "横向移动"
L["Move apart from the game's roll frames"] = "与游戏掷骰框分开移动"
L["Move down"] = "下移"
L["Move this emote up: its button comes first."] = "上移此表情：其按钮排在前面。"
L["Move this row down: a plate tries it later."] = "下移此行：姓名板更晚尝试它。"
L["Move this row down: its trigger tries it later."] = "下移此行：其触发条件更晚尝试它。"
L["Move this row up: a plate tries it sooner."] = "上移此行：姓名板更早尝试它。"
L["Move this row up: its trigger tries it sooner."] = "上移此行：其触发条件更早尝试它。"
L["Move this rule up: it's read before the ones below it."] = "上移此规则：它会在下方规则之前读取。"
L["Move up"] = "上移"
L["Moves a name up (or down, below 0) from where the plates put it, with its unit about 10 yards from the camera."] = "单位离镜头约10码时，将名字从姓名板放置的位置上移（低于0则下移）。"
L["Moves a name up (or down, below 0) with its unit about 50 yards from the camera, as the game's names over heads sit closer to the head further off."] = "单位离镜头约50码时，将名字上移（低于0则下移），因为越远时游戏头顶上的名字离头部越近。"
L["Moves the card from where its place puts it: right, or left below 0, as a share of the screen's width."] = "将卡片从其位置设定的地方移动：向右，低于0则向左，以占屏幕宽度的比例表示。"
L["Moves the card from where its place puts it: up, or down below 0, as a share of the screen's height."] = "将卡片从其位置设定的地方移动：向上，低于0则向下，以占屏幕高度的比例表示。"
L["Moves the marks drawn over the plate (arrow, chevron, diamond) up, or down below 0, from just over the name, while the plate shows."] = "姓名板显示时，将绘制在姓名板上方的标记（箭头、V形、菱形）从名字正上方上移，低于0则下移。"
L["Moves the marks drawn over the plate up, or down below 0, from where the plate's middle is, while nothing of the plate shows. As the plate fades in or out, the marks move between the two heights."] = "姓名板完全不显示时，将绘制在姓名板上方的标记从姓名板中心位置上移，低于0则下移。姓名板淡入或淡出时，标记会在两个高度之间移动。"
L["Moves the names up (or down, below 0) from where the plates put them."] = "将名字从姓名板放置的位置上移（低于0则下移）。"
L["Moves the real camera through this script now (click again to stop it). Its stop rules count, as for a trigger."] = "现在让真实镜头按此脚本运行（再次点击可停止）。其停止规则会生效，与由触发条件启动时相同。"
L["Moves the real camera through this script now, with a drawing of it beside the settings and its steps lit up as it goes (click again to stop it). Its stop rules count, as for a trigger."] = "现在让真实镜头按此脚本运行，设置旁会显示其示意图，步骤会随运行逐一点亮（再次点击可停止）。其停止规则会生效，与由触发条件启动时相同。"
L["Moving, jumping or Esc cancels the cast: the spin slows to a stop and turns back to where the camera was before you started. Off: it stops where it is."] = "移动、跳跃或按 Esc 会取消施法：旋转减速停下，并转回你开始施法前镜头所在的位置。关闭：停在当前位置。"
L["Music can play all through CineMode. (The other columns then have nothing to add.)"] = "音乐可以在整个CineMode期间播放。（其他列就没有什么可补充的了。）"
L["Music fades out once you leave the camera modes and move on: walking off from the cozy camera, say. Going from one camera straight to another (vista to cozy) keeps it playing, as does standing still. A fresh track fades in when the next camera starts (standing still counts once the AFK camera starts, with Go AFK's music on, Scenes page). Fades at the music fade time."] = "当你离开镜头模式并继续移动时音乐会淡出：例如从温馨镜头走开。从一个镜头直接切换到另一个（远景到温馨）会继续播放，站着不动也是。下一个镜头启动时会淡入一首新曲目（站着不动在暂离镜头启动时才算，需要开启场景页面中“暂离”的音乐）。按音乐过渡时间淡出。"
L["Music file IDs, separated by commas. One is picked at random while the Die row's Music is ticked on the Scenes page."] = "音乐文件ID，用逗号分隔。在场景页面中勾选了死亡一行的音乐时，会随机选择一个。"
L["Music file IDs, separated by commas; one is picked at random each time you die (Wowhead lists the IDs on each sound's page). Try one with /cine songtest <ID>."] = "音乐文件ID，用逗号分隔；每次你死亡时随机选择一个（Wowhead 在每个声音的页面上列出了ID）。可以用 /cine songtest <ID> 试听。"
L["Music plays in"] = "音乐播放于"
L["Music starts as its camera starts (Audio page)."] = "其镜头启动时开始播放音乐（音频页面）。"
L["Music starts as this event's camera starts, unless the addon started music within the fatigue time (Audio page). Music already playing just carries on. Off: this camera never starts music. Needs the Audio page enabled."] = "此事件的镜头启动时开始播放音乐，除非插件在疲劳时间（音频页面）内已经播放过音乐。正在播放的音乐会继续。关闭：此镜头从不播放音乐。需要启用音频页面。"
L["My %s"] = "我的%s"
L["My Scene"] = "我的场景"
L["My Shots"] = "我的机位"
L["My camera"] = "我的镜头"
L["My camera %d"] = "我的镜头%d"
L["My wheel"] = "我的轮盘"
L["NOT CINEMATIC'S"] = "不归CINEMATIC管"
L["NOT FADED"] = "未淡出"
L["NOT SHOWING IT NOW"] = "现在不显示的原因"
L["NPC"] = "NPC"
L["NPC dialogue, and how it looks: the panels behind the NPC's words, your replies and the quest's card, and the words themselves. Where it sits: the Vision tab. Changes show at once, here and on a conversation going on."] = "NPC对话及其外观：NPC文字、你的回复和任务卡片后面的面板，以及文字本身。位置：Vision 标签页。更改会立即显示，包括此处和正在进行的对话中。"
L["NPCs"] = "NPC"
L["NPCs chatting nearby"] = "附近交谈的NPC"
L["NPCs you talk to"] = "与你对话的NPC"
L["Name"] = "名称"
L["Name color:"] = "名字颜色："
L["Name style"] = "名字风格"
L["Name:"] = "名称："
L["Nameplate"] = "姓名板"
L["Nameplate distance"] = "姓名板距离"
L["Names in Russian, Korean or Chinese keep the game's font, so their letters show."] = "俄文、韩文或中文的名字保持使用游戏字体，以便正确显示字符。"
L["Near (11 yards)"] = "近（11码）"
L["Near (28 yards)"] = "近（28码）"
L["Nearby"] = "附近"
L["Nearly every one of the addon's functions timed too, not just its busy parts, each listed under the part that called it: it shows what inside a busy part costs. The timing itself takes time, so everything reads higher than it is."] = "插件几乎每个函数也都会计时，而不只是其繁忙部分，每个都列在调用它的部分下方：这会显示繁忙部分内部的开销。计时本身也需要时间，所以所有数值都会比实际偏高。"
L["Need"] = "需求"
L["Need (off spec)"] = "需求（副天赋）"
L["Need, Greed or Transmog after each name, in their colors."] = "每个名字后用各自的颜色显示需求、贪婪或幻化。"
L["Need, greed and who won."] = "需求、贪婪以及谁获得了。"
L["Neutral"] = "中立"
L["Neutral players"] = "中立玩家"
L["Never"] = "从不"
L["New features"] = "新功能"
L["New mount"] = "新坐骑"
L["New pet"] = "新宠物"
L["New scene"] = "新场景"
L["New shot..."] = "新机位……"
L["Newest first. Restoring one adds it as a new profile and switches to it; the profile it came from stays as it is."] = "最新的在前。恢复一个会将其添加为新的配置文件并切换到它；它原来所属的配置文件保持不变。"
L["Next"] = "下一个"
L["Next rank:"] = "下一级："
L["Night (game time)"] = "夜晚（游戏时间）"
L["No action"] = "无动作"
L["No border around the letters, like the game's names over heads."] = "文字周围没有描边，与游戏头顶上的名字相同。"
L["No bubble: just the words, outlined, like a film's subtitles."] = "无气泡：只有带描边的文字，就像电影字幕。"
L["No button"] = "无按钮"
L["No card coming out of a fight shorter than this, so a stray hit doesn't bring it up. 0: after every fight."] = "短于此时长的战斗结束后不显示卡片，这样零星的一次攻击不会让它出现。0：每场战斗后都显示。"
L["No card uses it yet."] = "还没有卡片使用它。"
L["No emotes match."] = "没有匹配的表情。"
L["No emotes: no card"] = "无表情：无卡片"
L["No panels behind the cards: outlined text over the world, the winner just crowned."] = "卡片后面没有面板：世界上叠加带描边的文字，获胜者只加王冠。"
L["No panels: outlined words, like a film's subtitles."] = "无面板：带描边的文字，就像电影字幕。"
L["No profile yet"] = "尚无配置文件"
L["No recording yet."] = "尚无记录。"
L["No red error text at the top of the screen (like \"Target not in line of sight\" or \"Can't do that while moving\") while you're fighting, and for the Calm Timer after it."] = "战斗中以及战斗后的平静计时内，屏幕顶部不显示红色错误文字（例如“目标不在视野中”或“移动时无法那样做”）。"
L["No red error text at the top of the screen (like \"Target not in line of sight\" or \"Can't do that while moving\") while you're out of combat."] = "非战斗中屏幕顶部不显示红色错误文字（例如“目标不在视野中”或“移动时无法那样做”）。"
L["No rolls yet."] = "尚无掷骰。"
L["No samples yet (one a second)."] = "尚无采样（每秒一次）。"
L["No scene plays it yet: pick it as a scene's camera on the Scenes page."] = "还没有场景播放它：在场景页面中把它选为某个场景的镜头。"
L["No scene plays this camera yet: pick it as a scene's camera on the Scenes page."] = "还没有场景播放此镜头：在场景页面中把它选为某个场景的镜头。"
L["No shots yet. + New shot makes one, or Import adds one a friend shared."] = "尚无机位。“+ 新建机位”可以制作一个，“导入”可以添加朋友分享的机位。"
L["No sounds: silent"] = "无音效：静音"
L["No spell"] = "无法术"
L["No tooltip yet this session: point at something, then look again"] = "本次游戏期间尚无鼠标提示：先指向某个东西，然后再看一次"
L["None found"] = "未找到"
L["None of its own: it's all %s."] = "没有它自己的：全部是%s。"
L["None yet. A built-in profile is backed up just before Reset."] = "暂无。内置配置文件会在“重置”前备份。"
L["None yet. One's taken the first day this profile changes, and just before Delete."] = "暂无。此配置文件更改的第一天以及“删除”前会备份一次。"
L["None yet. Your own profiles are backed up the first day they change, and just before Delete; built-in ones just before Reset."] = "暂无。你自己的配置文件会在更改的第一天以及“删除”前备份；内置配置文件在“重置”前备份。"
L["None: its own settings"] = "无：使用它自己的设置"
L["Normal"] = "普通"
L["Normal NPC"] = "普通NPC"
L["Not a script yet: it runs on its own code. Laying it out as steps needs %s, steps the runner doesn't have yet."] = "还不是脚本：它运行自己的代码。要把它展开为步骤需要%s，而这些步骤运行器尚不支持。"
L["Not after fights under"] = "短于此时长的战斗后不显示"
L["Not again within"] = "在此时间内不再出现"
L["Not bosses"] = "非首领"
L["Not finished: %s. Closing now puts back the rule it had."] = "未完成：%s。现在关闭会恢复它原来的规则。"
L["Not finished: %s. Its ticks decide until it is."] = "未完成：%s。完成之前由其勾选项决定。"
L["Not finished: %s. The dropdowns decide until it is."] = "未完成：%s。完成之前由下拉菜单决定。"
L["Not for dailies"] = "日常任务除外"
L["Not in %s"] = "不在%s"
L["Not in a fight."] = "不在战斗中。"
L["Not in fights"] = "战斗中除外"
L["Not in the Cooldown Manager now"] = "当前不在冷却管理器中"
L["Not on flight paths"] = "飞行路线上除外"
L["Not on it"] = "不在上面"
L["Not on screen right now."] = "目前不在屏幕上。"
L["Not on you"] = "不在你身上"
L["Not ones lasting longer than"] = "不包括持续时间超过以下时长的"
L["Not shown at all in a fight, or in the 5 seconds after one."] = "战斗中及战斗后5秒内完全不显示。"
L["Not the damage meter's numbers: your race with the player ahead of you, or your lead over #2 once you're #1. It reads the game's own damage meter, so that needs to be on (Options, Gameplay Enhancements: Enable Damage Meter). Its type: the Settings tab. How it looks: the Look tab."] = "不是伤害统计的数字：而是你与前一名玩家的竞争，或者你成为第1名后对第2名的领先。它读取游戏自带的伤害统计，所以需要开启它（选项，游戏增强：启用伤害统计）。其类型：设置标签页。外观：外观标签页。"
L["Not with a soulstone or Reincarnation"] = "有灵魂石或复生时除外"
L["Not you"] = "不是你"
L["Nothing"] = "无"
L["Nothing found yet. Smart Find looks at what's on screen: run it while the frames you want are showing."] = "尚未找到任何东西。智能查找会查看屏幕上的内容：请在你想要的框体显示时运行它。"
L["Nothing in the Cooldown Manager right now."] = "冷却管理器中目前没有任何东西。"
L["Nothing is ticked on its row: tick Always to keep it up"] = "其行上没有勾选任何项：勾选“始终”可让它保持显示"
L["Nothing of its own here: its look is on the Style tab, its sound on the Sounds tab."] = "此处没有它自己的设置：其外观在风格标签页，其音效在音效标签页。"
L["Nothing on it yet"] = "上面还没有任何东西"
L["Nothing on the meter yet."] = "统计中尚无数据。"
L["Nothing ticked"] = "未勾选任何项"
L["Nothing yet."] = "暂无。"
L["Now"] = "现在"
L["Now and then in the middle of a flight, the camera slowly turns round to look back past you, holds there, then turns back behind you. On a route's first flight (its length not known yet), just one, early on. Dragging the camera stops it. /cine flyby starts one whenever you like. Once you move the camera yourself on a flight, there are no more for that flight."] = "飞行途中不时地，镜头会缓慢转身越过你回望，停留片刻，然后转回你身后。在某条路线的第一次飞行中（尚不知道其长度），只在早期出现一次。拖动镜头会停止它。/cine flyby 可随时启动一次。在一次飞行中你自己移动过镜头后，这次飞行就不会再出现。"
L["Now: %s"] = "现在：%s"
L["Numbers follow the game's Show Numbers for Cooldowns"] = "数字遵循游戏的“显示冷却时间数字”"
L["Numbers opacity"] = "数字不透明度"
L["Object detail distance"] = "物体细节距离"
L["Object fade distance"] = "物体淡出距离"
L["Objective boxes (below the minimap)"] = "目标框（小地图下方）"
L["Objects and creatures"] = "物体和生物"
L["Off with the General page's switch."] = "随“常规”页面的开关关闭。"
L["Off-screen bubble"] = "屏幕外气泡"
L["Off-screen plates in CineMode"] = "CineMode中的屏幕外姓名板"
L["Off. Right-click to turn this page on."] = "关闭。右键点击可开启此页面。"
L["Off: %s"] = "关闭：%s"
L["Off: right-click the Profiler icon to sample."] = "关闭：右键点击性能分析器图标开始采样。"
L["Off: the UI stays as it is and the camera's left to you, with just the visual effects over it (as the Visual Effects page says), as in the Subtle profile. Triggers with CineMode ticked on the Scenes page still bring CineMode on while their camera runs: standing still or going AFK, say, for a screensaver."] = "关闭：界面保持原样，镜头由你控制，只在上面叠加视觉效果（按视觉效果页面的设置），与Subtle配置文件相同。在场景页面中勾选了CineMode的触发条件，在其镜头运行期间仍会开启CineMode：例如站着不动或暂离，可以当作屏幕保护。"
L["Offline"] = "离线"
L["Offline members are hidden whatever their health, debuffs or role (unless one is your target). How much of them still shows. 0% hides them completely."] = "离线的成员无论生命值、减益效果或职责如何都会隐藏（除非是你的目标）。此值决定他们仍显示多少。0%表示完全隐藏。"
L["Offline opacity"] = "离线时不透明度"
L["On a flight path the minimap stays hidden: pings, the reveals above and the tracking and zones under Keep open don't bring it up (you can't gather while flying), and nothing is pinged. Hovering it still shows it."] = "在飞行路线上，小地图保持隐藏：信号、上方的显示选项以及“保持打开”下的追踪和区域都不会让它出现（飞行时无法采集），也不会发出任何信号。鼠标悬停仍会显示它。"
L["On a healer"] = "在治疗者身上"
L["On a non-tank"] = "在非坦克身上"
L["On after a fight, until the Calm Timer (CineMode page) has run out. With In combat too: the fight, then that."] = "战斗后开启，直到平静计时（CineMode页面）结束。同时勾选“战斗中”时：先是战斗中，然后是此时段。"
L["On flight paths. The camera swings around behind you as you take off, sways behind you on the way and settles behind you before landing."] = "在飞行路线上。起飞时镜头转到你身后，途中在你身后摇摆，降落前稳定在你身后。"
L["On in fights, and with the Calm Timer, after them till it's run out."] = "战斗中开启；勾选平静计时时，战斗后直到其结束也开启。"
L["On out of fights, once the Calm Timer after one has run out. With Calm Timer too: as soon as a fight ends."] = "非战斗中开启，在战斗后的平静计时结束后。同时勾选平静计时时：战斗一结束就开启。"
L["On the bar:"] = "条上："
L["On the master wheel"] = "在主轮盘上"
L["On the screen"] = "屏幕上"
L["On while a camera mode runs (flights, AFK, cozy and the rest)."] = "镜头模式运行时开启（飞行、暂离、温馨等）。"
L["On while you have one of these targeted, out of fights."] = "非战斗中选中这些目标之一时开启。"
L["On while you're in any of these (Party and Raid: in one, wherever you are)."] = "当你处于其中任一情况时开启（小队和团队：在其中，无论身在何处）。"
L["On you"] = "在你身上"
L["On. Right-click to turn this page off."] = "开启。右键点击可关闭此页面。"
L["On: Heal Vision works as ticked below. Off: it doesn't, and each keeps its tick for when you turn this back on."] = "开启：Heal Vision 按下方的勾选项工作。关闭：不工作，每项都会保留其勾选状态，以便你重新开启时使用。"
L["On: chat bubbles look as this page says. Off: the game's own bubbles (the preview shows that too). Each setting keeps its value for when you turn this back on. (Not in instances on retail: the game doesn't let addons change bubbles there.)"] = "开启：聊天气泡按本页面的设置显示外观。关闭：游戏自己的气泡（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。（在正式服的副本中不适用：游戏不允许插件在那里更改气泡。）"
L["On: chat bubbles show where this page says. Off: the game's own chat bubble settings, as you had them."] = "开启：聊天气泡按本页面的设置在相应位置显示。关闭：游戏自己的聊天气泡设置，保持你原来的设置。"
L["On: each card shows as its row says. Off: none of them do, and each row keeps its tick for when you turn this back on."] = "开启：每张卡片按其行的设置显示。关闭：都不显示，每行都会保留其勾选状态，以便你重新开启时使用。"
L["On: each card shows as the Events tab says, as this tab sets it. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "开启：每张卡片按事件标签页的设置显示，并使用此标签页的设置。关闭：都不显示。每项设置都会保留其值，以便你重新开启时使用。"
L["On: each card shows as the Events tab says, in its style. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "开启：每张卡片按事件标签页的设置显示，使用其风格。关闭：都不显示。每项设置都会保留其值，以便你重新开启时使用。"
L["On: each card shows as the Events tab says, looking as its Style page says. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "开启：每张卡片按事件标签页的设置显示，外观按其风格页面的设置。关闭：都不显示。每项设置都会保留其值，以便你重新开启时使用。"
L["On: each card shows as the Events tab says, with its sounds. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "开启：每张卡片按事件标签页的设置显示，带有其音效。关闭：都不显示。每项设置都会保留其值，以便你重新开启时使用。"
L["On: every Style page looks as it says. Off: none of them do; everything shows the game's look. Each page keeps its settings for when you turn this back on."] = "开启：每个风格页面按其设置显示外观。关闭：都不生效；所有东西都显示游戏的外观。每个页面都会保留其设置，以便你重新开启时使用。"
L["On: everything below works as ticked. Off: none of it does, and each keeps its tick for when you turn this back on."] = "开启：下方的所有内容按勾选项工作。关闭：都不工作，每项都会保留其勾选状态，以便你重新开启时使用。"
L["On: it looks as this page says. Off: Cinematic's plain look (the defaults). Each setting keeps its value for when you turn this back on."] = "开启：按本页面的设置显示外观。关闭：Cinematic的朴素外观（默认值）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: it shows as you cast. Off: it doesn't, and keeps its settings for when you turn this back on."] = "开启：施法时显示。关闭：不显示，并保留其设置，以便你重新开启时使用。"
L["On: new messages, typing, unread whispers and scrolling back bring up the chat windows as this page says. Off: none of them do, and the chat windows fade as their Game Frames row says."] = "开启：新消息、输入文字、未读密语和向上滚动会按本页面的设置调出聊天窗口。关闭：都不会，聊天窗口按其游戏框体行的设置淡出。"
L["On: right-click (or a gamepad button) casts again, and the Fishing cast bar hides, as this page says. Off: fishing is left to the game. (The fish camera is on the Scenes page.)"] = "开启：右键点击（或手柄按键）会再次抛竿，钓鱼施法条按本页面的设置隐藏。关闭：钓鱼交给游戏处理。（钓鱼镜头在场景页面。）"
L["On: the bars look as this page says. Off: Cinematic's own, thin black bars sliding in with the UI's fade (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：黑边按本页面的设置显示外观。关闭：Cinematic自己的细黑边，随界面淡出一起滑入（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the bars look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：条按本页面的设置显示外观。关闭：游戏自己的外观（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the button looks as this page says. Off: like the game's extra ability button (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：按钮按本页面的设置显示外观。关闭：与游戏的额外技能按钮相同（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the camera moves over your right shoulder. This uses one of Blizzard's experimental camera settings: the game shows its experimental camera warning (Accept keeps it working). The game's Keep Character Centered option (Accessibility) stops it, so that's turned off meanwhile. Off: your own settings come back."] = "开启：镜头移到你的右肩上方。这使用了暴雪的一项实验性镜头设置：游戏会显示实验性镜头警告（点击“接受”可让它继续工作）。游戏的“保持角色居中”选项（辅助功能）会阻止它，因此在此期间会关闭该选项。关闭：恢复你自己的设置。"
L["On: the cameras start as the rows below say. Off: none of them ever starts, and the camera is left to you; CineMode still fades the UI."] = "开启：镜头按下方各行的设置启动。关闭：都不会启动，镜头由你控制；CineMode仍会淡出界面。"
L["On: the cards show as ticked below. Off: none do, and it keeps its settings for when you turn this back on."] = "开启：卡片按下方的勾选项显示。关闭：都不显示，并保留其设置，以便你重新开启时使用。"
L["On: the cast bars look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：施法条按本页面的设置显示外观。关闭：游戏自己的外观（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the dialogue looks as this page says. Off: parchment, in the game's fonts (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：对话按本页面的设置显示外观。关闭：羊皮纸样式，使用游戏字体（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the edges look as this page says. Off: as they start out (each setting keeps its value for when you turn this back on)."] = "开启：边缘按本页面的设置显示外观。关闭：使用初始外观（每项设置都会保留其值，以便你重新开启时使用）。"
L["On: the graph samples the game's figure every second and keeps it over a reload, and you can record. Off (to start with): nothing is sampled or saved, and it costs nothing."] = "开启：图表每秒采样一次游戏的数据并在重载后保留，你也可以记录。关闭（初始状态）：不采样也不保存，没有任何开销。"
L["On: the marks and colors on this page show on the plates, when the Nameplates page's Target Indicator row says. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "开启：当姓名板页面的目标指示器行允许时，本页面的标记和颜色会显示在姓名板上。关闭：都不显示。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the raid frames look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：团队框体按本页面的设置显示外观。关闭：游戏自己的外观（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the settings below, as you've set them. Off: the game's own settings, put back as they were."] = "开启：使用下方你设定的设置。关闭：恢复游戏自己的设置，保持原样。"
L["On: the unit frames look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：单位框体按本页面的设置显示外观。关闭：游戏自己的外观（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: the unit frames show the parts the grids below say. Off: CineMode leaves them alone, every part showing as the game has it."] = "开启：单位框体显示下方表格中设定的部分。关闭：CineMode不做处理，每个部分都按游戏原样显示。"
L["On: the window looks as this page says. Off: as Roll Vision has always looked. Each setting keeps its value for when you turn this back on."] = "开启：窗口按本页面的设置显示外观。关闭：与 Roll Vision 一直以来的外观相同。每项设置都会保留其值，以便你重新开启时使用。"
L["On: these names look as this page says. Off: as the nameplate draws them: white or gray for every unit, with a heavy black outline, growing and shrinking with distance (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：这些名字按本页面的设置显示外观。关闭：按姓名板的绘制方式：每个单位都是白色或灰色，带粗黑描边，随距离放大缩小（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: this page's peeks bring your buffs and debuffs up in CineMode. Off: no peeks; they still fade as their Game Frames row says."] = "开启：本页面的短暂显示会在CineMode中调出你的增益和减益效果。关闭：不会短暂显示；它们仍按其游戏框体行的设置淡出。"
L["On: this page's settings can bring the minimap up or keep it up in CineMode. Off: they don't; it still fades as its Game Frames rows say."] = "开启：本页面的设置可以在CineMode中调出小地图或让它保持显示。关闭：不会；它仍按其游戏框体行的设置淡出。"
L["On: this page's settings can bring the quest tracker, quest timer and durability figure up in CineMode. Off: they don't; they still fade as their Game Frames rows say."] = "开启：本页面的设置可以在CineMode中调出任务追踪、任务计时器和耐久度人形图。关闭：不会；它们仍按其游戏框体行的设置淡出。"
L["On: this page's settings can fade out the bars you aren't using. Off: they don't; the swing timer still fades as its Game Frames row says, every bar alike."] = "开启：本页面的设置可以淡出你未使用的计时条。关闭：不会；攻击计时条仍按其游戏框体行的设置淡出，所有计时条都一样。"
L["On: this page's settings can keep the Cooldown Manager up in CineMode, or show only the icons you pick. Off: they don't; it still fades as its Game Frames row says."] = "开启：本页面的设置可以在CineMode中让冷却管理器保持显示，或只显示你选择的图标。关闭：不会；它仍按其游戏框体行的设置淡出。"
L["On: tooltips look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "开启：鼠标提示按本页面的设置显示外观。关闭：游戏自己的外观（预览中也会显示）。每项设置都会保留其值，以便你重新开启时使用。"
L["On: with your game music off, a camera starting (the ones ticked under Music on the Camera Triggers page) switches it on and fades it in, at your music volume; it fades out when the UI returns and your music is switched off again (logging out too). With your game music on, it's left alone, bar the stops below. Off: CineMode leaves your music alone."] = "开启：如果你的游戏音乐已关闭，镜头启动时（镜头触发页面“音乐”下勾选的镜头）会以你的音乐音量开启并淡入音乐；界面恢复时淡出，你的音乐也会再次关闭（登出时也是）。如果你的游戏音乐已开启，则不做处理，下方的停止选项除外。关闭：CineMode不处理你的音乐。"
L["On: your player frame, pet frame and personal resource display stay up or wait as this page says, and its mana bar and mana cost show. Off: none of it; they come up only as their Game Frames rows say."] = "开启：你的玩家框体、宠物框体和个人资源显示会按本页面的设置保持显示或等待，并显示其法力条和法力消耗。关闭：都不会；它们只按其游戏框体行的设置出现。"
L["Once anyone picks need, players on greed or transmog for that item aren't listed (they can't win it), only counted on a \"Lower picks\" line. Players still choosing stay listed. Click an item's panel to list everyone on it."] = "一旦有人对某件物品选择了需求，选择贪婪或幻化的玩家就不会被列出（他们赢不了），只在“较低的选择”一行中计数。仍在选择的玩家会保留在列表中。点击物品的面板可列出所有人。"
L["Once it has swung round to face you, the camera sways gently from side to side in front of your character, pausing between moves."] = "转到面对你之后，镜头会在你角色前方轻轻左右摇摆，每次移动之间会停顿。"
L["Once round in front, the spin keeps going and picks up speed until you go. 0 keeps a steady speed."] = "转到前方后，旋转会继续并加速，直到你被传送走。0 表示保持匀速。"
L["Once the camera has settled on a speaker, it drifts slowly to and fro, side to side, across this many degrees, so the shot isn't stock-still. 0 holds still."] = "镜头稳定在说话者身上后，会在这么多度的范围内缓慢左右来回漂移，让画面不会完全静止。0 表示保持静止。"
L["Once the camera has settled, it drifts slowly to and fro, side to side, across this many degrees, so the shot isn't stock-still. 0 holds still."] = "镜头稳定后，会在这么多度的范围内缓慢左右来回漂移，让画面不会完全静止。0 表示保持静止。"
L["Once the conversation's over, the camera zooms back out to your own distance at this speed (not if you zoomed yourself meanwhile). At 0 it stays in."] = "对话结束后，镜头以此速度拉远回你自己的距离（如果你在此期间自己缩放过则不会）。为0时保持拉近。"
L["Once you're there (after the loading screen, if there is one), the camera swings around behind you."] = "抵达后（如果有载入画面，则在其之后），镜头会转到你身后。"
L["Once you've stood still for a while with the UI faded, or as soon as you go AFK, the camera slowly sweeps around your character. Moving stops it. What starts it, and how long you stand still first, is on the Scenes page."] = "在界面淡出的状态下站着不动一段时间后，或一进入暂离状态，镜头就会缓慢地围绕你的角色环绕。移动会停止它。什么会启动它以及需要先站多久，在场景页面中设置。"
L["One line under the game's zone name, as it comes in at login, in place of a card. (The look above is the card's.)"] = "登录时在游戏区域名称下方显示一行，代替卡片。（上方的外观是卡片的。）"
L["One size at any distance. Unticked, a name grows and shrinks with its plate as its unit comes nearer or goes."] = "在任何距离都是同一大小。未勾选时，名字会随单位靠近或远离而与其姓名板一起放大缩小。"
L["One thing that starts this scene: an emote you do, a spell you cast, a buff on you, a place you're in, a moment (leveling up...), something you are (mounted...), or a key you press. Any one of a scene's triggers starts it."] = "启动此场景的一个条件：你做的表情、你施放的法术、你身上的增益效果、你所在的地点、某个时刻（升级……）、你的某种状态（骑乘……）或你按下的按键。场景的任一触发条件都能启动它。"
L["Only after progress"] = "仅在有进展后"
L["Only after you use mana, for"] = "仅在你消耗法力后，持续"
L["Only in CineMode"] = "仅在CineMode中"
L["Only in combat"] = "仅在战斗中"
L["Only items of this quality and better get a panel in the window. Rolls on the rest are only in chat. The test (/cine rolls test) goes by it too."] = "只有此品质及以上的物品才会在窗口中有面板。其余物品的掷骰只在聊天中显示。测试（/cine rolls test）也按此设置。"
L["Only items you can use"] = "仅限你能使用的物品"
L["Only out of combat"] = "仅在非战斗中"
L["Only show the best pick"] = "只显示最好的选择"
L["Only the buff you gained or refreshed shows; your other buffs stay faded. Hovering shows them all. In fights too, for new buffs (procs and the like)."] = "只显示你获得或刷新的那个增益效果；你的其他增益效果保持淡出。鼠标悬停可显示全部。对于新的增益效果（触发效果之类），战斗中也是如此。"
L["Only while you stand still"] = "仅在你站着不动时"
L["Only with Zone ticked: it takes the game's zone text away. Its look follows Zone's until it's given its own here; its lines are Zone's."] = "仅在勾选“区域”时：它会移除游戏的区域文字。其外观跟随“区域”，直到在这里给它单独设置；其行与“区域”相同。"
L["Only:"] = "仅："
L["Opacity"] = "不透明度"
L["Opacity while hidden"] = "隐藏时不透明度"
L["Opacity:"] = "不透明度："
L["Open"] = "打开"
L["Open its settings page"] = "打开其设置页面"
L["Open on Scenes >"] = "在场景中打开 >"
L["Open on Scripts >"] = "在脚本中打开 >"
L["Open or close this moment's emotes."] = "打开或关闭此时刻的表情。"
L["Open the Profiler"] = "打开性能分析器"
L["Open the log"] = "打开日志"
L["Opens the Card Vision page."] = "打开 Card Vision 页面。"
L["Opens the Settings tab with this event picked."] = "打开设置标签页并选中此事件。"
L["Opens the Sounds tab with this event picked."] = "打开音效标签页并选中此事件。"
L["Opens the Style hub's Cast bars page: how nameplate cast bars look."] = "打开风格中心的施法条页面：姓名板施法条的外观。"
L["Opens the Style hub's Chat bubbles page: how off-screen bubbles look and where they show."] = "打开风格中心的聊天气泡页面：屏幕外气泡的外观和显示位置。"
L["Opens the Style hub's Chat bubbles page: how the bubbles and speech from behind you look."] = "打开风格中心的聊天气泡页面：气泡和来自你身后的话语的外观。"
L["Opens the Style hub's Nameplates page: how nameplates look."] = "打开风格中心的姓名板页面：姓名板的外观。"
L["Opens the Style hub's Names page: how names over heads look."] = "打开风格中心的名字页面：头顶上名字的外观。"
L["Opens the Style hub's Personal Resource Display page: how the bars look."] = "打开风格中心的个人资源显示页面：条的外观。"
L["Opens the Style hub's Raid frames page: how the raid and raid-style party frames look."] = "打开风格中心的团队框体页面：团队框体和团队样式小队框体的外观。"
L["Opens the Style hub's Tooltips page: how tooltips look."] = "打开风格中心的鼠标提示页面：鼠标提示的外观。"
L["Opens the Style hub's Unit frames page: how the frames look."] = "打开风格中心的单位框体页面：框体的外观。"
L["Opens the Style tab with this event picked."] = "打开风格标签页并选中此事件。"
L["Opens the rule editor, for AND, NOT and more places and situations than the dropdowns have."] = "打开规则编辑器，可使用 AND、NOT 以及比下拉菜单更多的地点和情况。"
L["Opens this chat window's lines to copy."] = "打开此聊天窗口的内容以供复制。"
L["Opens this style on the Card Types tab: a change there is for every card using it."] = "在卡片类型标签页打开此风格：在那里的更改对使用它的每张卡片生效。"
L["Or find one:"] = "或查找一个："
L["Or hits adding up to"] = "或累计伤害达到"
L["Orbiting stars"] = "环绕的星星"
L["Other NPCs talking near you, such as a city's citizens chatting among themselves. The same chat camera, once you've stood still for the time below, so passers-by don't swing it about while you're busy."] = "你附近交谈的其他NPC，例如城市里互相聊天的市民。使用同样的聊天镜头，但需要你站着不动达到下方的时间，这样你忙碌时路人不会让镜头乱转。"
L["Other buffs"] = "其他增益效果"
L["Other frames"] = "其他框体"
L["Out of combat"] = "非战斗中"
L["Out of how many"] = "总数"
L["Outdoors"] = "户外"
L["Outline"] = "描边"
L["Outline color"] = "描边颜色"
L["Outline:"] = "描边："
L["Over %s"] = "超过%s"
L["Over after no one talks for"] = "多久无人说话后结束"
L["Over it"] = "在其上方"
L["Own row"] = "自己的行"
L["PARTLY SHOWN"] = "部分显示"
L["Pages"] = "页面"
L["Panel"] = "面板"
L["Panel:"] = "面板："
L["Panels"] = "面板"
L["Panels:"] = "面板："
L["Parchment, as the dialogue has always looked (the defaults)."] = "羊皮纸样式，与对话一直以来的外观相同（默认值）。"
L["Part"] = "部件"
L["Party frames (raid-style)"] = "小队框体（团队样式）"
L["Party title"] = "小队标题"
L["Pass"] = "放弃"
L["Passed: %s"] = "放弃：%s"
L["Passive"] = "被动"
L["Past 28 yards"] = "28码以外"
L["Past 40 yards"] = "40码以外"
L["Paste in a script someone shared (Ctrl+V), then Add script. It's added as a new script of yours."] = "粘贴别人分享的脚本（Ctrl+V），然后点击“添加脚本”。它会作为你自己的新脚本添加。"
L["Paste in a wheel someone shared (Ctrl+V), read what's on it below, and Add wheel. It's added as a new wheel of yours."] = "粘贴别人分享的轮盘（Ctrl+V），在下方阅读上面的内容，然后点击“添加轮盘”。它会作为你自己的新轮盘添加。"
L["Paste the text a friend sent (Ctrl+V). What it holds shows below before you add it."] = "粘贴朋友发来的文本（Ctrl+V）。添加前，其内容会显示在下方。"
L["Pattern:"] = "图案："
L["Peak"] = "峰值"
L["People joining and leaving your group."] = "有人加入和离开你的队伍。"
L["Personal Resource Display"] = "个人资源显示"
L["Personal mana bar"] = "个人法力条"
L["Personal resource display"] = "个人资源显示"
L["Pick Greed's color."] = "选择贪婪的颜色。"
L["Pick Need's color."] = "选择需求的颜色。"
L["Pick Transmog's color."] = "选择幻化的颜色。"
L["Pick a frame in game"] = "在游戏中选取框体"
L["Pick a level to try it now. You can change it any time, here or on the Profiles page."] = "选择一个等级立即试用。你可以随时在这里或配置文件页面更改。"
L["Pick a profile to switch to it."] = "选择一个配置文件以切换到它。"
L["Pick a setting"] = "选择一项设置"
L["Pick an emote to add as a button on this card: a common one, any of the game's, or a voice emote (said out loud). Up to six."] = "选择一个表情，作为按钮添加到此卡片上：常用表情、游戏中的任何表情或语音表情（会说出声）。最多六个。"
L["Pick its style, then how its words and frame look and where it sits. The font, outline, shadow and border start on Visions Style's. Press Test and close the settings to see it."] = "选择其风格，然后设置其文字和框架的外观以及位置。字体、描边、阴影和边框以 Visions 风格的设置为起点。按“测试”并关闭设置即可看到。"
L["Pick its type, then that type's settings below. Press Test and close the settings to see it. Its colors and words: the Look tab."] = "选择其类型，然后在下方设置该类型的选项。按“测试”并关闭设置即可看到。其颜色和文字：外观标签页。"
L["Pick sounds for this rule from the game's."] = "从游戏的音效中为此规则选择音效。"
L["Pick the bar's color."] = "选择条的颜色。"
L["Pick the bars' color."] = "选择条的颜色。"
L["Pick the color of a cast or channel that can't be interrupted."] = "选择无法打断的施法或引导的颜色。"
L["Pick the color of a cast that was interrupted (when the game says: not in every fight)."] = "选择被打断的施法的颜色（在游戏告知时：并非每场战斗都会）。"
L["Pick the color of a cast."] = "选择施法的颜色。"
L["Pick the color of a channel."] = "选择引导的颜色。"
L["Pick the glow's color."] = "选择光晕的颜色。"
L["Pick the line's color."] = "选择线的颜色。"
L["Pick the outline's color."] = "选择描边的颜色。"
L["Pick the pulse's color."] = "选择脉动的颜色。"
L["Pick the small lines' color."] = "选择小线条的颜色。"
L["Pick the text's color."] = "选择文字的颜色。"
L["Pick the winner's color."] = "选择获胜者的颜色。"
L["Pick when each spell's icon shows. Always: as the game shows it. When ready: out of fights, and while it recharges, it fades out; it comes back once it's ready, or the seconds in its box before (empty: %d%% of its cooldown). While recharging: in fights or not, it shows only while it recharges. When it procs: in fights or not, it shows only while the game makes it glow (a proc, like an instant Lightning Bolt). A faded icon keeps its place in the bar. In fights the game may not say how long is left, so then it goes by when you last cast it. The settings beside each group's name set every spell in it at once."] = "选择每个法术的图标何时显示。始终：按游戏的显示方式。就绪时：非战斗中以及冷却恢复期间淡出；就绪时重新出现，或在就绪前其框中填写的秒数时出现（留空：其冷却时间的%d%%）。冷却恢复中：无论是否在战斗中，只在冷却恢复期间显示。触发时：无论是否在战斗中，只在游戏让它发光时显示（触发效果，例如瞬发闪电箭）。淡出的图标在条中保留其位置。战斗中游戏可能不会告知剩余时间，所以那时按你上次施放的时间计算。每个分组名称旁的设置会一次性设置其中的所有法术。"
L["Picked now"] = "当前已选"
L["Picking up an item or spell (to drag it to your action bars, say) brings the UI back until you put it down. Off: picking things up never does; mouse over a faded bar to see it when dragging there."] = "拿起物品或法术（例如拖到你的动作条上）会让界面重新出现，直到你放下它。关闭：拿起东西从不会让界面出现；拖动到淡出的动作条时，把鼠标悬停在其上即可看到它。"
L["Picks"] = "选择"
L["Place"] = "地点"
L["Place:"] = "地点："
L["Plain discs on arrows: you in your color, them in their class's."] = "箭头上的纯色圆盘：你用你的颜色，他们用其职业颜色。"
L["Plate"] = "姓名板"
L["Plate color"] = "姓名板颜色"
L["Plate off screen"] = "姓名板在屏幕外"
L["Plate parts"] = "姓名板部件"
L["Plate size %d%%"] = "姓名板大小 %d%%"
L["Plate size %d%% x %d%%"] = "姓名板大小 %d%% x %d%%"
L["Plate style"] = "姓名板风格"
L["Play %s"] = "播放%s"
L["Play as usual. Stop on the Profiler page ends it."] = "照常游戏即可。在性能分析器页面点击“停止”可结束。"
L["Play it, at its volume."] = "以其音量播放。"
L["Play it, to see it (at no one)."] = "播放它看看效果（不针对任何人）。"
L["Play this shot now (stand still). Press it again, or move, to stop."] = "现在播放此机位（请站着不动）。再按一次或移动可停止。"
L["Played by"] = "播放者"
L["Played by: %s"] = "播放者：%s"
L["Player frame waits for your health or power to change"] = "玩家框体等待你的生命值或能量变化"
L["Players in their class color, everyone else red, yellow or green by how they see you."] = "玩家使用其职业颜色，其他所有单位按其对你的态度显示为红色、黄色或绿色。"
L["Players shown per item in a raid"] = "团队中每件物品显示的玩家数"
L["Players' names in their class color, NPCs' in their reaction to you (red, yellow or green)."] = "玩家的名字使用其职业颜色，NPC的名字按其对你的关系着色（红色、黄色或绿色）。"
L["Players' names show in their class color, as in the chat window. NPCs' don't have one."] = "玩家的名字以其职业颜色显示，与聊天窗口中相同。NPC没有职业颜色。"
L["Players, friendly or enemy as the Nameplates page has them (the other faction's are enemies)."] = "玩家，按姓名板页面的设定分为友方或敌方（另一阵营的为敌方）。"
L["Plays a card in this style in the preview and on your screen (close the settings to see it there): the first card using it, else the zone you're in."] = "在预览中和你的屏幕上播放一张此风格的卡片（关闭设置即可在屏幕上看到）：使用它的第一张卡片，否则为你所在的区域。"
L["Plays the card in the preview and on your screen, as it will look, with its sound (close the settings to see it there). A card with moments (Duel) plays each in turn; clicking Stop ends it."] = "在预览中和你的屏幕上播放卡片，按其实际外观，并带有音效（关闭设置即可在屏幕上看到）。带有多个时刻的卡片（决斗）会依次播放每个时刻；点击“停止”可结束。"
L["Plays the scenes of yours whose trigger is this key: set a scene's trigger to it on the Scenes page. Press again to stop it."] = "播放你自己那些以此按键为触发条件的场景：在场景页面中将某个场景的触发条件设为它。再按一次可停止。"
L["Points left"] = "剩余点数"
L["Pop out"] = "弹出"
L["Pop out: drag the window anywhere (by its edge). Dock: back beside the settings."] = "弹出：把窗口拖到任何位置（拖动其边缘）。停靠：回到设置旁边。"
L["Portal ring"] = "传送门光环"
L["Portrait"] = "头像"
L["Portrait:"] = "头像："
L["Position"] = "位置"
L["Position:"] = "位置："
L["Power"] = "能量"
L["Power bar"] = "能量条"
L["Preset"] = "预设"
L["Preset:"] = "预设："
L["Press Ctrl+C to copy this, then paste it wherever your friend will see it."] = "按 Ctrl+C 复制，然后粘贴到你朋友能看到的地方。"
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import a wheel on their Your wheels page."] = "按 Ctrl+C 复制，然后粘贴到你朋友们能看到的地方。他们可以在“你的轮盘”页面用“导入轮盘”添加。"
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import on their Scripts page."] = "按 Ctrl+C 复制，然后粘贴到你朋友们能看到的地方。他们可以在脚本页面用“导入”添加。"
L["Pressing Enter to type brings up the chat window with the input box where it's ticked. Elsewhere just the input box comes up, so you can type without the chat window (or Mouseover groups set to come up for Typing) showing."] = "在勾选的地方，按回车输入文字时会调出带输入框的聊天窗口。在其他地方只会出现输入框，这样你可以输入文字而不显示聊天窗口（或设为在输入文字时出现的鼠标悬停分组）。"
L["Preview"] = "预览"
L["Previewing - %s"] = "预览中 - %s"
L["Previously"] = "前情提要"
L["Previously, on %s"] = "前情提要，于%s"
L["Print to chat"] = "输出到聊天"
L["Profession"] = "专业"
L["Profiler"] = "性能分析器"
L["Profiler: press Ctrl+C to copy"] = "性能分析器：按 Ctrl+C 复制"
L["Progress in a scenario (the stages and objectives the tracker shows for some raid bosses, dungeons and events) shows the quest tracker the same way."] = "场景战役中的进展（追踪中为某些团队首领、地下城和活动显示的阶段和目标）也会以同样的方式显示任务追踪。"
L["Put %s back as it comes?"] = "将%s恢复为原样？"
L["Put back"] = "恢复"
L["Put every spell's, buff's and group's icon setting, and Smart set, back to the active profile's own."] = "将每个法术、增益效果和分组的图标设置以及“智能设置”恢复为当前配置文件自身的设置。"
L["Put everything back over %s s"] = "在%s秒内全部恢复"
L["Put the %d points the plan adds into your talents window, for its Apply Changes."] = "把方案新增的%d点放入你的天赋窗口，以便点击“应用更改”。"
L["Put the active profile back to how you last saved it, or a built-in one back to its own values (your own profiles keep your changes as you go)."] = "将当前配置文件恢复为你上次保存时的状态，或将内置配置文件恢复为其自身的值（你自己的配置文件会随时保留你的更改）。"
L["Put the mouse on it"] = "把鼠标放在上面"
L["Put the profile %s back to how you last saved it? Changes you've made since then go."] = "将配置文件%s恢复为你上次保存时的状态？此后所做的更改都会丢失。"
L["Put the turn and tilt back over %s s"] = "在%s秒内恢复转向和倾斜"
L["Put these settings back to the profile's own?"] = "将这些设置恢复为配置文件自身的设置？"
L["Puts one of the event's own settings back, to come from the style it starts from again."] = "恢复事件自己的一项设置，使其重新来自其起始风格。"
L["Puts one of your changes to the style back, as it comes."] = "将你对风格的一项更改恢复为原样。"
L["Puts our script back, made from its camera's settings again, in place of your changes (click twice)."] = "恢复我们的脚本，重新根据其镜头的设置生成，替换你的更改（点击两次）。"
L["Puts the card back where it starts: just above where speech from behind you shows (the Chat Bubbles page's Move), beside the chat window."] = "将卡片放回其起始位置：在来自你身后的话语显示位置的正上方（聊天气泡页面的“移动”），聊天窗口旁边。"
L["Puts the rule's words back in the dropdowns."] = "把规则中的词放回下拉菜单中。"
L["Puts this theme back as it comes, undoing your changes to its own settings (edge, colors, sparks, heartbeat)."] = "将此主题恢复为原样，撤销你对其自身设置（边缘、颜色、火花、心跳）的更改。"
L["PvP flagged"] = "处于PvP状态"
L["PvP icon"] = "PvP图标"
L["Quest Item Button"] = "任务物品按钮"
L["Quest Vision"] = "Quest Vision"
L["Quest Vision's list of replies and its bubble too."] = "Quest Vision 的回复列表及其气泡也是。"
L["Quest complete"] = "任务完成"
L["Quest givers"] = "任务NPC"
L["Quest icon by their nameplates or names"] = "姓名板或名字旁的任务图标"
L["Quest item button"] = "任务物品按钮"
L["Quest mark (!)"] = "任务标记（!）"
L["Quest mark icon"] = "任务标记图标"
L["Quest mobs' nameplates and marks, the quest item button, the glow on quest objects, and where the dialogue sits."] = "任务怪的姓名板和标记、任务物品按钮、任务物体的光晕以及对话的位置。"
L["Quest objective"] = "任务目标"
L["Quest talk"] = "任务对话"
L["Quest talk is on: talking to an NPC, what they say and what you can say back show here instead of the game's window"] = "任务对话已开启：与NPC对话时，他们说的话和你可以回答的内容会显示在这里，而不是游戏窗口中"
L["Quest/widget icons"] = "任务/小部件图标"
L["Questie's quest tracker and its quest item buttons fade with the Quest tracker row on the Game Frames page."] = "Questie 的任务追踪及其任务物品按钮会随游戏框体页面上的任务追踪行一起淡出。"
L["Quests done"] = "完成的任务"
L["Race track"] = "赛道"
L["Rage, runic power and the like count until drained"] = "怒气、符文能量等在清空前都计算在内"
L["Rage, runic power and the other resources that drain away out of combat count too: the frames ticked above stay up until they're back to 0, within the Calm Timer."] = "怒气、符文能量以及其他在非战斗时会逐渐消退的资源也计算在内：上方勾选的框体会在平静计时内保持显示，直到它们回到0。"
L["Raid marker"] = "团队标记"
L["Raid-style"] = "团队样式"
L["Raid-style party buffs"] = "团队样式小队增益效果"
L["Raid-style party debuffs"] = "团队样式小队减益效果"
L["Raid-style party pet names"] = "团队样式小队宠物名字"
L["Raid-style party pets"] = "团队样式小队宠物"
L["Raid-style party player names"] = "团队样式小队玩家名字"
L["Raid-style party players"] = "团队样式小队玩家"
L["Raid-style party role icons"] = "团队样式小队职责图标"
L["Raid-style party threat highlight"] = "团队样式小队仇恨高亮"
L["Raid-style party title"] = "团队样式小队标题"
L["Raises the game's max camera distance (to 2.6) while pulled back, so the zoom isn't cut short. Your own maximum comes back once you've zoomed in again."] = "拉远时提高游戏的最大镜头距离（到2.6），以免缩放被截断。你再次拉近后，会恢复你自己的最大值。"
L["Random fly-bys are spread over the part of the flight below: one per this many seconds of it (at least one), each at a random moment in its share."] = "随机掠过分布在下方设定的飞行区段内：每这么多秒出现一次（至少一次），每次都在其所属时段内的随机时刻。"
L["Random zoom only. Each pause is picked at random this much shorter or longer than the pause above: 3 sec with a 10 sec pause waits anywhere from 7 to 13 sec. 0 keeps every pause the same."] = "仅限随机缩放。每次间隔在上方的间隔基础上随机缩短或延长最多此值：间隔10秒、浮动3秒时，会等待7到13秒之间的任意时长。0 表示每次间隔都相同。"
L["Rank %d/%d"] = "等级 %d/%d"
L["Rank ladder"] = "排名阶梯"
L["Rare"] = "稀有"
L["Rare and up"] = "稀有及以上"
L["Rare elite"] = "稀有精英"
L["Reach"] = "范围"
L["Reach, sides"] = "范围，两侧"
L["Reach, top and bottom"] = "范围，上下"
L["Read every command before you add it: each runs as if you'd typed it, and /run ones can do anything an addon can."] = "添加前请阅读每条命令：每条命令都会像你亲自输入一样运行，而 /run 命令可以做插件能做的任何事。"
L["Ready"] = "就绪"
L["Ready also needs the resources to cast it: Maelstrom, mana, rage and so on. Until you have them the icon stays faded."] = "就绪还需要有施放它所需的资源：漩涡、法力、怒气等。在你拥有这些资源之前，图标保持淡出。"
L["Ready check"] = "就位确认"
L["Ready: it's up (you're near the quest's area) and not cooling down."] = "就绪：它可用（你在任务区域附近）且不在冷却中。"
L["Recap after:"] = "之后显示回顾："
L["Recaps"] = "回顾"
L["Recently deleted"] = "最近删除"
L["Record"] = "记录"
L["Recording (the addon's own timers)"] = "记录（插件自己的计时器）"
L["Recording CPU  %d:%02d"] = "记录CPU  %d:%02d"
L["Recording: %d:%02d left."] = "记录中：剩余%d:%02d。"
L["Red for hostile units, yellow for neutral ones and green for friendly ones, as over their heads. Unticked: the plate's own color, white or gray."] = "敌对单位为红色，中立单位为黄色，友方单位为绿色，与他们头顶上的一样。未勾选：姓名板自己的颜色，白色或灰色。"
L["Reduce view distance in rain"] = "下雨时缩短视野距离"
L["Regenerate"] = "重新生成"
L["Released to a graveyard with no spirit healer's countdown, the dark edges stay as you walk back, and lift the closer you get to your body, gone once you're there."] = "释放灵魂到没有灵魂医者倒计时的墓地后，暗色边缘会在你跑回去时保持，并随着你接近尸体逐渐褪去，到达后消失。"
L["Reload button on the screen"] = "屏幕上的重载按钮"
L["Reload the UI"] = "重载界面"
L["Reloads the UI, like /reload. With Keep windows open across a reload ticked (Quality of life > General), what you had open opens again after."] = "重载界面，与 /reload 相同。勾选了“重载后保持窗口打开”（便利功能 > 常规）时，之后会重新打开你之前打开的东西。"
L["Remove this copy."] = "移除此副本。"
L["Remove this row. Add it again under the grid."] = "移除此行。可在表格下方重新添加。"
L["Remove this rule and its sounds."] = "移除此规则及其音效。"
L["Remove this step"] = "移除此步骤"
L["Remove this trigger."] = "移除此触发条件。"
L["Rename the camera:"] = "重命名镜头："
L["Rename the theme:"] = "重命名主题："
L["Renown %d"] = "名望 %d"
L["Repeat %s times"] = "重复%s次"
L["Repeat until it ends"] = "重复直到结束"
L["Repeats:"] = "重复次数："
L["Replies to a /who, shift-clicking a name in the guild list too."] = "/who 的回复，也包括在公会列表中 Shift+点击名字。"
L["Requires %d points in %s"] = "需要投入%d点于%s"
