L["Resources"] = "资源"
L["Rested"] = "休息"
L["RestedXP's guide window, waypoint arrow, quest item and target buttons and level splits fade with the Quest tracker row on the Game Frames page."] = "RestedXP 的指南窗口、路径点箭头、任务物品和目标按钮以及等级分段会随游戏框体页面上的任务追踪行一起淡出。"
L["Resting (an inn or a city)"] = "休息状态（旅店或城市）"
L["Resting at a campfire, sitting, sleeping, dancing and the like (whichever events pick it on the Scenes page): the camera swings slowly round to face you, then sways gently from side to side in front of you, and eases in close. Moving (or standing up) ends it."] = "在篝火旁休息、坐下、睡觉、跳舞等（场景页面中选择它的任何事件）：镜头会缓慢转到面对你，然后在你前方轻轻左右摇摆，并缓缓拉近。移动（或站起来）会结束它。"
L["Restore"] = "恢复"
L["Restored from a backup of %s from %s."] = "已从%s于%s的备份中恢复。"
L["Restyle these bars"] = "重新设置这些条的风格"
L["Result"] = "结果"
L["Reveal on scenario progress"] = "场景战役有进展时显示"
L["Right click attack also uses Auto-shot"] = "右键攻击时也使用自动射击"
L["Right now: hidden"] = "当前：隐藏"
L["Right now: shown"] = "当前：显示"
L["Right-click for more."] = "右键点击查看更多。"
L["Right-click the Profiler icon to turn it on and record."] = "右键点击性能分析器图标可开启并记录。"
L["Right-click: back to its own icon."] = "右键点击：恢复为它自己的图标。"
L["Right-click: copy it, or rename, describe, change the icon of or delete one of yours."] = "右键点击：复制它，或者重命名、描述、更改图标或删除你自己的。"
L["Right-clicking an enemy targets it and attacks: Auto Shot when it's far enough away to shoot, a melee swing when it's too close, in a fight or out of one. In a fight the game only checks what's under the mouse a few times a second, so a very quick right-click on a new enemy can still be a melee one."] = "右键点击敌人会选中并攻击它：距离足够远可以射击时使用自动射击，太近时使用近战攻击，战斗中和战斗外都是如此。战斗中游戏每秒只会检查几次鼠标下的单位，所以对新敌人非常快速的右键点击仍可能是近战攻击。"
L["Ripple wave"] = "涟漪波"
L["Rise up from below the screen"] = "从屏幕下方升起"
L["Rising heat"] = "升腾的热气"
L["Rising motes"] = "上升的光点"
L["Role"] = "职责"
L["Role icon (damage)"] = "职责图标（伤害输出）"
L["Role icon (healer)"] = "职责图标（治疗者）"
L["Role icon (tank)"] = "职责图标（坦克）"
L["Roll Vision"] = "Roll Vision"
L["Rolling..."] = "掷骰中……"
L["Roomy"] = "宽松"
L["Rotate %s° %s over %s s"] = "旋转%s°（%s），用时%s秒"
L["Round"] = "圆形"
L["Round each bar: the game's frame alone, or a border of ours (Custom: its thickness and color under it)."] = "每个条的外框：仅游戏的框架，或我们的边框（自定义：其下方可设置粗细和颜色）。"
L["Round each frame: the game's, or a border of ours (Custom: its thickness and color under it)."] = "每个框体的外框：游戏的，或我们的边框（自定义：其下方可设置粗细和颜色）。"
L["Round the button: the game's (the extra ability button's frame), or one of ours (Custom: its thickness and color under it)."] = "按钮的外框：游戏的（额外技能按钮的框架），或我们的（自定义：其下方可设置粗细和颜色）。"
L["Row"] = "行"
L["Rows:"] = "行数："
L["Rule"] = "规则"
L["Rule: %s"] = "规则：%s"
L["Rule: %s (the rule decides, not the ticks)"] = "规则：%s（由规则决定，而不是勾选项）"
L["Rules for the card's sound, read top to bottom as it shows: the first that fits plays one of its sounds at random. A rule's condition uses the rules' words (Cities, Raids, In CineMode...); none: any time. A rule with no sounds: silent. Each sound's slider sets it next to the others, the cue volume sets them all (every card's sounds share it)."] = "卡片音效的规则，在卡片显示时从上到下读取：第一个符合的规则随机播放其中一个音效。规则的条件使用规则词（Cities、Raids、In CineMode……）；无：任何时候。没有音效的规则：静音。每个音效的滑块设置它相对于其他音效的音量，提示音音量设置全部音效（所有卡片的音效共用它）。"
L["Rules for the sounds, read top to bottom as a fight starts or ends: the first that fits plays one of its sounds at random. A rule's condition uses the rules' words (Boss fight, Raids, In CineMode...); none: any fight. Each sound's slider sets it next to the others, the cue volume sets them all. They play on the Ambience channel, its volume set for them and put back after."] = "音效的规则，在战斗开始或结束时从上到下读取：第一个符合的规则随机播放其中一个音效。规则的条件使用规则词（Boss fight、Raids、In CineMode……）；无：任何战斗。每个音效的滑块设置它相对于其他音效的音量，提示音音量设置全部音效。它们在环境音频道播放，会为它们设置该频道音量，之后再恢复。"
L["Rules for the sounds, read top to bottom as the time of day changes: the first for the new time that fits plays one of its sounds at random. A rule's condition uses the rules' words (Cities, In CineMode...); none: any time. A rule with no sounds: silent. Each sound's slider sets it next to the others, the cue volume sets them all (the fights' sounds share it)."] = "音效的规则，在时段变化时从上到下读取：第一个符合新时段的规则随机播放其中一个音效。规则的条件使用规则词（Cities、In CineMode……）；无：任何时候。没有音效的规则：静音。每个音效的滑块设置它相对于其他音效的音量，提示音音量设置全部音效（与战斗的音效共用）。"
L["Run"] = "运行"
L["Runs its command now, as picking it on the wheel would."] = "立即运行其命令，与在轮盘上选择它相同。"
L["Runs this camera for 30 seconds where you stand, to see your settings at work. Moving, or clicking Stop, ends it."] = "在你站的地方运行此镜头30秒，查看你的设置效果。移动或点击“停止”会结束它。"
L["Runs when the camera ends, whatever ends it (its stop rules say which do). Every camera has it: it can't be removed. Pick it and add steps to put them inside."] = "镜头结束时运行，无论是什么结束了它（其停止规则决定哪些会结束它）。每个镜头都有它：无法移除。选择它并添加步骤即可放入其中。"
L["SD (the game's look)"] = "标清（游戏的外观）"
L["SHOWING"] = "显示中"
L["SHOWN BECAUSE"] = "显示原因"
L["Same as raid frames"] = "与团队框体相同"
L["Same as target"] = "与目标相同"
L["Same as the words"] = "与文字相同"
L["Same back"] = "同样回应"
L["Same size at any distance"] = "在任何距离大小相同"
L["Save"] = "保存"
L["Says and yells whose bubble isn't on your screen (the speaker is behind you, or out of view) show in a bubble low on the screen, with the speaker's name, instead of bringing up chat. It needs the Chat page's Show chat when a message arrives and Hide speech you can see as a bubble."] = "气泡不在你屏幕上的说话和大喊（说话者在你身后或视野之外）会显示在屏幕下方的气泡中，带有说话者的名字，而不会调出聊天框。需要聊天页面的“收到消息时显示聊天”和“隐藏能在气泡中看到的话”。"
L["Says and yells whose bubble isn't on your screen, shown low on the screen instead. Turn it on on the Interface hub's Chat bubbles page (with that page on)."] = "气泡不在你屏幕上的说话和大喊，改为显示在屏幕下方。在界面中心的聊天气泡页面开启它（需要开启该页面）。"
L["Scale"] = "缩放"
