L["Scene:"] = "场景："
L["Scenes"] = "场景"
L["Screen edges"] = "屏幕边缘"
L["Script"] = "脚本"
L["Script: %s"] = "脚本：%s"
L["Scripts"] = "脚本"
L["Scroll the mouse wheel over it, or type a number and press Enter."] = "在其上滚动鼠标滚轮，或输入数字并按回车。"
L["Search"] = "搜索"
L["Seats"] = "座位"
L["Second pattern:"] = "第二图案："
L["Seconds left at its right end"] = "剩余秒数在右端"
L["Seconds left in the middle"] = "剩余秒数在中间"
L["Seconds the edges take to close all the way in when your health drops. Keep it short: it's the warning."] = "生命值下降时边缘完全收拢所需的秒数。尽量短一些：这是警告。"
L["See-through"] = "半透明"
L["See-through and borderless, the health bar thin along the top."] = "半透明且无边框，生命条在顶部细细一条。"
L["Sending your log"] = "发送你的日志"
L["Separate"] = "分开"
L["Separate: the card stays where you drag it (or at the list's height), wherever the bubble goes."] = "分开：卡片停留在你拖动到的位置（或列表的高度），无论气泡在哪里。"
L["Server messages"] = "服务器消息"
L["Server shutdowns and restarts."] = "服务器关闭和重启。"
L["Set by:"] = "设置者："
L["Sets every buff in this group to this. Buffs you haven't set on their own follow it."] = "将此分组中的每个增益效果设为此值。你没有单独设置的增益效果会跟随它。"
L["Sets every spell in this group to this. Spells you haven't set on their own follow it, and a spell here made When ready on its own starts with its Resources and Show early."] = "将此分组中的每个法术设为此值。你没有单独设置的法术会跟随它；此处单独设为“就绪时”的法术会以其“资源”和“提前显示”为起点。"
