L["Shortly before you land, the rotation stops and the camera turns back behind you and stays there until you touch down. Needs one flight on a route to learn how long it takes. Skipped if you've moved the camera yourself on that flight: it stays how you set it."] = "降落前不久，旋转停止，镜头转回你身后并保持在那里直到着陆。需要在一条路线上飞行一次来了解所需时间。如果你在那次飞行中自己移动过镜头则跳过：镜头保持你设置的样子。"
L["Shot:"] = "机位："
L["Shoulder Cam"] = "肩部镜头"
L["Shoulder Cam turned off: the game's experimental camera warning was disabled."] = "肩部镜头已关闭：游戏的实验性镜头警告被禁用了。"
L["Show all"] = "显示全部"
L["Show all through CineMode in capital cities."] = "在主城中，CineMode期间始终显示。"
L["Show all through CineMode out in the world, inns included (capital cities are Cities)."] = "在野外（包括旅店），CineMode期间始终显示（主城属于“城市”）。"
L["Show below health"] = "生命值低于此值时显示"
L["Show below this much mana"] = "法力低于此值时显示"
L["Show during:"] = "显示时段："
L["Show emotes too"] = "也显示表情"
L["Show fewer"] = "显示更少"
L["Show in"] = "显示于"
L["Show in capital cities."] = "在主城中显示。"
L["Show it"] = "显示它"
L["Show it now"] = "立即显示"
L["Show it the whole time, CineMode or not. Unticked, it's hidden, except as the other columns say."] = "一直显示它，无论是否处于CineMode。未勾选时隐藏，其他列另有设定的除外。"
L["Show keybinds"] = "显示按键绑定"
L["Show mana cost indicator"] = "显示法力消耗指示"
L["Show me"] = "让我看看"
L["Show members with a debuff you can dispel"] = "显示身上有你能驱散的减益效果的成员"
L["Show members with any debuff"] = "显示身上有任何减益效果的成员"
L["Show off-screen bubbles"] = "显示屏幕外气泡"
L["Show off-screen bubbles is on: a say or yell from someone you can't see shows here instead of bringing up the chat window"] = "“显示屏幕外气泡”已开启：你看不到的人的说话或大喊会显示在这里，而不会调出聊天窗口"
L["Show or hide this row's settings."] = "显示或隐藏此行的设置。"
L["Show out in the world, inns included (capital cities are Cities)."] = "在野外显示，包括旅店（主城属于“城市”）。"
L["Show out of fights while you have a living enemy targeted."] = "非战斗中选中活着的敌人时显示。"
L["Show out of fights while you have anything else targeted: friends, NPCs, dead enemies."] = "非战斗中选中其他任何目标时显示：友方、NPC、死亡的敌人。"
L["Show remaining mana text"] = "显示剩余法力文字"
L["Show rolls on"] = "掷骰显示于"
L["Show the counts under each item"] = "在每件物品下显示计数"
L["Show the game's window brings the game's own window back for the rest of the conversation"] = "“显示游戏窗口”会在对话剩余时间内恢复游戏自己的窗口"
L["Show timers in the quest tracker while one is running"] = "任务追踪中有计时器运行时显示计时器"
L["Show tooltips"] = "显示鼠标提示"
L["Show who said it"] = "显示是谁说的"
L["Show your mana when it isn't your power"] = "法力不是你的能量类型时也显示法力"
L["Show your personal resource display until health and power are full"] = "生命值和能量恢复满之前显示个人资源显示"
L["Show your pet frame until its health is full"] = "宠物生命值回满之前显示宠物框体"
L["Show your player frame until health and power are full"] = "生命值和能量恢复满之前显示玩家框体"
L["Show:"] = "显示："
L["Showing in its own window. Click here to put it back."] = "正在单独的窗口中显示。点击这里放回。"
L["Shown as:"] = "显示为："
L["Shown in fights: any of them, or only while you're PvP flagged."] = "战斗中显示：任何战斗，或仅在你处于PvP状态时。"
L["Shown in the wheel's middle, on the master wheel and in the game's key bindings."] = "显示在轮盘中间、主轮盘上以及游戏的按键设置中。"
L["Shows a box where speech from behind you appears: drag it where you want the lines."] = "显示一个方框，表示来自你身后的话语出现的位置：把它拖到你想要显示文字的地方。"
L["Shows a line of speech from behind you, from you, as it looks now."] = "显示一行来自你身后的话语（以你为说话者），按当前外观。"
L["Shows all through CineMode. (The other columns then have nothing to add.)"] = "在整个CineMode期间显示。（其他列就没有什么可补充的了。）"
L["Shows as:"] = "显示为："
L["Shows each of its cards in turn, to see how they look (close the settings to see them). Clicking Stop ends it."] = "依次显示其每张卡片，查看效果（关闭设置即可看到）。点击“停止”可结束。"
L["Shows in every fight, wherever you are. (The other columns then have nothing to add.)"] = "在每场战斗中显示，无论身在何处。（其他列就没有什么可补充的了。）"
L["Shows its card now, to see how it looks (close the settings to see it)."] = "立即显示其卡片，查看效果（关闭设置即可看到）。"
L["Shows the key each spell is bound to in the corner of its icon in the Essential and Utility bars, as on an action button: the key of the first action bar button holding it (or a macro casting it)."] = "在核心和辅助技能条中每个法术图标的角落显示其绑定的按键，就像动作按钮一样：放有该法术的第一个动作条按钮的按键（或施放它的宏）。"
L["Shows the lines in their chat colors. Copied text keeps the color codes, so untick this to copy plain text."] = "以聊天颜色显示各行。复制的文本会保留颜色代码，所以取消勾选此项可复制纯文本。"
L["Shows the preview larger, in a window of its own beside the settings (its Pop out lets you move it anywhere) that you can resize from its corner, so you can watch it while you scroll down the page. Click again to put it back."] = "在设置旁的单独窗口中放大显示预览（其“弹出”可让你把它移到任何位置），可从角落调整大小，这样你向下滚动页面时也能看着它。再次点击可放回。"
L["Shows wherever you are. (Never in a fight: a card from one waits for it to end.)"] = "无论身在何处都显示。（战斗中从不显示：战斗中的卡片会等到战斗结束。）"
L["Shows wherever you are. (The other columns then have nothing to add.)"] = "无论身在何处都显示。（其他列就没有什么可补充的了。）"
L["Sides"] = "两侧"
L["Size %d%%"] = "大小 %d%%"
L["Size:"] = "大小："
L["Sizes"] = "大小"
L["Skip it"] = "跳过"
L["Slide in"] = "滑入"
L["Slim"] = "纤细"
L["Slow frames"] = "慢帧"
L["Slow orbit"] = "缓慢环绕"
L["Slowly swings the camera around behind your character as you take off, ready for the sway behind you. Also once the pause after you move the camera mid-flight is up."] = "起飞时缓慢地把镜头转到你角色身后，为在你身后摇摆做好准备。飞行途中你移动镜头后的暂停结束时也会如此。"
L["Small lines' color:"] = "小字颜色："
L["Small lines' font:"] = "小字字体："
L["Small lines' size"] = "小字大小"
L["Smaller hits count as a big one too once they've taken this much of your health together (since the last one; again each fight)."] = "较小的伤害累计达到你生命值的这么多时，也算作一次重击（从上一次重击算起；每场战斗重新计算）。"
L["Smaller, no frame, a quiet edge glow and a dark cooldown fill, no key."] = "更小，没有框架，柔和的边缘光晕和深色冷却填充，不显示按键。"
L["Smallest ammo stack first after Clean Up Bags"] = "整理背包后最小的弹药堆叠排在最前"
L["Smart Find"] = "智能查找"
L["Smart Find every 20 seconds while an addon is new to it (its first 15 minutes of play, for each addon you install that isn't supported), not in fights, so frames that come and go (another addon's popups) are caught while they're up. After that, look with the button below."] = "当某个插件对它来说是新的时（你安装的每个不受支持的插件的前15分钟游戏时间），每20秒进行一次智能查找，战斗中除外，这样时有时无的框体（其他插件的弹窗）在出现时就能被捕捉到。之后请用下方的按钮查找。"
L["Smart Find for %d seconds"] = "智能查找%d秒"
L["Smart set"] = "智能设置"
L["Smooth"] = "平滑"
L["Socials"] = "社交"
L["Soft"] = "柔和"
L["Soft (feathered)"] = "柔和（羽化）"
L["Soft bars and Friz Quadrata, thinly outlined."] = "柔和的条和 Friz Quadrata 字体，细描边。"
L["Soft bars with a fine edge, class icons for players."] = "带细边的柔和条，玩家显示职业图标。"
L["Soft bars with a fine edge, names outlined."] = "带细边的柔和条，名字带描边。"
L["Soft wisps of heat rising from the bottom of the screen, flickering, higher the weaker you are. Fire themes have it."] = "从屏幕底部升起的柔和热气，闪烁不定，你越虚弱升得越高。火焰主题带有此效果。"
L["Soft, thin bars with a fine edge, health in your class color."] = "带细边的柔和纤细条，生命值为你的职业颜色。"
L["Some nameplate and name changes only take effect once the fight ends."] = "某些姓名板和名字的更改要等战斗结束后才会生效。"
L["Something has been taking the turnips at night, and nobody here is brave enough to keep watch. Would you?"] = "晚上总有什么东西来偷萝卜，这里没有人敢守夜。你愿意吗？"
L["Sort by"] = "排序方式"
L["Sort:"] = "排序："
L["Souls banner"] = "魂系横幅"
L["Sound rule %d"] = "音效规则%d"
L["Sounds"] = "音效"
L["Sounds for boss fights, read before the fights' (Entering and Leaving combat's): as a boss is pulled, killed or your group wipes, the first rule that fits plays one of its sounds at random. A rule here has Boss fight in its condition (taken out, it moves to the fights'). Each sound's slider sets it next to the others, the cue volume sets them all."] = "首领战的音效，在战斗音效（进入战斗和脱离战斗）之前读取：首领被拉住、被击杀或你的队伍团灭时，第一个符合的规则随机播放其中一个音效。此处的规则在条件中包含 Boss fight（去掉后会移到战斗音效中）。每个音效的滑块设置它相对于其他音效的音量，提示音音量设置全部音效。"
L["Spark"] = "火花"
L["Sparks"] = "火花"
L["Speech from behind you"] = "来自你身后的话语"
L["Speech from behind you shows here."] = "来自你身后的话语显示在这里。"
L["Speech from behind you shows here.\nDrag it where you want it, left-click to set, right-click to reset."] = "来自你身后的话语显示在这里。\n把它拖到你想要的位置，左键点击确定，右键点击重置。"
L["Speech from behind you starts with the speaker's name (\"Name says: ...\"). Unticked, just their words show."] = "来自你身后的话语以说话者的名字开头（“某某说：……”）。未勾选时只显示其话语。"
