L["Spin, speeding up to %s°/s, for %s s"] = "旋转，加速到%s°/秒，持续%s秒"
L["Spin, speeding up to %s°/s, until it ends"] = "旋转，加速到%s°/秒，直到结束"
L["Spiral arms"] = "螺旋臂"
L["Spiraling motes"] = "螺旋光点"
L["Square"] = "方形"
L["Start now"] = "立即开始"
L["Start right away, with the settings open, instead of when you close them: to measure the settings pages themselves. Click through the ones to check while it runs."] = "立即开始并保持设置打开，而不是在你关闭设置时开始：用于测量设置页面本身。运行期间点击浏览要检查的页面。"
L["Start the RP walk camera"] = "启动RP漫步镜头"
L["Start the auto-run camera"] = "启动自动奔跑镜头"
L["Started as: %s"] = "初始为：%s"
L["Starts"] = "开始"
L["Starts from:"] = "起始于："
L["Starts on any of these: %s."] = "以下任一情况都会启动：%s。"
L["Starts the RP walk camera now, walking or not. Press again to stop it; its stop rules (its Scripts page) say what else does."] = "立即启动RP漫步镜头，无论是否在行走。再按一次可停止；其停止规则（其脚本页面）决定还有什么会停止它。"
L["Starts the auto-run camera now, running or not. Press again to stop it; its stop rules (its Scripts page) say what else does."] = "立即启动自动奔跑镜头，无论是否在奔跑。再按一次可停止；其停止规则（其脚本页面）决定还有什么会停止它。"
L["Starts when you close the settings: %d seconds, detailed."] = "在你关闭设置时开始：%d秒，详细。"
L["Starts when you close the settings: %d seconds."] = "在你关闭设置时开始：%d秒。"
L["Starts when: %s"] = "启动条件：%s"
L["Starts when: no trigger yet. Set a row on the Scenes page to it."] = "启动条件：尚无触发条件。在场景页面中将某行设为它。"
L["Starts:"] = "启动："
L["State"] = "状态"
L["Stays"] = "保持"
L["Stays after a fight:"] = "战斗后保持："
L["Stays for:"] = "保持时长："
L["Stays the row's rule (it can't go in the dropdowns: %s)."] = "保留为该行的规则（无法放入下拉菜单：%s）。"
L["Stealthed"] = "潜行中"
L["Stop (%d)"] = "停止（%d）"
L["Stop and /stare out at the view (or any event set to it on the Scenes page): the camera glides around behind you and sways very gently there, looking out the way you're facing. Like the RP walk camera, only slower and softer. Moving, jumping or another emote ends it."] = "停下来 /stare 眺望风景（或在场景页面中设为它的任何事件）：镜头会平滑转到你身后，在那里非常轻柔地摇摆，朝你面对的方向眺望。与RP漫步镜头类似，只是更慢更柔和。移动、跳跃或做其他表情会结束它。"
L["Stop button"] = "停止按钮"
L["Stop camera"] = "停止镜头"
L["Stop music leaving a camera mode"] = "离开镜头模式时停止音乐"
L["Stop rules"] = "停止规则"
L["Stop the camera"] = "停止镜头"
L["Stopped. Run plays it again."] = "已停止。“运行”可再次播放。"
L["Stops following: its own ticks or rule, as they were, decide again."] = "停止跟随：由其自己的勾选项或规则（保持原样）重新决定。"
L["Stops within"] = "停止距离"
L["Stormwind"] = "暴风城"
L["Strength out of combat"] = "非战斗中的强度"
L["Stuck, or something looks wrong? Read up in the guide, or report it to us. Click a link and press Ctrl+C to copy it, then paste it into your browser (addons can't open one)."] = "卡住了，或者有什么看起来不对？请阅读指南，或向我们报告。点击链接并按 Ctrl+C 复制，然后粘贴到你的浏览器中（插件无法打开浏览器）。"
L["Style"] = "风格"
L["Style:"] = "风格："
L["Subtitle"] = "字幕"
L["Subtitles"] = "字幕"
L["Subtle"] = "Subtle"
L["Sure?"] = "确定吗？"
L["Sway either side"] = "两侧摇摆"
L["Sway within %s° of behind you over %s s"] = "在你身后%s°范围内摇摆，用时%s秒"
L["Sway within %s° of your front over %s s"] = "在你前方%s°范围内摇摆，用时%s秒"
L["Swift Gray Gryphon"] = "迅捷灰色狮鹫"
L["Swimming"] = "游泳中"
L["Swing speed"] = "转动速度"
L["Swing to who's talking, %s° off the middle, over %s s"] = "转向正在说话的人，偏离中心%s°，用时%s秒"
L["Swirl"] = "漩涡"
L["Swirling clouds"] = "旋转的云"
L["Switch to it"] = "切换到它"
L["TO FADE IT"] = "要淡出它"
L["Tabs"] = "标签页"
L["Tail on top"] = "尾巴在上"
L["Tail position"] = "尾巴位置"
L["Tailoring"] = "裁缝"
L["Take it off this card."] = "从此卡片上移除。"
L["Take it off this rule."] = "从此规则中移除。"
L["Takes off the piece before the cursor."] = "删除光标前的部分。"
L["Takes the bars out and brings them back in, as at a fight's start and end."] = "收起黑边再让它们出现，就像战斗开始和结束时一样。"
L["Takes this icon off the wheel."] = "从轮盘上移除此图标。"
L["Talent calculator"] = "天赋模拟器"
L["Talent calculator button on the talents window"] = "天赋窗口上的天赋模拟器按钮"
L["Talents button when inspecting someone"] = "观察他人时的天赋按钮"
L["Talk about a quest"] = "谈论任务"
L["Talking to a quest giver, the camera zooms in and swings around behind you, looking past you at them. It goes back once you close the window or move off (your zoom stays if you zoomed yourself meanwhile). Works whether or not CineMode is on. The \"Talk to a quest giver\" and \"Talk about a quest\" events on the Scenes page can also turn it off or make it wait a moment."] = "与任务NPC对话时，镜头会拉近并转到你身后，越过你看向对方。关闭窗口或走开后，镜头会恢复（如果你在此期间自己缩放过，缩放保持不变）。无论CineMode是否开启都有效。场景页面中的“与任务NPC对话”和“谈论任务”事件也可以关闭它或让它稍等片刻。"
L["Talking to an NPC with a \"(Quest)\" line to pick but no quest to pick up or hand in: a quest step done by talking to them. Works whether or not CineMode is on."] = "与一个有“（任务）”对话选项、但没有任务可接或可交的NPC对话：通过与其对话完成的任务步骤。无论CineMode是否开启都有效。"
L["Tank"] = "坦克"
L["Tanks"] = "坦克"
L["Tar enemy is ticked, and you target an enemy"] = "已勾选“敌方目标”，且你选中了敌人"
L["Tar enemy is ticked: it shows when you target an enemy"] = "已勾选“敌方目标”：选中敌人时显示"
L["Tar friendly is ticked, and you target a friend"] = "已勾选“友方目标”，且你选中了友方"
L["Tar friendly is ticked: it shows when you target a friend"] = "已勾选“友方目标”：选中友方时显示"
L["Target Indicator"] = "目标指示器"
L["Target circle"] = "目标圈"
L["Target min opacity"] = "目标最低不透明度"
L["Target the last speaker"] = "选中最后说话的人"
L["Targets the last NPC who spoke near you (your character turns their head to them). Addons can't target on their own: the game only lets a key press do it. Out of fights."] = "选中最后一个在你附近说话的NPC（你的角色会把头转向他们）。插件无法自行选择目标：游戏只允许通过按键来做到。仅限非战斗中。"
L["Tele Vision"] = "Tele Vision"
L["Tele Vision colors: %d specs, %d seconds each (/cine teleport colors again to stop)."] = "Tele Vision 颜色：%d个专精，每个%d秒（再次输入 /cine teleport colors 可停止）。"
L["Tele Vision colors: all %d shown."] = "Tele Vision 颜色：全部%d个已显示。"
L["Tele Vision colors: stopped."] = "Tele Vision 颜色：已停止。"
L["Terrain detail distance"] = "地形细节距离"
L["Territory"] = "领地"
L["Test"] = "测试"
L["Test item"] = "测试物品"
L["Test recap"] = "测试回顾"
L["Text"] = "文字"
L["Text only"] = "仅文字"
L["Text size"] = "文字大小"
L["Text to send a friend: they add this scene (and the shot it plays) with Import on their Scenes page. Where it may start (its When) stays with you."] = "发送给朋友的文本：他们可以在场景页面用“导入”添加此场景（以及它播放的机位）。它可以在哪里启动（其“符合条件”）会保留在你这里。"
L["Text to send a friend: they add this shot with Import here or on their Scenes page."] = "发送给朋友的文本：他们可以在这里或场景页面用“导入”添加此机位。"
L["Texture:"] = "材质："
L["Thanks"] = "致谢"
L["That isn't a Vitals theme."] = "这不是 Vitals 主题。"
L["That isn't all of it: copy it again, every letter."] = "内容不完整：请重新复制，一个字符都不能少。"
L["The AFK camera sweeps right round your character, which can bump into walls in tight rooms. Its zoom still runs (within the limit above)."] = "暂离镜头会围绕你的角色转一整圈，在狭窄的房间里可能会撞到墙。其缩放仍会运行（在上方的限制内）。"
L["The Card Vision page's Last time line: what you did last session, as you log in"] = "Card Vision 页面的“上次”一行：登录时显示你上次游戏做了什么"
L["The Card Vision page's time of day at login, under the zone's name"] = "Card Vision 页面的登录时段，在区域名称下方"
L["The Corpse line on a dead player, NPC or mob."] = "死亡的玩家、NPC或怪物身上的“尸体”一行。"
L["The Deadmines"] = "死亡矿井"
L["The Default row is what frames you add, and addons you install later, start with; its Copy to all gives it to every row here."] = "“默认”行是你添加的框体以及你之后安装的插件的初始设置；其“复制到全部”会把它应用到这里的每一行。"
L["The Defias Brotherhood"] = "迪菲亚兄弟会"
L["The Tooltips page is off, so Cinematic leaves tooltips alone"] = "鼠标提示页面已关闭，因此Cinematic不处理鼠标提示"
L["The Tooltips row was off then for: %s"] = "当时鼠标提示行因以下原因关闭：%s"
L["The Tooltips row was on then for: %s"] = "当时鼠标提示行因以下原因开启：%s"
L["The UI fades and the look stays, with just a few cameras: flights, AFK, and your Hearthstone and teleports. No cozy, vista, fish, RP walk, auto-run, death or quest cameras."] = "界面淡出，画面效果保留，只有少数几个镜头：飞行、暂离以及你的炉石和传送法术。没有温馨、远景、钓鱼、RP漫步、自动奔跑、死亡或任务镜头。"
L["The Unloaded tab has the addons installed but not loaded, to set them up before you turn them on, and the ones supported but not installed."] = "“未加载”标签页列出已安装但未加载的插件（可在开启前进行设置），以及受支持但未安装的插件。"
L["The addons loaded now: their frames, and the ones you added."] = "当前已加载的插件：它们的框体，以及你添加的框体。"
L["The arrow by your buffs that folds them away. Hidden in CineMode even while your buffs show; hovering your buffs brings it up."] = "增益效果旁用于折叠它们的箭头。即使你的增益效果显示，它在CineMode中也会隐藏；鼠标悬停在增益效果上会让它出现。"
L["The arrow, chevron and diamond bob up and down, the brackets, carets and corners close in and out, the glow and underline pulse. Unticked, it holds still."] = "箭头、V形和菱形上下浮动，括号、尖角和角落收拢又展开，光晕和下划线脉动。未勾选时保持静止。"
L["The art's color."] = "美术的颜色。"
L["The background's color, for Custom."] = "背景的颜色，用于自定义。"
L["The bar behind the zone's name above the minimap (the name has a row of its own). Untick it to leave the name floating on its own. Hovering the minimap brings it up with the map: to keep it hidden then too, take Minimap header out of the Minimap group on the Hover groups page."] = "小地图上方区域名称后面的条（名称有自己的一行）。取消勾选可让名称单独浮在那里。鼠标悬停在小地图上会让它随地图一起出现：如果那时也要保持隐藏，请在鼠标悬停分组页面中将小地图标题移出小地图分组。"
L["The bar in your class's color, whether you lead or chase."] = "使用你职业颜色的条，无论你领先还是追赶。"
L["The bar's color once you lead. Picking one turns Colors to Your own."] = "你领先后条的颜色。选择一种会把“颜色”改为“你自己的”。"
L["The bar's color while you're behind. Picking one turns Colors to Your own."] = "你落后时条的颜色。选择一种会把“颜色”改为“你自己的”。"
L["The bar's fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "条的填充。在游戏自带的几种之下：其他插件共享的任何材质（通过 LibSharedMedia）。"
L["The bars and boxes the game puts at the top of the screen for a zone event or scenario, such as a timer to the next event. Until you change its ticks it does what the quest tracker's row does."] = "游戏为区域事件或场景战役在屏幕顶部放置的条和框，例如距离下一个事件的计时器。在你更改其勾选项之前，它与任务追踪行的行为相同。"
L["The bars as tall as it takes for what's left between them to have a film's shape, whatever your screen."] = "黑边的高度会让两者之间剩下的画面呈现电影的画幅比例，无论你的屏幕是什么比例。"
L["The bars fade in at their full height."] = "黑边以完整高度淡入。"
L["The bars fade into the scene past their edge."] = "黑边越过其边缘后融入画面。"
L["The bars grow in from the screen's edges."] = "黑边从屏幕边缘长出。"
L["The bars of every Vision that follows this page (Damage Vision's, Roll Vision's time left). Below the game's own few: any other addon shares (through LibSharedMedia)."] = "所有跟随本页面的 Vision 的条（Damage Vision 的条、Roll Vision 的剩余时间）。在游戏自带的几种之下：其他插件共享的任何材质（通过 LibSharedMedia）。"
L["The bars' border: the game's, or one of ours (Custom: its thickness and color under it)."] = "条的边框：游戏的，或我们的（自定义：其下方可设置粗细和颜色）。"
L["The bars' fill."] = "条的填充。"
L["The bars' fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "条的填充。在游戏自带的几种之下：其他插件共享的任何材质（通过 LibSharedMedia）。"
L["The battle begins"] = "战斗开始"
L["The big words across the screen. <NAME>: the name of the one that fell."] = "横跨屏幕的大字。<NAME>：倒下者的名字。"
L["The big words as you lose a duel."] = "你输掉决斗时的大字。"
L["The big words as you win a duel."] = "你赢得决斗时的大字。"
L["The border round every page's bars, panels and buttons that follow General. The game's: as each page's default has it. Custom: its thickness and color under it."] = "所有跟随“常规”的页面的条、面板和按钮周围的边框。游戏自带：按各页面的默认设置。自定义：其下方可设置粗细和颜色。"
L["The border around the Vision parts that follow this page (the quest item button's frame). Custom: its thickness and color under it."] = "跟随本页面的 Vision 部件周围的边框（任务物品按钮的框架）。自定义：其下方可设置粗细和颜色。"
L["The border the game puts round your target's health bar, in its mark's color."] = "游戏在你目标生命条周围加的边框，使用其标记的颜色。"
L["The border's color."] = "边框的颜色。"
L["The border's color. Picking one turns it to Custom."] = "边框的颜色。选择一种会将其改为自定义。"
L["The boss's name as its fight starts, in place of Entering combat's card. Once a run for each boss."] = "首领战开始时显示首领的名字，代替进入战斗的卡片。每次副本中每个首领只显示一次。"
L["The boss's name as you first come within about 28 yards of it, before the fight. A dungeon or raid boss is told by its level: a skull, or on retail two over yours."] = "战斗前你第一次进入首领约28码范围内时显示其名字。地下城或团队副本首领通过其等级判断：骷髅，或在正式服上比你高两级。"
L["The boss's name as you first target it, before the fight. A dungeon or raid boss is told by its level: a skull, or on retail two over yours."] = "战斗前你第一次选中首领时显示其名字。地下城或团队副本首领通过其等级判断：骷髅，或在正式服上比你高两级。"
L["The boxes the game puts under the minimap for a scenario's or quest's current step, such as a capture bar. Always shown to start with."] = "游戏为场景战役或任务的当前步骤在小地图下方放置的框，例如占领进度条。初始为始终显示。"
L["The bubble's color, for Custom."] = "气泡的颜色，用于自定义。"
L["The bubble's tail sits on top, pointing up, instead of under it pointing down. (In a bubble only: not with no bubble behind the words.)"] = "气泡的尾巴位于顶部向上指，而不是在底部向下指。（仅限气泡：文字后面没有气泡时不适用。）"
L["The bubble's words in a color of your own (the quest card keeps its ink)."] = "气泡文字使用你自己的颜色（任务卡片保持其墨色）。"
L["The buff fades"] = "增益效果消失"
L["The button's width and height."] = "按钮的宽度和高度。"
L["The buttons beside the chat window (chat menu, channels, voice...) come up with a new message."] = "聊天窗口旁的按钮（聊天菜单、频道、语音……）会在有新消息时出现。"
L["The calendar button on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地图标题上的日历按钮。取消勾选可在CineMode中隐藏它，即使小地图显示时也是如此。鼠标悬停在小地图上会让它随地图一起出现。"
L["The camera distance to start at. The game's furthest out may be less than this."] = "起始的镜头距离。游戏的最远距离可能小于此值。"
L["The camera eases out a little, then drifts in and out around your own distance. When you stop it glides back."] = "镜头会稍微拉远，然后在你自己的距离附近前后漂移。你停下时它会平滑恢复。"
L["The camera eases out a little, then drifts in and out around your own distance. When you stop walking it glides back."] = "镜头会稍微拉远，然后在你自己的距离附近前后漂移。你停止行走时它会平滑恢复。"
L["The camera eases out a little, then drifts slowly in and out around your own distance. Your own distance comes back afterwards."] = "镜头会稍微拉远，然后在你自己的距离附近缓慢前后漂移。之后会恢复你自己的距离。"
L["The camera is %d yards from you: a unit next to you is about %d yards from it, one at 20 yards about %d, one at 35 about %d."] = "镜头离你%d码：你旁边的单位离镜头约%d码，20码外的单位约%d码，35码外的约%d码。"
L["The camera it moves like: cozy swings round to face you, vista and fish settle behind you (fish sways less), AFK turns right around you. Its other settings (Camera Settings page) go on as they are."] = "它的移动方式类似哪个镜头：温馨会转到面对你，远景和钓鱼会停在你身后（钓鱼摇摆更少），暂离会围着你转一圈。其他设置（镜头设置页面）保持不变。"
L["The camera lines up behind you, then turns this far round: 180 looks straight back at you."] = "镜头排到你身后，然后转过这么多角度：180 表示正面回望你。"
L["The camera never tilts more than this far below where it was when auto-run started, even when it lowers while you steer."] = "镜头的倾斜永远不会比自动奔跑开始时的位置低这么多以上，即使你转向时它降低也是如此。"
L["The camera slowly pulls back, then (with random zoom) drifts in and out. Moving glides it back to your distance; zooming yourself keeps your new distance."] = "镜头缓慢拉远，然后（开启随机缩放时）前后漂移。移动会让它平滑恢复到你的距离；你自己缩放会保持你的新距离。"
L["The camera snaps straight to whoever's talking instead of swinging, the letterbox comes in twice as tall for the conversation with subtitles in its bottom bar, and the whole UI fades out: the minimap, frames, nameplates, names and the circle under your target."] = "镜头直接切到正在说话的人而不是转过去，对话期间宽银幕黑边变为两倍高，底部黑边中显示字幕，整个界面淡出：小地图、框体、姓名板、名字以及目标脚下的圆圈。"
L["The camera sways this much lower than where it lines up behind you, so it looks out across the view rather than down at it. 0 keeps your angle."] = "镜头摇摆的位置比它排到你身后时低这么多，这样它会平视风景而不是俯视。0 表示保持你的角度。"
L["The camera sways this much lower than where it lines up behind you, so it looks out across the water rather than down at it. 0 keeps your angle."] = "镜头摇摆的位置比它排到你身后时低这么多，这样它会平视水面而不是俯视。0 表示保持你的角度。"
L["The camera sweeps around your character, pausing between sweeps. Moving or dragging the camera stops it."] = "镜头围绕你的角色环绕，每次环绕之间暂停。移动或拖动镜头会停止它。"
L["The camera swings a little from side to side behind your character, pausing between moves. Narrower than the vista camera's sway."] = "镜头在你角色身后轻微地左右摆动，每次移动之间暂停。比远景镜头的摇摆幅度更窄。"
L["The camera swings from side to side behind your character, pausing between moves. Dragging the camera pauses it."] = "镜头在你角色身后左右摆动，每次移动之间暂停。拖动镜头会让它暂停。"
L["The camera swings gently from side to side behind your character, pausing between moves."] = "镜头在你角色身后轻轻左右摆动，每次移动之间暂停。"
L["The camera swings very gently from side to side behind your character, pausing between moves."] = "镜头在你角色身后非常轻柔地左右摆动，每次移动之间暂停。"
L["The camera this row starts. No camera: none (and its trigger's rows below aren't tried)."] = "此行启动的镜头。无镜头：不启动（其触发条件下方的行也不再尝试）。"
L["The camera turns back over the 6 seconds before this, so it's settled behind you this long before you land."] = "镜头在此时间之前的6秒内转回，所以在你降落前这么久就已稳定在你身后。"
L["The camera waits this long on a quest window before starting. Accept a quest and go sooner, and it doesn't move at all; stay to read, and it starts. Clicking through several quests, each new window adds a second to the wait. 0 starts at once."] = "镜头在任务窗口上等待这么久才开始。如果你接受任务后更早离开，它完全不会移动；如果你停下来阅读，它就会开始。连续点击多个任务时，每个新窗口会让等待增加一秒。0 表示立即开始。"
L["The camera waits this long on the window before starting. Close it sooner, and it doesn't move at all. 0 starts at once."] = "镜头在窗口上等待这么久才开始。如果你更早关闭窗口，它完全不会移动。0 表示立即开始。"
L["The camera's steps, in order, and what it does when it ends."] = "镜头的步骤（按顺序），以及它结束时做什么。"
L["The card fades in and out."] = "卡片淡入淡出。"
L["The cast bar's border: the game's, or one of ours (Custom: its thickness and color under it)."] = "施法条的边框：游戏的，或我们的（自定义：其下方可设置粗细和颜色）。"
L["The cast ends"] = "施法结束"
L["The chat window's dark background comes up with a new message. Untick for just the lines of text."] = "有新消息时出现聊天窗口的深色背景。取消勾选则只显示文字行。"
L["The chat window's tabs (General, Combat Log...) come up with a new message."] = "有新消息时出现聊天窗口的标签（综合、战斗记录……）。"
L["The chat windows, with their tabs and buttons. Tick where they stay up while the rest fades; which messages bring them up for a moment is on the Chat page."] = "聊天窗口及其标签和按钮。勾选它们在其余部分淡出时保持显示的情况；哪些消息会让它们短暂出现在聊天页面设置。"
L["The classic smooth fill in your colors, no border."] = "经典的平滑填充，使用你的颜色，无边框。"
L["The clock on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地图标题上的时钟。取消勾选可在CineMode中隐藏它，即使小地图显示时也是如此。鼠标悬停在小地图上会让它随地图一起出现。"
L["The close-up distance the cozy camera zooms in to, if you're further out. The zoom settings above then work around it. Your own distance comes back afterwards."] = "如果你离得更远，温馨镜头会拉近到的特写距离。上方的缩放设置会围绕它工作。之后会恢复你自己的距离。"
L["The color grading over the game world: a preset, the time of day and each zone's mood. Where and when it shows: the Tint tab. The UI isn't tinted."] = "游戏世界上的色彩分级：预设、时段以及每个区域的氛围。在何处、何时显示：色调标签页。界面不会被着色。"
L["The dark edges' color, at full Shadow tint."] = "暗色边缘的颜色，在阴影色调最大时。"
L["The day and night dial by the minimap. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地图旁的昼夜表盘。取消勾选可在CineMode中隐藏它，即使小地图显示时也是如此。鼠标悬停在小地图上会让它随地图一起出现。"
L["The death camera fades everything while you're dead"] = "你死亡期间死亡镜头会淡出一切"
L["The dungeon or raid and its difficulty under the boss's name (beside it in a letterbox bar)."] = "首领名字下方显示地下城或团队副本及其难度（在宽银幕黑边中则显示在旁边）。"
L["The edge in a unit's class or reaction color, or an item's quality."] = "边缘使用单位的职业或关系颜色，或物品的品质颜色。"
L["The edges flash in the theme's color when a hit takes a lot at once. (What counts as big: the Vision tab.)"] = "一次受到大量伤害时，边缘以主题颜色闪烁。（什么算大伤害：Vision 标签页。）"
L["The edges of the screen flash for a moment as the card shows, this strongly. 0: no pulse."] = "卡片显示时屏幕边缘短暂闪烁，强度为此值。0：无脉动。"
L["The edges throb with a heartbeat, quicker as you weaken."] = "边缘随心跳跳动，你越虚弱跳得越快。"
L["The extra bar some bosses, quests and vehicles bring up, such as a boss's own power."] = "某些首领、任务和载具会调出的额外条，例如首领自己的能量。"
L["The fastest the camera swings toward a new speaker. Each swing speeds up and slows down gently, as the flight camera's fly-bys do, so a short one never gets this fast and takes a few seconds."] = "镜头转向新说话者的最快速度。每次转动都会平缓地加速和减速，就像飞行镜头的掠过一样，所以短距离转动永远达不到这个速度，需要几秒钟。"
L["The fastest the edges lift when you're healed, as a share of all the way each second (40%: a full heal takes at least 2.5 seconds). They speed up to it and slow as they settle."] = "你被治疗时边缘褪去的最快速度，以每秒占全程的比例表示（40%：一次满额治疗至少需要2.5秒）。它们会加速到此速度，并在稳定时减速。"
L["The first swing waits for the zoom in to finish."] = "第一次转动会等拉近完成。"
L["The first time you log in after Cinematic updates, a line in chat says so, with a What's new link to what's been added. Chat shows for it while the UI is faded."] = "Cinematic更新后你第一次登录时，聊天中会有一行提示，附带“新内容”链接，指向新增的内容。界面淡出时，聊天会为它显示。"
L["The full report: how you did on the run, boss by boss and the rest, with the whole party (/cine report). Made-up bosses while the meter has none."] = "完整报告：你在这次副本中的表现，逐个首领以及其余部分，包含整个队伍（/cine report）。统计中没有数据时使用模拟的首领。"
L["The game only shows a bubble over someone on your screen, and puts one from someone above you at the very top of the screen, under the letterbox bar. So Cinematic draws bubbles of its own, looking like the game's, for speech whose bubble you can't see. How they look, and where speech from behind you shows: the Style hub's Chat bubbles page."] = "游戏只在你屏幕上的人头顶显示气泡，并把来自你上方的人的气泡放在屏幕最顶端、宽银幕黑边下面。因此，对于你看不到气泡的话语，Cinematic会绘制自己的气泡，看起来像游戏的气泡。它们的外观以及来自你身后的话语的显示位置：风格中心的聊天气泡页面。"
L["The game shows only your main power under your character: Maelstrom, Insanity, Astral Power, rage or energy in a form. Ticked, your mana gets a bar of its own under it. When it comes up is the Personal mana bar row on the Game Frames page."] = "游戏只在你角色下方显示你的主要能量：漩涡、狂乱值、星界能量，或某种形态下的怒气或能量。勾选后，你的法力会在其下方有一个单独的条。它何时出现由游戏框体页面上的个人法力条行决定。"
L["The game's"] = "游戏的"
L["The game's Show Offscreen Nameplates in CineMode. Ticked: on, plates for units out of view stay, pinned to the edge of the screen, so rows and rules that look for plates still find them, like an elite behind you for the elite rules. Unticked: off in CineMode. Your own setting comes back when CineMode ends."] = "CineMode中游戏的“显示屏幕外姓名板”。勾选：开启，视野外单位的姓名板会保留并固定在屏幕边缘，这样寻找姓名板的行和规则仍能找到它们，例如精英规则中你身后的精英。未勾选：在CineMode中关闭。CineMode结束时恢复你自己的设置。"
L["The game's background tinted a color of your own (the swatch)."] = "游戏的背景，染上你自己的颜色（色块）。"
L["The game's bars, as it draws them (the defaults)."] = "游戏的条，按游戏的绘制方式（默认值）。"
L["The game's bubbles, with bigger words."] = "游戏的气泡，文字更大。"
L["The game's dice and coin before each name."] = "每个名字前显示游戏的骰子和硬币图标。"
L["The game's effect shown. Theme's pick: the one picked to go with your theme (it changes with it)."] = "显示的游戏效果。主题的选择：为配合你的主题而选的效果（随主题变化）。"
L["The game's effects slide slowly under their edge, as they do in the game (not an edge like the red one)."] = "游戏的效果在其边缘下方缓慢滑动，与游戏中一样（不像红色那样有边缘）。"
L["The game's figure"] = "游戏的数据"
L["The game's figure, the last five minutes"] = "游戏的数据，最近五分钟"
L["The game's frame"] = "游戏的框架"
L["The game's frames, as it draws them (the defaults)."] = "游戏的框体，按游戏的绘制方式（默认值）。"
L["The game's mark and name for who the spell is cast at."] = "游戏为法术施放对象显示的标记和名字。"
L["The game's mark on casts it counts as important, ones worth interrupting or getting out of."] = "游戏为它认为重要的施法加的标记，值得打断或躲开的施法。"
L["The game's menu doesn't change it. Its default is %s."] = "游戏菜单不会更改它。其默认值为%s。"
L["The game's menu doesn't change it: it's %s."] = "游戏菜单不会更改它：它是%s。"
L["The game's menu goes from %s to %s."] = "游戏菜单的范围是%s到%s。"
L["The game's own bubble."] = "游戏自己的气泡。"
L["The game's own bubbles (the defaults)."] = "游戏自己的气泡（默认值）。"
L["The game's own cast bars (the defaults)."] = "游戏自己的施法条（默认值）。"
L["The game's own chat bubble."] = "游戏自己的聊天气泡。"
L["The game's own graphics settings one by one, past its Graphics menu either way: higher for a better look, lower for a faster game. They're this computer's: the same in every profile."] = "游戏自身的图形设置，逐项列出，范围超出其图形菜单的上下限：更高画面更好，更低游戏更流畅。它们属于这台电脑：在每个配置文件中都相同。"
L["The game's own screen effects (fire, frost, lightning, ripples...) cut to an edge, closing in with ours, over it. Each theme has one picked to go with it. Classic has only a few of them."] = "游戏自身的屏幕效果（火焰、冰霜、闪电、涟漪……）裁切到边缘，随我们的边缘一起收拢，叠加在其上。每个主题都选了一个与之搭配的效果。经典版只有其中少数几种。"
L["The game's own screen effects, cut to an edge, over ours."] = "游戏自身的屏幕效果，裁切到边缘，叠加在我们的效果之上。"
L["The game's own setting (Options, Nameplates, Style): the size and color of its plates' bars, all in the same texture. Shown here for what it is; Cinematic doesn't change it."] = "游戏自身的设置（选项，姓名板，风格）：其姓名板条的大小和颜色，全部使用同一种材质。这里只是显示它的状态；Cinematic不会更改它。"
L["The game's party and raid frames show only who needs healing: everyone (pets too) while below full health, and tanks as set below. The group titles hide. The members stay in their places, so there are gaps. Out of combat, the mouse over the frames brings everyone back. Ticked in the grid, it's on there. Always: everywhere. Party and Raid: while you're in one, wherever you are. Members with debuffs can't be shown: the game doesn't let addons see your group's debuffs in fights."] = "游戏的小队和团队框体只显示需要治疗的人：生命值未满的所有人（包括宠物），以及按下方设置的坦克。小队标题隐藏。成员保持在各自的位置，所以会有空隙。非战斗中，鼠标悬停在框体上会让所有人重新出现。在表格中勾选的地方生效。始终：所有地方。小队和团队：当你在其中时，无论身在何处。无法显示有减益效果的成员：游戏不允许插件在战斗中查看你队伍的减益效果。"
L["The game's profiler isn't on this client."] = "此客户端没有游戏的性能分析器。"
L["The game's profiler isn't on this client: use a recording below."] = "此客户端没有游戏的性能分析器：请使用下方的记录。"
L["The game's raid frames, as it draws them (the defaults)."] = "游戏的团队框体，按游戏的绘制方式（默认值）。"
L["The game's shield over the icon while the cast can't be interrupted."] = "施法无法打断时，图标上显示游戏的盾牌。"
L["The game's sweep"] = "游戏的扫描效果"
L["The game's tooltips, as it draws them (the defaults)."] = "游戏的鼠标提示，按游戏的绘制方式（默认值）。"
L["The game's: each part in its own (the quest window's for the words). Russian, Korean or Chinese text keeps the game's, so its letters show."] = "游戏的：每个部分使用其自己的字体（文字使用任务窗口的字体）。俄文、韩文或中文文本保持使用游戏字体，以便正确显示字符。"
L["The game's: its own fill, in its own colors. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "游戏的：其自己的填充，使用其自己的颜色。在游戏自带的几种之下：其他插件共享的任何材质（通过 LibSharedMedia）。"
L["The glow round it, added on as light (Glow's only color)."] = "其周围的光晕，以光的形式叠加（光晕的唯一颜色）。"
L["The health bar's color, for Custom."] = "生命条的颜色，用于自定义。"
L["The health bar's fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "生命条的填充。在游戏自带的几种之下：其他插件共享的任何材质（通过 LibSharedMedia）。"
L["The health bar's height, next to the game's."] = "生命条的高度，相对于游戏的高度。"
L["The health bar's height."] = "生命条的高度。"
L["The health bar's width."] = "生命条的宽度。"
L["The icon glows bright and dim while it flashes."] = "闪光期间图标忽明忽暗。"
L["The icon grows a little and back with each beat while it flashes."] = "闪光期间图标随每次跳动稍微放大再复原。"
L["The icon's size, next to the game's. On nameplates, the health bar and name ride up on it."] = "图标的大小，相对于游戏的大小。在姓名板上，生命条和名字会随之上移。"
L["The icon. Click to pick it from all the game's. Right-click: back to the event's own."] = "图标。点击从游戏的所有图标中选择。右键点击：恢复为事件自己的图标。"
L["The icons this bar shows sit together in their order, centered on the bar, instead of faded ones leaving gaps. Edit Mode shows the game's own layout."] = "此条显示的图标按顺序排在一起，在条上居中，而不是让淡出的图标留下空隙。编辑模式显示游戏自己的布局。"
L["The item's quality"] = "物品品质"
L["The key you've bound to it (Key Bindings, Cinematic: Use the quest item), in its top corner."] = "你为它绑定的按键（按键设置，Cinematic：使用任务物品），显示在其上角。"
L["The kind of plate the row is for: your target, focus or the unit under the mouse; Aggro, enemies by who they're attacking; Units, by what they are; or Default, every other plate."] = "该行适用的姓名板类别：你的目标、焦点或鼠标下的单位；仇恨：按敌人在攻击谁；单位：按单位是什么；或默认：其他所有姓名板。"
L["The last tooltip, %d sec ago"] = "上一个鼠标提示，%d秒前"
L["The least of the member you've targeted that shows while they'd be hidden. It only ever makes them more visible: a target whose own opacity above is higher (a tank shown always, say) keeps it. 100% always shows them, at full health too."] = "你选中的成员在本应隐藏时显示的最低程度。它只会让他们更显眼：上方自身不透明度更高的目标（例如始终显示的坦克）保持其值。100%表示始终显示，满血时也会。"
L["The letters start spread apart and close up, as a film's title comes in; the other lines rise in after. A name the game keeps secret (a boss's before its fight, on retail) opens as Reveal instead."] = "字母一开始分散，然后靠拢，就像电影标题出现时那样；其他行随后升起。游戏保密的名字（正式服上首领战前的首领名字）会改用“揭示”方式出现。"
L["The level you reached, if you went up."] = "如果你升级了，显示你达到的等级。"
L["The line round a Dark or Custom bubble. Custom: its thickness and color under it."] = "深色或自定义气泡周围的线。自定义：其下方可设置粗细和颜色。"
L["The lines under an item's players: \"and N more\", \"Lower picks\", who passed, and \"Click to list everyone\". Off: just the players. Clicking an item's panel still lists everyone."] = "物品玩家下方的行：“还有N人”、“较低的选择”、谁放弃了，以及“点击列出所有人”。关闭：只显示玩家。点击物品的面板仍会列出所有人。"
L["The list comes with each release. (For the dev copy, run Tools/commits.sh and /reload.)"] = "此列表随每个版本发布。（开发版请运行 Tools/commits.sh 并 /reload。）"
L["The little point under the bubble. Unticked, just the bubble."] = "气泡下方的小尖角。未勾选时只有气泡。"
L["The look every Vision shares. Each setting starts on the Style hub's General page's; a Vision with a setting of its own on its page keeps it."] = "所有 Vision 共用的外观。每项设置以风格中心“常规”页面的设置为起点；在其页面上有单独设置的 Vision 会保留其设置。"
L["The look of Cinematic's settings pages and windows, for all your characters. HD: flat and dark, with thin edges. SD: the game's own buttons and windows. Auto: HD on retail, SD on classic, and on WoW Forever as your Character Models setting is (Standard: SD)."] = "Cinematic设置页面和窗口的外观，对你的所有角色生效。高清：扁平深色，细边。标清：游戏自己的按钮和窗口。自动：正式服为高清，经典版为标清，WoW Forever 上按你的角色模型设置（标准：标清）。"
L["The look: Auto picks your class and spec's (by the talent tree you've put most into, on clients without specs), or pick any. Each class has a theme for each spec. Create theme makes one of your own from the one shown, under Your themes; the theme's own settings below change the one shown (ours become your version, which Reset theme puts back)."] = "外观：自动会选择你的职业和专精的主题（在没有专精的客户端上，按你投入最多的天赋树），或任选一个。每个职业的每个专精都有一个主题。“创建主题”会基于当前显示的主题制作一个你自己的主题，放在“你的主题”下；下方的主题自身设置会更改当前显示的主题（我们的主题会变成你的版本，“重置主题”可恢复）。"
L["The mana bar shows for this many seconds after you spend mana, then fades out until you spend some again. 0: whenever it's up."] = "你消耗法力后，法力条显示这么多秒，然后淡出，直到你再次消耗法力。0：只要它出现就显示。"
L["The mana bar's color, for Custom."] = "法力条的颜色，用于自定义。"
L["The mana bar's height, next to the power bar's."] = "法力条的高度，相对于能量条的高度。"
L["The mark on important casts"] = "重要施法上的标记"
L["The mark's color."] = "标记的颜色。"
L["The mark's own opacity (the plate's is on the Plate line)."] = "标记自己的不透明度（姓名板的不透明度在“姓名板”一栏）。"
L["The mark's size."] = "标记的大小。"
L["The member under your mouse fades in to at least this, in fights too, and starts fading out the moment the mouse leaves them. 0% turns it off."] = "鼠标下的成员至少淡入到此值，战斗中也是，鼠标离开时立即开始淡出。0%表示关闭。"
L["The meter's totals are hidden in a fight (and for a whole key). The report fills in once it's over."] = "统计的总计在战斗中（以及整个钥石期间）是隐藏的。结束后报告才会填入数据。"
L["The minimap stays up only this long after you pick up a quest or make progress on a tracked one, then fades until you do again. Off: it stays up the whole time a quest is tracked."] = "你接受任务或已追踪的任务有进展后，小地图只保持显示这么久，然后淡出，直到你再次接受或取得进展。关闭：只要有任务被追踪就一直保持显示。"
L["The moment this rule is for. Click to switch."] = "此规则适用的时刻。点击切换。"
L["The most the addon took in one frame."] = "插件在一帧中占用的最长时间。"
L["The mouse is on it, or on a frame in its Hover group"] = "鼠标在它上面，或在其鼠标悬停分组中的某个框体上"
L["The name's font. Russian, Korean or Chinese names keep the game's, so their letters show."] = "名字的字体。俄文、韩文或中文的名字保持使用游戏字体，以便正确显示字符。"
L["The name's size, next to the game's."] = "名字的大小，相对于游戏的大小。"
L["The names and portraits above the chat of who's talking in voice chat. Untick Always to hide them in CineMode."] = "聊天框上方显示在语音聊天中说话的人的名字和头像。取消勾选“始终”可在CineMode中隐藏它们。"
L["The new angle is never within this many degrees of the current one, either way. Keep it below the swing for varied moves."] = "新角度与当前角度的差值永远不会小于这么多度，无论哪个方向。将它保持在摆动角度以下，移动才会多变。"
L["The new buff shows at the start of the row, not in its own place among empty spaces."] = "新的增益效果显示在该行的开头，而不是在空位中它自己的位置。"
L["The other player's name as they challenge you to a duel."] = "对方向你发起决斗时显示其名字。"
L["The other player's name as you challenge them to a duel."] = "你向对方发起决斗时显示其名字。"
L["The parts of the plate in its color, ticks."] = "姓名板中使用其颜色的部分，勾选项。"
L["The pattern's own"] = "图案自己的"
L["The pattern's own choice"] = "图案自己的选择"
L["The place's color (and the recap's title). Picking one turns it to Your own."] = "地点的颜色（以及回顾的标题）。选择一种会将其改为“你自己的”。"
L["The plan adds nothing to your talents."] = "此方案没有给你的天赋增加任何内容。"
L["The plan needs level %d; you're level %d."] = "此方案需要%d级；你是%d级。"
L["The plan takes back talents you've learned: only a class trainer can unlearn them."] = "此方案会退回你已学会的天赋：只有职业训练师才能重置它们。"
L["The plate's color, for the parts ticked beside it. -: the next row that fits the plate decides (the game's if none does). The game's: the game's, whatever the rows below say. Mark's: the mark's color. The rest as the mark's colors."] = "姓名板的颜色，用于旁边勾选的部分。-：由下一个符合该姓名板的行决定（没有则使用游戏的）。游戏的：使用游戏的颜色，无论下方的行如何设置。标记的：标记的颜色。其余与标记的颜色相同。"
L["The power bar's height, next to the game's."] = "能量条的高度，相对于游戏的高度。"
L["The quest camera can't start now: it's off (Scenes page), you're moving or in a fight, or it's turned off where you are."] = "任务镜头现在无法启动：它已关闭（场景页面）、你正在移动或战斗，或在你所在的地方被关闭了。"
L["The quest card and the list of replies have the bubble's look instead of their own dark one, their words in colors that suit it."] = "任务卡片和回复列表使用气泡的外观，而不是它们自己的深色外观，文字颜色也与之相配。"
L["The quest mark's icon on enemies you still need for a quest (a mob to kill): on their nameplates or names, and on your target frame. Click to pick another."] = "你仍需要用于任务的敌人（要击杀的怪物）身上的任务标记图标：在其姓名板或名字上，以及你的目标框体上。点击选择其他图标。"
L["The quest mark's icon on friendly NPCs you still need for a quest (an NPC to talk to): on their nameplates or names, on your target frame, and over the quest object that glows. One you can't do anything with yourself shows it grayed (with the !, the game's \"in progress\" mark). Click to pick another."] = "你仍需要用于任务的友方NPC（要对话的NPC）身上的任务标记图标：在其姓名板或名字上、你的目标框体上，以及发光的任务物体上方。你自己无法与之互动的会显示为灰色（带有 !，游戏的“进行中”标记）。点击选择其他图标。"
L["The ranged bar goes on top, where the main hand's was, and the main hand and off-hand bars each move down one. Set for each class on its own (ticked for hunters, mages, priests and warlocks to start with), so one profile suits all your characters."] = "远程计时条移到顶部主手原来的位置，主手和副手计时条各下移一位。每个职业单独设置（初始勾选了猎人、法师、牧师和术士），所以一个配置文件适合你的所有角色。"
L["The ready check's tick, cross or question mark on each member's raid frame."] = "每个成员团队框体上就位确认的勾、叉或问号。"
L["The recap card, with the meter's whole run if you've one, else made up (Stop hides it)."] = "回顾卡片，如果有统计数据则显示整个副本的数据，否则使用模拟数据（“停止”可隐藏）。"
L["The rest of its settings are on the Scripts page, under the steps they make: pick this camera there."] = "其其余设置在脚本页面上，位于它们生成的步骤下方：在那里选择此镜头。"
L["The rule isn't finished. Finish it, or close with X or Escape to put back the rule it had."] = "规则未完成。完成它，或用 X 或 Esc 关闭以恢复它原来的规则。"
L["The same for your personal health bar: it comes up with the first hit or heal you take."] = "你的个人生命条也一样：受到第一次攻击或治疗时出现。"
L["The same for your personal resource display."] = "你的个人资源显示也一样。"
L["The same for your player frame: it comes up once your health or your power changes."] = "你的玩家框体也一样：生命值或能量变化时出现。"
L["The same person doing the same again (buffing you again, another wave) brings up no card for the minutes below. Their other moments still do."] = "同一个人再次做同样的事（再次给你上增益、再挥一次手）时，在下方的分钟数内不会弹出卡片。他们的其他时刻仍会。"
L["The same place shows at most once every 90 seconds."] = "同一地点每90秒最多显示一次。"
L["The screen's edges close in as your health drops, with your theme's art (all the sections below)."] = "随着你的生命值下降，屏幕边缘会以你主题的美术向内收拢（下方所有部分）。"
L["The seconds left in the middle of the button while it cools down."] = "冷却期间按钮中间显示剩余秒数。"
L["The seconds left on the Cooldown Manager's icons show only when the game's Show Numbers for Cooldowns (Options > Action Bars) is on. Unticked, the Cooldown Manager shows them as it likes."] = "只有在游戏的“显示冷却时间数字”（选项 > 动作条）开启时，冷却管理器图标上才显示剩余秒数。未勾选时，冷却管理器按它自己的方式显示。"
L["The seconds left on the cast, at the bar's right end (in the same font). Hidden while the game keeps them secret, in some fights."] = "施法剩余秒数，显示在条的右端（使用相同字体）。在某些战斗中游戏保密时隐藏。"
L["The selection circle on the ground under your target. Hidden, your own setting is put back when the UI returns."] = "你目标脚下地面上的选择圈。隐藏后，界面恢复时会还原你自己的设置。"
L["The settings below as they are while you're this role (your specialization's, or the one picked in the group finder)."] = "你担任此职责时下方的设置（你专精的职责，或在队伍查找器中选择的职责）。"
L["The settings below for every role that uses the default settings."] = "所有使用默认设置的职责的下方设置。"
L["The settings every frame has while its tab uses the default settings."] = "当其标签页使用默认设置时，每个框体使用的设置。"
L["The settings every group has while its tab uses the default settings."] = "当其标签页使用默认设置时，每个分组使用的设置。"
L["The settings every kind of cast bar has while its tab uses the default settings."] = "当其标签页使用默认设置时，每种施法条使用的设置。"
L["The share of your health a hit has to take at once to count as big."] = "一次攻击需要一下子打掉你生命值的多少比例才算作重击。"
L["The shield on casts that can't be interrupted"] = "无法打断的施法上的盾牌"
L["The shot to show and change."] = "要显示和更改的机位。"
L["The shot's name, as the Scenes page lists it."] = "机位的名称，按场景页面列出的名称。"
L["The size of the bubble and the list as a whole (their words grow with them)."] = "气泡和列表整体的大小（其文字随之变大）。"
L["The size of the game's shadow maps: bigger gives crisper shadow edges, smaller saves frame rate. Players found nothing more above 2048, so 4096 may look the same. Needs shadows on in the game's menu."] = "游戏阴影贴图的大小：越大阴影边缘越清晰，越小越省帧率。玩家发现超过2048后没有更多提升，所以4096可能看起来一样。需要在游戏菜单中开启阴影。"
L["The slow drift the camera keeps up between moves. 0: none."] = "镜头在两次移动之间保持的缓慢漂移。0：无。"
L["The small lines over and under the words, bigger or smaller than they come (100%: as they come, by the words' size)."] = "文字上方和下方的小字，比原本更大或更小（100%：原样，按文字的大小）。"
L["The small lines' font, over and under the words."] = "文字上方和下方小字的字体。"
L["The spark at the fill's end"] = "填充末端的火花"
L["The spell's icon"] = "法术图标"
L["The spell's name"] = "法术名称"
L["The spell's name and seconds left in a color of your own."] = "法术名称和剩余秒数使用你自己的颜色。"
L["The strength, reach and brightness of it all, the shadow, the heartbeat and big hits."] = "整体的强度、范围和亮度，阴影、心跳和重击。"
L["The style this card starts from. Settings you give it on the Style tab go over it."] = "此卡片的起始风格。你在风格标签页给它的设置会覆盖在其上。"
L["The style this card starts from. The settings below that you change go over it, as its own."] = "此卡片的起始风格。你在下方更改的设置会作为它自己的设置覆盖在其上。"
L["The style this tab shows and sets."] = "此标签页显示和设置的风格。"
L["The styles the cards start from. Change one here and every card that starts from it changes too, except where a card has a setting of its own (its Style page, from its row on the Events tab). Changes play at once in the preview."] = "卡片的起始风格。在这里更改一个，所有以它为起点的卡片也会随之改变，除非某张卡片有自己的设置（其风格页面，从事件标签页上其所在行进入）。更改会立即在预览中播放。"
L["The styles the cards start from: change one for every card using it."] = "卡片的起始风格：更改一个，对使用它的每张卡片生效。"
L["The swing round to face you is timed to get there this long before the cast ends. More is a quicker swing."] = "转到面对你的时机经过调整，会在施法结束前这么久到位。越大转得越快。"
L["The swing stops with the speaker this far from the middle of the screen, on their side, so you stay in the shot beside them. 0 aims right at them (you may block the view)."] = "转动停止时，说话者位于离屏幕中心这么远的位置，在其所在一侧，这样你会和他们一起留在画面中。0 表示正对着他们（你可能会挡住视线）。"
L["The tail curls the other way, as if seen in a mirror."] = "尾巴向另一个方向弯曲，就像镜像一样。"
L["The tail pointing at who's talking"] = "指向说话者的尾巴"
L["The talent calculator can't read your talents here."] = "天赋模拟器在这里无法读取你的天赋。"
L["The theme's art soaking in from the edges as they close in (blood, smoke, a glow...)."] = "边缘收拢时，主题的美术从边缘渗入（鲜血、烟雾、光晕……）。"
L["The theme's art: smoke billowing in, a soft glow, blood (or water) soaking in, frost on glass, fur... None: no art, its sparks and shadow only."] = "主题的美术：涌入的烟雾、柔和的光晕、渗入的鲜血（或水）、玻璃上的冰霜、毛皮……无：没有美术，只有火花和阴影。"
L["The theme's color"] = "主题的颜色"
L["The theme's color: the effect turned grey and tinted to match your theme. Its own colors: as the game draws it."] = "主题的颜色：效果变为灰色并染上与你的主题相配的色调。其自身的颜色：按游戏的绘制方式。"
L["The theme's own art and its sparks."] = "主题自己的美术及其火花。"
L["The theme's sparks (motes, stars, lightning) and the haze drifting over the edges."] = "主题的火花（光点、星星、闪电）以及飘过边缘的雾气。"
L["The theme's swirl turning over the screen, closing in from past the corners as they close in, and turning quicker the weaker you are."] = "主题的漩涡在屏幕上旋转，随边缘收拢而从角落外向内收拢，你越虚弱转得越快。"
L["The theme's swirl: up to two layers turning over the screen."] = "主题的漩涡：最多两层在屏幕上旋转。"
L["The thing on the ground you pick up or use for a quest objective glows gold, with the quest mark over it, in CineMode and out. One at a time: the one in front of you that your interact key would use, up to 20 yards away. Only while a quest in this zone still needs something picked up or used. Then it turns on the game's soft targeting for things to interact with (Interact key on keyboard and mouse too); your own settings come back after."] = "你为任务目标拾取或使用的地面物体会发出金光，上方带有任务标记，CineMode内外都是如此。一次只有一个：你面前互动键会使用的那个，最远20码。只在此区域的某个任务仍需要拾取或使用某物时。届时它会开启游戏对可互动物体的软目标锁定（键盘和鼠标的互动键也是）；之后会恢复你自己的设置。"
L["The time of day this rule is for. Click to switch."] = "此规则适用的时段。点击切换。"
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive: how far either way, as a share of the strength. Paused while the Style tab is open. Off: it stays put."] = "色调的强度会在几分钟内缓慢上下浮动，让静止的画面显得更生动一些：浮动幅度以强度的比例表示。打开风格标签页时暂停。关闭：保持不变。"
L["The tooltip fades out over the first 3 seconds of the cast too, and comes back as the cast ends or is cancelled."] = "施法的前3秒内鼠标提示也会淡出，施法结束或取消时恢复。"
L["The tooltip's edge. In its color: a unit's class or reaction color, an item's quality. Custom: its thickness and color under it."] = "鼠标提示的边缘。使用其颜色：单位的职业或关系颜色、物品的品质颜色。自定义：其下方可设置粗细和颜色。"
L["The tracking button on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地图标题上的追踪按钮。取消勾选可在CineMode中隐藏它，即使小地图显示时也是如此。鼠标悬停在小地图上会让它随地图一起出现。"
L["The two colors after it."] = "其后的两种颜色。"
L["The unit under the mouse. Hovering a unit itself works too, not just its plate. Just the marks over the plate: the others hang in the air where its plate is hidden."] = "鼠标下的单位。悬停在单位本身上也可以，不只是其姓名板。只有姓名板上方的标记：其他标记会在姓名板隐藏的位置悬在空中。"
L["The unit's health bar in its mark's color."] = "单位的生命条使用其标记的颜色。"
L["The unit's name in its mark's color, on its plate or shown alone."] = "单位的名字使用其标记的颜色，无论在姓名板上还是单独显示。"
L["The wheel's icon, as it shows on the master wheel. Click to pick another."] = "轮盘的图标，显示在主轮盘上。点击选择其他图标。"
L["The whole card at once."] = "整张卡片一起出现。"
L["The whole plate's opacity while this row fits it, whether it has a mark or not. CineMode's own fade comes on top."] = "此行符合时整个姓名板的不透明度，无论它是否有标记。CineMode自身的淡出会叠加在其上。"
L["The whole run"] = "整个副本"
L["The window shows this many items at once, newest at the top: four down, the rest in a second column. When another drops, the oldest goes."] = "窗口同时显示这么多件物品，最新的在顶部：向下四件，其余在第二列。再有物品掉落时，最旧的会移除。"
L["The window sits to the right of the game's roll frames, level with their top, instead of under them, so a long list of drops doesn't push it down the screen. It stays there once you've chosen."] = "窗口位于游戏掷骰框右侧，与其顶部平齐，而不是在其下方，这样一长串掉落不会把它推到屏幕下方。你选择后它会保持在那里。"
L["The windows you have open open again after."] = "之后会重新打开你打开过的窗口。"
L["The words before it all (on a card, over the zone name)."] = "所有内容前面的文字（在卡片上，区域名称上方）。"
L["The words come in a letter at a time from the left, as if typed; the other lines rise in after. A secret name opens as Reveal instead."] = "文字从左边一个字一个字地出现，就像打字一样；其他行随后升起。保密的名字会改用“揭示”方式出现。"
L["The words coming out of a fight. Empty: none, just the rest of the card."] = "脱离战斗时的文字。留空：无，只显示卡片的其余部分。"
L["The words going into a fight. Empty: none, just the rest of the card."] = "进入战斗时的文字。留空：无，只显示卡片的其余部分。"
L["The words open out from their middle (or from their side, in the lower third or at a bar's side), the line drawing out with them; the other lines rise in after."] = "文字从中间展开（在下三分之一或黑边侧边时从其一侧展开），线条随之延伸；其他行随后升起。"
L["The words over a line that draws out, as a new scene starts."] = "新场景开始时，文字位于一条逐渐延伸的线上方。"
L["The words the banner shows with Custom picked. Left blank: YOU DIED."] = "选择“自定义”时横幅显示的文字。留空：你死了。"
L["The words the banner shows with Custom picked. Left blank: the first ones in the list."] = "选择“自定义”时横幅显示的文字。留空：列表中的第一项。"
L["The words under both names as the duel starts. Empty: none."] = "决斗开始时显示在双方名字下方的文字。留空：无。"
L["The words' color; the lines with them in a lighter shade."] = "文字的颜色；与之一起的线条使用较浅的色调。"
L["The words' font. Russian, Korean or Chinese text keeps the game's, so its letters show."] = "文字的字体。俄文、韩文或中文文本保持使用游戏字体，以便正确显示字符。"
L["The words' height next to the bar's: they grow and shrink with your letterbox. (With no letterbox up, a bar as tall as your letterbox's comes in for the card.)"] = "文字的高度相对于黑边：它们随宽银幕黑边放大缩小。（没有宽银幕黑边时，会为卡片出现一条与你的宽银幕黑边一样高的条。）"
L["The words' size, next to their own."] = "文字的大小，相对于其自身大小。"
L["The world dims and goes cold and gray-blue, with a heavy vignette closing in from the edges. It clears when you release or come back."] = "世界变暗，变得冰冷灰蓝，浓重的暗角从边缘收拢。你释放灵魂或复活时消失。"
L["The zone you spent the most time in (on a card, its big name)."] = "你待得最久的区域（在卡片上，是其大字名称）。"
L["The zone's name on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地图标题上的区域名称。取消勾选可在CineMode中隐藏它，即使小地图显示时也是如此。鼠标悬停在小地图上会让它随地图一起出现。"
L["Their class's color, as the plates draw them."] = "他们的职业颜色，与姓名板的绘制方式相同。"
L["Their color."] = "他们的颜色。"
L["Their face"] = "他们的头像"
L["Their face."] = "他们的头像。"
L["Their name"] = "他们的名字"
L["Their numbers, once the rolls are shown"] = "掷骰公布后显示他们的点数"
L["Their portrait on the card (their class's icon when they're out of sight)."] = "卡片上显示他们的头像（他们不在视野内时显示其职业图标）。"
L["Theme colors"] = "主题颜色"
L["Theme's pick"] = "主题的选择"
L["Theme's sparks"] = "主题的火花"
L["Theme's speed"] = "主题的速度"
L["Theme's swirl"] = "主题的漩涡"
L["Theme's throb"] = "主题的跳动"
L["Theme:"] = "主题："
L["These bubbles show everywhere, in fights and out. (The other columns then have nothing to add.)"] = "这些气泡在所有地方显示，战斗中和战斗外都是。（其他列就没有什么可补充的了。）"
L["These cast bars' settings: Default's until you untick Use default settings."] = "这些施法条的设置：使用默认的，直到你取消勾选“使用默认设置”。"
L["These settings back on General."] = "这些设置恢复为跟随“常规”。"
L["These settings back on the Visions hub's Style page."] = "这些设置恢复为跟随 Visions 中心的风格页面。"
L["Thick"] = "粗"
L["Thick + shadow"] = "粗 + 阴影"
L["Thickness"] = "粗细"
L["Thin"] = "细"
L["Thin bars with a thin gold line along their edge."] = "细条，边缘有一条细金线。"
L["Thin black bars that slide in with the UI's fade (the defaults)."] = "随界面淡出滑入的细黑边（默认值）。"
L["Thin, borderless bars that barely show over the world."] = "细而无边框的条，在世界上几乎看不出来。"
L["This Edit Mode layout's action bars come on or off after a reload. Reload now?"] = "此编辑模式布局的动作条会在重载后开启或关闭。现在重载吗？"
L["This Vision's shared settings back on Visions Style."] = "此 Vision 的共享设置恢复为跟随 Visions 风格。"
L["This boss only"] = "仅此首领"
L["This boss only: everyone starts at 0 as a boss is pulled, and when it dies it's back to the whole run. The whole run: the meter's Overall. Each fight: every pull starts at 0."] = "仅此首领：首领被拉住时所有人从0开始，首领死亡后恢复为整个副本的数据。整个副本：统计的总计。每场战斗：每次拉怪都从0开始。"
L["This camera can't be tested now: Cinematic or the camera is off (Camera Triggers page), or you're moving, flying or in a fight."] = "现在无法测试此镜头：Cinematic或该镜头已关闭（镜头触发页面），或你正在移动、飞行或战斗。"
L["This card's rules as they come."] = "此卡片规则的原样。"
L["This client has no damage meter."] = "此客户端没有伤害统计。"
L["This frame's settings: Default's until you untick Use default settings."] = "此框体的设置：使用默认的，直到你取消勾选“使用默认设置”。"
L["This game version has none of these settings."] = "此游戏版本没有这些设置。"
L["This group's settings: Default's until you untick Use default settings."] = "此分组的设置：使用默认的，直到你取消勾选“使用默认设置”。"
L["This is from a newer Cinematic: update it to add this one."] = "这来自更新版本的Cinematic：请更新后再添加。"
L["This page's shared settings back on General."] = "本页面的共享设置恢复为跟随“常规”。"
L["This row fits everywhere. The rest of the row keeps its ticks for when you untick this."] = "此行在所有地方都符合。取消勾选此项时，该行的其余部分会保留其勾选项。"
L["This row's camera may start anywhere. The rest of the row keeps its ticks for when you untick this."] = "此行的镜头可以在任何地方启动。取消勾选此项时，该行的其余部分会保留其勾选项。"
L["This row's camera waits until the Calm Timer (CineMode page) has run out after a fight."] = "此行的镜头会等到战斗后的平静计时（CineMode页面）结束。"
L["This row: just the enemies among them."] = "此行：只针对其中的敌人。"
L["This row: just the friendly ones among them."] = "此行：只针对其中的友方。"
L["This row: just the neutral ones among them."] = "此行：只针对其中的中立单位。"
L["This row: just these among them: %s."] = "此行：只针对其中的这些：%s。"
L["This row: just those about that far from you. 11 and 28 yards are the game's interact distances; 40 asks a 40-yard spell on your action bars (harmful for enemies, helpful for friends), and with none there the row fits no unit past 28 yards."] = "此行：只针对离你大约那么远的单位。11码和28码是游戏的互动距离；40码需要你的动作条上有一个40码的法术（对敌人为有害法术，对友方为有益法术），如果没有，该行不适用于28码外的任何单位。"
L["This sound's volume, next to the others."] = "此音效的音量，相对于其他音效。"
L["This swing bar isn't in use"] = "此攻击计时条未在使用"
L["This tab's rules as they come: a sound as any other fight starts and one as it ends."] = "此标签页规则的原样：其他战斗开始时一个音效，结束时一个音效。"
L["This tab's rules as they come: a war horn as a boss is pulled; a kill and a wipe, no sound yet."] = "此标签页规则的原样：首领被拉住时吹响战争号角；击杀和团灭暂无音效。"
L["This tab's rules as they come: one for each time of day, a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "此标签页规则的原样：每个时段一个，黎明时公鸡、上午马、正午你阵营的钟声、傍晚青蛙、黄昏猫头鹰、夜晚狼。"
L["This theme as a line of text to send a friend, who adds it with Import theme in their theme menu. Only the theme (edge, colors, sparks, heartbeat), not this page's other settings."] = "将此主题作为一行文本发送给朋友，他们可以在其主题菜单中用“导入主题”添加。只包括主题（边缘、颜色、火花、心跳），不包括本页面的其他设置。"
L["This theme's heartbeat, next to the beats a minute above (slower for a creeping theme)."] = "此主题的心跳，相对于上方的每分钟心跳数（缓慢蔓延的主题更慢）。"
L["Threat glow"] = "仇恨光晕"
L["Throb"] = "跳动"
L["Tick Enemy, Neutral or Friendly for just those of them; all of them: any."] = "勾选敌方、中立或友方，只针对其中的这些；全部勾选：任何。"
L["Ticked, \"#2 of 5\". Unticked, just \"#2\"."] = "勾选：“#2 / 5”。未勾选：只显示“#2”。"
L["Ticked, a bright spark at the edge of the filled part."] = "勾选：在已填充部分的边缘显示明亮的火花。"
L["Ticked, a crown pops in as you take #1."] = "勾选：你成为第1名时弹出王冠。"
L["Ticked, how you did on that boss as it dies."] = "勾选：首领死亡时显示你在该首领战中的表现。"
L["Ticked, how you did on the whole run as it's done."] = "勾选：副本完成时显示你在整个副本中的表现。"
L["Ticked, only while the UI is faded."] = "勾选：仅在界面淡出时。"
L["Ticked, supported addons you install later start with Always ticked: shown the whole time in CineMode. Unticked, they start hidden, except as the other columns say. (Frames you add yourself start faded either way.)"] = "勾选：你之后安装的受支持插件初始勾选“始终”：在CineMode中一直显示。未勾选：初始隐藏，其他列另有设定的除外。（你自己添加的框体无论如何初始都会淡出。）"
L["Ticked, the bars glide to each new value instead of jumping."] = "勾选：条会平滑过渡到每个新值，而不是跳变。"
L["Ticked, the name of the one you race, in their class's color."] = "勾选：显示你竞争对手的名字，使用其职业颜色。"
L["Ticked, the wind comes and goes in gusts every few seconds. Unticked, it blows steadily."] = "勾选：风每隔几秒一阵一阵地吹。未勾选：持续地吹。"
L["Ticked, the wind drops while you're in a fight."] = "勾选：你在战斗中时风会停。"
L["Ticked, your damage (or healing) so far."] = "勾选：显示你目前的伤害（或治疗）。"
L["On the rows:"] = "行上显示："
L["Ticked, each player's name on their row."] = "勾选：在每行显示该玩家的名字。"
L["Ticked, your place over it (#2)."] = "勾选：在其上方显示你的名次（#2）。"
L["Ticked: party frames shown raid-style (the game's Use Raid-Style Party Frames, in Edit Mode) fade as the Raid tab's rows say. Untick it to give them rows of their own."] = "勾选：以团队样式显示的小队框体（游戏的“使用团队风格的小队框体”，在编辑模式中）按团队标签页的行淡出。取消勾选可给它们单独的行。"
L["Ticked: the spells with no cooldown you haven't set yourself go by what they cost, until you set their group's mode: When ready with Resources if they spend a resource you build up (like Maelstrom), else When it procs (like Lightning Bolt). Spells with a cooldown or charges go by their group's setting. It also turns on Flash for Utility Cooldowns, until you set that group's Flash. Unticked: every spell you haven't set yourself goes by its group's setting."] = "勾选：你没有自己设置过的无冷却法术，在你设置其分组的模式之前，按其消耗决定：如果它们消耗你积攒的资源（如漩涡），则为“就绪时”并带“资源”，否则为“触发时”（如闪电箭）。有冷却或充能的法术按其分组的设置。它还会为辅助技能冷却开启“闪光”，直到你设置该分组的“闪光”。未勾选：你没有自己设置过的每个法术都按其分组的设置。"
L["Ticked: these cast bars look as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "勾选：这些施法条按默认标签页的设置显示外观。未勾选：按下方的设置（初始与默认相同，勾选期间会保留）。"
L["Ticked: these cast bars take this page's look (the Default tab's, or this tab's own). Unticked: they keep the game's own. Their size stays the game's (yours is sized in Edit Mode)."] = "勾选：这些施法条采用本页面的外观（默认标签页的，或此标签页自己的）。未勾选：保持游戏自己的外观。其大小保持游戏的大小（你自己的施法条在编辑模式中调整大小）。"
L["Ticked: this card shows where its row says. Unticked: never."] = "勾选：此卡片按其行的设置显示。未勾选：从不显示。"
L["Ticked: this frame looks as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "勾选：此框体按默认标签页的设置显示外观。未勾选：按下方的设置（初始与默认相同，勾选期间会保留）。"
L["Ticked: this frame shows the parts the Target grid says. Untick it to give the frame choices of its own."] = "勾选：此框体显示目标表格中设定的部分。取消勾选可给此框体单独的选项。"
L["Ticked: this group looks as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "勾选：此分组按默认标签页的设置显示外观。未勾选：按下方的设置（初始与默认相同，勾选期间会保留）。"
L["Ticked: while no letterbox is up, the card shows in the lower third. Unticked: a bar of its own comes in for it."] = "勾选：没有宽银幕黑边时，卡片显示在下三分之一处。未勾选：会为它出现一条单独的黑边。"
L["Ticked: while you're this role, Heal Vision goes by the Default tab. Unticked: by the settings on this tab."] = "勾选：你担任此职责时，Heal Vision 按默认标签页的设置。未勾选：按此标签页的设置。"
L["Tied: rolling again"] = "平局：重新掷骰"
L["Tighter rows and smaller text, for raids."] = "更紧凑的行和更小的文字，适用于团队。"
L["Tilt %s° down over %s s"] = "向下倾斜%s°，用时%s秒"
L["Tilt %s° up over %s s"] = "向上倾斜%s°，用时%s秒"
L["Tilt 0° (no tilt)"] = "倾斜0°（无倾斜）"
L["Tilt down to"] = "向下倾斜至"
L["Tilt to %s° give or take %s/%s over %s s"] = "倾斜到%s°，上下浮动%s/%s，用时%s秒"
L["Tilt up to"] = "向上倾斜至"
L["Time"] = "时间"
L["Time left"] = "剩余时间"
L["Time played"] = "游戏时长"
L["Times the addon's busy parts as you play, for as long as is picked beside it. It starts when you close the settings (or right away, with Start now), and the results show here. Click it again to stop."] = "在你游戏时为插件的繁忙部分计时，时长为旁边所选的时间。它在你关闭设置时开始（或选择“立即开始”时马上开始），结果显示在这里。再次点击可停止。"
L["Timing and extras"] = "时机和附加"
L["Title card"] = "标题卡"
L["To fade something else, use the Find frames tab: search by name, pick frames by hovering, or let Smart Find look for them. Or hover over a frame and type |cffffd100/cine add|r. Frames you add are listed under their addon, with the same columns; the X takes one off the list."] = "要淡出其他东西，请使用查找框体标签页：按名称搜索、悬停选取框体，或让智能查找去寻找。或者将鼠标悬停在框体上并输入 |cffffd100/cine add|r。你添加的框体列在其插件下方，带有相同的列；X 可将其从列表中移除。"
L["Today, %s"] = "今天，%s"
L["Together (empty: pick it and add steps)"] = "同时（空：选择它并添加步骤）"
L["Together: these at once"] = "同时：同时执行这些"
L["Toggle Duel Vision"] = "开关 Duel Vision"
L["Toggle Heal Vision"] = "开关 Heal Vision"
L["Toggle Quest Vision"] = "开关 Quest Vision"
L["Toggle Roll Vision"] = "开关 Roll Vision"
L["Toggle Vitals Vision"] = "开关 Vitals Vision"
L["Tooltip"] = "鼠标提示"
L["Tooltip: %s"] = "鼠标提示：%s"
L["Tooltips show all through CineMode. (The other columns then have nothing to add.)"] = "鼠标提示在整个CineMode期间显示。（其他列就没有什么可补充的了。）"
L["Top"] = "顶部"
L["Top letterbox bar"] = "顶部宽银幕黑边"
L["Top speed in the middle of a sweep. At 6°/sec with 50% ease, a 30° sweep takes 10 seconds."] = "环绕中段的最高速度。速度为6°/秒、缓入缓出50%时，30°的环绕需要10秒。"
L["Tracked Bars"] = "追踪的条"
L["Tracked Buffs"] = "追踪的增益效果"
L["Tracked buffs and bars: Always, In combat, Out of combat or Hidden (the game keeps your buffs secret in fights, so they go by that alone). Each group has a tab of its own."] = "追踪的增益效果和条：始终、战斗中、非战斗中或隐藏（游戏在战斗中会把你的增益效果设为保密，所以只能按此设置）。每个分组都有自己的标签页。"
L["Tracking a quest"] = "正在追踪任务"
L["Tracking button"] = "追踪按钮"
L["Tracking in"] = "追踪于"
L["Transmog"] = "幻化"
L["Triggers"] = "触发条件"
L["Triggers: %s"] = "触发条件：%s"
L["Trying %s. Close this window to keep it."] = "正在试用%s。关闭此窗口即可保留。"
L["Turn %d°   Tilt %d°   Zoom %s yd   %s / %s s"] = "转向 %d°   倾斜 %d°   缩放 %s码   %s / %s秒"
L["Turn %s° toward where you clicked them over %s s"] = "转%s°到你点击他们的一侧，用时%s秒"
L["Turn each move"] = "每次移动的转角"
L["Turn it on to see and change its settings."] = "开启后才能查看和更改其设置。"
L["Turn off"] = "关闭"
L["Turn on"] = "开启"
L["Turn on %s"] = "开启%s"
L["Turn on the Profiler page and record a while of your usual play (a fight too), then click Copy report there and send it with your bug report."] = "开启性能分析器页面，记录一段你平常的游戏过程（包括一场战斗），然后在那里点击“复制报告”，并随错误报告一起发送。"
L["Turn on the loot roll window first."] = "请先开启拾取掷骰窗口。"
L["Turn around behind you over %s s"] = "转到你身后，用时%s秒"
L["Turn to face you before the cast ends"] = "施法结束前转到面对你"
L["Turn to face you over %s s"] = "转到面对你，用时%s秒"
L["Turning it on, and which rolls it shows."] = "开启它，以及它显示哪些掷骰。"
L["Turning it on, the moments a card shows for and each one's emotes."] = "开启它，卡片显示的时刻，以及每个时刻的表情。"
L["Turning it on, when it shows and what it counts."] = "开启它，何时显示，以及统计什么。"
L["Turns Duel Vision on or off."] = "开启或关闭 Duel Vision。"
L["Turns Heal Vision on or off (its Enable Page switch), in a fight too: off, the party and raid frames all show again."] = "开启或关闭 Heal Vision（其“启用页面”开关），战斗中也可以：关闭时，小队和团队框体会全部重新显示。"
L["Turns Quest Vision on or off (its Enable Page switch)."] = "开启或关闭 Quest Vision（其“启用页面”开关）。"
L["Turns Roll Vision on or off."] = "开启或关闭 Roll Vision。"
L["Turns Vitals Vision on or off (its Enable Page switch)."] = "开启或关闭 Vitals Vision（其“启用页面”开关）。"
L["Turns a minute at full (half that as it starts). Below 0: the other way."] = "满值时每分钟旋转的圈数（开始时为一半）。低于0：反方向。"
L["Turns the Tooltips page on or off (its Enable Page switch)."] = "开启或关闭鼠标提示页面（其“启用页面”开关）。"
L["Turns the visual effects on or off (their Enable Visual Effects switch): the letterbox, tint, vignette, weather and the rest."] = "开启或关闭视觉效果（其“启用视觉效果”开关）：宽银幕黑边、色调、暗角、天气等。"
L["Turns the whole Atmosphere hub on or off at once: the letterbox, tint, time of day, zone tints, vignette, inn glow, weather, depth of field, Graphics+ and Audio. Each keeps its own settings for when you turn this back on."] = "一次开启或关闭整个氛围中心：宽银幕黑边、色调、时段、区域色调、暗角、旅店光晕、天气、景深、图形+和音频。每项都会保留其自己的设置，以便你重新开启时使用。"
L["Turns this group on or off. While it's off it's kept as it is, but its frames come up on their own (or with their other groups), and its events don't bring it up."] = "开启或关闭此分组。关闭期间它保持原样，但其框体会单独出现（或随其所在的其他分组出现），其事件也不会让它出现。"
L["Twinkling stars"] = "闪烁的星星"
L["Type"] = "类型"
L["Type part of a frame's name or of the addon that made it. Hover over a match to see it marked on screen, click it to put it on the list below, to add. Only other addons' frames that aren't faded yet are listed."] = "输入框体名称或创建它的插件名称的一部分。将鼠标悬停在匹配项上可在屏幕上看到其标记，点击可将其放入下方列表以供添加。只列出尚未淡出的其他插件框体。"
L["Type part of a name to see the icons it matches: any spell, the items you carry and wear, mounts, or an icon's file name such as INV_Misc_Bag_07. Enter picks the first."] = "输入名称的一部分，查看匹配的图标：任何法术、你携带和穿戴的物品、坐骑，或图标的文件名，例如 INV_Misc_Bag_07。按回车选择第一个。"
L["Type part of an icon's name to see the ones it matches, such as bang, turnin or speak. Enter picks the first."] = "输入图标名称的一部分，查看匹配的图标，例如 bang、turnin 或 speak。按回车选择第一个。"
L["Typewriter"] = "打字机"
L["Typing brings up the chat window any time. (The other columns then have nothing to add.)"] = "输入文字时随时调出聊天窗口。（其他列就没有什么可补充的了。）"
L["Ultra immersive"] = "极致沉浸"
L["Uncommon and up"] = "优秀及以上"
L["Under it"] = "在其下方"
L["Under the indicator, while you cast: your mana's numbers on the bar show what you'll have once the cast is done, paler. The amount and the percent, whichever the game shows there (its Status Text setting); with the game's numbers off, the amount in the middle of the bar."] = "在指示条下方，施法时：条上的法力数值会以较淡的颜色显示施法完成后你将剩余的法力。数量和百分比，按游戏在那里显示的方式（其“状态文字”设置）；游戏数字关闭时，在条的中间显示数量。"
L["Under the name, what the game says of the place: Contested Territory, Sanctuary, Alliance or Horde Territory..."] = "名称下方显示游戏对该地点的描述：争夺中的领土、安全区域、联盟或部落领地……"
L["Under the tooltip, where the game puts it."] = "在鼠标提示下方，游戏放置它的位置。"
L["Under the words: their color, lighter. Over them: a pale gray."] = "在文字下方：其颜色，较浅。在文字上方：淡灰色。"
L["Under the zone name"] = "在区域名称下方"
L["Underline"] = "下划线"
L["Undo"] = "撤销"
L["Undo pending changes"] = "撤销待定的更改"
L["Unit Name"] = "单位名称"
L["Unit frame"] = "单位框体"
L["Units"] = "单位"
L["Unloaded"] = "未加载"
L["Untick to leave the camera running when this happens. Moving the camera yourself still takes over: it carries on a second after you let go."] = "取消勾选可在发生这种情况时让镜头继续运行。你自己移动镜头仍会接管：你松开后一秒它会继续。"
L["Until %s s before landing"] = "直到降落前%s秒"
L["Until %s s go by"] = "直到%s秒过去"
L["Until someone new talks"] = "直到有新的人说话"
L["Until the cast ends"] = "直到施法结束"
L["Until the cast is %s s from done"] = "直到施法离完成还有%s秒"
L["Until you're back to life"] = "直到你复活"
L["Use General"] = "使用“常规”"
L["Use Visions Style"] = "使用 Visions 风格"
L["Use default settings"] = "使用默认设置"
L["Use the camera's own numbers"] = "使用镜头自己的数值"
L["Use the quest item"] = "使用任务物品"
L["Use this row. Unticked, its trigger passes it over: the next row for it is tried, and with none it starts no camera. Its settings stay for when you tick it again."] = "使用此行。未勾选时，其触发条件会跳过它：尝试它的下一行，如果没有则不启动任何镜头。其设置会保留，以便你再次勾选时使用。"
L["Used by: %s"] = "使用者：%s"
L["Uses the item on Quest Vision's quest item button, while it shows."] = "在 Quest Vision 的任务物品按钮显示时，使用其上的物品。"
L["Usual order"] = "通常顺序"
L["Utility"] = "辅助"
L["Utility Cooldowns"] = "辅助冷却"
L["Utility: stay up while a cooldown is recharging"] = "辅助：冷却恢复中时保持显示"
L["Version %s, %d settings changed"] = "版本%s，%d项设置已更改"
L["Victory"] = "胜利"
L["View distance"] = "视野距离"
L["Vision"] = "Vision"
L["Vision wheel"] = "Vision 轮盘"
L["Visions"] = "Visions"
L["Visions Style"] = "Visions 风格"
L["Visions in use"] = "使用中的 Vision"
L["Vitals Vision"] = "Vitals Vision"
L["Vitals Vision demo stopped."] = "Vitals Vision 演示已停止。"
L["Vitals Vision demo: a new theme every %s seconds (/cine vital demo to stop)."] = "Vitals Vision 演示：每%s秒一个新主题（输入 /cine vital demo 停止）。"
L["Vitals Vision demo: all %d shown."] = "Vitals Vision 演示：全部%d个已显示。"
L["Vitals Vision demo: no class called \"%s\"."] = "Vitals Vision 演示：没有名为“%s”的职业。"
L["Vitals Vision shows it as far as your health says"] = "Vitals Vision 按你的生命值显示它"
L["Vitals Vision test done."] = "Vitals Vision 测试完成。"
L["Voice chat speakers"] = "语音聊天说话者"
L["W"] = "宽"
L["Wait"] = "等待"
L["Wait %s s"] = "等待%s秒"
L["Wait %s sec"] = "等待%s秒"
L["Wait %s to %s s"] = "等待%s到%s秒"
L["Wait before starting"] = "开始前等待"
L["Wait for boss fights to end"] = "等待首领战结束"
L["Wait for the Calm Timer"] = "等待平静计时"
L["Wait till after"] = "等到之后"
L["Wait to the side"] = "在侧边等待"
L["Warsong Gulch"] = "战歌峡谷"
L["What blows: Auto picks your class and spec's (the same as Vitals Vision's theme), or pick any, or plain wind or motes of light."] = "吹的是什么：自动会选择你的职业和专精的效果（与 Vitals Vision 的主题相同），或任选一个，或者普通的风或光点。"
L["What cuts the pattern to an edge, so it stays around the screen's sides. None: the pattern over all of the screen (an edge already, like the red one, needs none)."] = "用什么把图案裁切到边缘，使其保持在屏幕四周。无：图案覆盖整个屏幕（本身已是边缘的，例如红色那种，不需要）。"
L["What each row of frames is doing right now, and the settings behind it. Click a row for all its reasons. To ask about one frame on the screen, pick it in game (or type /cine why)."] = "每一行框体当前在做什么，以及背后的设置。点击一行可查看其全部原因。若要查询屏幕上的某个框体，请在游戏中选取它（或输入 /cine why）。"
L["What happens when you move the camera, a fight starts, you walk, you zoom or its trigger ends; and its edge haze and Stop button while it runs."] = "当你移动镜头、战斗开始、你行走、你缩放或其触发条件结束时会发生什么；以及运行时的边缘模糊和停止按钮。"
L["What it counts"] = "统计内容"
L["What it is: motes of light floating up, stars twinkling, lightning flickering, gas drifting in over the edges, motes spiraling in the way the swirl turns, or stars circling the middle. None: not there."] = "它是什么：向上飘浮的光点、闪烁的星星、闪动的闪电、从边缘飘入的气体、随漩涡方向螺旋涌入的光点，或环绕中心的星星。无：不显示。"
L["What it is: wispy spiral arms (added on as light), clouds wound into a whirlpool, or a portal's glowing rim closing in around you. None: not there."] = "它是什么：纤细的螺旋臂（以光的形式叠加）、卷成漩涡的云，或向你收拢的传送门发光边缘。无：不显示。"
L["What picking it does: a slash command, such as /rw Pull in 10, or several, a line each (anything a macro can do). The game cuts a line at 255 letters."] = "选择它会做什么：一条斜杠命令，例如 /rw Pull in 10，或多条，每行一条（宏能做的任何事）。游戏会在255个字符处截断一行。"
L["What shows of mobs and NPCs you still need for a quest objective (a mob to kill, an NPC to talk to), whatever the Nameplates page's grids say; tick any. Nameplate: their whole nameplates. Name: their names, on their nameplates. Quest mark: a golden ! added to the nameplate or name shown, else the ! alone. These three in CineMode, in fights and out, and need the Nameplates page enabled; once the objective is done, they fade with the rest. Unit frame: the same mark beside your target frame's health bar while your target is one of them, in CineMode and out. None ticked: as the Nameplates page's settings say."] = "无论姓名板页面的表格如何设置，你仍需要用于任务目标的怪物和NPC（要击杀的怪物、要对话的NPC）显示什么；可任意勾选。姓名板：它们的完整姓名板。名字：它们的名字，在其姓名板上。任务标记：在显示的姓名板或名字上添加一个金色的 !，否则只显示 !。这三项在CineMode中、战斗中和战斗外都有效，需要启用姓名板页面；任务目标完成后，它们会随其余部分淡出。单位框体：当你的目标是其中之一时，在你目标框体的生命条旁显示同样的标记，CineMode内外都是如此。都不勾选：按姓名板页面的设置。"
L["What the addon's timers measured: ms a frame, and its share of the frame."] = "插件计时器测得的数据：每帧毫秒数，以及它在帧中的占比。"
L["What the bubble and card do while the camera moves: the quest camera's swing, zoom and turn (its drift is Hold the camera still's), or you turning it. Follow: they stay over the NPC's nameplate, sliding with it. Fade out: they fade out, and back in over the NPC once it's still. Dim: they fade down, still readable. Wait to the side: they stay still where Default would put them, and fade over to the NPC once the camera's still."] = "镜头移动时气泡和卡片怎么做：任务镜头的转动、缩放和转向（其漂移由“保持镜头静止”决定），或你自己转动镜头。跟随：它们保持在NPC的姓名板上方，随之滑动。淡出：它们淡出，镜头静止后在NPC上方重新淡入。暗淡：它们变淡，但仍可阅读。在侧边等待：它们静止在“默认”会放置的位置，镜头静止后淡入到NPC上方。"
L["What the game measured for Cinematic meanwhile, the timers' parts and all the rest."] = "在此期间游戏为Cinematic测得的数据，包括计时器的各部分和其余所有部分。"
L["What this card does if it comes while you're in a fight, or in the 5 seconds after one."] = "如果此卡片在你战斗中或战斗后5秒内出现，它会怎么做。"
L["What this card plays as it shows."] = "此卡片显示时播放什么。"
L["What's new"] = "新内容"
L["What's new in Cinematic, newest first. Show me opens the page a feature is on. Every change, fixes too, is on the All changes page."] = "Cinematic的新内容，最新的在前。“让我看看”会打开功能所在的页面。所有更改（包括修复）都在“所有更改”页面。"
L["What's this card's alone: when it shows, the lines with its name, its words. How it looks: the Style tab."] = "此卡片独有的内容：何时显示、带有其名字的行、其文字。外观：风格标签页。"
L["Whatever style that event starts from."] = "该事件起始的任何风格。"
L["Wheels"] = "轮盘"
L["Wheels on it"] = "上面的轮盘"
L["When"] = "符合条件"
L["When all a quest giver has to offer or take in is daily or weekly quests, the camera stays as it is."] = "当任务NPC能提供或接收的只有日常或每周任务时，镜头保持不动。"
L["When it blows"] = "何时吹"
L["When it ends"] = "它结束时"
L["When it ends: nothing, it stays where it is"] = "它结束时：不做任何事，保持在原位"
L["When it procs"] = "触发时"
L["When it's ready"] = "就绪时"
L["When its camera stops. Moving always stops it too, as it does every camera that runs while you stand still. It ends: when the trigger that started it ends (the cast, the buff, leaving the place)."] = "其镜头何时停止。移动也总会停止它，就像所有在你站着不动时运行的镜头一样。它结束时：启动它的触发条件结束时（施法、增益效果、离开该地点）。"
L["When ready"] = "就绪时"
L["When someone does something for you or at you, a small card shows who it was, with a few emotes to answer in one click. It waits out fights and fades away by itself. Pick the moments and their emotes below. When it shows: the Settings tab. Its style and look: the Look tab."] = "当有人为你或对你做了什么时，会显示一张小卡片说明是谁，并附有几个表情，可一键回应。它会等战斗结束，并自行淡出。在下方选择时刻及其表情。何时显示：设置标签页。其风格和外观：外观标签页。"
L["When someone talks out of sight (behind you, say), the camera turns around, a full turn at most, until their chat bubble shows, then frames them. If they're nowhere to be seen, it ends up back where it was."] = "当有人在视野外说话（例如在你身后）时，镜头会转过去，最多转一整圈，直到看到其聊天气泡，然后对准他们。如果哪里都看不到他们，镜头会回到原来的位置。"
L["When the cards show and for how long. The moments and their emotes: the Vision tab. Its look: the Look tab."] = "卡片何时显示以及显示多久。时刻及其表情：Vision 标签页。其外观：外观标签页。"
L["When the cards show, and for how long."] = "卡片何时显示，以及显示多久。"
L["When the edges close in, the health bars and how fast."] = "边缘何时收拢、生命条以及速度。"
L["When the release popup offers a way to come back yourself (a soulstone, Reincarnation, an ankh...), there's no death camera: you keep your own view to pick your moment."] = "当释放灵魂弹窗提供了自行复活的方式（灵魂石、复生、十字章……）时，不会使用死亡镜头：你保持自己的视角来选择时机。"
L["When this buff's icon or bar shows. The game keeps your buffs secret in fights, so these go by whether you're in one."] = "此增益效果的图标或条何时显示。游戏在战斗中会把你的增益效果设为保密，所以这些只按你是否在战斗中来判断。"
L["When this group works: any time, only out of combat or only in combat. Click to change. The rest of the time its frames come up on their own (or with their other groups), and its events don't bring it up."] = "此分组何时生效：任何时候、仅非战斗中或仅战斗中。点击更改。其余时间它的框体会单独出现（或随其所在的其他分组出现），其事件也不会让它出现。"
L["When this rule fits. Click to write it in the rule editor; empty: any fight."] = "此规则何时符合。点击在规则编辑器中编写；留空：任何战斗。"
L["When this rule fits. Click to write it in the rule editor; empty: any time."] = "此规则何时符合。点击在规则编辑器中编写；留空：任何时候。"
L["When this spell's icon shows in the Cooldown Manager."] = "此法术的图标何时在冷却管理器中显示。"
L["When you die, the camera turns slowly round your body until you release or are resurrected. CineMode stays on (straight away), with the release button (and any soulstone or Reincarnation button) still showing."] = "你死亡时，镜头会围绕你的尸体缓慢旋转，直到你释放灵魂或被复活。CineMode保持开启（立即），释放灵魂按钮（以及任何灵魂石或复生按钮）仍会显示。"
L["When you turn left or right, the camera doesn't snap round with you: it carries on as it was (sway and all) until you stop turning, then glides gently around to your new facing, easing in and out. Dragging with either mouse button hands the camera straight back to you."] = "当你向左或向右转时，镜头不会立刻跟着你转：它保持原样（包括摇摆）直到你停止转向，然后平滑地转到你的新朝向，带缓入缓出。用任一鼠标键拖动会立即把镜头交还给你。"
L["Where"] = "位置"
L["Where and when each effect shows in CineMode. Always: everywhere. Combat: In combat, Calm Timer (after a fight, till it's run out), Out of combat (the rest of the time), In a camera mode (flights, AFK, cozy and the rest). Location: the places. Nothing ticked: it's off."] = "每种效果在CineMode中何处、何时显示。始终：所有地方。战斗：战斗中、平静计时（战斗后，直到其结束）、非战斗中（其余时间）、镜头模式中（飞行、暂离、温馨等）。地点：各个地方。未勾选任何项：关闭。"
L["Where and when each kind of bubble shows. Always: everywhere. Nothing ticked: never."] = "每种气泡在何处、何时显示。始终：所有地方。未勾选任何项：从不。"
L["Where and when music can play in CineMode; anywhere else it fades out (your own game music too) and back in after. Always: everywhere. Out of combat: back once the Calm Timer has run out after a fight (with Calm Timer too: as soon as the fight ends)."] = "CineMode中音乐可以在何处、何时播放；在其他地方会淡出（你自己的游戏音乐也是），之后再淡入。始终：所有地方。非战斗中：战斗后平静计时结束时恢复（同时勾选平静计时时：战斗一结束就恢复）。"
L["Where chat bubbles show. How they look: the Style hub's Chat bubbles page."] = "聊天气泡在哪里显示。外观：风格中心的聊天气泡页面。"
L["Where in the letterbox bar the card sits."] = "卡片在宽银幕黑边中的位置。"
L["Where it comes when other scenes are on at the same time: the first one on in this order plays. Going AFK while doing an emote is the AFK scene, say."] = "当其他场景同时生效时它的顺序：按此顺序第一个生效的场景会播放。例如在做表情时暂离，就是暂离场景。"
L["Where the bubble goes. Over the head: over the NPC's nameplate, following them on the screen. Default: above the middle of the screen, or wherever you drag it. Opposite clicked: wherever you drag it, but when you clicked the NPC on that half of the screen, at the same spot on the other half (they stand where you clicked, so that half is clearer), the quest card beside it. With nobody to stand over or no click (a quest from an item, or the interact key), it goes where Default would."] = "气泡的位置。头顶：在NPC的姓名板上方，在屏幕上跟随他们。默认：屏幕中间上方，或你拖动到的任何位置。点击的对侧：你拖动到的位置，但如果你点击NPC的位置在屏幕的那一半，则放在另一半的相同位置（他们站在你点击的地方，所以那一半更清楚），任务卡片在其旁边。如果没有可以悬停的对象或没有点击（来自物品的任务，或互动键），则放在“默认”的位置。"
L["Where the card shows: in the middle of the screen, in a letterbox bar or in the lower third. (A banner goes across the middle.)"] = "卡片显示的位置：屏幕中间、宽银幕黑边中或下三分之一处。（横幅横跨屏幕中间。）"
L["Where the tail sits along the bubble: 0 at its left end, 50 in the middle, 100 at its right end."] = "尾巴在气泡上的位置：0 在左端，50 在中间，100 在右端。"
L["Where the zoom ends as the cast does, if you're further out. Closer already, it stays where it is. Arriving, the camera is back at your own distance."] = "如果你离得更远，施法结束时缩放结束的位置。如果已经更近，则保持原位。抵达后，镜头恢复你自己的距离。"
L["Where this row's camera may start (Grouped: in a party or raid). Anywhere else the next row of its trigger is tried, and with none the camera doesn't start (or stops if it's running). For flights, Cities means taking off from one, and Open world taking off anywhere else."] = "此行的镜头可以在哪里启动（组队时：在小队或团队中）。在其他地方会尝试其触发条件的下一行，如果没有，镜头不会启动（正在运行的也会停止）。对于飞行，“城市”指从城市起飞，“开放世界”指从其他任何地方起飞。"
L["Where to find Cinematic outside the game. Click a link and press Ctrl+C to copy it, then paste it into your browser."] = "在游戏外哪里可以找到Cinematic。点击链接并按 Ctrl+C 复制，然后粘贴到你的浏览器中。"
L["Where your damage came from"] = "你的伤害来源"
L["Where your extra ability button goes (the extra abilities frame's place in Edit Mode), a big button with the item the nearest tracked quest gives you to use, the one in the quest tracker. Click it or press its key (Keybinds page). Shows near the quest's area, beside the game's own button when that's up. It can't show, hide or move in a fight: it stays as it was until the fight ends."] = "额外技能按钮所在的位置（编辑模式中额外技能框体的位置），一个大按钮，上面是最近的已追踪任务给你使用的物品，即任务追踪中的那个。点击它或按其按键（按键绑定页面）。在任务区域附近显示，游戏自己的按钮出现时位于其旁边。战斗中它无法显示、隐藏或移动：在战斗结束前保持原样。"
L["Where your healing came from"] = "你的治疗来源"
L["Whether this row's camera may start in a fight (unticked, one running stops when a fight starts), and whether it waits for things to calm down after one."] = "此行的镜头能否在战斗中启动（未勾选时，正在运行的镜头会在战斗开始时停止），以及战斗后是否等待平静下来。"
L["Whether you won or lost (or someone fled) as the duel ends."] = "决斗结束时显示你赢了还是输了（或有人逃跑）。"
L["Which Visions follow this page. One with a setting of its own shows which; Use Visions Style puts them all back on this page. The name opens its page."] = "哪些 Vision 跟随本页面。有自己设置的 Vision 会显示是哪项；“使用 Visions 风格”会让它们全部回到跟随本页面。点击名称可打开其页面。"
L["Which addons the table shows: tick the ones to compare, or All addons for every one."] = "表格显示哪些插件：勾选要比较的插件，或勾选“所有插件”显示全部。"
L["Which edge they start from."] = "它们从哪个边缘开始。"
L["Which items"] = "哪些物品"
L["Which of them, ticks. Aggro: who the enemy's attacking, You or Not you (someone friendly: a group member, a pet or another player), and their role, Tank, Healer or DPS (no role set counts as DPS; a pet only with all three ticked). Units: any of Normal NPC, Elite NPC (elite, rare elite and bosses), Players, and Minions (their pets, totems and guardians); all four, any unit."] = "其中哪些，勾选项。仇恨：敌人在攻击谁，你或不是你（友方单位：队伍成员、宠物或其他玩家），以及他们的职责，坦克、治疗者或伤害输出（未设职责算作伤害输出；宠物只在三种都勾选时才算）。单位：普通NPC、精英NPC（精英、稀有精英和首领）、玩家和仆从（他们的宠物、图腾和守护者）中的任何一种；四种都勾选：任何单位。"
L["Which one. Key bindings are set in the game's Key Bindings, under Cinematic."] = "哪一个。按键绑定在游戏的按键设置中Cinematic下设置。"
L["Which pages follow General. A page with a setting of its own shows which; Use General puts them all back on General. The page's name opens it."] = "哪些页面跟随“常规”。有自己设置的页面会显示是哪项；“使用常规”会让它们全部回到跟随“常规”。点击页面名称可打开它。"
L["Which parts of the player, target, focus and pet frames show. Keeping a frame up, always or in fights, is on the Game Frames page; your own while you recover, on the Resource Display page."] = "玩家、目标、焦点和宠物框体显示哪些部分。要让框体一直显示或在战斗中显示，请到游戏框体页面设置；你自己的框体在恢复期间的显示，在资源显示页面设置。"
L["Which parts of the unit frames show, CineMode or not: your own frame and your pet's, and the target, focus and target of target frames. Pick a frame's tab to see its grid: the focus and target of target go as the target's grid says until you untick Same as target. Untick parts to keep just the bars. The frame art is the portrait ring, the name box and the bars' borders: the game draws them as one picture. Icons are the rest Zzz, the group leader's crown, role and quest icons, and the raid marker (skull, moon...) on the target and focus frames. Auras are the buffs and debuffs on the target and focus frames. Hit text is the damage and healing numbers on your and your pet's portraits. Threat is the threat percentage and aggro glow on the target and focus frames, for NPCs you can fight."] = "单位框体显示哪些部分，无论是否处于CineMode：你自己的框体和宠物的框体，以及目标、焦点和目标的目标框体。选择框体的标签页查看其表格：焦点和目标的目标按目标的表格设置，直到你取消勾选“与目标相同”。取消勾选部分即可只保留条。框架美术是头像圆环、名字框和条的边框：游戏把它们作为一张图片绘制。图标是其余部分：休息的Zzz、队长的王冠、职责和任务图标，以及目标和焦点框体上的团队标记（骷髅、月亮……）。光环是目标和焦点框体上的增益和减益效果。命中文字是你和你宠物头像上的伤害和治疗数字。仇恨是目标和焦点框体上的仇恨百分比和仇恨光晕，针对你可以攻击的NPC。"
L["Which side the camera comes round to. On your right, the quest giver is on the right of the screen. (The game doesn't tell addons where the quest giver stands, or what's around you, so it can't pick the open side.) \"Where you clicked them\": the side of the screen you clicked the quest giver on, and the camera turns toward it; talking to them with a key instead, the side is picked at random."] = "镜头转到哪一侧。在你的右侧时，任务NPC位于屏幕右侧。（游戏不会告诉插件任务NPC站在哪里，或你周围有什么，所以它无法选择开阔的一侧。）“你点击他们的一侧”：你点击任务NPC时所在的屏幕一侧，镜头会朝它转；如果改用按键与其对话，则随机选择一侧。"
L["Which way the lines line up: their left edges, their middles or their right edges. By where it's moved to: by which side of the screen the Move box is on."] = "各行的对齐方式：左边缘、中间或右边缘。按移动到的位置：按“移动”框位于屏幕的哪一侧。"
L["While CineMode is on, the camera comes alive when something happens: an emote, a campfire, going AFK, your Hearthstone, fishing, a flight, a quest giver, auto-walking or dying. The Scenes page says what starts which camera; the Scripts page has each camera's steps and settings. Moving by hand cancels them all, and everything goes back to normal when the UI returns."] = "CineMode开启时，镜头会在发生某些事情时动起来：表情、篝火、暂离、你的炉石、钓鱼、飞行、任务NPC、自动行走或死亡。场景页面设置什么启动哪个镜头；脚本页面包含每个镜头的步骤和设置。手动移动会取消所有这些镜头，界面恢复时一切都会回到正常。"
L["While a quest is tracked in the quest tracker, the minimap stays up during CineMode, so you can see where to go. Untrack your quests and it fades again."] = "当任务追踪中有任务被追踪时，小地图在CineMode期间保持显示，这样你可以看到要去哪里。取消追踪你的任务后，它会再次淡出。"
L["While a vision is doing something (Heal Vision fading frames, a duel being watched, the roll window up...), the minimap button glows in its color. Its menu and tooltip list that vision, and the camera running, with a link to its page."] = "当某个 Vision 正在工作时（Heal Vision 正在淡出框体、正在观看决斗、掷骰窗口已打开……），小地图按钮会以其颜色发光。其菜单和鼠标提示会列出该 Vision 以及正在运行的镜头，并附有其页面的链接。"
L["While it runs"] = "运行时"
L["While recharging"] = "冷却恢复中"
L["While the UI is faded, a new message briefly shows just the chat window it arrived in. Choose which messages below, and what of the window comes up with them under Chat window."] = "界面淡出时，新消息会短暂只显示它所在的聊天窗口。在下方选择哪些消息，并在“聊天窗口”下选择窗口的哪些部分随之出现。"
L["While the camera moves"] = "镜头移动时"
L["While you cast a spell that costs mana, the mana it will take shows as a pale stretch at the end of your mana: what's left after the cast is the fill to its left."] = "施放消耗法力的法术时，它将消耗的法力会以淡色段显示在你法力的末端：施法后剩余的是其左侧的填充部分。"
L["While you're auto-running (the auto-run key). Pressing forward or back, or stopping, ends it; stop and stand, and the AFK camera takes over. Auto-walking counts as RP walk instead."] = "当你自动奔跑时（自动奔跑键）。按前进或后退键，或停下，会结束它；停下站着不动，暂离镜头会接管。自动行走则算作RP漫步。"
L["While you're auto-walking (auto-run in walk mode). Walking by hand cancels the camera, as all moving by hand does. Stop and stand, and the AFK camera takes over. Walking is recognized from your speed; /cine walk shows what the addon thinks."] = "当你自动行走时（行走模式下的自动奔跑）。手动行走会取消镜头，就像所有手动移动一样。停下站着不动，暂离镜头会接管。行走根据你的速度识别；/cine walk 会显示插件的判断。"
L["While you're in a duel (or have asked for one, or been asked), other players' duels nearby don't show. Off: they show all through yours."] = "当你在决斗中（或已发起决斗或被邀请决斗）时，附近其他玩家的决斗不会显示。关闭：在你的决斗期间它们也会显示。"
L["While you're moving the card waits, and shows once you stop (if that's within 20 seconds)."] = "你移动时卡片会等待，停下后才显示（如果在20秒以内）。"
L["Whirlpool clouds"] = "漩涡云"
L["White"] = "白色"
L["Who it's cast at"] = "施法对象"
L["Whole run"] = "整个副本"
L["Why Is It Showing?"] = "为什么显示？"
L["Why is it showing?"] = "为什么显示？"
L["Width"] = "宽度"
L["Width:"] = "宽度："
L["Wind Guide"] = "风之指引"
L["Wind Guide can't tell which way you face here."] = "风之指引在这里无法判断你面朝的方向。"
L["Wind Guide test done."] = "风之指引测试完成。"
L["Wind Guide test: blowing toward your waypoint."] = "风之指引测试：朝你的路径点吹。"
L["Wind Guide test: no waypoint, so a pretend one off to your right."] = "风之指引测试：没有路径点，因此使用你右侧的一个假想点。"
L["Windows the game opens on the left (quest log, group finder, profession book and the like) open on the right instead, near the top, leaving your character in view. Two open at once still sit side by side. Narrow ones on their own (character, trade, merchant, mail) and quest givers' windows open a little in from the left edge instead, halfway up the screen, leaving the world and the quest giver in view. A window another addon has moved stays where that addon put it."] = "游戏在左侧打开的窗口（任务日志、队伍查找器、专业技能书等）改为在右侧靠上打开，让你的角色保持在视野中。同时打开两个时仍会并排放置。单独打开的窄窗口（角色、交易、商人、邮件）以及任务NPC的窗口会改为离左边缘稍远一点、在屏幕中间高度打开，让世界和任务NPC保持在视野中。被其他插件移动过的窗口保持在那个插件放置的位置。"
L["Winner"] = "获胜者"
L["Winner color:"] = "获胜者颜色："
L["Winner's row:"] = "获胜者所在行："
L["Wipe"] = "团灭"
L["With \"Start in CineMode\" off (Cinematic's main page), its camera starting brings CineMode on, and it ends with the camera."] = "在“以CineMode启动”关闭时（Cinematic主页面），其镜头启动会开启CineMode，并随镜头一同结束。"
L["With Custom dialogue frames unticked, it places the game's own gossip and quest window instead. Default: wherever you drag it (else where the game puts it). Opposite clicked: the same, but on the other half of the screen from where you clicked the NPC. Over the head isn't for a whole window (it would cover them): the game's window is left where the game puts it."] = "未勾选“自定义对话框”时，它会改为放置游戏自己的对话和任务窗口。默认：你拖动到的任何位置（否则在游戏放置的位置）。点击的对侧：相同，但在你点击NPC位置的屏幕另一半。头顶不适用于整个窗口（会挡住NPC）：游戏的窗口保持在游戏放置的位置。"
L["With Legacy"] = "使用传承"
L["With Smart set ticked, until you set a bar's mode, its spells with no cooldown go by what they cost; unticked, by their group's setting."] = "勾选“智能设置”时，在你设置某个条的模式之前，其无冷却法术按其消耗决定；未勾选时，按其分组的设置。"
L["With no one talking for this long, the camera turns back and zooms back out. Moving ends it at once, leaving the camera where it is."] = "无人说话达到这么久时，镜头会转回并拉远。移动会立即结束它，镜头保持在原位。"
L["With the UI"] = "随界面"
L["Within 11 yards"] = "11码以内"
L["Within 28 yards"] = "28码以内"
L["Within 40 yards"] = "40码以内"
L["Won"] = "获胜"
L["Won:"] = "获胜："
L["Words"] = "文字"
L["Words in Russian, Korean or Chinese keep the game's font, so their letters show."] = "俄文、韩文或中文的文字保持使用游戏字体，以便正确显示字符。"
L["Words that mark a campfire when they're in the name its tooltip shows (\"Campfire\"), separated by commas. Use words in your game language."] = "鼠标提示中显示的名称里出现时即表示篝火的词语（如“篝火”），用逗号分隔。请使用你游戏语言中的词语。"
L["Words:"] = "文字："
L["Worst"] = "最差"
L["Worst frame"] = "最差帧"
L["Worst ms"] = "最差毫秒"
L["X"] = "X"
L["XP bars"] = "经验条"
L["Y"] = "Y"
L["YOU DIED"] = "你死了"
L["YOU DIED, \"wasted\" (a picture) or words of your own."] = "“你死了”、“wasted”（一张图片）或你自己的文字。"
L["Yesterday, %s"] = "昨天，%s"
L["You"] = "你"
L["You challenge"] = "你发起挑战"
L["You challenge them to a duel"] = "你向对方发起决斗"
L["You come back to life"] = "你复活了"
L["You earn an achievement"] = "你获得了一项成就"
L["You fled from %s"] = "你从%s面前逃跑了"
L["You have %d scenes of your own already: delete one to make another."] = "你已经有%d个自己的场景：删除一个才能再制作。"
L["You have %d shots already: delete one to make another."] = "你已经有%d个机位：删除一个才能再制作。"
L["You have %d wheels already: delete one to make another."] = "你已经有%d个轮盘：删除一个才能再制作。"
L["You have 30 camera scripts already: delete one to add another."] = "你已经有30个镜头脚本：删除一个才能再添加。"
L["You haven't made a wheel yet."] = "你还没有制作过轮盘。"
L["You leave"] = "你离开"
L["You level up"] = "你升级了"
L["You move"] = "你移动"
L["You press its key again"] = "你再次按下其按键"
L["You set it to always show (Custom frames, Addon Frames page)"] = "你已将其设为始终显示（插件框体页面的自定义框体）"
L["You turn in a quest"] = "你交了一个任务"
L["You were holding the key that shows tooltips"] = "你按住了显示鼠标提示的按键"
L["You're challenged"] = "你受到挑战"
L["You're not on the meter"] = "你不在统计中"
L["You're not on the meter yet"] = "你还不在统计中"
L["You're typing in chat"] = "你正在聊天中输入文字"
L["Your camera"] = "你的镜头"
L["Your cast bar fades out over the first 3 seconds of the cast, so you see it start, then the portal closing in is its progress. Other casts show it as usual."] = "你的施法条会在施法的前3秒内淡出，让你看到它开始，之后传送门的收拢就是施法进度。其他施法照常显示施法条。"
L["Your character looks around as the camera starts turning, as if they'd spotted something. Players nearby see the emote in chat. Fly-bys you start count too."] = "镜头开始转动时，你的角色会四处张望，就像发现了什么。附近的玩家会在聊天中看到这个表情。你自己启动的掠过也算。"
L["Your class"] = "你的职业"
L["Your class's color, whether you lead or chase."] = "你职业的颜色，无论你领先还是追赶。"
L["Your class's color."] = "你职业的颜色。"
L["Your face on your dot, their class icon on theirs."] = "你的圆点上是你的头像，他们的圆点上是他们的职业图标。"
L["Your focus."] = "你的焦点。"
L["Your frame stays up while you recover"] = "你恢复期间你的框体保持显示"
L["Your gear is damaged (durability alert)"] = "你的装备已损坏（耐久度警报）"
L["Your group"] = "你的队伍"
L["Your group kills a boss"] = "你的队伍击杀了一个首领"
L["Your health at a glance, without the portrait: as it drops, the screen's edges close in, with your theme's art soaking in from them (blood, smoke, a glow in its color), a heartbeat that quickens as you weaken and a flash on big hits. Auto picks a theme for your class and spec. The death screen takes over if you die."] = "不看头像也能一眼看到你的生命值：随着生命值下降，屏幕边缘会向内收拢，你主题的美术从边缘渗入（鲜血、烟雾、其颜色的光晕），心跳随你变虚弱而加快，重击时会闪光。自动会为你的职业和专精选择一个主题。如果你死亡，死亡画面会接管。"
L["Your health falls in hits in the preview, and on the screen as the Vitals Vision page's Test says. Close the settings to see it all."] = "你的生命值会在预览中一下下地下降，在屏幕上则按 Vitals Vision 页面的“测试”设置。关闭设置即可看到全部效果。"
L["Your health the edges are all the way in at (under Starts)."] = "边缘完全收拢时你的生命值（低于“开始”）。"
L["Your health the edges start creeping in below."] = "边缘开始向内蔓延时你的生命值。"
L["Your health this bar is fully up at (under Starts)."] = "此条完全显示时你的生命值（低于“开始”）。"
L["Your health this bar starts fading in below."] = "此条开始淡入时你的生命值。"
L["Your icons on it"] = "上面你的图标"
L["Your mana under your character when it isn't your power (Elemental Shaman, Shadow Priest...): once it's on, on the Resource Display page."] = "当法力不是你的能量类型时（元素萨满、暗影牧师……），在你角色下方显示你的法力：开启后在资源显示页面设置。"
L["Your own"] = "你自己的"
L["Your own color"] = "你自己的颜色"
L["Your own color for it."] = "你为它选的颜色。"
L["Your own mix of this part's settings"] = "你对此部件设置的自定义组合"
L["Your own pick and number are always on an item's panel, even when it lists only the top few players or only the best pick."] = "你自己的选择和点数总会显示在物品的面板上，即使它只列出前几名玩家或只显示最好的选择。"
L["Your own profile"] = "你自己的配置文件"
L["Your own profile. Right-click it, then Description to say what it's for."] = "你自己的配置文件。右键点击它，然后选择“描述”来说明它的用途。"
L["Your own settings, as they were before you picked a preset."] = "你自己的设置，即你选择预设之前的设置。"
L["Your own words."] = "你自己的文字。"
L["Your party uses its own frames, not raid-style ones: they follow the Unit frames page's Party tab."] = "你的小队使用自己的框体，而不是团队样式框体：它们按单位框体页面的小队标签页设置。"
L["Your party uses raid-style frames (Edit Mode's party frames setting): they follow the Raid frames page, not this tab."] = "你的小队使用团队样式框体（编辑模式的小队框体设置）：它们按团队框体页面设置，而不是此标签页。"
L["Your personal resource display (the health bar under your character) fades in as your health drops."] = "你的个人资源显示（角色下方的生命条）会随你的生命值下降而淡入。"
L["Your pet is unhappy"] = "你的宠物不快乐"
L["Your place"] = "你的名次"
L["Your player frame (portrait and health bar) fades in as your health drops."] = "你的玩家框体（头像和生命条）会随你的生命值下降而淡入。"
L["Your player frame too"] = "也包括你的玩家框体"
L["Your player frame, pet frame and personal resource display in CineMode: kept up while you recover after a fight or run low on mana, and held back at the start of a fight until there's something to see. When they come up at all (always, in fights, in places) is their rows' on the Game Frames page."] = "CineMode中你的玩家框体、宠物框体和个人资源显示：在战斗后恢复期间或法力不足时保持显示，在战斗开始时暂缓显示，直到有东西可看。它们到底何时出现（始终、战斗中、某些地点）由游戏框体页面上它们的行决定。"
L["Your portrait"] = "你的头像"
L["Your scenes"] = "你的场景"
