L["Not the damage meter's numbers: your race with the player ahead of you, or your lead over #2 once you're #1. It reads the game's own damage meter, so that needs to be on (Options, Gameplay Enhancements: Enable Damage Meter). Its type and how it looks: the Look tab."] = "不是伤害统计的数字：而是你与前一名玩家的竞争，或者你成为第1名后对第2名的领先。它读取游戏自带的伤害统计，所以需要开启它（选项，游戏增强：启用伤害统计）。其类型和外观：外观标签页。"
L["Turning it on, when it shows, what it counts, its tests and the picked type's settings."] = "开启、何时显示、统计什么、它的测试，以及所选类型的设置。"
L["%.2f yards"] = "%.2f码"

-- Options.lua: Reset addon (Reset Settings, Reset EVERYTHING)
L["Reset Settings puts every setting back and keeps what you made: your own profiles, cameras, scripts, themes and backups. Reset EVERYTHING deletes all of it. Either reloads the UI."] = "“重置设置”会还原所有设置，并保留你创建的内容：你自己的配置档、镜头、脚本、主题和备份。“全部重置”会删除这一切。两者都会重载界面。"
L["Reset Cinematic?\n\nReset Settings: every setting goes back to how it was on install, and you start on the default profile. Nothing you made is deleted: your own profiles, cameras, scripts, themes, rules, wheels and backups stay, and so do flight times and what Cinematic has learned as you played.\n\nReset EVERYTHING: deletes all of it, as on a fresh install.\n\nEither way the UI reloads, and Cinematic's Edit Mode layouts are removed so your own comes back."] = "重置 Cinematic？\n\n重置设置：所有设置恢复到安装时的样子，并从默认配置档开始。你创建的内容都不会删除：你自己的配置档、镜头、脚本、主题、规则、轮盘和备份都会保留，飞行时间和 Cinematic 在你游玩中学到的东西也会保留。\n\n全部重置：删除这一切，如同全新安装。\n\n无论哪种都会重载界面，并移除 Cinematic 的编辑模式布局，让你自己的布局回来。"
L["Delete everything in Cinematic? Your own profiles, cameras, scripts, themes, rules, wheels and backups are deleted for good, along with every setting. This can't be undone."] = "删除 Cinematic 中的一切？你自己的配置档、镜头、脚本、主题、规则、轮盘和备份将连同所有设置被永久删除。此操作无法撤销。"
L["Reset Settings"] = "重置设置"
L["Reset EVERYTHING"] = "全部重置"

-- ShoulderCam.lua
L["Over your shoulder wherever you are. (The other columns then have nothing to add.)"] = "无论在哪里都越过你的肩膀。（其他列此时没有可添加的。）"
L["Frames follow you"] = "框体跟随你"
L["Your cast bar and Personal Resource Display slide over to where you are on the screen, and glide back as the camera goes behind you. Edit Mode still places them: this moves them from there."] = "你的施法条和个人资源显示会滑到你在屏幕上的位置，镜头回到你身后时滑回。它们仍由编辑模式摆放：这只是从那里移动它们。"
L["Follow strength"] = "跟随强度"
L["How far they slide. Where you are on the screen is worked out from the camera, not read: if they land short of you or past you, turn this up or down."] = "它们滑动的距离。你在屏幕上的位置是根据镜头推算的，而非读取：如果它们没到你或超过你，就调高或调低此项。"
L["The camera sits over your shoulder, with you to one side of the screen."] = "镜头位于你的肩膀上方，你在屏幕的一侧。"
L["On: the camera moves over your shoulder. This uses one of Blizzard's experimental camera settings: the game shows its experimental camera warning (Accept keeps it working). The game's Keep Character Centered option (Accessibility) stops it, so that's turned off meanwhile. Off: your own settings come back."] = "开启：镜头移到你的肩膀上方。这会用到暴雪的一项实验性镜头设置：游戏会显示实验性镜头警告（选择接受可保持生效）。游戏的“保持角色居中”选项（辅助功能）会阻止它，因此期间会关闭该选项。关闭：恢复你自己的设置。"
L["Shoulder"] = "肩膀"
L["Offset"] = "偏移"
L["How far to the side the camera moves. About 1 is subtle; 1.5 to 2 is a strong over-the-shoulder look."] = "镜头向侧边移动的距离。约 1 较为含蓄；1.5 到 2 则是明显的过肩视角。"
L["Right shoulder"] = "右肩"
L["Left shoulder"] = "左肩"
L["Which shoulder the camera looks over. The swap key below flips it."] = "镜头越过哪一侧肩膀。下方的切换键可以翻转。"
L["Swap shoulders key"] = "切换肩膀按键"
L["Not during Cinematic's cameras that frame you"] = "Cinematic 以你为中心的镜头期间不生效"
L["On a mount the camera stays straight behind you: a big mount's head fills the shot from the side."] = "骑乘时镜头保持在你正后方：从侧面看，大型坐骑的头会占满画面。"
L["While the standing-still, AFK, flight, fly-by or death camera runs, the camera goes back behind you, as their shots are built around you in the middle. It comes back as they end. The quest and chat cameras keep it."] = "站立不动、暂离、飞行、飞掠或死亡镜头运行时，镜头会回到你身后，因为它们的画面以你为中心构图。它们结束后恢复。任务和聊天镜头会保留。"
L["Frames"] = "框体"
L["Pause"] = "暂停"

-- TalkingHeads.lua (its option on the Quest Vision page)
L["Talking heads"] = "对话头像"
L["Hide repeated talking heads"] = "隐藏重复的对话头像"
L["The game's talking head (the NPC portrait at the top of the screen, with their line and voice) closes at once when it's a line you've already seen. Daily and world quest lines come back every day, so you see them once; the story's lines play only once anyway. Each character remembers its own, ticked or not, so an alt still sees the story's."] = "游戏的对话头像（屏幕顶部的 NPC 头像，带台词和语音）若是你已看过的台词，会立即关闭。日常和世界任务的台词每天都会重来，所以你只看一次；剧情台词本来就只播放一次。无论是否勾选，每个角色各自记录，所以小号仍能看到剧情台词。"

-- ProfileChoices.lua and Welcome.lua: profile choices
L["Fights and opening windows bring your UI back"] = "战斗和打开窗口会让界面回来"
L["Most of the time"] = "大部分时间"
L["Between fights, and fights bring back less: no minimap, fewer group nameplates"] = "战斗之间，战斗中回来得更少：没有小地图，更少的队伍姓名板"
L["Always show"] = "始终显示"
L["Action bars (Classic group)"] = "动作条（经典组）"
L["Action bars (Retail group)"] = "动作条（正式服组）"
L["General and Trade too"] = "也包括综合和交易"
L["Neither NPC speech nor public channels bring chat up"] = "NPC 发言和公共频道都不会让聊天出现"
L["No NPC chatter; speech from behind you shows low on the screen"] = "没有 NPC 闲聊；你身后的话语显示在屏幕下方"
L["A portal opens around you as you hearth or teleport"] = "使用炉石或传送时，你周围会打开一道传送门"
L["A card shows who buffed you or emoted at you"] = "卡片显示谁给你加了增益或对你做了表情"
L["Your race with the top of the meter, in dungeons and raids"] = "在地下城和团队副本中与统计榜首的竞赛"
L["NPC speech brings chat up; public channels don't"] = "NPC 发言会让聊天出现；公共频道不会"
L["NPC speech, and the General and Trade channels"] = "NPC 发言，以及综合和交易频道"

-- CardMoments.lua, CardsPage.lua, FlightLine.lua: Flight departure
L["Click to target %s"] = "点击以选中%s"
L["As a flight lands: where it took you, and how long the flight took."] = "飞行降落时：它把你带到了哪里，以及飞了多久。"
L["Flight departure"] = "起飞"
L["As a flight takes off: where it's taking you, and about how long it takes on a route you've flown before. With a line along the top or bottom of the screen filling up on the way, if you like."] = "飞行起飞时：它要带你去哪里，以及在飞过的航线上大约要多久。如果你愿意，屏幕顶部或底部还会有一条随途中进度填满的线。"
L["Flying to"] = "飞往"
L["First time on this route"] = "首次飞这条航线"
L["about %d min"] = "约 %d 分钟"
L["%s flight"] = "飞行 %s"
L["Progress line"] = "进度线"
L["Show a line as you fly"] = "飞行时显示一条线"
L["On a route you've flown before, a thin line along a letterbox bar (or that edge of the screen) fills up as you fly, with the time left at its end. It shows while your UI is faded, and goes a moment before you land. A route's first flight has none: it's timed as you fly it."] = "在飞过的航线上，一条细线会沿着宽银幕黑边（或屏幕那一侧边缘）随飞行填满，末端显示剩余时间。界面淡出时显示，降落前片刻消失。航线的首次飞行没有：会在飞行中计时。"
L["Flight progress line"] = "飞行进度线"
L["Top bar"] = "顶部黑边"
L["Only at the start and end"] = "仅在开始和结束时"
L["The line shows for this long as the flight starts and before it lands, and is hidden in between: point the mouse at its place to see it. 0: it shows the whole way."] = "线会在飞行开始和降落前显示这么久，中途隐藏：把鼠标指向它的位置即可看到。0：全程显示。"
L["Bottom bar"] = "底部黑边"
L["The letterbox bar the line and its time go in (no letterbox up: that edge of the screen)."] = "线和时间所在的宽银幕黑边（没有黑边时：屏幕那一侧边缘）。"
L["Not on flights"] = "飞行时不显示"
L["No Zone or Subzone card on a flight path: the places you fly over don't bring one after another, and the Flight departure and arrival cards say where you're going."] = "飞行路线上不显示区域或子区域卡片：飞过的地方不会一张接一张地出现，起飞和抵达卡片会告诉你要去哪里。"
L["Minutes only"] = "仅分钟"
L["\"2 min\", rounded up, then \"under a minute\"."] = "“2 分钟”，向上取整，然后“不到一分钟”。"
L["Minutes and seconds"] = "分和秒"
L["\"1:12\", counting down."] = "“1:12”，倒计时。"
L["Don't show"] = "不显示"
L["Just the line."] = "只显示线。"
L["Time left:"] = "剩余时间："
L["The time left at the line's end."] = "线末端的剩余时间。"
L["The Flight departure card's line is on: on a route you've flown before, it fills up as you fly"] = "起飞卡片的线已开启：在飞过的航线上，它会随飞行填满"
L["Where:"] = "位置："

-- EmoteVision.lua
