-- Options.lua: the CineMode page's Overview
L["Overview"] = "概览"
L["Everything CineMode can do, page by page, and whether each page is on."] = "CineMode 能做的一切，逐页列出，以及每页是否开启。"
L["How fast the UI fades, the Calm Timer, combat text and error messages."] = "界面淡出的速度、平静计时器、战斗文字和错误信息。"
L["What fades in CineMode, and what brings it back."] = "CineMode 中什么会淡出，以及什么会让它回来。"
L["How the world looks and sounds in CineMode."] = "CineMode 中世界的样子和声音。"
L["The camera coming alive while CineMode is on."] = "CineMode 开启时活起来的镜头。"
L["On and off with the General page's switch."] = "随“通用”页面的开关开启和关闭。"
L["On. Click to turn this page off."] = "已开启。点击关闭此页面。"
L["Off. Click to turn this page on."] = "已关闭。点击开启此页面。"
L["Everything CineMode can do, page by page. Click On or Off to turn a page on or off; Open takes you there."] = "CineMode 能做的一切，逐页列出。点击“开”或“关”来开启或关闭一个页面；“打开”会带你过去。"
L["Go to this page."] = "前往此页面。"
L["%d of %d pages on."] = "已开启 %d / %d 个页面。"

-- ShowMe.lua and Welcome.lua: See it first, Show me
L["Nothing to show here."] = "这里没有可展示的。"
L["Not in a fight: try it once the fight ends."] = "战斗中不可用：战斗结束后再试。"
L["Click the row to turn it on first."] = "请先点击该行将其开启。"
L["See it first"] = "先看看"
L["Click one to see it for a few seconds."] = "点击一项可观看几秒钟。"
L["Vitals"] = "生命体征"
L["Teleport"] = "传送"
L["Black bars at the top and bottom of the screen, as in a film."] = "屏幕顶部和底部的黑边，就像电影一样。"
L["A color wash over the world that follows the time of day and the zone, with soft dark edges and weather to match."] = "覆盖世界的色调，随时段和区域变化，带有柔和的暗边和相配的天气。"
L["The camera moves on its own at quiet moments: on flights, when you go AFK, by a campfire. This shows a half turn around you; move the camera yourself to stop it."] = "镜头会在安静时刻自行移动：飞行时、暂离时、篝火旁。这里展示绕你半圈；自己移动镜头即可停止。"
L["As your health drops, the screen's edges close in, so you feel a fight without watching your health bar."] = "生命值下降时，屏幕边缘会向内收拢，让你无需盯着生命条也能感受战斗。"
L["As you cast your Hearthstone or a teleport, a portal opens around you and the world fades out as you leave."] = "施放炉石或传送时，你周围会打开一道传送门，离开时世界逐渐消失。"
